--
-- Name: activate_offline_learner_account(uuid, uuid, bytea, bytea, text, text, uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_offline_learner_account(p_actor_auth_user_id uuid, p_invitation_id uuid, p_token_digest bytea, p_recipient_email_digest bytea, p_learner_login text, p_raw_pin text, p_provisional_auth_user_id uuid, p_acknowledge_recovery_delegate boolean, p_request_observer_invitation boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.activate_offline_learner_account_impl(
    p_actor_auth_user_id, p_invitation_id,
    p_token_digest, p_recipient_email_digest,
    p_learner_login, p_raw_pin, p_provisional_auth_user_id,
