--
-- Name: activate_offline_learner_account_impl(uuid, uuid, bytea, bytea, text, text, uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_offline_learner_account_impl(p_actor_auth_user_id uuid, p_invitation_id uuid, p_token_digest bytea, p_recipient_email_digest bytea, p_learner_login text, p_raw_pin text, p_provisional_auth_user_id uuid, p_acknowledge_recovery_delegate boolean, p_request_observer_invitation boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_recipient_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_provisional_account public.account%rowtype;
  v_source_profile public.learner_profile%rowtype;
  v_target_profile public.learner_profile%rowtype;
  v_invitation public.learner_claim_invitation%rowtype;
  v_operation_id uuid;
  v_preview jsonb;
  v_target_id uuid;
  v_pin_hash text;
  v_observer_token_digest bytea;
  v_observer_invitation_id uuid;
  v_completed_operation public.learner_profile_merge%rowtype;
  v_recovery_delegate public.learner_credential_recovery_delegate%rowtype;
  v_recovery_delegate_created boolean := false;
begin
  if not coalesce(p_acknowledge_recovery_delegate, false) then
    raise exception 'learner_activation_recovery_acknowledgement_required'
      using errcode = '55000';
  end if;
  if v_recipient_account_id is null
    or p_provisional_auth_user_id is null
    or p_provisional_auth_user_id = p_actor_auth_user_id
    or octet_length(p_token_digest) <> 32
    or octet_length(p_recipient_email_digest) <> 32
    or p_learner_login is null
    or lower(btrim(p_learner_login)) !~ '^[[:alnum:]_.-]{3,80}$'
    or p_raw_pin !~ '^\d{4,8}$'
  then
    raise exception 'learner_activation_not_found' using errcode = 'P0002';
  end if;
  if not public.learner_identity_rate_limit_hit(
    'learner_activation',
    extensions.digest(
      v_recipient_account_id::text || ':' || p_invitation_id::text,
      'sha256'
    ),
    20, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;

  select invitation.* into v_invitation
  from public.learner_claim_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.kind = 'child_activation'
    and invitation.token_digest = p_token_digest
    and invitation.recipient_email_digest = p_recipient_email_digest
    and invitation.recipient_account_id = v_recipient_account_id
    and invitation.status = 'accepted';
  if found then
    select * into v_completed_operation
    from public.learner_profile_merge
    where invitation_id = v_invitation.id and status = 'completed';
    if found then
      insert into public.learner_credential_recovery_delegate (
        subject_account_id, delegate_account_id, activation_invitation_id
      ) values (
        v_completed_operation.subject_account_id,
        v_recipient_account_id,
        v_invitation.id
      ) on conflict (subject_account_id, delegate_account_id) do nothing
      returning * into v_recovery_delegate;
      v_recovery_delegate_created := found;
      if not v_recovery_delegate_created then
        select delegate.* into v_recovery_delegate
        from public.learner_credential_recovery_delegate as delegate
        where delegate.subject_account_id = v_completed_operation.subject_account_id
          and delegate.delegate_account_id = v_recipient_account_id;
      else
        perform public.append_learner_identity_audit(
          'learner_credential_recovery_delegate_granted',
          v_recipient_account_id, v_completed_operation.subject_account_id,
          v_completed_operation.target_learner_profile_id, null,
          v_recovery_delegate.id,
          jsonb_build_object('projectionVersion', 1)
        );
      end if;
      return jsonb_build_object(
        'invitation', jsonb_build_object(
          'id', v_invitation.id, 'kind', v_invitation.kind,
          'status', 'accepted',
          'learnerProfileId', v_completed_operation.target_learner_profile_id,
          'learnerLabel', coalesce((select display_name from public.learner_profile where id = v_completed_operation.target_learner_profile_id), 'Учебный профиль'),
          'inviterLabel', (select display_name from public.account where id = v_invitation.inviter_account_id),
          'expiresAt', v_invitation.expires_at,
          'createdAt', v_invitation.created_at,
          'acceptedAt', v_invitation.accepted_at
        ),
        'mergePreview', v_completed_operation.preview_payload,
        'completed', true,
        'childAccountLogin', (
          select normalized_login from public.account_login_alias
          where account_id = v_completed_operation.subject_account_id
            and revoked_at is null limit 1
        ),
        'observerInvitationId', (
          select id from public.learner_observer_invitation
          where learner_profile_id = v_completed_operation.target_learner_profile_id
            and subject_account_id = v_completed_operation.subject_account_id
            and recipient_account_id = v_recipient_account_id
          order by created_at desc limit 1
        ),
        'provisionalAuthUserConsumed', coalesce((
          select account.auth_user_id = p_provisional_auth_user_id
          from public.account as account
          where account.id = v_completed_operation.subject_account_id
        ), false),
        'recoveryDelegateId', v_recovery_delegate.id,
        'recoveryDelegateActive', coalesce(
          v_recovery_delegate.status = 'active', false
        )
      );
    end if;
  end if;

  select invitation.* into v_invitation
  from public.learner_claim_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.kind = 'child_activation'
    and invitation.token_digest = p_token_digest
    and invitation.recipient_email_digest = p_recipient_email_digest
    and invitation.status in ('pending', 'bound')
    and invitation.expires_at > now()
    and (invitation.recipient_account_id is null
      or invitation.recipient_account_id = v_recipient_account_id)
  for update of invitation;
  if not found then
    raise exception 'learner_activation_not_found' using errcode = 'P0002';
  end if;

  select account.* into v_provisional_account
  from public.account as account
  where account.auth_user_id = p_provisional_auth_user_id
    and account.status = 'provisional'
    and account.id <> v_recipient_account_id
  for update of account;
  if not found then
    raise exception 'learner_activation_not_found' using errcode = 'P0002';
  end if;
  select profile.* into v_target_profile
  from public.learner_profile as profile
  where profile.account_id = v_provisional_account.id
  for update of profile;
  if not found
    or exists (select 1 from public.learning_record where learner_profile_id = v_target_profile.id)
    or exists (select 1 from public.teacher_learner where learner_profile_id = v_target_profile.id)
    or exists (select 1 from public.learner_profile_alias where target_learner_profile_id = v_target_profile.id)
  then
    raise exception 'learner_activation_target_not_empty' using errcode = '55000';
  end if;
  select profile.* into v_source_profile
  from public.learner_profile as profile
  where profile.id = v_invitation.source_learner_profile_id
    and profile.account_id is null
  for update of profile;
  if not found then
    raise exception 'learner_activation_not_found' using errcode = 'P0002';
  end if;

  insert into public.account_login_alias (account_id, normalized_login)
  values (v_provisional_account.id, lower(btrim(p_learner_login)));
  v_pin_hash := extensions.crypt(p_raw_pin, extensions.gen_salt('bf'));
  update public.account_security
  set pin_hash = v_pin_hash, pin_failed_attempts = 0,
      pin_locked_until = null,
      pin_created_at = coalesce(pin_created_at, now()),
      pin_updated_at = now()
  where account_id = v_provisional_account.id;
  update public.account
  set status = 'active', display_name = v_source_profile.display_name
  where id = v_provisional_account.id;
  update public.learner_profile
  set display_name = v_source_profile.display_name
  where id = v_target_profile.id;
  update public.learner_claim_invitation
  set recipient_account_id = v_recipient_account_id, status = 'bound'
  where id = v_invitation.id;

  insert into public.learner_profile_merge (
    source_learner_profile_id, target_learner_profile_id,
    invitation_id, requested_by_account_id, subject_account_id, expires_at
  ) values (
    v_source_profile.id, v_target_profile.id,
    v_invitation.id, v_invitation.inviter_account_id,
    v_provisional_account.id, least(v_invitation.expires_at, now() + interval '1 day')
  ) returning id into v_operation_id;
  v_preview := public.learner_profile_merge_preview_for_actor(
    v_operation_id, v_provisional_account.id
  );
  if not coalesce((v_preview ->> 'canConfirm')::boolean, false) then
    raise exception 'learner_activation_merge_blocked' using errcode = '55000';
  end if;
  v_target_id := public.execute_learner_profile_merge_for_actor(
    v_operation_id, v_provisional_account.id,
    v_preview ->> 'previewFingerprint'
  );

  insert into public.learner_credential_recovery_delegate (
    subject_account_id, delegate_account_id, activation_invitation_id
  ) values (
    v_provisional_account.id, v_recipient_account_id, v_invitation.id
  ) on conflict (subject_account_id, delegate_account_id) do nothing
  returning * into v_recovery_delegate;
  v_recovery_delegate_created := found;
  if not v_recovery_delegate_created then
    select delegate.* into v_recovery_delegate
    from public.learner_credential_recovery_delegate as delegate
    where delegate.subject_account_id = v_provisional_account.id
      and delegate.delegate_account_id = v_recipient_account_id;
  end if;
  if v_recovery_delegate.id is null
    or v_recovery_delegate.status <> 'active'
  then
    raise exception 'learner_activation_recovery_delegate_unavailable'
      using errcode = '55000';
  end if;
  if v_recovery_delegate_created then
    perform public.append_learner_identity_audit(
      'learner_credential_recovery_delegate_granted',
      v_recipient_account_id, v_provisional_account.id,
      v_target_id, null, v_recovery_delegate.id,
      jsonb_build_object('projectionVersion', 1)
    );
  end if;

  if coalesce(p_request_observer_invitation, false) then
    v_observer_token_digest := extensions.digest(
      encode(p_token_digest, 'hex') || ':observer', 'sha256'
    );
    insert into public.learner_observer_invitation (
      learner_profile_id, subject_account_id, recipient_account_id,
      recipient_email_digest, token_digest, status, expires_at
    ) values (
      v_target_id, v_provisional_account.id, v_recipient_account_id,
      p_recipient_email_digest, v_observer_token_digest, 'bound',
      least(v_invitation.expires_at, now() + interval '14 days')
    ) returning id into v_observer_invitation_id;
  end if;

  perform public.append_learner_identity_audit(
    'offline_learner_account_activated', v_recipient_account_id,
    v_provisional_account.id, v_target_id, v_source_profile.id,
    v_invitation.id,
    jsonb_build_object(
      'observerInvitationRequested', coalesce(p_request_observer_invitation, false),
      'projectionVersion', 1
    )
  );
  return jsonb_build_object(
    'invitation', jsonb_build_object(
      'id', v_invitation.id, 'kind', v_invitation.kind,
      'status', 'accepted', 'learnerProfileId', v_target_id,
      'learnerLabel', v_source_profile.display_name,
      'inviterLabel', (select display_name from public.account where id = v_invitation.inviter_account_id),
      'expiresAt', v_invitation.expires_at, 'createdAt', v_invitation.created_at,
      'acceptedAt', now()
    ),
    'mergePreview', v_preview,
    'completed', true,
    'childAccountLogin', lower(btrim(p_learner_login)),
    'observerInvitationId', v_observer_invitation_id,
    'provisionalAuthUserConsumed', true,
    'recoveryDelegateId', v_recovery_delegate.id,
    'recoveryDelegateActive', true
  );
exception
  when unique_violation then
    raise exception 'learner_activation_login_unavailable' using errcode = '23505';
end
$_$;


--
-- Name: activate_verified_offline_learner_account(uuid, uuid, bytea, text, text, uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_verified_offline_learner_account(p_actor_auth_user_id uuid, p_invitation_id uuid, p_recipient_email_digest bytea, p_child_login text, p_raw_pin text, p_provisional_auth_user_id uuid, p_acknowledge_recovery_delegate boolean, p_request_observer_invitation boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_invitation public.learner_claim_invitation%rowtype;
  v_result jsonb;
begin
  if not coalesce(p_acknowledge_recovery_delegate, false) then
    raise exception 'learner_activation_recovery_acknowledgement_required'
      using errcode = '55000';
  end if;
  perform public.preview_verified_learner_profile_invitation(
    p_actor_auth_user_id, p_invitation_id, p_recipient_email_digest
  );
  select invitation.* into v_invitation
  from public.learner_claim_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.kind = 'child_activation'
    and invitation.recipient_account_id = v_actor_account_id
    and invitation.recipient_email_digest = p_recipient_email_digest
  for update of invitation;
  if not found then
    raise exception 'learner_activation_not_found' using errcode = 'P0002';
  end if;
  v_result := public.activate_offline_learner_account(
    p_actor_auth_user_id, p_invitation_id,
    v_invitation.token_digest, p_recipient_email_digest,
    p_child_login, p_raw_pin, p_provisional_auth_user_id,
    p_acknowledge_recovery_delegate, p_request_observer_invitation
  );
  return v_result;
end
$$;


--
-- Name: append_assistant_turn_admin(uuid, uuid, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_assistant_turn_admin(p_owner_account_id uuid, p_conversation_id uuid, p_body text, p_payload jsonb DEFAULT '{}'::jsonb, p_delivery_kind text DEFAULT 'interactive'::text, p_source_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.assistant_conversation%rowtype;
  v_existing public.assistant_turn%rowtype;
  v_turn public.assistant_turn%rowtype;
begin
  if p_owner_account_id is null
    or p_conversation_id is null
    or p_body is null
    or btrim(p_body) = ''
    or char_length(btrim(p_body)) > 6000
    or p_payload is null
    or jsonb_typeof(p_payload) <> 'object'
    or pg_column_size(p_payload) > 65536
    or p_delivery_kind not in (
      'interactive',
      'background_result',
      'insight'
    )
    or (
      p_source_key is not null
      and (
        btrim(p_source_key) = ''
        or char_length(p_source_key) > 240
      )
    )
  then
    raise exception 'assistant_turn_invalid' using errcode = '22023';
  end if;

  select conversation.*
  into v_conversation
  from public.assistant_conversation as conversation
  join public.account as owner_account
    on owner_account.id = conversation.owner_account_id
   and owner_account.status = 'active'
  where conversation.id = p_conversation_id
    and conversation.owner_account_id = p_owner_account_id
    and conversation.archived_at is null
  for update of conversation;

  if not found then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  if p_source_key is not null then
    select turn.*
    into v_existing
    from public.assistant_turn as turn
    where turn.conversation_id = p_conversation_id
      and turn.source_key = btrim(p_source_key);

    if found then
      if v_existing.role <> 'assistant'
        or v_existing.body <> btrim(p_body)
        or v_existing.payload <> p_payload
        or v_existing.delivery_kind <> p_delivery_kind
      then
        raise exception 'assistant_turn_idempotency_conflict'
          using errcode = '23505';
      end if;

      return public.assistant_turn_projection(v_existing.id);
    end if;
  end if;

  insert into public.assistant_turn (
    conversation_id,
    role,
    delivery_kind,
    body,
    payload,
    source_key
  )
  values (
    p_conversation_id,
    'assistant',
    p_delivery_kind,
    btrim(p_body),
    p_payload,
    case when p_source_key is null then null else btrim(p_source_key) end
  )
  returning * into v_turn;

  update public.assistant_conversation as conversation
  set last_turn_id = v_turn.id,
      last_assistant_turn_id = v_turn.id,
      last_turn_at = v_turn.created_at,
      updated_at = v_turn.created_at
  where conversation.id = p_conversation_id;

  return public.assistant_turn_projection(v_turn.id);
end
$$;


--
-- Name: append_learner_identity_audit(text, uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_learner_identity_audit(p_event_type text, p_actor_account_id uuid DEFAULT NULL::uuid, p_subject_account_id uuid DEFAULT NULL::uuid, p_learner_profile_id uuid DEFAULT NULL::uuid, p_related_learner_profile_id uuid DEFAULT NULL::uuid, p_related_entity_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id bigint;
begin
  insert into public.learner_identity_audit_event (
    event_type,
    actor_account_id,
    subject_account_id,
    learner_profile_id,
    related_learner_profile_id,
    related_entity_id,
    metadata
  ) values (
    p_event_type,
    p_actor_account_id,
    p_subject_account_id,
    p_learner_profile_id,
    p_related_learner_profile_id,
    p_related_entity_id,
    coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end
$$;


--
-- Name: append_my_assistant_turn(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_my_assistant_turn(p_conversation_id uuid, p_body text, p_client_turn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_conversation public.assistant_conversation%rowtype;
  v_existing public.assistant_turn%rowtype;
  v_turn public.assistant_turn%rowtype;
begin
  if v_actor_account_id is null
    or p_conversation_id is null
    or p_client_turn_id is null
    or p_body is null
    or btrim(p_body) = ''
    or char_length(btrim(p_body)) > 6000
  then
    raise exception 'assistant_turn_invalid' using errcode = '22023';
  end if;

  select conversation.*
  into v_conversation
  from public.assistant_conversation as conversation
  where conversation.id = p_conversation_id
    and conversation.owner_account_id = v_actor_account_id
    and conversation.archived_at is null
  for update;

  if not found then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  -- Context IDs are labels, never durable authority. Recheck ownership before
  -- accepting the next user turn; deleted contexts have already been nulled.
  if v_conversation.context_course_id is not null
    and not exists (
      select 1
      from public.course as course
      where course.id = v_conversation.context_course_id
        and course.owner_account_id = v_actor_account_id
        and course.archived_at is null
    )
  then
    raise exception 'assistant_context_not_found' using errcode = 'P0002';
  end if;

  if v_conversation.context_lesson_id is not null
    and not exists (
      select 1
      from public.lesson as lesson
      where lesson.id = v_conversation.context_lesson_id
        and lesson.course_id = v_conversation.context_course_id
    )
  then
    raise exception 'assistant_context_not_found' using errcode = 'P0002';
  end if;

  select turn.*
  into v_existing
  from public.assistant_turn as turn
  where turn.conversation_id = p_conversation_id
    and turn.client_turn_id = p_client_turn_id;

  if found then
    if v_existing.role <> 'user' or v_existing.body <> btrim(p_body) then
      raise exception 'assistant_turn_idempotency_conflict'
        using errcode = '23505';
    end if;

    return public.assistant_turn_projection(v_existing.id);
  end if;

  insert into public.assistant_turn (
    conversation_id,
    role,
    delivery_kind,
    body,
    payload,
    client_turn_id
  )
  values (
    p_conversation_id,
    'user',
    'interactive',
    btrim(p_body),
    '{}'::jsonb,
    p_client_turn_id
  )
  returning * into v_turn;

  update public.assistant_conversation as conversation
  set last_turn_id = v_turn.id,
      last_turn_at = v_turn.created_at,
      updated_at = v_turn.created_at
  where conversation.id = p_conversation_id;

  return public.assistant_turn_projection(v_turn.id);
end
$$;


--
-- Name: append_system_notification_admin(uuid, text, text, text, text, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_system_notification_admin(p_recipient_account_id uuid, p_event_type text, p_severity text, p_title text, p_body text, p_payload jsonb, p_dedupe_key text, p_occurred_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.system_notification%rowtype;
begin
  v_notification := public.append_system_notification_internal(
    p_recipient_account_id,
    p_event_type,
    p_severity,
    p_title,
    p_body,
    p_payload,
    p_dedupe_key,
    p_occurred_at
  );

  if v_notification.id is null then
    raise exception 'system_notification_recipient_not_found'
      using errcode = 'P0002';
  end if;

  return public.system_notification_projection(v_notification.id);
end
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: system_notification; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.system_notification (
    id bigint NOT NULL,
    recipient_account_id uuid NOT NULL,
    event_type text NOT NULL,
    severity text DEFAULT 'info'::text NOT NULL,
    title text NOT NULL,
    body text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    dedupe_key text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    read_at timestamp with time zone,
    CONSTRAINT system_notification_body_check CHECK (((btrim(body) <> ''::text) AND (char_length(body) <= 6000))),
    CONSTRAINT system_notification_dedupe_key_check CHECK (((btrim(dedupe_key) <> ''::text) AND (char_length(dedupe_key) <= 240))),
    CONSTRAINT system_notification_event_type_check CHECK ((event_type ~ '^[a-z][a-z0-9_.]{1,99}$'::text)),
    CONSTRAINT system_notification_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (pg_column_size(payload) <= 16384))),
    CONSTRAINT system_notification_read_at_check CHECK (((read_at IS NULL) OR (read_at >= occurred_at))),
    CONSTRAINT system_notification_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'success'::text, 'warning'::text, 'error'::text, 'action_required'::text]))),
    CONSTRAINT system_notification_title_check CHECK (((btrim(title) <> ''::text) AND (char_length(title) <= 160)))
);


--
-- Name: append_system_notification_internal(uuid, text, text, text, text, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_system_notification_internal(p_recipient_account_id uuid, p_event_type text, p_severity text, p_title text, p_body text, p_payload jsonb, p_dedupe_key text, p_occurred_at timestamp with time zone DEFAULT now()) RETURNS public.system_notification
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_notification public.system_notification%rowtype;
begin
  if p_recipient_account_id is null
    or p_event_type is null
    or p_event_type !~ '^[a-z][a-z0-9_.]{1,99}$'
    or p_severity not in (
      'info',
      'success',
      'warning',
      'error',
      'action_required'
    )
    or p_title is null
    or btrim(p_title) = ''
    or char_length(btrim(p_title)) > 160
    or p_body is null
    or btrim(p_body) = ''
    or char_length(btrim(p_body)) > 6000
    or p_payload is null
    or jsonb_typeof(p_payload) <> 'object'
    or pg_column_size(p_payload) > 16384
    or p_dedupe_key is null
    or btrim(p_dedupe_key) = ''
    or char_length(btrim(p_dedupe_key)) > 240
    or p_occurred_at is null
  then
    raise exception 'system_notification_invalid' using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.account as recipient
    where recipient.id = p_recipient_account_id
      and recipient.status = 'active'
  ) then
    return null;
  end if;

  insert into public.system_notification (
    recipient_account_id,
    event_type,
    severity,
    title,
    body,
    payload,
    dedupe_key,
    occurred_at
  )
  values (
    p_recipient_account_id,
    p_event_type,
    p_severity,
    btrim(p_title),
    btrim(p_body),
    p_payload,
    btrim(p_dedupe_key),
    p_occurred_at
  )
  on conflict (recipient_account_id, dedupe_key) do nothing
  returning * into v_notification;

  if not found then
    select notification.*
    into v_notification
    from public.system_notification as notification
    where notification.recipient_account_id = p_recipient_account_id
      and notification.dedupe_key = btrim(p_dedupe_key);

    if v_notification.event_type <> p_event_type
      or v_notification.severity <> p_severity
      or v_notification.title <> btrim(p_title)
      or v_notification.body <> btrim(p_body)
      or v_notification.payload <> p_payload
    then
      raise exception 'system_notification_idempotency_conflict'
        using errcode = '23505';
    end if;
  end if;

  return v_notification;
end
$_$;


--
-- Name: approve_educator_course_revision_admin(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_educator_course_revision_admin(p_publication_id uuid, p_revision_id uuid, p_reviewer_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_publication public.course_publication%rowtype;
  v_review public.educator_course_revision_review%rowtype;
  v_revision public.course_publication_revision%rowtype;
begin
  if p_publication_id is null or p_revision_id is null then
    raise exception 'educator_course_review_input_invalid'
      using errcode = '22023';
  end if;

  if p_reviewer_account_id is not null and not exists (
    select 1
    from public.account as account
    where account.id = p_reviewer_account_id
      and account.status = 'active'
  ) then
    raise exception 'educator_course_reviewer_not_active'
      using errcode = '42501';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  where publication.id = p_publication_id
    and publication.learning_audience = 'educators'
    and publication.is_shidao
  for update;

  if not found then
    raise exception 'educator_course_review_not_found'
      using errcode = 'P0002';
  end if;

  if v_publication.current_revision_id <> p_revision_id then
    raise exception 'educator_course_review_revision_stale'
      using errcode = '40001';
  end if;

  select review.*
  into v_review
  from public.educator_course_revision_review as review
  where review.publication_id = p_publication_id
    and review.revision_id = p_revision_id
  for update;

  if not found then
    raise exception 'educator_course_review_not_found'
      using errcode = 'P0002';
  end if;

  if v_review.status <> 'pending' then
    raise exception 'educator_course_review_not_pending'
      using errcode = '55000';
  end if;

  select revision.*
  into strict v_revision
  from public.course_publication_revision as revision
  join public.course_publication_attestation as attestation
    on attestation.publication_id = revision.publication_id
   and attestation.revision_id = revision.id
  where revision.publication_id = p_publication_id
    and revision.id = p_revision_id
    and revision.license_code = 'shidao_official_learning_v1'
  for share of revision, attestation;

  update public.educator_course_revision_review as review
  set status = 'approved',
      reviewed_by_account_id = p_reviewer_account_id,
      review_feedback = null,
      reviewed_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where review.revision_id = p_revision_id
    and review.status = 'pending'
  returning review.* into v_review;

  if not found then
    raise exception 'educator_course_review_not_pending'
      using errcode = '40001';
  end if;

  update public.course_publication as publication
  set approved_revision_id = p_revision_id,
      title = v_revision.snapshot -> 'course' ->> 'title',
      subject = v_revision.snapshot -> 'course' ->> 'subject',
      goal = v_revision.snapshot -> 'course' ->> 'goal',
      level = v_revision.snapshot -> 'course' ->> 'level',
      audience_description =
        v_revision.snapshot -> 'course' ->> 'audienceDescription',
      target_lesson_count = (
        v_revision.snapshot -> 'course' ->> 'targetLessonCount'
      )::integer,
      lesson_count = jsonb_array_length(v_revision.snapshot -> 'lessons'),
      material_count = jsonb_array_length(v_revision.snapshot -> 'materials'),
      status = 'published',
      unpublished_at = null,
      published_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where publication.id = p_publication_id
    and publication.current_revision_id = p_revision_id
  returning publication.* into v_publication;

  if not found then
    raise exception 'educator_course_review_revision_stale'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'publicationId', v_publication.id,
    'status', v_publication.status,
    'reviewStatus', v_review.status,
    'reviewRevisionId', v_review.revision_id,
    'approvedRevisionId', v_publication.approved_revision_id
  );
end
$$;


--
-- Name: archive_course(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_course(p_course_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_course_id uuid;
begin
  if v_actor_user_id is null or p_course_id is null then
    return 'not_found';
  end if;

  select course.id
  into v_course_id
  from public.course as course
  join public.account as account on account.id = course.owner_account_id
  where course.id = p_course_id
    and course.archived_at is null
    and account.auth_user_id = v_actor_user_id
    and account.status = 'active'
  for update of course;

  if not found then
    return 'not_found';
  end if;

  if exists (
    select 1
    from public.course_publication as publication
    where publication.source_course_id = v_course_id
      and publication.status = 'published'
  ) then
    return 'course_is_published';
  end if;

  if exists (
    select 1
    from public.lesson as lesson
    join public.lesson_run as run on run.lesson_id = lesson.id
    where lesson.course_id = v_course_id
      and run.ended_at is null
      and run.cancelled_at is null
  ) then
    return 'course_has_open_lesson_runs';
  end if;

  update public.course as course
  set archived_at = clock_timestamp()
  where course.id = v_course_id
    and course.archived_at is null;

  if not found then
    return 'not_found';
  end if;

  return 'archived';
end
$$;


--
-- Name: teacher_learner; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.teacher_learner (
    teacher_account_id uuid NOT NULL,
    learner_profile_id uuid NOT NULL,
    display_name text NOT NULL,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT teacher_learner_display_name_check CHECK (((btrim(display_name) <> ''::text) AND (char_length(display_name) <= 160)))
);


--
-- Name: archive_learner_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_learner_profile(p_learner_profile_id uuid) RETURNS public.teacher_learner
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile_id uuid := public.resolve_learner_profile_alias(p_learner_profile_id);
  v_relation public.teacher_learner%rowtype;
  v_was_archived boolean;
begin
  if v_actor_account_id is null or v_profile_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  -- Match the lock ordering used by audience mutation and merge: Account,
  -- profile, Courses, groups, then the teacher-local relation/link rows.
  perform 1 from public.account as account
  where account.id = v_actor_account_id
  for update of account;
  perform 1 from public.learner_profile as profile
  where profile.id = v_profile_id
  for update of profile;
  perform course.id
  from public.course as course
  where course.owner_account_id = v_actor_account_id
    and (
      exists (
        select 1 from public.course_learner as direct
        where direct.course_id = course.id
          and direct.learner_profile_id = v_profile_id
      )
      or exists (
        select 1
        from public.course_learner_group as course_group
        join public.learner_group_member as member
          on member.learner_group_id = course_group.learner_group_id
        where course_group.course_id = course.id
          and member.learner_profile_id = v_profile_id
      )
    )
  order by course.id
  for update of course;

  perform learner_group.id
  from public.learner_group as learner_group
  where learner_group.owner_account_id = v_actor_account_id
    and exists (
      select 1 from public.learner_group_member as member
      where member.learner_group_id = learner_group.id
        and member.learner_profile_id = v_profile_id
    )
  order by learner_group.id
  for update of learner_group;

  select relation.* into v_relation
  from public.teacher_learner as relation
  where relation.teacher_account_id = v_actor_account_id
    and relation.learner_profile_id = v_profile_id
  for update of relation;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  v_was_archived := v_relation.archived_at is not null;

  perform 1 from public.course_learner as direct
  where direct.learner_profile_id = v_profile_id
    and exists (
      select 1 from public.course as course
      where course.id = direct.course_id
        and course.owner_account_id = v_actor_account_id
    )
  order by direct.course_id, direct.learner_profile_id
  for update of direct;
  perform 1 from public.learner_group_member as member
  where member.learner_profile_id = v_profile_id
    and exists (
      select 1 from public.learner_group as learner_group
      where learner_group.id = member.learner_group_id
        and learner_group.owner_account_id = v_actor_account_id
    )
  order by member.learner_group_id, member.learner_profile_id
  for update of member;

  delete from public.course_learner as direct
  using public.course as course
  where course.id = direct.course_id
    and course.owner_account_id = v_actor_account_id
    and direct.learner_profile_id = v_profile_id;

  delete from public.learner_group_member as member
  using public.learner_group as learner_group
  where learner_group.id = member.learner_group_id
    and learner_group.owner_account_id = v_actor_account_id
    and member.learner_profile_id = v_profile_id;

  update public.teacher_learner as relation
  set archived_at = coalesce(relation.archived_at, now())
  where relation.teacher_account_id = v_actor_account_id
    and relation.learner_profile_id = v_profile_id
  returning relation.* into v_relation;

  if not v_was_archived then
    perform public.append_learner_identity_audit(
      'teacher_learner_archived', v_actor_account_id,
      (select profile.account_id from public.learner_profile as profile where profile.id = v_profile_id),
      v_profile_id, null, null,
      jsonb_build_object('projectionVersion', 1)
    );
  end if;

  return v_relation;
end
$$;


--
-- Name: learning_objective; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learning_objective (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    course_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learning_objective_description_check CHECK (((description IS NULL) OR ((btrim(description) <> ''::text) AND (char_length(btrim(description)) <= 2000)))),
    CONSTRAINT learning_objective_title_check CHECK (((char_length(btrim(title)) >= 2) AND (char_length(btrim(title)) <= 240)))
);


--
-- Name: archive_learning_objective(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_learning_objective(p_objective_id uuid) RETURNS SETOF public.learning_objective
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_course_id uuid;
  v_objective public.learning_objective%rowtype;
begin
  if v_actor_user_id is null or p_objective_id is null then
    raise exception 'learning_objective_invalid'
      using errcode = '22023';
  end if;

  select objective.course_id
  into v_course_id
  from public.learning_objective as objective
  join public.course as course on course.id = objective.course_id
  join public.account as account on account.id = course.owner_account_id
  where objective.id = p_objective_id
    and course.archived_at is null
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'learning_objective_not_found'
      using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = v_course_id
  for update of course;

  select objective.*
  into v_objective
  from public.learning_objective as objective
  where objective.id = p_objective_id
    and objective.course_id = v_course_id
  for update of objective;

  if not found then
    raise exception 'learning_objective_not_found'
      using errcode = 'P0002';
  end if;

  update public.learning_objective as objective
  set archived_at = coalesce(objective.archived_at, clock_timestamp())
  where objective.id = p_objective_id
  returning objective.* into v_objective;

  return next v_objective;
end
$$;


--
-- Name: assemble_course_draft(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assemble_course_draft(p_course_id uuid, p_lesson_title text, p_lesson_summary text, p_components jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_assembled_at timestamptz;
  v_lesson_id uuid;
  v_component_id uuid;
  v_component jsonb;
  v_position integer := 0;
  v_lesson_ids uuid[] := '{}'::uuid[];
  v_component_ids uuid[] := '{}'::uuid[];
begin
  if p_components is null or jsonb_typeof(p_components) <> 'array' then
    raise exception
      'course_components_must_be_array'
      using errcode = '22023';
  end if;

  select course.assembled_at
  into v_assembled_at
  from public.course
  where course.id = p_course_id
  for update;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  if v_assembled_at is not null then
    select coalesce(
      array_agg(lesson.id order by lesson.position),
      '{}'::uuid[]
    )
    into v_lesson_ids
    from public.lesson
    where lesson.course_id = p_course_id;

    select coalesce(
      array_agg(
        component.id
        order by lesson.position, component.position
      ),
      '{}'::uuid[]
    )
    into v_component_ids
    from public.lesson_component as component
    join public.lesson on lesson.id = component.lesson_id
    where lesson.course_id = p_course_id;

    return jsonb_build_object(
      'courseId', p_course_id,
      'lessonIds', to_jsonb(v_lesson_ids),
      'componentIds', to_jsonb(v_component_ids),
      'alreadyAssembled', true
    );
  end if;

  if exists (
    select 1
    from public.lesson
    where lesson.course_id = p_course_id
  ) then
    raise exception
      'course_contains_manual_content'
      using errcode = '23505';
  end if;

  insert into public.lesson (course_id, position, title, summary)
  values (p_course_id, 1, p_lesson_title, p_lesson_summary)
  returning id into v_lesson_id;

  for v_component in
    select component.value
    from jsonb_array_elements(p_components) as component(value)
  loop
    v_position := v_position + 1;

    insert into public.lesson_component (
      lesson_id,
      position,
      type_key,
      schema_version,
      payload,
      placement_config
    )
    values (
      v_lesson_id,
      v_position,
      v_component ->> 'typeKey',
      (v_component ->> 'schemaVersion')::integer,
      v_component -> 'payload',
      v_component -> 'placement'
    )
    returning id into v_component_id;

    v_component_ids := array_append(v_component_ids, v_component_id);
  end loop;

  update public.course
  set assembled_at = now()
  where id = p_course_id;

  return jsonb_build_object(
    'courseId', p_course_id,
    'lessonIds', jsonb_build_array(v_lesson_id),
    'componentIds', to_jsonb(v_component_ids),
    'alreadyAssembled', false
  );
end
$$;


--
-- Name: assert_course_publication_copy_eligible_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_course_publication_copy_eligible_admin(p_actor_account_id uuid, p_publication_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if p_actor_account_id is null or p_publication_id is null then
    raise exception 'course_publication_copy_eligibility_invalid'
      using errcode = '22023';
  end if;

  perform 1
  from public.account as actor_account
  where actor_account.id = p_actor_account_id
    and actor_account.status = 'active';

  if not found then
    raise exception 'course_publication_catalog_actor_not_active'
      using errcode = '42501';
  end if;

  perform 1
  from public.course_publication as publication
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id
  where publication.id = p_publication_id
    and publication.status = 'published'
    and owner_account.status = 'active';

  if not found then
    raise exception 'course_publication_not_published'
      using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.course_publication as publication
    where publication.id = p_publication_id
      and publication.learning_audience = 'educators'
  ) then
    raise exception 'educator_course_copy_forbidden'
      using errcode = '42501';
  end if;

  return jsonb_build_object('eligible', true);
end
$$;


--
-- Name: assert_learning_evidence_supersession_chain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_learning_evidence_supersession_chain() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.supersedes_evidence_id is not null
    and not exists (
      select 1
      from public.learning_evidence as prior
      where prior.id = new.supersedes_evidence_id
        and prior.superseded_by_evidence_id = new.id
        and prior.recorded_by_account_id = new.recorded_by_account_id
        and prior.learner_profile_id = new.learner_profile_id
        and prior.source_course_id_at_time = new.source_course_id_at_time
        and prior.source_learning_objective_id_at_time =
          new.source_learning_objective_id_at_time
    )
  then
    raise exception 'learning_evidence_supersession_inconsistent'
      using errcode = '23514';
  end if;

  if new.superseded_by_evidence_id is not null
    and not exists (
      select 1
      from public.learning_evidence as replacement
      where replacement.id = new.superseded_by_evidence_id
        and replacement.supersedes_evidence_id = new.id
        and replacement.recorded_by_account_id = new.recorded_by_account_id
        and replacement.learner_profile_id = new.learner_profile_id
        and replacement.source_course_id_at_time = new.source_course_id_at_time
        and replacement.source_learning_objective_id_at_time =
          new.source_learning_objective_id_at_time
    )
  then
    raise exception 'learning_evidence_supersession_inconsistent'
      using errcode = '23514';
  end if;

  return null;
end
$$;


--
-- Name: assistant_conversation_projection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_conversation_projection(p_conversation_id uuid, p_actor_account_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', conversation.id,
    'title', conversation.title,
    'contextCourseId', conversation.context_course_id,
    'contextLessonId', conversation.context_lesson_id,
    'lastTurnId', conversation.last_turn_id,
    'lastActivityAt', coalesce(
      conversation.last_turn_at,
      conversation.created_at
    ),
    'unreadCount', (
      select count(*)
      from public.assistant_turn as turn
      where turn.conversation_id = conversation.id
        and turn.role = 'assistant'
        and turn.id > conversation.last_read_assistant_turn_id
    ),
    'archivedAt', conversation.archived_at,
    'createdAt', conversation.created_at,
    'updatedAt', conversation.updated_at
  )
  from public.assistant_conversation as conversation
  where conversation.id = p_conversation_id
    and conversation.owner_account_id = p_actor_account_id;
$$;


--
-- Name: assistant_turn_projection(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_turn_projection(p_turn_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', turn.id,
    'role', turn.role,
    'deliveryKind', turn.delivery_kind,
    'body', turn.body,
    'payload', turn.payload,
    'createdAt', turn.created_at
  )
  from public.assistant_turn as turn
  where turn.id = p_turn_id;
$$;


--
-- Name: build_course_learning_activity_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_course_learning_activity_context(p_actor_auth_user_id uuid, p_course_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid :=
    public.account_id_for_auth_user(p_actor_auth_user_id);
  v_initial_profile_ids uuid[];
  v_profile_ids uuid[];
  v_initial_audience_boundary text;
  v_audience_boundary text;
  v_course_boundary text;
  v_generated_at timestamptz := clock_timestamp();
  v_profile_id uuid;
  v_projection jsonb;
  v_states jsonb := '[]'::jsonb;
  v_total_state_count integer := 0;
  v_included_state_count integer := 0;
  v_forming_count integer := 0;
  v_confirmed_count integer := 0;
  v_recheck_due_count integer := 0;
  v_evidence_reference_count integer := 0;
  v_revision text;
  v_summary jsonb;
  v_unused jsonb := jsonb_build_object(
    'used', false,
    'revision', repeat('0', 64),
    'projectionVersion', 1,
    'summary', jsonb_build_object(
      'totalStateCount', 0,
      'includedStateCount', 0,
      'formingCount', 0,
      'confirmedCount', 0,
      'recheckDueCount', 0,
      'evidenceReferenceCount', 0,
      'truncated', false
    ),
    'states', '[]'::jsonb
  );
begin
  if v_actor_account_id is null or not exists (
    select 1
    from public.course as course
    where course.id = p_course_id
      and course.owner_account_id = v_actor_account_id
      and course.archived_at is null
  ) then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  with effective_audience as (
    select direct.learner_profile_id
    from public.course_learner as direct
    where direct.course_id = p_course_id
    union
    select member.learner_profile_id
    from public.course_learner_group as course_group
    join public.learner_group_member as member
      on member.learner_group_id = course_group.learner_group_id
    where course_group.course_id = p_course_id
  )
  select
    array_agg(
      effective_audience.learner_profile_id
      order by effective_audience.learner_profile_id
    ),
    string_agg(
      effective_audience.learner_profile_id::text,
      ',' order by effective_audience.learner_profile_id
    )
  into v_initial_profile_ids, v_initial_audience_boundary
  from effective_audience
  join public.learner_profile as profile
    on profile.id = effective_audience.learner_profile_id;

  if coalesce(cardinality(v_initial_profile_ids), 0) = 0 then
    return v_unused;
  end if;

  perform public.lock_learning_activity_learners(v_initial_profile_ids);
  select
    course.id::text || ':' || course.owner_account_id::text || ':'
      || course.updated_at::text
  into v_course_boundary
  from public.course as course
  where course.id = p_course_id
    and course.owner_account_id = v_actor_account_id
    and course.archived_at is null
  for update of course;
  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  perform direct.learner_profile_id
  from public.course_learner as direct
  where direct.course_id = p_course_id
  order by direct.learner_profile_id
  for share of direct;
  perform course_group.learner_group_id
  from public.course_learner_group as course_group
  where course_group.course_id = p_course_id
  order by course_group.learner_group_id
  for share of course_group;
  perform member.learner_profile_id
  from public.course_learner_group as course_group
  join public.learner_group_member as member
    on member.learner_group_id = course_group.learner_group_id
  where course_group.course_id = p_course_id
  order by member.learner_group_id, member.learner_profile_id
  for share of member;
  perform profile.id
  from public.learner_profile as profile
  where profile.id = any(v_initial_profile_ids)
  order by profile.id
  for update of profile;

  with effective_audience as (
    select direct.learner_profile_id
    from public.course_learner as direct
    where direct.course_id = p_course_id
    union
    select member.learner_profile_id
    from public.course_learner_group as course_group
    join public.learner_group_member as member
      on member.learner_group_id = course_group.learner_group_id
    where course_group.course_id = p_course_id
  )
  select
    array_agg(
      effective_audience.learner_profile_id
      order by effective_audience.learner_profile_id
    ),
    string_agg(
      effective_audience.learner_profile_id::text,
      ',' order by effective_audience.learner_profile_id
    )
  into v_profile_ids, v_audience_boundary
  from effective_audience
  join public.learner_profile as profile
    on profile.id = effective_audience.learner_profile_id;

  if v_profile_ids is distinct from v_initial_profile_ids
    or v_audience_boundary is distinct from v_initial_audience_boundary
  then
    raise exception 'learning_activity_context_changed'
      using errcode = '40001';
  end if;

  foreach v_profile_id in array v_profile_ids
  loop
    perform public.refresh_learning_activity_states_for_profile(
      v_profile_id,
      v_actor_account_id,
      v_generated_at
    );
  end loop;

  v_projection := public.course_learning_activity_projection(
    v_profile_ids,
    v_actor_account_id,
    p_course_id,
    v_generated_at
  );
  v_states := coalesce(v_projection -> 'states', '[]'::jsonb);
  v_total_state_count := coalesce(
    (v_projection ->> 'totalStateCount')::integer,
    0
  );
  v_included_state_count := jsonb_array_length(v_states);

  if v_included_state_count = 0 then
    return v_unused;
  end if;

  select
    count(*) filter (where item.value ->> 'state' = 'forming')::integer,
    count(*) filter (where item.value ->> 'state' = 'confirmed')::integer,
    count(*) filter (where item.value ->> 'state' = 'recheck_due')::integer,
    coalesce(sum(jsonb_array_length(
      item.value -> 'evidenceReferences'
    )), 0)::integer
  into
    v_forming_count,
    v_confirmed_count,
    v_recheck_due_count,
    v_evidence_reference_count
  from jsonb_array_elements(v_states) as item(value);

  v_revision := encode(
    extensions.digest(
      coalesce(v_course_boundary, '') || ':'
        || coalesce(v_audience_boundary, '') || ':'
        || v_total_state_count::text || ':' || v_states::text,
      'sha256'
    ),
    'hex'
  );
  v_summary := jsonb_build_object(
    'totalStateCount', v_total_state_count,
    'includedStateCount', v_included_state_count,
    'formingCount', v_forming_count,
    'confirmedCount', v_confirmed_count,
    'recheckDueCount', v_recheck_due_count,
    'evidenceReferenceCount', v_evidence_reference_count,
    'truncated', v_total_state_count > v_included_state_count
  );

  perform public.append_learner_identity_audit(
    'course_learning_activity_context_used',
    v_actor_account_id,
    null,
    null,
    null,
    p_course_id,
    jsonb_build_object(
      'effectiveAudienceCount', cardinality(v_profile_ids),
      'includedStateCount', v_included_state_count,
      'evidenceReferenceCount', v_evidence_reference_count,
      'projectionVersion', 1,
      'revision', v_revision
    )
  );

  return jsonb_build_object(
    'used', true,
    'revision', v_revision,
    'projectionVersion', 1,
    'summary', v_summary,
    'states', v_states
  );
end
$$;


--
-- Name: build_course_publication_progress_admin(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_course_publication_progress_admin(p_account_id uuid, p_publication_id uuid, p_revision_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with revision_lessons as (
    select
      (lesson.value ->> 'ref')::uuid as lesson_ref,
      lesson.position
    from public.course_publication_revision as revision
    cross join lateral jsonb_array_elements(revision.snapshot -> 'lessons')
      with ordinality as lesson(value, position)
    where revision.publication_id = p_publication_id
      and revision.id = p_revision_id
  ),
  completed as (
    select lesson.lesson_ref, lesson.position
    from revision_lessons as lesson
    join public.course_publication_lesson_completion as completion
      on completion.account_id = p_account_id
     and completion.publication_id = p_publication_id
     and completion.revision_id = p_revision_id
     and completion.lesson_ref = lesson.lesson_ref
  ),
  counts as (
    select
      (select count(*)::integer from revision_lessons) as total_count,
      (select count(*)::integer from completed) as completed_count
  )
  select jsonb_build_object(
    'publicationId', p_publication_id,
    'revisionId', p_revision_id,
    'lastOpenedLessonRef', enrollment.last_opened_lesson_ref,
    'completedLessonRefs', coalesce((
      select jsonb_agg(completed.lesson_ref order by completed.position)
      from completed
    ), '[]'::jsonb),
    'completedLessonCount', counts.completed_count,
    'totalLessonCount', counts.total_count,
    'percent', case
      when counts.total_count = 0 then 0
      else floor(
        counts.completed_count::numeric * 100 / counts.total_count
      )::integer
    end,
    'complete', counts.total_count > 0
      and counts.completed_count = counts.total_count
  )
  from counts
  left join public.course_publication_self_enrollment as enrollment
    on enrollment.account_id = p_account_id
   and enrollment.publication_id = p_publication_id
   and enrollment.revision_id = p_revision_id;
$$;


--
-- Name: build_cross_provider_learner_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_cross_provider_learner_context(p_actor_auth_user_id uuid, p_course_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_grant_count integer;
  v_revision text;
  v_aggregates jsonb;
  v_comments jsonb;
begin
  if v_actor_account_id is null or not exists (
    select 1 from public.course as course
    where course.id = p_course_id
      and course.owner_account_id = v_actor_account_id
  ) then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  with valid_consents as (
    select consent.*
    from public.learner_ai_consent as consent
    join public.course as course on course.id = consent.course_id
    where consent.course_id = p_course_id
      and consent.owner_account_id = v_actor_account_id
      and course.owner_account_id = consent.owner_account_id
      and consent.status = 'active'
      and consent.expires_at > now()
      and public.course_has_effective_learner(
        consent.course_id, consent.learner_profile_id
      )
  )
  select
    count(*)::integer,
    coalesce(encode(extensions.digest(
      string_agg(id::text || ':' || revision::text || ':' || expires_at::text, ',' order by id),
      'sha256'
    ), 'hex'), repeat('0', 64))
  into v_grant_count, v_revision
  from valid_consents;

  if v_grant_count = 0 then
    return jsonb_build_object(
      'used', false,
      'revision', repeat('0', 64),
      'projectionVersion', 1,
      'aggregates', jsonb_build_object(
        'conductedCount', 0,
        'presentCount', 0,
        'absentCount', 0,
        'repeatCount', 0,
        'knownDurationCount', 0,
        'actualDurationMinutes', 0,
        'subjectBreakdown', '[]'::jsonb
      ),
      'sharedCommentSummaries', '[]'::jsonb
    );
  end if;

  with valid_profiles as (
    select consent.learner_profile_id
    from public.learner_ai_consent as consent
    join public.course as course on course.id = consent.course_id
    where consent.course_id = p_course_id
      and consent.owner_account_id = v_actor_account_id
      and course.owner_account_id = consent.owner_account_id
      and consent.status = 'active' and consent.expires_at > now()
      and public.course_has_effective_learner(consent.course_id, consent.learner_profile_id)
  ), records as (
    select record.*,
      case
        when lower(coalesce(record.subject_at_time, '')) ~ '(матем|алгеб|геомет)' then 'Математика'
        when lower(coalesce(record.subject_at_time, '')) ~ '(русс|литерат|язык)' then 'Язык и литература'
        when lower(coalesce(record.subject_at_time, '')) ~ '(физик|хим|биол|естеств)' then 'Естественные науки'
        when lower(coalesce(record.subject_at_time, '')) ~ '(истор|обществ|геогр)' then 'Общественные науки'
        when lower(coalesce(record.subject_at_time, '')) ~ '(информ|програм)' then 'Технологии'
        when lower(coalesce(record.subject_at_time, '')) ~ '(музык|искус|рисов)' then 'Искусство'
        else 'Другое'
      end as subject_bucket
    from public.learning_record as record
    join valid_profiles on valid_profiles.learner_profile_id = record.learner_profile_id
    where record.occurred_at is not null
      and record.superseded_by_record_id is null
  ), subject_counts as (
    select subject_bucket, least(count(*), 10000)::integer as count
    from records group by subject_bucket
  )
  select jsonb_strip_nulls(jsonb_build_object(
    'conductedCount', least(count(*), 10000)::integer,
    'presentCount', least(count(*) filter (where was_present), 10000)::integer,
    'absentCount', least(count(*) filter (where not was_present), 10000)::integer,
    'repeatCount', least(count(*) filter (where needs_repeat is true), 10000)::integer,
    'knownDurationCount', least(count(actual_duration_minutes_at_time)
      filter (where was_present), 10000)::integer,
    'actualDurationMinutes', coalesce(
      least(
        sum(actual_duration_minutes_at_time) filter (where was_present),
        10000000
      ), 0
    )::integer,
    'lastActivityMonth', to_char(date_trunc('month', max(occurred_at)), 'YYYY-MM'),
    'subjectBreakdown', coalesce((select jsonb_agg(jsonb_build_object(
      'subjectBucket', subject_bucket, 'count', count
    ) order by subject_bucket) from subject_counts), '[]'::jsonb)
  )) into v_aggregates
  from records;

  with valid_profiles as (
    select consent.learner_profile_id
    from public.learner_ai_consent as consent
    join public.course as course on course.id = consent.course_id
    where consent.course_id = p_course_id
      and consent.owner_account_id = v_actor_account_id
      and course.owner_account_id = consent.owner_account_id
      and consent.status = 'active' and consent.expires_at > now()
      and public.course_has_effective_learner(consent.course_id, consent.learner_profile_id)
  ), safe_comment_categories as (
    -- Never quote or truncate the source comment. Even aggressive regex PII
    -- replacement leaves names, addresses, institutions and novel contacts.
    -- The cross-provider boundary emits one deterministic value from this
    -- closed vocabulary, with a non-informative fallback.
    select distinct case
      when lower(record.teacher_comment)
        ~ '(сложн|трудн|затруд|ошиб|не понима|поддержк)'
        then 'Требуется дополнительная учебная поддержка.'
      when lower(record.teacher_comment)
        ~ '(повтор|закреп|практик|тренир|упражнен)'
        then 'Рекомендовано повторение и дополнительная практика.'
      when lower(record.teacher_comment)
        ~ '(прогресс|улучш|успех|справил|верно|хорош)'
        then 'Отмечена положительная учебная динамика.'
      when lower(record.teacher_comment)
        ~ '(вниман|сосредоточ|концентрац)'
        then 'Отмечены особенности внимания и концентрации.'
      when lower(record.teacher_comment)
        ~ '(актив|участв|вовлеч|отвечал|инициатив)'
        then 'Отмечено активное участие в занятиях.'
      when lower(record.teacher_comment)
        ~ '(темп|медлен|быстр)'
        then 'Отмечен индивидуальный темп учебной работы.'
      else 'Есть опубликованное наблюдение преподавателя.'
    end as summary
    from public.learning_record as record
    join valid_profiles on valid_profiles.learner_profile_id = record.learner_profile_id
    where record.occurred_at is not null
      and record.superseded_by_record_id is null
      and record.shared_with_learner_at is not null
      and record.teacher_comment is not null
    order by summary
    limit 20
  )
  select coalesce(jsonb_agg(summary order by summary), '[]'::jsonb)
  into v_comments from safe_comment_categories;

  perform public.append_learner_identity_audit(
    'learner_ai_cross_provider_context_used', v_actor_account_id,
    null, null, null, p_course_id,
    jsonb_build_object(
      'grantCount', v_grant_count,
      'projectionVersion', 1,
      'revision', v_revision
    )
  );
  return jsonb_build_object(
    'used', true,
    'revision', v_revision,
    'projectionVersion', 1,
    'aggregates', v_aggregates,
    'sharedCommentSummaries', v_comments
  );
end
$$;


--
-- Name: cancel_learner_profile_merge(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_learner_profile_merge(p_merge_operation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_operation public.learner_profile_merge%rowtype;
begin
  select operation.* into v_operation
  from public.learner_profile_merge as operation
  where operation.id = p_merge_operation_id
    and operation.subject_account_id = v_actor_account_id
  for update of operation;
  if not found then
    raise exception 'learner_profile_merge_not_found' using errcode = 'P0002';
  end if;
  if v_operation.status = 'cancelled' then return; end if;
  if v_operation.status not in ('pending', 'ready') then
    raise exception 'learner_profile_merge_not_available' using errcode = '55000';
  end if;
  update public.learner_profile_merge as operation
  set status = 'cancelled', cancelled_at = now()
  where operation.id = p_merge_operation_id
    and operation.status in ('pending', 'ready');
  update public.learner_claim_invitation
  set status = 'rejected', rejected_at = now()
  where id = v_operation.invitation_id
    and status in ('pending', 'bound');
  perform public.append_learner_identity_audit(
    'learner_profile_merge_cancelled', v_actor_account_id,
    v_actor_account_id, null, null, p_merge_operation_id, '{}'::jsonb
  );
end
$$;


--
-- Name: lesson_run; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lesson_run (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lesson_id uuid NOT NULL,
    scheduled_at timestamp with time zone NOT NULL,
    planned_duration_minutes integer NOT NULL,
    started_at timestamp with time zone,
    ended_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    teacher_report text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    actual_duration_minutes integer,
    started_at_is_actual boolean DEFAULT false NOT NULL,
    CONSTRAINT lesson_run_actual_duration_minutes_check CHECK (((actual_duration_minutes IS NULL) OR ((actual_duration_minutes >= 1) AND (actual_duration_minutes <= 720)))),
    CONSTRAINT lesson_run_actual_start_shape_check CHECK (((NOT started_at_is_actual) OR (started_at IS NOT NULL))),
    CONSTRAINT lesson_run_cancellation_time_check CHECK (((cancelled_at IS NULL) OR (started_at IS NULL) OR (cancelled_at >= started_at))),
    CONSTRAINT lesson_run_closed_once_check CHECK (((ended_at IS NULL) OR (cancelled_at IS NULL))),
    CONSTRAINT lesson_run_completion_time_check CHECK (((ended_at IS NULL) OR (started_at IS NULL) OR (ended_at >= started_at))),
    CONSTRAINT lesson_run_planned_duration_minutes_check CHECK (((planned_duration_minutes >= 5) AND (planned_duration_minutes <= 480))),
    CONSTRAINT lesson_run_teacher_report_check CHECK (((teacher_report IS NULL) OR ((ended_at IS NOT NULL) AND (btrim(teacher_report) <> ''::text) AND (char_length(teacher_report) <= 4000))))
);


--
-- Name: cancel_lesson_run(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_lesson_run(p_lesson_run_id uuid, p_cancelled_at timestamp with time zone DEFAULT now()) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_run public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  if p_cancelled_at is null then
    raise exception
      'lesson_run_cancelled_at_required'
      using errcode = '22023';
  end if;

  select run.lesson_id
  into v_lesson_id
  from public.lesson_run as run
  join public.lesson as lesson on lesson.id = run.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where run.id = p_lesson_run_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.id = p_lesson_run_id
    and run.lesson_id = v_lesson_id
  for update of run;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  if v_run.cancelled_at is not null then
    return v_run;
  end if;

  if v_run.ended_at is not null then
    raise exception
      'lesson_run_already_completed'
      using errcode = '55000';
  end if;

  if v_run.started_at is not null
    and p_cancelled_at < v_run.started_at
  then
    raise exception
      'lesson_run_cancelled_before_start'
      using errcode = '22007';
  end if;

  perform 1
  from public.learning_record as record
  where record.lesson_run_id = p_lesson_run_id
  order by record.id
  for update;

  if exists (
    select 1
    from public.learning_record as record
    where record.lesson_run_id = p_lesson_run_id
      and record.occurred_at is not null
  ) then
    raise exception
      'lesson_run_contains_finalized_records'
      using errcode = '55000';
  end if;

  delete from public.learning_record as record
  where record.lesson_run_id = p_lesson_run_id
    and record.occurred_at is null;

  update public.lesson_run as run
  set cancelled_at = p_cancelled_at
  where run.id = p_lesson_run_id
  returning run.* into v_run;

  return v_run;
end
$$;


--
-- Name: capture_erasure_learning_activity_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_erasure_learning_activity_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_lineage_ids uuid[];
begin
  if new.preview_fingerprint is null then
    new.learning_activity_scope_fingerprint := null;
  else
    select array_agg(lineage.id order by lineage.id)
    into v_lineage_ids
    from (
      select new.current_learner_profile_id as id
      union
      select alias.source_learner_profile_id
      from public.learner_profile_alias as alias
      where alias.target_learner_profile_id =
        new.current_learner_profile_id
    ) as lineage;
    new.learning_activity_scope_fingerprint :=
      public.learning_activity_scope_fingerprint(v_lineage_ids);
  end if;
  return new;
end
$$;


--
-- Name: capture_learning_record_source_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_learning_record_source_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.source_course_id_at_time := coalesce(
      new.source_course_id_at_time,
      new.source_course_id
    );
    new.source_lesson_id_at_time := coalesce(
      new.source_lesson_id_at_time,
      new.source_lesson_id
    );
    new.source_lesson_run_id_at_time := coalesce(
      new.source_lesson_run_id_at_time,
      new.lesson_run_id
    );
  else
    if new.source_course_id_at_time is distinct from
      old.source_course_id_at_time
    then
      raise exception 'learning_record_source_identity_immutable'
        using errcode = '55000';
    end if;
    if new.source_lesson_id_at_time is distinct from
      old.source_lesson_id_at_time
    then
      raise exception 'learning_record_source_identity_immutable'
        using errcode = '55000';
    end if;
    if new.source_lesson_run_id_at_time is distinct from
      old.source_lesson_run_id_at_time
    then
      raise exception 'learning_record_source_identity_immutable'
        using errcode = '55000';
    end if;
  end if;
  return new;
end
$$;


--
-- Name: capture_merge_learning_activity_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_merge_learning_activity_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.preview_fingerprint is null then
    new.learning_activity_scope_fingerprint := null;
  else
    new.learning_activity_scope_fingerprint :=
      public.learning_activity_scope_fingerprint(array[
        new.source_learner_profile_id,
        new.target_learner_profile_id
      ]);
  end if;
  return new;
end
$$;


--
-- Name: capture_observation_component_visibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_observation_component_visibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_visibility text;
begin
  if tg_op = 'INSERT'
    and new.corrected_from_observation_id is not null
  then
    return new;
  end if;

  if new.lesson_component_id is null then
    if tg_op = 'UPDATE' then
      new.component_visibility_at_time := old.component_visibility_at_time;
    end if;
    return new;
  end if;

  select component.visibility
  into v_visibility
  from public.lesson_component as component
  where component.id = new.lesson_component_id;

  if not found or v_visibility not in ('learner_visible', 'staff_only') then
    raise exception 'lesson_component_observation_visibility_invalid'
      using errcode = '55000';
  end if;

  new.component_visibility_at_time := v_visibility;
  return new;
end
$$;


--
-- Name: cleanup_empty_lesson_student_slide(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_empty_lesson_student_slide() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.student_slide_id is null
    or not exists (
      select 1 from public.lesson where lesson.id = old.lesson_id
    )
  then
    return old;
  end if;

  delete from public.lesson_student_slide as slide
  where slide.id = old.student_slide_id
    and slide.lesson_id = old.lesson_id
    and not exists (
      select 1
      from public.lesson_component as component
      where component.student_slide_id = slide.id
        and component.visibility = 'learner_visible'
    );

  if found then
    with ordered as (
      select
        slide.id,
        row_number() over (order by slide.position, slide.id)::integer
          as new_position
      from public.lesson_student_slide as slide
      where slide.lesson_id = old.lesson_id
    )
    update public.lesson_student_slide as slide
    set position = ordered.new_position
    from ordered
    where slide.id = ordered.id
      and slide.position <> ordered.new_position;
  end if;

  return old;
end
$$;


--
-- Name: cleanup_empty_provisional_profile_on_account_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_empty_provisional_profile_on_account_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid;
begin
  if old.status <> 'provisional' then
    return old;
  end if;

  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = old.id
  for update of profile;

  if v_profile_id is null
    or exists (select 1 from public.learning_record where learner_profile_id = v_profile_id)
    or exists (select 1 from public.teacher_learner where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_group_member where learner_profile_id = v_profile_id)
    or exists (select 1 from public.course_learner where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_profile_share_code where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_connection_request where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_claim_invitation where source_learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_profile_merge where source_learner_profile_id = v_profile_id or target_learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_profile_alias where source_learner_profile_id = v_profile_id or target_learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_observer_invitation where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_observer_grant where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_ai_consent where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_credential_recovery_delegate
      where subject_account_id = old.id or delegate_account_id = old.id)
    or exists (select 1 from public.learner_identity_reconciliation
      where learner_profile_id = v_profile_id)
  then
    return old;
  end if;

  perform set_config('app.learner_profile_link_mutation', 'on', true);
  delete from public.learner_profile where id = v_profile_id;
  return old;
end
$$;


--
-- Name: clone_course_publication_admin(uuid, uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_course_publication_admin(p_actor_account_id uuid, p_publication_id uuid, p_target_course_id uuid, p_target_title text, p_id_map jsonb, p_asset_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_publication public.course_publication%rowtype;
  v_revision public.course_publication_revision%rowtype;
  v_catalog_owner_account_id uuid;
  v_lesson_count integer;
  v_component_count integer;
  v_slide_count integer;
  v_objective_count integer;
  v_asset_count integer;
  v_asset_total_bytes bigint;
  v_asset_id_map jsonb;
  v_snapshot_version integer;
  v_objective_created_at timestamptz;
begin
  if p_actor_account_id is null
    or p_publication_id is null
    or p_target_course_id is null
    or (
      p_target_title is not null
      and (
        btrim(p_target_title) = ''
        or char_length(btrim(p_target_title)) > 160
      )
    )
    or p_id_map is null
    or jsonb_typeof(p_id_map) <> 'object'
    or p_asset_manifest is null
    or jsonb_typeof(p_asset_manifest) <> 'array'
  then
    raise exception 'course_publication_clone_invalid'
      using errcode = '22023';
  end if;

  select publication.owner_account_id
  into v_catalog_owner_account_id
  from public.course_publication as publication
  where publication.id = p_publication_id;

  if not found then
    raise exception 'course_publication_not_published'
      using errcode = 'P0002';
  end if;

  -- Lock actor and catalog owner in one deterministic order. Account status
  -- transitions therefore serialize with cloning without cross-owner deadlocks.
  perform 1
  from public.account as account
  where account.id in (p_actor_account_id, v_catalog_owner_account_id)
  order by account.id
  for share;

  perform 1
  from public.account as account
  where account.id = p_actor_account_id
    and account.status = 'active';

  if not found then
    raise exception 'course_publication_clone_actor_not_active'
      using errcode = '42501';
  end if;

  perform 1
  from public.account as account
  where account.id = v_catalog_owner_account_id
    and account.status = 'active';

  if not found then
    raise exception 'course_publication_not_published'
      using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.course as course
    where course.id = p_target_course_id
  ) then
    raise exception 'course_publication_clone_course_id_conflict'
      using errcode = '23505';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  where publication.id = p_publication_id
    and publication.status = 'published'
    and publication.owner_account_id = v_catalog_owner_account_id
  for share;

  if not found then
    raise exception 'course_publication_not_published'
      using errcode = 'P0002';
  end if;

  select revision.*
  into strict v_revision
  from public.course_publication_revision as revision
  where revision.publication_id = v_publication.id
    and revision.id = v_publication.current_revision_id
  for share;

  v_snapshot_version := (v_revision.snapshot ->> 'schemaVersion')::integer;
  if not (p_id_map ? 'objectives') then
    p_id_map := p_id_map || jsonb_build_object('objectives', '[]'::jsonb);
  end if;

  if (p_id_map - array[
      'objectives', 'lessons', 'components', 'slides'
    ]) <> '{}'::jsonb
    or jsonb_typeof(p_id_map -> 'objectives') <> 'array'
    or jsonb_typeof(p_id_map -> 'lessons') <> 'array'
    or jsonb_typeof(p_id_map -> 'components') <> 'array'
    or jsonb_typeof(p_id_map -> 'slides') <> 'array'
  then
    raise exception 'course_publication_clone_id_map_shape_invalid'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'components') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) then
    raise exception 'course_publication_clone_id_map_shape_invalid'
      using errcode = '22023';
  end if;

  v_objective_count := case
    when v_snapshot_version = 2
      then jsonb_array_length(v_revision.snapshot -> 'objectives')
    else 0
  end;
  v_lesson_count := jsonb_array_length(v_revision.snapshot -> 'lessons');

  select count(*)::integer
  into v_component_count
  from jsonb_array_elements(v_revision.snapshot -> 'lessons') as lesson(value)
  cross join lateral jsonb_array_elements(
    lesson.value -> 'components'
  ) as component(value);

  select count(*)::integer
  into v_slide_count
  from jsonb_array_elements(v_revision.snapshot -> 'lessons') as lesson(value)
  cross join lateral jsonb_array_elements(
    lesson.value -> 'slides'
  ) as slide(value);

  if jsonb_array_length(p_id_map -> 'objectives') <> v_objective_count
    or jsonb_array_length(p_id_map -> 'lessons') <> v_lesson_count
    or jsonb_array_length(p_id_map -> 'components') <> v_component_count
    or jsonb_array_length(p_id_map -> 'slides') <> v_slide_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    ) <> v_objective_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    ) <> v_objective_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    ) <> v_lesson_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    ) <> v_lesson_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'components') as item(value)
    ) <> v_component_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'components') as item(value)
    ) <> v_component_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    ) <> v_slide_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    ) <> v_slide_count
  then
    raise exception 'course_publication_clone_id_map_not_exact'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(
      case
        when v_snapshot_version = 2
          then v_revision.snapshot -> 'objectives'
        else '[]'::jsonb
      end
    ) as objective(value)
    where not exists (
      select 1
      from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
      where item.value ->> 'ref' = objective.value ->> 'ref'
    )
  ) or exists (
    select 1
    from jsonb_array_elements(v_revision.snapshot -> 'lessons') as lesson(value)
    where not exists (
      select 1
      from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
      where item.value ->> 'ref' = lesson.value ->> 'ref'
    )
  ) or exists (
    select 1
    from jsonb_array_elements(v_revision.snapshot -> 'lessons') as lesson(value)
    cross join lateral jsonb_array_elements(
      lesson.value -> 'components'
    ) as component(value)
    where not exists (
      select 1
      from jsonb_array_elements(p_id_map -> 'components') as item(value)
      where item.value ->> 'ref' = component.value ->> 'ref'
    )
  ) or exists (
    select 1
    from jsonb_array_elements(v_revision.snapshot -> 'lessons') as lesson(value)
    cross join lateral jsonb_array_elements(
      lesson.value -> 'slides'
    ) as slide(value)
    where not exists (
      select 1
      from jsonb_array_elements(p_id_map -> 'slides') as item(value)
      where item.value ->> 'ref' = slide.value ->> 'ref'
    )
  ) then
    raise exception 'course_publication_clone_id_map_not_exact'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    join public.learning_objective as objective
      on objective.id = (item.value ->> 'id')::uuid
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    join public.lesson as lesson
      on lesson.id = (item.value ->> 'id')::uuid
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'components') as item(value)
    join public.lesson_component as component
      on component.id = (item.value ->> 'id')::uuid
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    join public.lesson_student_slide as slide
      on slide.id = (item.value ->> 'id')::uuid
  ) then
    raise exception 'course_publication_clone_target_id_conflict'
      using errcode = '23505';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_asset_manifest) as asset(value)
    where jsonb_typeof(asset.value) <> 'object'
      or (asset.value - array[
        'publicationAssetId',
        'targetStoredFileId',
        'originalFilename',
        'mimeType',
        'sizeBytes',
        'checksumSha256',
        'storageBucket',
        'storagePath'
      ]) <> '{}'::jsonb
      or not (asset.value ?& array[
        'publicationAssetId',
        'targetStoredFileId',
        'originalFilename',
        'mimeType',
        'sizeBytes',
        'checksumSha256',
        'storageBucket',
        'storagePath'
      ])
  ) then
    raise exception 'course_publication_clone_asset_manifest_shape_invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer, coalesce(sum(asset.size_bytes), 0)
  into v_asset_count, v_asset_total_bytes
  from public.course_publication_asset as asset
  where asset.revision_id = v_revision.id;

  if v_asset_count > 24
    or v_asset_total_bytes > 125829120
    or jsonb_array_length(p_asset_manifest) <> v_asset_count
    or (
      select count(distinct asset."publicationAssetId")
      from jsonb_to_recordset(p_asset_manifest) as asset(
        "publicationAssetId" uuid,
        "targetStoredFileId" uuid
      )
    ) <> v_asset_count
    or (
      select count(distinct asset."targetStoredFileId")
      from jsonb_to_recordset(p_asset_manifest) as asset(
        "publicationAssetId" uuid,
        "targetStoredFileId" uuid
      )
    ) <> v_asset_count
  then
    raise exception 'course_publication_clone_asset_manifest_not_exact'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_asset_manifest) as submitted(
      "publicationAssetId" uuid,
      "targetStoredFileId" uuid,
      "originalFilename" text,
      "mimeType" text,
      "sizeBytes" bigint,
      "checksumSha256" text,
      "storageBucket" text,
      "storagePath" text
    )
    left join public.course_publication_asset as asset
      on asset.revision_id = v_revision.id
      and asset.id = submitted."publicationAssetId"
    left join public.stored_file as existing_file
      on existing_file.id = submitted."targetStoredFileId"
    where asset.id is null
      or existing_file.id is not null
      or submitted."originalFilename" is distinct from asset.original_filename
      or submitted."mimeType" is distinct from asset.mime_type
      or submitted."sizeBytes" is distinct from asset.size_bytes
      or submitted."checksumSha256" is distinct from asset.checksum_sha256
      or submitted."storageBucket" <> 'course-assets'
      or public.course_publication_asset_extension(submitted."mimeType") is null
      or submitted."storagePath" <> concat(
        p_actor_account_id::text,
        '/courses/',
        p_target_course_id::text,
        '/assets/',
        submitted."targetStoredFileId"::text,
        '/',
        submitted."targetStoredFileId"::text,
        '.',
        public.course_publication_asset_extension(submitted."mimeType")
      )
      or not exists (
        select 1
        from storage.objects as object
        where object.bucket_id = 'course-assets'
          and object.name = submitted."storagePath"
      )
  ) then
    raise exception 'course_publication_clone_asset_manifest_mismatch'
      using errcode = '23514';
  end if;

  select coalesce(
    jsonb_object_agg(
      asset."publicationAssetId"::text,
      to_jsonb(asset."targetStoredFileId"::text)
    ),
    '{}'::jsonb
  )
  into v_asset_id_map
  from jsonb_to_recordset(p_asset_manifest) as asset(
    "publicationAssetId" uuid,
    "targetStoredFileId" uuid
  );

  insert into public.course (
    id,
    owner_account_id,
    title,
    subject,
    goal,
    level,
    audience_description,
    target_lesson_count,
    teacher_preferences,
    audience_type,
    settings,
    assembled_at,
    archived_at,
    created_at,
    updated_at
  )
  values (
    p_target_course_id,
    p_actor_account_id,
    coalesce(
      btrim(p_target_title),
      v_revision.snapshot -> 'course' ->> 'title'
    ),
    v_revision.snapshot -> 'course' ->> 'subject',
    v_revision.snapshot -> 'course' ->> 'goal',
    v_revision.snapshot -> 'course' ->> 'level',
    v_revision.snapshot -> 'course' ->> 'audienceDescription',
    (v_revision.snapshot -> 'course' ->> 'targetLessonCount')::integer,
    '',
    'none',
    '{}'::jsonb,
    clock_timestamp(),
    null,
    clock_timestamp(),
    clock_timestamp()
  );

  v_objective_created_at := clock_timestamp();

  insert into public.learning_objective (
    id,
    course_id,
    title,
    description,
    archived_at,
    created_at,
    updated_at
  )
  select
    objective_map.id,
    p_target_course_id,
    submitted.title,
    submitted.description,
    null,
    v_objective_created_at
      + interval '1 microsecond' * (submitted.position - 1),
    v_objective_created_at
      + interval '1 microsecond' * (submitted.position - 1)
  from jsonb_to_recordset(
    case
      when v_snapshot_version = 2
        then v_revision.snapshot -> 'objectives'
      else '[]'::jsonb
    end
  ) as submitted(
    ref uuid,
    position integer,
    title text,
    description text,
    "archivedAt" timestamptz
  )
  join jsonb_to_recordset(p_id_map -> 'objectives') as objective_map(
    ref uuid,
    id uuid
  ) on objective_map.ref = submitted.ref
  order by submitted.position;

  insert into public.stored_file (
    id,
    owner_account_id,
    storage_bucket,
    storage_path,
    original_filename,
    mime_type,
    size_bytes,
    checksum_sha256,
    status,
    metadata,
    created_at,
    updated_at
  )
  select
    asset."targetStoredFileId",
    p_actor_account_id,
    'course-assets',
    asset."storagePath",
    asset."originalFilename",
    asset."mimeType",
    asset."sizeBytes",
    asset."checksumSha256",
    'ready',
    jsonb_build_object(
      'coursePublicationId', p_publication_id,
      'coursePublicationRevisionId', v_revision.id,
      'coursePublicationAssetId', asset."publicationAssetId"
    ),
    clock_timestamp(),
    clock_timestamp()
  from jsonb_to_recordset(p_asset_manifest) as asset(
    "publicationAssetId" uuid,
    "targetStoredFileId" uuid,
    "originalFilename" text,
    "mimeType" text,
    "sizeBytes" bigint,
    "checksumSha256" text,
    "storageBucket" text,
    "storagePath" text
  );

  insert into public.course_attachment (
    course_id,
    stored_file_id,
    created_at,
    updated_at
  )
  select
    p_target_course_id,
    asset."targetStoredFileId",
    clock_timestamp(),
    clock_timestamp()
  from jsonb_to_recordset(p_asset_manifest) as asset(
    "publicationAssetId" uuid,
    "targetStoredFileId" uuid
  );

  insert into public.lesson (
    id,
    course_id,
    position,
    title,
    summary,
    estimated_duration_minutes,
    settings,
    created_at,
    updated_at
  )
  select
    lesson_map.id,
    p_target_course_id,
    submitted.position,
    submitted.title,
    submitted.summary,
    submitted."estimatedDurationMinutes",
    '{}'::jsonb,
    clock_timestamp(),
    clock_timestamp()
  from jsonb_to_recordset(v_revision.snapshot -> 'lessons') as submitted(
    ref uuid,
    position integer,
    title text,
    summary text,
    "estimatedDurationMinutes" integer,
    components jsonb,
    slides jsonb
  )
  join jsonb_to_recordset(p_id_map -> 'lessons') as lesson_map(
    ref uuid,
    id uuid
  ) on lesson_map.ref = submitted.ref;

  insert into public.lesson_student_slide (
    id,
    lesson_id,
    position,
    created_at,
    updated_at
  )
  select
    slide_map.id,
    lesson_map.id,
    submitted_slide.position,
    clock_timestamp(),
    clock_timestamp()
  from jsonb_to_recordset(v_revision.snapshot -> 'lessons') as submitted_lesson(
    ref uuid,
    components jsonb,
    slides jsonb
  )
  join jsonb_to_recordset(p_id_map -> 'lessons') as lesson_map(
    ref uuid,
    id uuid
  ) on lesson_map.ref = submitted_lesson.ref
  cross join lateral jsonb_to_recordset(submitted_lesson.slides)
    as submitted_slide(ref uuid, position integer)
  join jsonb_to_recordset(p_id_map -> 'slides') as slide_map(
    ref uuid,
    id uuid
  ) on slide_map.ref = submitted_slide.ref;

  insert into public.lesson_component (
    id,
    lesson_id,
    position,
    type_key,
    schema_version,
    payload,
    placement_config,
    visibility,
    student_slide_id,
    primary_learning_objective_id,
    activity_role,
    created_at,
    updated_at
  )
  select
    component_map.id,
    lesson_map.id,
    submitted_component.position,
    submitted_component."typeKey",
    submitted_component."schemaVersion",
    public.remap_course_publication_component_assets(
      submitted_component."typeKey",
      submitted_component.payload,
      v_asset_id_map
    ),
    submitted_component.placement,
    submitted_component.visibility,
    case
      when submitted_component.visibility = 'learner_visible'
        then slide_map.id
      else null
    end,
    objective_map.id,
    submitted_component."activityRole",
    clock_timestamp(),
    clock_timestamp()
  from jsonb_to_recordset(v_revision.snapshot -> 'lessons') as submitted_lesson(
    ref uuid,
    components jsonb,
    slides jsonb
  )
  join jsonb_to_recordset(p_id_map -> 'lessons') as lesson_map(
    ref uuid,
    id uuid
  ) on lesson_map.ref = submitted_lesson.ref
  cross join lateral jsonb_to_recordset(submitted_lesson.components)
    as submitted_component(
      ref uuid,
      position integer,
      "typeKey" text,
      "schemaVersion" integer,
      payload jsonb,
      placement jsonb,
      visibility text,
      "studentSlideRef" uuid,
      "primaryObjectiveRef" uuid,
      "activityRole" text
    )
  join jsonb_to_recordset(p_id_map -> 'components') as component_map(
    ref uuid,
    id uuid
  ) on component_map.ref = submitted_component.ref
  left join jsonb_to_recordset(p_id_map -> 'slides') as slide_map(
    ref uuid,
    id uuid
  ) on slide_map.ref = submitted_component."studentSlideRef"
  left join jsonb_to_recordset(p_id_map -> 'objectives') as objective_map(
    ref uuid,
    id uuid
  ) on objective_map.ref = submitted_component."primaryObjectiveRef";

  update public.learning_objective as objective
  set archived_at = submitted."archivedAt"
  from jsonb_to_recordset(
    case
      when v_snapshot_version = 2
        then v_revision.snapshot -> 'objectives'
      else '[]'::jsonb
    end
  ) as submitted(ref uuid, "archivedAt" timestamptz)
  join jsonb_to_recordset(p_id_map -> 'objectives') as objective_map(
    ref uuid,
    id uuid
  ) on objective_map.ref = submitted.ref
  where objective.id = objective_map.id
    and submitted."archivedAt" is not null;

  insert into public.course_publication_origin (
    course_id,
    publication_id,
    revision_id,
    created_at
  )
  values (
    p_target_course_id,
    p_publication_id,
    v_revision.id,
    clock_timestamp()
  );

  return jsonb_build_object('courseId', p_target_course_id);
end
$$;


--
-- Name: clone_course_publication_with_attestation_admin(uuid, uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clone_course_publication_with_attestation_admin(p_actor_account_id uuid, p_publication_id uuid, p_target_course_id uuid, p_target_title text, p_id_map jsonb, p_asset_manifest jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if exists (
    select 1
    from public.course_publication as publication
    where publication.id = p_publication_id
      and publication.learning_audience = 'educators'
  ) then
    raise exception 'educator_course_copy_forbidden'
      using errcode = '42501';
  end if;

  v_result := public.clone_course_publication_admin(
    p_actor_account_id,
    p_publication_id,
    p_target_course_id,
    p_target_title,
    p_id_map,
    p_asset_manifest
  );

  return v_result || jsonb_build_object('learningAudience', 'children');
end
$$;


--
-- Name: communication_course_account_is_member(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_course_account_is_member(p_course_id uuid, p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.course as course
    join public.account as owner_account
      on owner_account.id = course.owner_account_id
     and owner_account.status = 'active'
    where course.id = p_course_id
      and course.learning_audience = 'children'
      and (
        course.owner_account_id = p_account_id
        or exists (
          select 1
          from public.learner_profile as profile
          join public.account as learner_account
            on learner_account.id = profile.account_id
           and learner_account.status = 'active'
          join public.teacher_learner as relation
            on relation.teacher_account_id = course.owner_account_id
           and relation.learner_profile_id = profile.id
           and relation.archived_at is null
          where profile.account_id = p_account_id
            and (
              exists (
                select 1
                from public.course_learner as direct
                where direct.course_id = course.id
                  and direct.learner_profile_id = profile.id
              )
              or exists (
                select 1
                from public.course_learner_group as course_group
                join public.learner_group_member as member
                  on member.learner_group_id = course_group.learner_group_id
                where course_group.course_id = course.id
                  and member.learner_profile_id = profile.id
              )
            )
        )
      )
  );
$$;


--
-- Name: communication_current_active_account_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_current_active_account_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select account.id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  limit 1;
$$;


--
-- Name: communication_direct_link_is_active(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_direct_link_is_active(p_account_a_id uuid, p_account_b_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_account_a_id is not null
    and p_account_b_id is not null
    and p_account_a_id <> p_account_b_id
    and exists (
      select 1
      from public.teacher_learner as relation
      join public.learner_profile as profile
        on profile.id = relation.learner_profile_id
      join public.account as teacher_account
        on teacher_account.id = relation.teacher_account_id
       and teacher_account.status = 'active'
      join public.account as learner_account
        on learner_account.id = profile.account_id
       and learner_account.status = 'active'
      where relation.archived_at is null
        and (
          (
            relation.teacher_account_id = p_account_a_id
            and profile.account_id = p_account_b_id
          )
          or (
            relation.teacher_account_id = p_account_b_id
            and profile.account_id = p_account_a_id
          )
        )
    );
$$;


--
-- Name: communication_message_projection(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_message_projection(p_message_id bigint, p_actor_account_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', message.id,
    'threadId', message.thread_id,
    'senderLabel', public.communication_person_label(
      p_actor_account_id,
      message.sender_account_id
    ),
    'body', message.body,
    'createdAt', message.created_at,
    'isOwn', message.sender_account_id = p_actor_account_id
  )
  from public.communication_message as message
  where message.id = p_message_id
    and public.communication_thread_is_accessible(
      message.thread_id,
      p_actor_account_id,
      false
    );
$$;


--
-- Name: communication_person_label(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_person_label(p_viewer_account_id uuid, p_person_account_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_viewer_account_id = p_person_account_id then person.display_name
    else coalesce(
      (
        select relation.display_name
        from public.teacher_learner as relation
        join public.learner_profile as profile
          on profile.id = relation.learner_profile_id
        where relation.teacher_account_id = p_viewer_account_id
          and profile.account_id = p_person_account_id
          and relation.archived_at is null
        limit 1
      ),
      person.display_name
    )
  end
  from public.account as person
  where person.id = p_person_account_id;
$$;


--
-- Name: communication_seed_read_states(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_seed_read_states(p_thread_id uuid, p_baseline_message_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_thread public.communication_thread%rowtype;
begin
  select thread.*
  into v_thread
  from public.communication_thread as thread
  where thread.id = p_thread_id;

  if not found then
    return;
  end if;

  if v_thread.kind = 'direct' then
    insert into public.communication_read_state (
      thread_id,
      account_id,
      last_read_message_id
    )
    values
      (
        v_thread.id,
        v_thread.direct_account_low_id,
        greatest(coalesce(p_baseline_message_id, 0), 0)
      ),
      (
        v_thread.id,
        v_thread.direct_account_high_id,
        greatest(coalesce(p_baseline_message_id, 0), 0)
      )
    on conflict (thread_id, account_id) do nothing;
  else
    insert into public.communication_read_state (
      thread_id,
      account_id,
      last_read_message_id
    )
    select
      v_thread.id,
      participant.account_id,
      greatest(coalesce(p_baseline_message_id, 0), 0)
    from (
      select course.owner_account_id as account_id
      from public.course as course
      join public.account as owner_account
        on owner_account.id = course.owner_account_id
       and owner_account.status = 'active'
      where course.id = v_thread.course_id
        and course.learning_audience = 'children'
      union
      select learner_account.id
      from public.course as course
      join public.teacher_learner as relation
        on relation.teacher_account_id = course.owner_account_id
       and relation.archived_at is null
      join public.learner_profile as profile
        on profile.id = relation.learner_profile_id
      join public.account as learner_account
        on learner_account.id = profile.account_id
       and learner_account.status = 'active'
      where course.id = v_thread.course_id
        and course.learning_audience = 'children'
        and (
          exists (
            select 1
            from public.course_learner as direct
            where direct.course_id = course.id
              and direct.learner_profile_id = profile.id
          )
          or exists (
            select 1
            from public.course_learner_group as course_group
            join public.learner_group_member as member
              on member.learner_group_id = course_group.learner_group_id
            where course_group.course_id = course.id
              and member.learner_profile_id = profile.id
          )
        )
    ) as participant
    on conflict (thread_id, account_id) do nothing;
  end if;
end
$$;


--
-- Name: communication_thread_is_accessible(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_thread_is_accessible(p_thread_id uuid, p_account_id uuid, p_for_write boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.communication_thread as thread
    where thread.id = p_thread_id
      and exists (
        select 1
        from public.account as actor
        where actor.id = p_account_id
          and actor.status = 'active'
      )
      and (
        (
          thread.kind = 'direct'
          and p_account_id in (
            thread.direct_account_low_id,
            thread.direct_account_high_id
          )
          and public.communication_direct_link_is_active(
            thread.direct_account_low_id,
            thread.direct_account_high_id
          )
        )
        or (
          thread.kind = 'course'
          and public.communication_course_account_is_member(
            thread.course_id,
            p_account_id
          )
          and (
            not p_for_write
            or exists (
              select 1
              from public.course as course
              where course.id = thread.course_id
                and course.archived_at is null
            )
          )
        )
      )
  );
$$;


--
-- Name: communication_thread_projection(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.communication_thread_projection(p_thread_id uuid, p_actor_account_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', thread.id,
    'kind', thread.kind,
    'title', case
      when thread.kind = 'course' then course.title
      else public.communication_person_label(
        p_actor_account_id,
        case
          when thread.direct_account_low_id = p_actor_account_id
            then thread.direct_account_high_id
          else thread.direct_account_low_id
        end
      )
    end,
    'courseId', case when thread.kind = 'course' then thread.course_id else null end,
    'directLearnerProfileId', case
      when thread.kind = 'direct' then (
        select profile.id
        from public.teacher_learner as relation
        join public.learner_profile as profile
          on profile.id = relation.learner_profile_id
        where relation.teacher_account_id = p_actor_account_id
          and relation.archived_at is null
          and profile.account_id = case
            when thread.direct_account_low_id = p_actor_account_id
              then thread.direct_account_high_id
            else thread.direct_account_low_id
          end
        limit 1
      )
      else null
    end,
    'preview', message.body,
    'lastMessageId', thread.last_message_id,
    'lastActivityAt', coalesce(thread.last_message_at, thread.created_at),
    'canSend', public.communication_thread_is_accessible(
      thread.id,
      p_actor_account_id,
      true
    ),
    'unreadCount', case
      when read_state.account_id is null then 0
      else (
        select count(*)
        from public.communication_message as unread_message
        where unread_message.thread_id = thread.id
          and unread_message.id > read_state.last_read_message_id
          and unread_message.sender_account_id <> p_actor_account_id
      )
    end
  )
  from public.communication_thread as thread
  left join public.course as course on course.id = thread.course_id
  left join public.communication_message as message
    on message.id = thread.last_message_id
   and message.thread_id = thread.id
  left join public.communication_read_state as read_state
    on read_state.thread_id = thread.id
   and read_state.account_id = p_actor_account_id
  where thread.id = p_thread_id
    and public.communication_thread_is_accessible(
      thread.id,
      p_actor_account_id,
      false
    );
$$;


--
-- Name: compact_course_lesson_positions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compact_course_lesson_positions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  update public.lesson
  set position = position - 1
  where course_id = old.course_id
    and position > old.position;
  return old;
end
$$;


--
-- Name: compact_lesson_component_positions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compact_lesson_component_positions() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.lesson as lesson
    where lesson.id = old.lesson_id
  ) then
    return old;
  end if;

  update public.lesson_component
  set position = position - 1
  where lesson_id = old.lesson_id
    and position > old.position;
  return old;
end
$$;


--
-- Name: complete_lesson_run(uuid, jsonb, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_lesson_run(p_lesson_run_id uuid, p_records jsonb, p_teacher_report text DEFAULT NULL::text, p_ended_at timestamp with time zone DEFAULT now()) RETURNS public.lesson_run
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.complete_lesson_run_v2(
    p_lesson_run_id,
    p_records,
    p_teacher_report,
    p_ended_at,
    null
  );
$$;


--
-- Name: complete_lesson_run_v2(uuid, jsonb, text, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_lesson_run_v2(p_lesson_run_id uuid, p_records jsonb, p_teacher_report text DEFAULT NULL::text, p_ended_at timestamp with time zone DEFAULT now(), p_actual_duration_minutes integer DEFAULT NULL::integer) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid;
  v_course_id uuid;
  v_course_title text;
  v_lesson_title text;
  v_subject text;
  v_lesson_id uuid;
  v_run public.lesson_run%rowtype;
  v_actual_duration integer;
  v_learner_profile_ids uuid[];
  v_learning_record_ids uuid[];
  v_projection_at timestamptz;
  v_projection_key record;
begin
  if (select auth.uid()) is null then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;
  if p_ended_at is null then
    raise exception 'lesson_run_ended_at_required' using errcode = '22023';
  end if;
  if p_records is null or jsonb_typeof(p_records) <> 'array'
    or jsonb_array_length(p_records) not between 1 and 200
  then
    raise exception 'lesson_run_records_must_be_nonempty_bounded_array'
      using errcode = '22023';
  end if;
  if p_actual_duration_minutes is not null
    and p_actual_duration_minutes not between 1 and 720
  then
    raise exception 'lesson_run_actual_duration_invalid' using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_records) as submitted(value)
    where jsonb_typeof(submitted.value) is distinct from 'object'
      or jsonb_typeof(submitted.value -> 'learnerProfileId')
        is distinct from 'string'
      or jsonb_typeof(submitted.value -> 'wasPresent')
        is distinct from 'boolean'
      or (submitted.value ? 'needsRepeat' and coalesce(
        jsonb_typeof(submitted.value -> 'needsRepeat'), 'null'
      ) not in ('boolean', 'null'))
      or (submitted.value ? 'teacherComment' and coalesce(
        jsonb_typeof(submitted.value -> 'teacherComment'), 'null'
      ) not in ('string', 'null'))
      or (submitted.value ? 'shareWithLearner' and coalesce(
        jsonb_typeof(submitted.value -> 'shareWithLearner'), 'null'
      ) not in ('boolean', 'null'))
      or (
        coalesce((submitted.value ->> 'shareWithLearner')::boolean, false)
        and nullif(btrim(submitted.value ->> 'teacherComment'), '') is null
      )
  ) then
    raise exception 'lesson_run_record_shape_invalid' using errcode = '22023';
  end if;

  if (select count(*) from jsonb_array_elements(p_records)) <>
     (select count(distinct (value ->> 'learnerProfileId')::uuid)
      from jsonb_array_elements(p_records))
  then
    raise exception 'lesson_run_record_learner_duplicate' using errcode = '22023';
  end if;

  select
    run.lesson_id,
    array_agg(
      (submitted.value ->> 'learnerProfileId')::uuid
      order by (submitted.value ->> 'learnerProfileId')::uuid
    )
  into v_lesson_id, v_learner_profile_ids
  from public.lesson_run as run
  join public.lesson as lesson on lesson.id = run.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  cross join jsonb_array_elements(p_records) as submitted(value)
  where run.id = p_lesson_run_id
    and account.auth_user_id = (select auth.uid())
  group by run.lesson_id;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  perform public.lock_learning_activity_learners(v_learner_profile_ids);

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = (select auth.uid())
  for update of lesson;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  perform component.id
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update of component;

  select run.* into v_run
  from public.lesson_run as run
  where run.id = p_lesson_run_id
    and run.lesson_id = v_lesson_id
  for update of run;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  select
    course.owner_account_id,
    course.id,
    course.title,
    lesson.title,
    course.subject
  into
    v_actor_account_id,
    v_course_id,
    v_course_title,
    v_lesson_title,
    v_subject
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  where lesson.id = v_run.lesson_id;

  if v_run.ended_at is not null then return v_run; end if;
  if v_run.cancelled_at is not null then
    raise exception 'lesson_run_not_open' using errcode = '55000';
  end if;
  if v_run.started_at_is_actual and p_ended_at < v_run.started_at then
    raise exception 'lesson_run_ended_before_start' using errcode = '22007';
  end if;

  perform 1 from public.learning_record as record
  where record.lesson_run_id = p_lesson_run_id
  order by record.id
  for update of record;

  if exists (
    select 1 from public.learning_record as record
    where record.lesson_run_id = p_lesson_run_id
      and record.occurred_at is not null
  ) then
    raise exception 'lesson_run_contains_finalized_records' using errcode = '55000';
  end if;

  if (select count(*) from public.learning_record
      where lesson_run_id = p_lesson_run_id)
      <> jsonb_array_length(p_records)
    or exists (
      select 1
      from jsonb_array_elements(p_records) as submitted(value)
      left join public.learning_record as record
        on record.lesson_run_id = p_lesson_run_id
       and record.learner_profile_id =
         (submitted.value ->> 'learnerProfileId')::uuid
      where record.id is null
    )
  then
    raise exception 'lesson_run_records_do_not_match_expected_learners'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_records) as submitted(value)
    join public.learning_record as record
      on record.lesson_run_id = p_lesson_run_id
     and record.learner_profile_id =
       (submitted.value ->> 'learnerProfileId')::uuid
    join public.lesson_component_observation as observation
      on observation.learning_record_id = record.id
     and observation.recorded_by_account_id = record.recorded_by_account_id
    where not (submitted.value ->> 'wasPresent')::boolean
  ) then
    raise exception 'lesson_run_absent_learner_has_observation'
      using errcode = '23514';
  end if;

  v_actual_duration := p_actual_duration_minutes;
  if v_actual_duration is null and v_run.started_at_is_actual then
    v_actual_duration := greatest(
      1,
      ceil(extract(epoch from (p_ended_at - v_run.started_at)) / 60.0)::integer
    );
    if v_actual_duration not between 1 and 720 then
      raise exception 'lesson_run_actual_duration_invalid' using errcode = '22023';
    end if;
  end if;

  update public.learning_record as record
  set occurred_at = p_ended_at,
      was_present = (submitted.value ->> 'wasPresent')::boolean,
      needs_repeat = case
        when jsonb_typeof(submitted.value -> 'needsRepeat') = 'boolean'
          then (submitted.value ->> 'needsRepeat')::boolean
        else null
      end,
      teacher_comment = case
        when jsonb_typeof(submitted.value -> 'teacherComment') = 'string'
          then nullif(btrim(submitted.value ->> 'teacherComment'), '')
        else null
      end,
      shared_with_learner_at = case
        when coalesce(
          (submitted.value ->> 'shareWithLearner')::boolean,
          false
        )
          and nullif(
            btrim(submitted.value ->> 'teacherComment'), ''
          ) is not null
          then p_ended_at
        else null
      end,
      actual_duration_minutes_at_time = v_actual_duration,
      course_title_at_time = v_course_title,
      lesson_title_at_time = v_lesson_title,
      subject_at_time = v_subject
  from jsonb_array_elements(p_records) as submitted(value)
  where record.lesson_run_id = p_lesson_run_id
    and record.learner_profile_id =
      (submitted.value ->> 'learnerProfileId')::uuid;

  select array_agg(record.id order by record.id)
  into v_learning_record_ids
  from public.learning_record as record
  where record.lesson_run_id = p_lesson_run_id;

  update public.lesson_run as run
  set ended_at = p_ended_at,
      actual_duration_minutes = v_actual_duration,
      teacher_report = nullif(btrim(p_teacher_report), '')
  where run.id = p_lesson_run_id
  returning run.* into v_run;

  v_projection_at := clock_timestamp();
  perform public.materialize_learning_evidence_for_records(
    v_learning_record_ids,
    v_projection_at
  );

  for v_projection_key in
    select distinct
      evidence.recorded_by_account_id,
      evidence.learner_profile_id,
      evidence.source_learning_objective_id_at_time
    from public.learning_evidence as evidence
    where evidence.learning_record_id = any(v_learning_record_ids)
      and evidence.superseded_by_evidence_id is null
    order by
      evidence.recorded_by_account_id,
      evidence.learner_profile_id,
      evidence.source_learning_objective_id_at_time
  loop
    perform public.rebuild_learner_objective_state_for_actor(
      v_projection_key.recorded_by_account_id,
      v_projection_key.learner_profile_id,
      v_projection_key.source_learning_objective_id_at_time,
      v_projection_at
    );
  end loop;

  return v_run;
end
$$;


--
-- Name: confirm_learner_profile_merge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_learner_profile_merge(p_merge_operation_id uuid, p_preview_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid;
  v_target_id uuid;
begin
  v_actor_account_id := public.current_account_id();
  if v_actor_account_id is null then
    raise exception 'learner_profile_merge_not_found' using errcode = 'P0002';
  end if;
  v_target_id := public.execute_learner_profile_merge_for_actor(
    p_merge_operation_id, v_actor_account_id, p_preview_fingerprint
  );
  return jsonb_build_object(
    'operationId', p_merge_operation_id,
    'targetLearnerProfileId', v_target_id,
    'completed', true
  );
end
$$;


--
-- Name: confirm_my_learner_profile_unlink(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_my_learner_profile_unlink(p_actor_auth_user_id uuid, p_preview_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_old_profile public.learner_profile%rowtype;
  v_new_profile public.learner_profile%rowtype;
  v_account public.account%rowtype;
  v_preview jsonb;
begin
  if v_actor_account_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  select account.* into v_account from public.account as account
  where account.id = v_actor_account_id for update of account;
  select profile.* into v_old_profile from public.learner_profile as profile
  where profile.account_id = v_actor_account_id for update of profile;
  v_preview := public.learner_safe_unlink_preview_for_actor(v_actor_account_id);
  if not coalesce((v_preview ->> 'canUnlink')::boolean, false)
    or p_preview_fingerprint is null
    or p_preview_fingerprint <> v_preview ->> 'previewFingerprint'
  then
    raise exception 'learner_profile_unlink_preview_stale' using errcode = '40001';
  end if;
  perform set_config('app.learner_profile_link_mutation', 'on', true);
  update public.learner_profile set account_id = null
  where id = v_old_profile.id;
  insert into public.learner_profile (display_name, account_id)
  values (v_account.display_name, v_actor_account_id)
  returning * into v_new_profile;
  perform public.append_learner_identity_audit(
    'learner_profile_safely_unlinked', v_actor_account_id,
    v_actor_account_id, v_old_profile.id, null, null,
    jsonb_build_object('projectionVersion', 1)
  );
  return jsonb_build_object(
    'learnerProfileId', v_new_profile.id,
    'displayName', v_new_profile.display_name,
    'createdAt', v_new_profile.created_at,
    'mergedLineageCount', 0,
    'canSafeUnlink', true,
    'pendingConnections', '[]'::jsonb
  );
end
$$;


--
-- Name: confirm_my_learning_data_erasure(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_my_learning_data_erasure(p_actor_auth_user_id uuid, p_preview_fingerprint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_account_id uuid :=
    public.account_id_for_auth_user(p_actor_auth_user_id);
  v_account public.account%rowtype;
  v_profile_id uuid;
  v_request public.learner_erasure_request%rowtype;
  v_lineage_ids uuid[];
  v_new_profile public.learner_profile%rowtype;
  v_counts jsonb;
  v_current_base jsonb;
  v_current_fingerprint bytea;
  v_learning_evidence_count integer;
  v_objective_state_count integer;
  v_recommendation_override_count integer;
begin
  if v_actor_account_id is null
    or p_preview_fingerprint !~ '^[0-9a-f]{64}$'
  then
    raise exception 'learning_data_erasure_not_found' using errcode = 'P0002';
  end if;

  -- Discovery is deliberately lock-free.  The shared learner advisory locks
  -- are first, and every authoritative value is re-read under row locks.
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id;
  if not found then
    raise exception 'learning_data_erasure_not_found' using errcode = 'P0002';
  end if;

  select array_agg(lineage.id order by lineage.id)
  into v_lineage_ids
  from (
    select v_profile_id as id
    union
    select alias.source_learner_profile_id
    from public.learner_profile_alias as alias
    where alias.target_learner_profile_id = v_profile_id
  ) as lineage;
  perform public.lock_learning_activity_learners(v_lineage_ids);

  select account.* into v_account
  from public.account as account
  where account.id = v_actor_account_id
  for update of account;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.id = v_profile_id
    and profile.account_id = v_actor_account_id
  for update of profile;
  if not found then
    raise exception 'learning_data_erasure_not_found' using errcode = 'P0002';
  end if;

  select request.* into v_request
  from public.learner_erasure_request as request
  where request.account_id = v_actor_account_id
    and request.current_learner_profile_id = v_profile_id
    and request.preview_fingerprint = decode(p_preview_fingerprint, 'hex')
    and request.consumed_at is null
    and request.expires_at > now()
  order by request.created_at desc
  limit 1
  for update of request;
  if not found then
    raise exception 'learning_data_erasure_not_found' using errcode = 'P0002';
  end if;
  v_counts := v_request.preview_payload;

  -- Recompute lineage after the canonical Account/Profile locks.
  select array_agg(lineage.id order by lineage.id)
  into v_lineage_ids
  from (
    select v_profile_id as id
    union
    select alias.source_learner_profile_id
    from public.learner_profile_alias as alias
    where alias.target_learner_profile_id = v_profile_id
  ) as lineage;

  perform 1 from public.learner_profile_alias
    where source_learner_profile_id = any(v_lineage_ids)
      or target_learner_profile_id = v_profile_id
    order by source_learner_profile_id for update;
  perform 1 from public.learner_profile_merge
    where source_learner_profile_id = any(v_lineage_ids)
      or target_learner_profile_id = v_profile_id
    order by id for update;
  perform 1 from public.learner_claim_invitation
    where source_learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learner_connection_request
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learner_observer_invitation
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learner_observer_grant
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learner_ai_consent
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learner_credential_recovery_delegate
    where subject_account_id = v_actor_account_id
    order by id for update;
  perform 1 from public.course_learner
    where learner_profile_id = any(v_lineage_ids)
    order by course_id, learner_profile_id for update;
  perform 1 from public.learner_group_member
    where learner_profile_id = any(v_lineage_ids)
    order by learner_group_id, learner_profile_id for update;
  perform 1 from public.teacher_learner
    where learner_profile_id = any(v_lineage_ids)
    order by teacher_account_id, learner_profile_id for update;
  perform 1 from public.learner_profile_share_code
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learning_record
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform 1 from public.learning_evidence
    where learner_profile_id = any(v_lineage_ids)
    order by id for update;
  perform link.learning_evidence_id
  from public.learner_objective_state_evidence as link
  join public.learner_objective_state as state
    on state.id = link.learner_objective_state_id
  where state.learner_profile_id = any(v_lineage_ids)
  order by link.learner_objective_state_id, link.position
  for update of link;
  perform 1 from public.learner_objective_state
    where learner_profile_id = any(v_lineage_ids)
    order by
      recorded_by_account_id,
      source_course_id_at_time,
      source_learning_objective_id_at_time
    for update;
  perform 1 from public.learner_recommendation_override
    where learner_profile_id = any(v_lineage_ids)
    order by
      recorded_by_account_id,
      source_course_id_at_time,
      source_learning_objective_id_at_time,
      id
    for update;

  v_current_base := public.learner_erasure_state_for_actor(
    v_actor_account_id,
    v_profile_id
  );
  v_current_fingerprint := extensions.digest(v_current_base::text, 'sha256');
  if v_current_fingerprint <> v_request.preview_fingerprint
    or v_request.learning_activity_scope_fingerprint is null
    or v_request.learning_activity_scope_fingerprint is distinct from
      public.learning_activity_scope_fingerprint(v_lineage_ids)
  then
    raise exception 'learning_data_erasure_preview_stale'
      using errcode = '40001';
  end if;

  select count(*)::integer into v_learning_evidence_count
  from public.learning_evidence
  where learner_profile_id = any(v_lineage_ids);
  select count(*)::integer into v_objective_state_count
  from public.learner_objective_state
  where learner_profile_id = any(v_lineage_ids);
  select count(*)::integer into v_recommendation_override_count
  from public.learner_recommendation_override
  where learner_profile_id = any(v_lineage_ids);

  perform set_config('app.learner_identity_erasure', 'on', true);
  perform set_config('app.learner_profile_link_mutation', 'on', true);

  delete from public.learner_profile_alias
  where source_learner_profile_id = any(v_lineage_ids)
    or target_learner_profile_id = v_profile_id;
  delete from public.learner_profile_merge
  where source_learner_profile_id = any(v_lineage_ids)
    or target_learner_profile_id = v_profile_id;
  delete from public.learner_claim_invitation
  where source_learner_profile_id = any(v_lineage_ids);
  delete from public.learner_connection_request
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_observer_invitation
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_observer_grant
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_ai_consent
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_credential_recovery_delegate
  where subject_account_id = v_actor_account_id;
  delete from public.course_learner
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_group_member
  where learner_profile_id = any(v_lineage_ids);
  delete from public.teacher_learner
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_profile_share_code
  where learner_profile_id = any(v_lineage_ids);

  delete from public.learner_objective_state_evidence as link
  using public.learner_objective_state as state
  where state.id = link.learner_objective_state_id
    and state.learner_profile_id = any(v_lineage_ids);
  delete from public.learner_recommendation_override
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learner_objective_state
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learning_evidence
  where learner_profile_id = any(v_lineage_ids);
  delete from public.learning_record
  where learner_profile_id = any(v_lineage_ids);

  update public.learner_identity_audit_event
  set learner_profile_id = null,
      related_learner_profile_id = null,
      related_entity_id = case
        when related_entity_id = any(v_lineage_ids) then null
        else related_entity_id
      end
  where learner_profile_id = any(v_lineage_ids)
    or related_learner_profile_id = any(v_lineage_ids)
    or related_entity_id = any(v_lineage_ids);

  delete from public.learner_profile where id = v_profile_id;
  insert into public.learner_profile (display_name, account_id)
  values (v_account.display_name, v_actor_account_id)
  returning * into v_new_profile;

  perform public.append_learner_identity_audit(
    'learning_data_erased',
    v_actor_account_id,
    v_actor_account_id,
    null,
    null,
    null,
    jsonb_build_object(
      'lineageProfileCount', v_counts -> 'lineageProfileCount',
      'learningRecordCount', v_counts -> 'learningRecordCount',
      'learningEvidenceCount', v_learning_evidence_count,
      'objectiveStateCount', v_objective_state_count,
      'recommendationOverrideCount', v_recommendation_override_count,
      'learningActivityProjectionVersion', 1,
      'projectionVersion', 1
    )
  );
  return jsonb_build_object(
    'learnerProfileId', v_new_profile.id,
    'displayName', v_new_profile.display_name,
    'createdAt', v_new_profile.created_at,
    'mergedLineageCount', 0,
    'canSafeUnlink', true,
    'pendingConnections', '[]'::jsonb
  );
end
$_$;


--
-- Name: correct_finalized_lesson_component_observation(uuid, uuid, uuid, text, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_finalized_lesson_component_observation(p_observation_id uuid, p_learner_profile_id uuid, p_expected_learning_record_id uuid, p_rating text, p_private_note text, p_correction_reason text, p_idempotency_key uuid, p_corrected_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_actor_account_id uuid;
  v_source_record public.learning_record%rowtype;
  v_source_observation public.lesson_component_observation%rowtype;
  v_old_observation public.lesson_component_observation%rowtype;
  v_new_record_id uuid := gen_random_uuid();
  v_new_observation_id uuid;
  v_candidate_observation_id uuid;
  v_replay_record_id uuid;
  v_replay_observation_id uuid;
  v_replay_record public.learning_record%rowtype;
  v_replay_observation public.lesson_component_observation%rowtype;
  v_objective_id uuid;
  -- p_corrected_at remains in the rolling application signature, but is not
  -- authoritative.  Direct PostgREST callers cannot backdate or future-date
  -- durable history; the database linearizes the correction itself.
  v_corrected_at timestamptz := clock_timestamp();
begin
  if v_actor_user_id is null
    or p_observation_id is null
    or p_learner_profile_id is null
    or p_expected_learning_record_id is null
    or p_rating not in ('independent', 'with_support', 'not_yet')
    or (
      p_private_note is not null
      and (
        btrim(p_private_note) = ''
        or char_length(btrim(p_private_note)) > 500
      )
    )
    or p_correction_reason is null
    or char_length(btrim(p_correction_reason)) not between 1 and 500
    or p_idempotency_key is null
    or p_corrected_at is null
  then
    raise exception 'finalized_observation_correction_invalid'
      using errcode = '22023';
  end if;

  select account.id
  into v_actor_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'finalized_observation_not_found'
      using errcode = 'P0002';
  end if;

  select replacement.*
  into v_replay_record
  from public.learning_record as replacement
  where replacement.recorded_by_account_id = v_actor_account_id
    and replacement.correction_idempotency_key = p_idempotency_key
  limit 1;

  if found then
    select replacement_observation.*
    into v_replay_observation
    from public.lesson_component_observation as replacement_observation
    where replacement_observation.learning_record_id = v_replay_record.id
      and replacement_observation.corrected_from_observation_id =
        p_observation_id
    limit 1;
    if not found
      or v_replay_record.corrected_from_record_id is distinct from
        p_expected_learning_record_id
      or v_replay_record.learner_profile_id is distinct from
        p_learner_profile_id
      or v_replay_record.correction_reason is distinct from
        btrim(p_correction_reason)
      or v_replay_observation.rating is distinct from p_rating
      or v_replay_observation.private_note is distinct from
        nullif(btrim(p_private_note), '')
    then
      raise exception 'correction_idempotency_conflict'
        using errcode = '23505';
    end if;
    v_replay_record_id := v_replay_record.id;
    v_replay_observation_id := v_replay_observation.id;
    return jsonb_build_object(
      'idempotencyKey', p_idempotency_key,
      'newLearningRecordId', v_replay_record_id,
      'newObservationId', v_replay_observation_id,
      'correctedAt', (
        select record.corrected_at
        from public.learning_record as record
        where record.id = v_replay_record_id
      ),
      'replayed', true
    );
  end if;

  -- Discovery is read-only.  The profile advisory lock is acquired before any
  -- authoritative row lock and all values are re-read below.
  select record.*
  into v_source_record
  from public.lesson_component_observation as observation
  join public.learning_record as record
    on record.id = observation.learning_record_id
   and record.recorded_by_account_id = observation.recorded_by_account_id
  where observation.id = p_observation_id
    and record.id = p_expected_learning_record_id
    and record.learner_profile_id = p_learner_profile_id
    and record.recorded_by_account_id = v_actor_account_id
    and record.occurred_at is not null
    and record.superseded_by_record_id is null;

  if not found then
    raise exception 'finalized_observation_not_found'
      using errcode = 'P0002';
  end if;

  select observation.*
  into v_source_observation
  from public.lesson_component_observation as observation
  where observation.id = p_observation_id
    and observation.learning_record_id = v_source_record.id
    and observation.recorded_by_account_id = v_actor_account_id;
  if not found then
    raise exception 'finalized_observation_not_found'
      using errcode = 'P0002';
  end if;

  perform public.lock_learning_activity_learners(
    array[v_source_record.learner_profile_id]
  );

  perform 1
  from public.learner_profile as profile
  where profile.id = v_source_record.learner_profile_id
  for update of profile;

  if not found or not exists (
    select 1
    from public.teacher_learner as relation
    where relation.teacher_account_id = v_actor_account_id
      and relation.learner_profile_id = v_source_record.learner_profile_id
  ) then
    raise exception 'finalized_observation_not_found'
      using errcode = 'P0002';
  end if;

  -- A concurrent retry may have committed while this transaction waited for
  -- the shared learner lock.
  select replacement.*
  into v_replay_record
  from public.learning_record as replacement
  where replacement.recorded_by_account_id = v_actor_account_id
    and replacement.correction_idempotency_key = p_idempotency_key
  limit 1;

  if found then
    select replacement_observation.*
    into v_replay_observation
    from public.lesson_component_observation as replacement_observation
    where replacement_observation.learning_record_id = v_replay_record.id
      and replacement_observation.corrected_from_observation_id =
        p_observation_id
    limit 1;
    if not found
      or v_replay_record.corrected_from_record_id is distinct from
        p_expected_learning_record_id
      or v_replay_record.learner_profile_id is distinct from
        p_learner_profile_id
      or v_replay_record.correction_reason is distinct from
        btrim(p_correction_reason)
      or v_replay_observation.rating is distinct from p_rating
      or v_replay_observation.private_note is distinct from
        nullif(btrim(p_private_note), '')
    then
      raise exception 'correction_idempotency_conflict'
        using errcode = '23505';
    end if;
    v_replay_record_id := v_replay_record.id;
    v_replay_observation_id := v_replay_observation.id;
    return jsonb_build_object(
      'idempotencyKey', p_idempotency_key,
      'newLearningRecordId', v_replay_record_id,
      'newObservationId', v_replay_observation_id,
      'correctedAt', (
        select record.corrected_at
        from public.learning_record as record
        where record.id = v_replay_record_id
      ),
      'replayed', true
    );
  end if;

  select record.*
  into v_source_record
  from public.learning_record as record
  where record.id = p_expected_learning_record_id
    and record.recorded_by_account_id = v_actor_account_id
    and record.learner_profile_id = p_learner_profile_id
    and record.occurred_at is not null
    and record.superseded_by_record_id is null
  for update of record;

  if not found then
    raise exception 'finalized_observation_changed'
      using errcode = '40001';
  end if;

  perform observation.id
  from public.lesson_component_observation as observation
  where observation.learning_record_id = v_source_record.id
    and observation.recorded_by_account_id = v_actor_account_id
  order by observation.id
  for update of observation;

  select observation.*
  into v_source_observation
  from public.lesson_component_observation as observation
  where observation.id = p_observation_id
    and observation.learning_record_id = v_source_record.id
    and observation.superseded_by_observation_id is null;

  if not found then
    raise exception 'finalized_observation_changed'
      using errcode = '40001';
  end if;

  if p_rating is not distinct from v_source_observation.rating
    and nullif(btrim(p_private_note), '') is not distinct from
      v_source_observation.private_note
  then
    raise exception 'learning_observation_correction_no_change'
      using errcode = '22023';
  end if;

  -- The self-FK is deferred.  Marking the source first removes it from the
  -- active partial Run+learner key without detaching the stable Run chain.
  update public.learning_record as record
  set superseded_by_record_id = v_new_record_id
  where record.id = v_source_record.id;

  insert into public.learning_record (
    id,
    learner_profile_id,
    recorded_by_account_id,
    lesson_run_id,
    source_course_id,
    source_lesson_id,
    source_course_id_at_time,
    source_lesson_id_at_time,
    source_lesson_run_id_at_time,
    occurred_at,
    was_present,
    needs_repeat,
    teacher_comment,
    shared_with_learner_at,
    actual_duration_minutes_at_time,
    course_title_at_time,
    lesson_title_at_time,
    subject_at_time,
    corrected_from_record_id,
    correction_reason,
    correction_idempotency_key,
    corrected_at
  ) values (
    v_new_record_id,
    v_source_record.learner_profile_id,
    v_source_record.recorded_by_account_id,
    v_source_record.lesson_run_id,
    v_source_record.source_course_id,
    v_source_record.source_lesson_id,
    v_source_record.source_course_id_at_time,
    v_source_record.source_lesson_id_at_time,
    v_source_record.source_lesson_run_id_at_time,
    v_source_record.occurred_at,
    v_source_record.was_present,
    v_source_record.needs_repeat,
    v_source_record.teacher_comment,
    v_source_record.shared_with_learner_at,
    v_source_record.actual_duration_minutes_at_time,
    v_source_record.course_title_at_time,
    v_source_record.lesson_title_at_time,
    v_source_record.subject_at_time,
    v_source_record.id,
    btrim(p_correction_reason),
    p_idempotency_key,
    v_corrected_at
  );

  for v_old_observation in
    select observation.*
    from public.lesson_component_observation as observation
    where observation.learning_record_id = v_source_record.id
      and observation.recorded_by_account_id = v_actor_account_id
    order by observation.id
  loop
    v_candidate_observation_id := gen_random_uuid();

    update public.lesson_component_observation as observation
    set superseded_by_observation_id = v_candidate_observation_id
    where observation.id = v_old_observation.id;

    insert into public.lesson_component_observation (
      id,
      learning_record_id,
      lesson_component_id,
      source_lesson_component_id_at_time,
      learning_objective_id,
      source_learning_objective_id_at_time,
      learning_objective_title_at_time,
      component_position_at_time,
      component_type_key_at_time,
      component_label_at_time,
      component_visibility_at_time,
      observable_criterion_at_time,
      rating,
      entry_method,
      private_note,
      observed_at,
      recorded_by_account_id,
      corrected_from_observation_id
    ) values (
      v_candidate_observation_id,
      v_new_record_id,
      v_old_observation.lesson_component_id,
      v_old_observation.source_lesson_component_id_at_time,
      v_old_observation.learning_objective_id,
      v_old_observation.source_learning_objective_id_at_time,
      v_old_observation.learning_objective_title_at_time,
      v_old_observation.component_position_at_time,
      v_old_observation.component_type_key_at_time,
      v_old_observation.component_label_at_time,
      v_old_observation.component_visibility_at_time,
      v_old_observation.observable_criterion_at_time,
      case when v_old_observation.id = p_observation_id
        then p_rating else v_old_observation.rating end,
      v_old_observation.entry_method,
      case when v_old_observation.id = p_observation_id
        then nullif(btrim(p_private_note), '')
        else v_old_observation.private_note end,
      v_old_observation.observed_at,
      v_old_observation.recorded_by_account_id,
      v_old_observation.id
    );

    if v_old_observation.id = p_observation_id then
      v_new_observation_id := v_candidate_observation_id;
    end if;
  end loop;

  perform public.materialize_learning_evidence_for_records(
    array[v_new_record_id],
    v_corrected_at
  );

  for v_objective_id in
    select distinct observation.source_learning_objective_id_at_time
    from public.lesson_component_observation as observation
    where observation.learning_record_id = v_new_record_id
      and observation.source_learning_objective_id_at_time is not null
    order by observation.source_learning_objective_id_at_time
  loop
    perform public.rebuild_learner_objective_state_for_actor(
      v_actor_account_id,
      v_source_record.learner_profile_id,
      v_objective_id,
      v_corrected_at
    );
  end loop;

  return jsonb_build_object(
    'idempotencyKey', p_idempotency_key,
    'newLearningRecordId', v_new_record_id,
    'newObservationId', v_new_observation_id,
    'correctedAt', v_corrected_at,
    'replayed', false
  );
end
$$;


--
-- Name: course_attestation_definition_is_valid(integer, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_attestation_definition_is_valid(p_version integer, p_title text, p_description text, p_passing_score_percent integer, p_questions jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    p_version > 0
    and p_title = btrim(p_title)
    and char_length(p_title) between 2 and 240
    and p_description = btrim(p_description)
    and char_length(p_description) <= 2000
    and p_passing_score_percent between 1 and 100
    and public.course_attestation_questions_are_valid(p_questions),
    false
  );
$$;


--
-- Name: course_attestation_questions_are_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_attestation_questions_are_valid(p_questions jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_question jsonb;
  v_option jsonb;
  v_count integer;
  v_distinct_count integer;
begin
  if p_questions is null
    or jsonb_typeof(p_questions) <> 'array'
    or jsonb_array_length(p_questions) < 1
    or jsonb_array_length(p_questions) > 50
  then
    return false;
  end if;

  select count(*), count(distinct question.value ->> 'id')
  into v_count, v_distinct_count
  from jsonb_array_elements(p_questions) as question(value);

  if v_count <> v_distinct_count then
    return false;
  end if;

  for v_question in
    select question.value
    from jsonb_array_elements(p_questions) with ordinality
      as question(value, position)
    order by question.position
  loop
    if jsonb_typeof(v_question) <> 'object'
      or (v_question - array[
        'id',
        'prompt',
        'options',
        'correctOptionId',
        'explanation'
      ]) <> '{}'::jsonb
      or not (v_question ?& array[
        'id',
        'prompt',
        'options',
        'correctOptionId',
        'explanation'
      ])
      or jsonb_typeof(v_question -> 'id') <> 'string'
      or (v_question ->> 'id') !~ '^[A-Za-z0-9_-]{1,80}$'
      or jsonb_typeof(v_question -> 'prompt') <> 'string'
      or btrim(v_question ->> 'prompt') = ''
      or v_question ->> 'prompt' <> btrim(v_question ->> 'prompt')
      or char_length(v_question ->> 'prompt') > 2000
      or jsonb_typeof(v_question -> 'correctOptionId') <> 'string'
      or (v_question ->> 'correctOptionId') !~ '^[A-Za-z0-9_-]{1,80}$'
      or jsonb_typeof(v_question -> 'explanation') <> 'string'
      or v_question ->> 'explanation'
        <> btrim(v_question ->> 'explanation')
      or char_length(v_question ->> 'explanation') > 2000
      or jsonb_typeof(v_question -> 'options') <> 'array'
      or jsonb_array_length(v_question -> 'options') < 2
      or jsonb_array_length(v_question -> 'options') > 8
    then
      return false;
    end if;

    select count(*), count(distinct option.value ->> 'id')
    into v_count, v_distinct_count
    from jsonb_array_elements(v_question -> 'options') as option(value);

    if v_count <> v_distinct_count then
      return false;
    end if;

    for v_option in
      select option.value
      from jsonb_array_elements(v_question -> 'options') with ordinality
        as option(value, position)
      order by option.position
    loop
      if jsonb_typeof(v_option) <> 'object'
        or (v_option - array['id', 'label']) <> '{}'::jsonb
        or not (v_option ?& array['id', 'label'])
        or jsonb_typeof(v_option -> 'id') <> 'string'
        or (v_option ->> 'id') !~ '^[A-Za-z0-9_-]{1,80}$'
        or jsonb_typeof(v_option -> 'label') <> 'string'
        or btrim(v_option ->> 'label') = ''
        or v_option ->> 'label' <> btrim(v_option ->> 'label')
        or char_length(v_option ->> 'label') > 500
      then
        return false;
      end if;
    end loop;

    if not exists (
      select 1
      from jsonb_array_elements(v_question -> 'options') as option(value)
      where option.value ->> 'id' = v_question ->> 'correctOptionId'
    ) then
      return false;
    end if;
  end loop;

  return true;
exception
  when others then
    return false;
end
$_$;


--
-- Name: course_attestation_selected_answers_are_valid(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_attestation_selected_answers_are_valid(p_answers jsonb, p_expected_count integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_key text;
  v_value jsonb;
  v_count integer := 0;
begin
  if p_answers is null
    or jsonb_typeof(p_answers) <> 'object'
    or p_expected_count is null
    or p_expected_count < 1
    or p_expected_count > 50
  then
    return false;
  end if;

  for v_key, v_value in
    select answer.key, answer.value
    from jsonb_each(p_answers) as answer(key, value)
  loop
    v_count := v_count + 1;
    if v_key !~ '^[A-Za-z0-9_-]{1,80}$'
      or jsonb_typeof(v_value) <> 'string'
      or (v_value #>> '{}') !~ '^[A-Za-z0-9_-]{1,80}$'
    then
      return false;
    end if;
  end loop;

  return v_count = p_expected_count;
exception
  when others then
    return false;
end
$_$;


--
-- Name: course_has_effective_learner(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_has_effective_learner(p_course_id uuid, p_learner_profile_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.course_learner as direct
    where direct.course_id = p_course_id
      and direct.learner_profile_id = p_learner_profile_id
    union all
    select 1
    from public.course_learner_group as course_group
    join public.learner_group_member as member
      on member.learner_group_id = course_group.learner_group_id
    where course_group.course_id = p_course_id
      and member.learner_profile_id = p_learner_profile_id
  );
$$;


--
-- Name: course_learning_activity_projection(uuid[], uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_learning_activity_projection(p_learner_profile_ids uuid[], p_recorded_by_account_id uuid, p_course_id uuid, p_generated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with profiles as materialized (
    select distinct submitted.id
    from unnest(coalesce(p_learner_profile_ids, '{}'::uuid[]))
      as submitted(id)
    where submitted.id is not null
  ), candidate as materialized (
    select
      state.id as state_id,
      state.learner_profile_id,
      state.recorded_by_account_id,
      state.source_learning_objective_id_at_time,
      state.source_course_id_at_time,
      state.course_title_at_time,
      state.subject_at_time,
      state.objective_title_at_time,
      state.status,
      state.reason_code,
      state.reason_text,
      state.evaluated_at,
      state.last_evidence_at,
      state.freshness_due_at,
      override_row.action as override_action,
      override_row.recommendation_type as override_type,
      true as has_data
    from public.learner_objective_state as state
    join profiles on profiles.id = state.learner_profile_id
    left join public.learner_recommendation_override as override_row
      on override_row.recorded_by_account_id =
        state.recorded_by_account_id
     and override_row.learner_profile_id = state.learner_profile_id
     and override_row.source_course_id_at_time =
        state.source_course_id_at_time
     and override_row.source_learning_objective_id_at_time =
        state.source_learning_objective_id_at_time
    where state.recorded_by_account_id = p_recorded_by_account_id
      and state.source_course_id_at_time = p_course_id

    union all

    select
      null::uuid,
      profiles.id,
      course.owner_account_id,
      objective.id,
      course.id,
      btrim(course.title),
      nullif(btrim(course.subject), ''),
      btrim(objective.title),
      'no_data'::text,
      'no_eligible_evidence'::text,
      'Пока нет подходящих наблюдений по этой учебной цели.'::text,
      greatest(course.updated_at, objective.updated_at),
      null::timestamptz,
      null::timestamptz,
      null::text,
      null::text,
      false
    from profiles
    join public.course as course
      on course.id = p_course_id
     and course.owner_account_id = p_recorded_by_account_id
     and course.archived_at is null
     and public.course_has_effective_learner(course.id, profiles.id)
    join public.learning_objective as objective
      on objective.course_id = course.id
     and objective.archived_at is null
    where not exists (
      select 1
      from public.learner_objective_state as state
      where state.learner_profile_id = profiles.id
        and state.recorded_by_account_id = p_recorded_by_account_id
        and state.source_course_id_at_time = course.id
        and state.source_learning_objective_id_at_time = objective.id
    )
  ), bounded as materialized (
    select candidate.*
    from candidate
    order by
      candidate.has_data desc,
      candidate.evaluated_at desc,
      candidate.course_title_at_time,
      candidate.objective_title_at_time,
      candidate.learner_profile_id,
      candidate.recorded_by_account_id,
      candidate.source_course_id_at_time,
      candidate.source_learning_objective_id_at_time,
      candidate.state_id nulls last
    limit 80
  ), projected as (
    select
      bounded.*,
      'las_' || encode(
        extensions.digest(
          case when bounded.state_id is null
            then 'course-no-data-v1:' || bounded.learner_profile_id::text || ':'
              || bounded.source_course_id_at_time::text || ':'
              || bounded.source_learning_objective_id_at_time::text
            else 'course-state-v1:' || bounded.learner_profile_id::text || ':'
              || bounded.state_id::text
          end,
          'sha256'
        ),
        'hex'
      ) as opaque_state_key,
      coalesce(evidence_projection.items, '[]'::jsonb)
        as evidence_items,
      coalesce(evidence_projection.keys, '[]'::jsonb)
        as evidence_keys
    from bounded
    left join lateral (
      select
        jsonb_agg(item.payload order by item.position) as items,
        jsonb_agg(to_jsonb(item.opaque_key) order by item.position) as keys
      from (
        select
          link.position,
          'lae_' || encode(
            extensions.digest(
              'course-evidence-v1:' || bounded.learner_profile_id::text || ':'
                || evidence.id::text,
              'sha256'
            ),
            'hex'
          ) as opaque_key,
          jsonb_build_object(
            'key', 'lae_' || encode(
              extensions.digest(
                'course-evidence-v1:'
                  || bounded.learner_profile_id::text || ':'
                  || evidence.id::text,
                'sha256'
              ),
              'hex'
            ),
            'direction', evidence.direction,
            'support', evidence.support,
            'observedAt', evidence.observed_at,
            'evidenceAt', evidence.materialized_at,
            'courseTitle', evidence.course_title_at_time,
            'lessonTitle', evidence.lesson_title_at_time,
            'componentLabel', case
              when evidence.component_visibility_at_time = 'learner_visible'
                then evidence.component_label_at_time
              else 'Служебный компонент преподавателя'
            end,
            'objectiveTitle', evidence.objective_title_at_time,
            'criterion', case
              when evidence.component_visibility_at_time = 'learner_visible'
                then evidence.criterion_at_time
              else 'Служебный критерий преподавателя'
            end
          ) as payload
        from public.learner_objective_state_evidence as link
        join public.learning_evidence as evidence
          on evidence.id = link.learning_evidence_id
        where link.learner_objective_state_id = bounded.state_id
        order by link.position
        limit 3
      ) as item
    ) as evidence_projection on bounded.state_id is not null
  ), state_items as (
    select
      projected.*,
      jsonb_build_object(
        'key', projected.opaque_state_key,
        'courseTitle', projected.course_title_at_time,
        'subject', projected.subject_at_time,
        'objectiveTitle', projected.objective_title_at_time,
        'state', projected.status,
        'reasonCode', projected.reason_code,
        'reasonText', projected.reason_text,
        'evaluatedAt', projected.evaluated_at,
        'lastEvidenceAt', projected.last_evidence_at,
        'freshnessDueAt', projected.freshness_due_at,
        'evidenceReferences', projected.evidence_items,
        'recommendation', case
          when projected.state_id is null
            or projected.override_action = 'dismiss'
            then null::jsonb
          else jsonb_build_object(
            'type', case
              when projected.override_action = 'replace'
                then projected.override_type
              when projected.reason_code = 'latest_not_yet' then 'repeat'
              when projected.reason_code = 'latest_with_support'
                then 'try_without_support'
              when projected.reason_code =
                'independent_opportunities_missing'
                then 'apply_in_new_context'
              when projected.reason_code =
                'multiple_independent_opportunities'
                then 'move_forward'
              else 'recheck_freshness'
            end,
            'reasonCode', case projected.reason_code
              when 'latest_not_yet' then 'repeat_after_not_yet'
              when 'latest_with_support'
                then 'try_without_support_after_supported_success'
              when 'independent_opportunities_missing'
                then 'apply_in_new_context_after_one_independent_opportunity'
              when 'multiple_independent_opportunities'
                then 'move_forward_after_confirmation'
              else 'recheck_due_to_freshness'
            end,
            'reasonText', case
              when projected.override_action = 'replace' then
                case projected.override_type
                  when 'repeat' then
                    'Повторите материал и попробуйте ещё раз.'
                  when 'try_without_support' then
                    'Попробуйте выполнить навык без подсказки.'
                  when 'apply_in_new_context' then
                    'Примените навык в новом контексте.'
                  when 'move_forward' then
                    'Можно переходить к следующему материалу.'
                  else
                    'Перепроверьте навык, чтобы обновить подтверждение.'
                end
              when projected.reason_code = 'latest_not_yet' then
                'Пока не получилось — повторите материал и попробуйте ещё раз.'
              when projected.reason_code = 'latest_with_support' then
                'Получилось с поддержкой — следующим шагом попробуйте без подсказки.'
              when projected.reason_code =
                'independent_opportunities_missing' then
                'Получилось самостоятельно один раз — примените навык в новом контексте.'
              when projected.reason_code =
                'multiple_independent_opportunities' then
                'Навык подтверждён в нескольких занятиях — можно переходить дальше.'
              else
                'Подтверждение давно не обновлялось — пора перепроверить навык.'
            end,
            'source', case when projected.override_action = 'replace'
              then 'teacher_override' else 'rule' end,
            'generatedAt', projected.evaluated_at,
            'evidenceReferenceKeys', projected.evidence_keys
          )
        end
      ) as payload
    from projected
  )
  select jsonb_build_object(
    'totalStateCount', (select count(*)::integer from candidate),
    'states', coalesce(
      jsonb_agg(
        state_items.payload order by
          state_items.has_data desc,
          state_items.evaluated_at desc,
          state_items.course_title_at_time,
          state_items.objective_title_at_time,
          state_items.learner_profile_id,
          state_items.recorded_by_account_id,
          state_items.source_course_id_at_time,
          state_items.source_learning_objective_id_at_time,
          state_items.state_id nulls last
      ),
      '[]'::jsonb
    )
  )
  from state_items;
$$;


--
-- Name: course_publication_asset_extension(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_publication_asset_extension(p_mime_type text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select case p_mime_type
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
    when 'image/gif' then 'gif'
    when 'application/pdf' then 'pdf'
    when 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
      then 'docx'
    when 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
      then 'pptx'
    when 'text/plain' then 'txt'
    when 'text/markdown' then 'md'
    else null
  end
$$;


--
-- Name: course_publication_revision_has_lesson_ref(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_publication_revision_has_lesson_ref(p_publication_id uuid, p_revision_id uuid, p_lesson_ref uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.course_publication_revision as revision
    cross join lateral jsonb_array_elements(revision.snapshot -> 'lessons')
      as lesson(value)
    where revision.publication_id = p_publication_id
      and revision.id = p_revision_id
      and lesson.value ->> 'ref' = p_lesson_ref::text
  );
$$;


--
-- Name: course_publication_snapshot_payloads_match(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.course_publication_snapshot_payloads_match(p_source_course_id uuid, p_snapshot jsonb, p_asset_id_map jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select not exists (
    select 1
    from public.lesson_component as source_component
    join public.lesson as source_lesson
      on source_lesson.id = source_component.lesson_id
    left join lateral (
      select submitted_component.value
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'components'
      ) as submitted_component(value)
      where (submitted_lesson.value ->> 'position')::integer
          = source_lesson.position
        and (submitted_component.value ->> 'position')::integer
          = source_component.position
      limit 1
    ) as submitted on true
    where source_lesson.course_id = p_source_course_id
      and (
        submitted.value is null
        or public.remap_course_publication_component_assets(
          source_component.type_key,
          source_component.payload,
          p_asset_id_map
        ) is distinct from submitted.value -> 'payload'
      )
  )
$$;


--
-- Name: create_learner_connection_request(uuid, text, bytea, bytea, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_learner_connection_request(p_actor_auth_user_id uuid, p_method text, p_code_or_email_digest bytea, p_token_digest bytea, p_target_learner_profile_id uuid, p_local_display_name text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_target_profile_id uuid := p_target_learner_profile_id;
  v_recipient_account_id uuid;
  v_share_code_id uuid;
  v_request public.learner_connection_request%rowtype;
  v_expired_request public.learner_connection_request%rowtype;
begin
  if v_actor_account_id is null
    or p_method not in ('share_code', 'email', 'exact_handle')
    or p_code_or_email_digest is null or octet_length(p_code_or_email_digest) <> 32
    or p_local_display_name is null or btrim(p_local_display_name) = ''
    or char_length(btrim(p_local_display_name)) > 160
    or p_expires_at <= now() or p_expires_at > now() + interval '30 days'
    or (p_method = 'email' and (p_token_digest is null or octet_length(p_token_digest) <> 32))
    or (p_method <> 'email' and p_token_digest is not null)
  then
    raise exception 'learner_connection_request_invalid' using errcode = '22023';
  end if;

  if not public.learner_identity_rate_limit_hit(
    'connection_create', extensions.digest(v_actor_account_id::text, 'sha256'),
    20, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;

  if p_method = 'share_code' then
    select code.id, code.learner_profile_id
    into v_share_code_id, v_target_profile_id
    from public.learner_profile_share_code as code
    where code.code_digest = p_code_or_email_digest
      and code.status = 'active'
      and code.expires_at > now()
    for update of code;
    if not found then
      raise exception 'learner_connection_target_unavailable' using errcode = 'P0002';
    end if;
    update public.learner_profile_share_code
    set status = 'used', used_at = now()
    where id = v_share_code_id;
  elsif p_method = 'exact_handle' then
    if v_target_profile_id is null then
      raise exception 'learner_connection_target_unavailable' using errcode = 'P0002';
    end if;
  end if;

  if v_target_profile_id is not null then
    select profile.account_id into v_recipient_account_id
    from public.learner_profile as profile
    where profile.id = v_target_profile_id
    for update of profile;
    if not found or v_recipient_account_id = v_actor_account_id then
      raise exception 'learner_connection_target_unavailable' using errcode = 'P0002';
    end if;
  end if;

  for v_expired_request in
    update public.learner_connection_request as request
    set status = 'expired', acted_at = now(), updated_at = now()
    where request.teacher_account_id = v_actor_account_id
      and request.status = 'pending'
      and request.expires_at <= now()
      and (
        (p_method = 'email' and request.method = 'email'
          and request.recipient_email_digest = p_code_or_email_digest)
        or (v_target_profile_id is not null
          and request.learner_profile_id = v_target_profile_id)
      )
    returning request.*
  loop
    perform public.append_learner_identity_audit(
      'learner_connection_expired', v_actor_account_id,
      v_expired_request.recipient_account_id,
      v_expired_request.learner_profile_id, null, v_expired_request.id,
      jsonb_build_object(
        'method', v_expired_request.method,
        'expiredAt', v_expired_request.expires_at,
        'projectionVersion', 1
      )
    );
  end loop;

  insert into public.learner_connection_request (
    teacher_account_id,
    learner_profile_id,
    share_code_id,
    recipient_account_id,
    method,
    recipient_email_digest,
    token_digest,
    local_display_name,
    expires_at
  ) values (
    v_actor_account_id,
    v_target_profile_id,
    v_share_code_id,
    v_recipient_account_id,
    p_method,
    case when p_method = 'email' then p_code_or_email_digest else null end,
    p_token_digest,
    btrim(p_local_display_name),
    p_expires_at
  ) returning * into v_request;

  perform public.append_learner_identity_audit(
    'learner_connection_requested', v_actor_account_id,
    v_recipient_account_id, v_target_profile_id, null, v_request.id,
    jsonb_build_object('method', p_method, 'projectionVersion', 1)
  );

  return jsonb_build_object(
    'id', v_request.id,
    'direction', 'outgoing',
    'status', v_request.status,
    'method', v_request.method,
    'counterpartyLabel', case when v_target_profile_id is null
      then 'Приглашение отправлено'
      else (select display_name from public.learner_profile where id = v_target_profile_id)
    end,
    'localDisplayName', v_request.local_display_name,
    'learnerProfileId', v_target_profile_id,
    'expiresAt', v_request.expires_at,
    'createdAt', v_request.created_at,
    'acceptedAt', v_request.accepted_at
  );
exception
  when unique_violation then
    raise exception 'learner_connection_request_already_pending' using errcode = '23505';
end
$$;


--
-- Name: learner_group; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learner_group (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_account_id uuid NOT NULL,
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_group_name_check CHECK (((btrim(name) <> ''::text) AND (char_length(name) <= 160)))
);


--
-- Name: create_learner_group(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_learner_group(p_name text, p_learner_profile_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.learner_group
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_profile_ids uuid[];
  v_group public.learner_group%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if p_name is null
    or btrim(p_name) = ''
    or char_length(btrim(p_name)) > 160
  then
    raise exception 'learner_group_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_profile_ids, null) is not null
    or cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_profile_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.learner_group as learner_group
    where learner_group.owner_account_id = v_teacher_account_id
      and lower(btrim(learner_group.name)) = lower(btrim(p_name))
  ) then
    raise exception 'learner_group_name_taken' using errcode = '23505';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_profile_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_profile_ids)
    and teacher_learner.archived_at is null
  order by teacher_learner.learner_profile_id
  for update of teacher_learner;

  if cardinality(v_profile_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_profile_ids)
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  insert into public.learner_group (owner_account_id, name)
  values (v_teacher_account_id, btrim(p_name))
  returning * into v_group;

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select v_group.id, requested.id
  from unnest(v_profile_ids) as requested(id);

  return v_group;
end
$$;


--
-- Name: create_learner_observer_invitation(uuid, bytea, bytea, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_learner_observer_invitation(p_actor_auth_user_id uuid, p_recipient_email_digest bytea, p_token_digest bytea, p_relationship_label text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_profile_id uuid;
  v_invitation public.learner_observer_invitation%rowtype;
  v_expired_invitation public.learner_observer_invitation%rowtype;
  v_overview jsonb;
begin
  if v_actor_account_id is null
    or octet_length(p_recipient_email_digest) <> 32
    or octet_length(p_token_digest) <> 32
    or (p_relationship_label is not null
      and (btrim(p_relationship_label) = '' or char_length(btrim(p_relationship_label)) > 80))
    or p_expires_at <= now() or p_expires_at > now() + interval '30 days'
  then
    raise exception 'learner_observer_invitation_invalid' using errcode = '22023';
  end if;
  if not public.learner_identity_rate_limit_hit(
    'observer_invitation_create', extensions.digest(v_actor_account_id::text, 'sha256'),
    20, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id
  for update of profile;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  for v_expired_invitation in
    update public.learner_observer_invitation as invitation
    set status = 'expired', updated_at = now()
    where invitation.learner_profile_id = v_profile_id
      and invitation.recipient_email_digest = p_recipient_email_digest
      and invitation.status in ('pending', 'bound')
      and invitation.expires_at <= now()
    returning invitation.*
  loop
    perform public.append_learner_identity_audit(
      'learner_observer_invitation_expired', v_actor_account_id,
      v_actor_account_id, v_profile_id, null, v_expired_invitation.id,
      jsonb_build_object(
        'expiredAt', v_expired_invitation.expires_at,
        'projectionVersion', 1
      )
    );
  end loop;
  insert into public.learner_observer_invitation (
    learner_profile_id, subject_account_id, recipient_email_digest,
    token_digest, relationship_label, expires_at
  ) values (
    v_profile_id, v_actor_account_id, p_recipient_email_digest,
    p_token_digest, nullif(btrim(p_relationship_label), ''), p_expires_at
  ) returning * into v_invitation;
  perform public.append_learner_identity_audit(
    'learner_observer_invitation_created', v_actor_account_id,
    v_actor_account_id, v_profile_id, null, v_invitation.id,
    jsonb_build_object('projectionVersion', 1)
  );
  v_overview := public.list_my_learner_observer_overview_for_actor(v_actor_account_id);
  return jsonb_build_object(
    'createdInvitationId', v_invitation.id,
    'overview', v_overview
  );
exception
  when unique_violation then
    raise exception 'learner_observer_invitation_already_pending' using errcode = '23505';
end
$$;


--
-- Name: create_learner_profile_invitation(uuid, uuid, text, bytea, bytea, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_learner_profile_invitation(p_actor_auth_user_id uuid, p_learner_profile_id uuid, p_kind text, p_recipient_email_digest bytea, p_token_digest bytea, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_profile public.learner_profile%rowtype;
  v_invitation public.learner_claim_invitation%rowtype;
  v_expired_invitation public.learner_claim_invitation%rowtype;
begin
  if p_kind not in ('claim', 'child_activation')
    or octet_length(p_recipient_email_digest) <> 32
    or octet_length(p_token_digest) <> 32
    or p_expires_at <= now() or p_expires_at > now() + interval '30 days'
  then
    raise exception 'learner_profile_invitation_invalid' using errcode = '22023';
  end if;
  if not public.learner_identity_rate_limit_hit(
    'profile_invitation_create', extensions.digest(v_actor_account_id::text, 'sha256'),
    20, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  select profile.* into v_profile
  from public.learner_profile as profile
  join public.teacher_learner as relation
    on relation.learner_profile_id = profile.id
   and relation.teacher_account_id = v_actor_account_id
   and relation.archived_at is null
  where profile.id = p_learner_profile_id
  for update of profile;
  if not found or v_profile.account_id is not null then
    raise exception 'learner_profile_not_available' using errcode = 'P0002';
  end if;
  for v_expired_invitation in
    update public.learner_claim_invitation as invitation
    set status = 'expired', updated_at = now()
    where invitation.source_learner_profile_id = v_profile.id
      and invitation.kind = p_kind
      and invitation.status in ('pending', 'bound')
      and invitation.expires_at <= now()
    returning invitation.*
  loop
    update public.learner_profile_merge
    set status = 'cancelled', cancelled_at = now(), updated_at = now()
    where invitation_id = v_expired_invitation.id
      and status in ('pending', 'ready');
    perform public.append_learner_identity_audit(
      'learner_profile_invitation_expired', v_actor_account_id,
      v_expired_invitation.recipient_account_id,
      v_profile.id, null, v_expired_invitation.id,
      jsonb_build_object(
        'kind', v_expired_invitation.kind,
        'expiredAt', v_expired_invitation.expires_at,
        'projectionVersion', 1
      )
    );
  end loop;
  insert into public.learner_claim_invitation (
    source_learner_profile_id, inviter_account_id, recipient_email_digest,
    token_digest, kind, expires_at
  ) values (
    v_profile.id, v_actor_account_id, p_recipient_email_digest,
    p_token_digest, p_kind, p_expires_at
  ) returning * into v_invitation;
  perform public.append_learner_identity_audit(
    'learner_profile_invitation_created', v_actor_account_id, null,
    v_profile.id, null, v_invitation.id,
    jsonb_build_object('kind', p_kind, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'id', v_invitation.id, 'kind', v_invitation.kind,
    'status', v_invitation.status, 'learnerProfileId', v_profile.id,
    'learnerLabel', v_profile.display_name,
    'inviterLabel', (select display_name from public.account where id = v_actor_account_id),
    'expiresAt', v_invitation.expires_at, 'createdAt', v_invitation.created_at,
    'acceptedAt', v_invitation.accepted_at
  );
exception
  when unique_violation then
    raise exception 'learner_profile_invitation_already_pending' using errcode = '23505';
end
$$;


--
-- Name: create_learner_profile_with_groups(text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_learner_profile_with_groups(p_display_name text, p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.teacher_learner
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_group_ids uuid[];
  v_profile public.learner_profile%rowtype;
  v_relation public.teacher_learner%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if p_display_name is null
    or btrim(p_display_name) = ''
    or char_length(btrim(p_display_name)) > 160
  then
    raise exception 'learner_profile_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_group_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_teacher_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = any(v_group_ids)
    and course.owner_account_id = v_teacher_account_id
  order by course.id
  for update of course;

  if exists (
    select 1
    from (
      select distinct course_group.course_id
      from public.course_learner_group as course_group
      where course_group.learner_group_id = any(v_group_ids)
    ) as target_course
    where (
      select count(*)
      from (
        select course_learner.learner_profile_id
        from public.course_learner as course_learner
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = course_learner.learner_profile_id
         and teacher_learner.archived_at is null
        where course_learner.course_id = target_course.course_id
        union
        select member.learner_profile_id
        from public.course_learner_group as linked_group
        join public.learner_group_member as member
          on member.learner_group_id = linked_group.learner_group_id
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = member.learner_profile_id
         and teacher_learner.archived_at is null
        where linked_group.course_id = target_course.course_id
      ) as effective
    ) >= 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_teacher_account_id
  order by learner_group.id
  for update of learner_group;

  insert into public.learner_profile (display_name)
  values (btrim(p_display_name))
  returning * into v_profile;

  insert into public.teacher_learner (
    teacher_account_id,
    learner_profile_id,
    display_name
  )
  values (
    v_teacher_account_id,
    v_profile.id,
    btrim(p_display_name)
  )
  returning * into v_relation;

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select requested.id, v_profile.id
  from unnest(v_group_ids) as requested(id);

  return v_relation;
end
$$;


--
-- Name: create_learning_objective(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_learning_objective(p_course_id uuid, p_title text, p_description text DEFAULT NULL::text) RETURNS SETOF public.learning_objective
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_objective public.learning_objective%rowtype;
begin
  if v_actor_user_id is null
    or p_course_id is null
    or p_title is null
    or char_length(btrim(p_title)) not between 2 and 240
    or (
      p_description is not null
      and (
        btrim(p_description) = ''
        or char_length(btrim(p_description)) > 2000
      )
    )
  then
    raise exception 'learning_objective_invalid'
      using errcode = '22023';
  end if;

  perform 1
  from public.course as course
  join public.account as account on account.id = course.owner_account_id
  where course.id = p_course_id
    and course.archived_at is null
    and account.auth_user_id = v_actor_user_id
  for update of course;

  if not found then
    raise exception 'learning_objective_not_found'
      using errcode = 'P0002';
  end if;

  insert into public.learning_objective (
    course_id,
    title,
    description
  ) values (
    p_course_id,
    btrim(p_title),
    nullif(btrim(p_description), '')
  )
  returning * into v_objective;

  return next v_objective;
end
$$;


--
-- Name: create_my_assistant_conversation(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_my_assistant_conversation(p_title text DEFAULT 'Новый диалог'::text, p_context_course_id uuid DEFAULT NULL::uuid, p_context_lesson_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_conversation public.assistant_conversation%rowtype;
begin
  if v_actor_account_id is null
    or p_title is null
    or btrim(p_title) = ''
    or char_length(btrim(p_title)) > 160
    or (p_context_lesson_id is not null and p_context_course_id is null)
  then
    raise exception 'assistant_conversation_invalid' using errcode = '22023';
  end if;

  if p_context_course_id is not null then
    perform course.id
    from public.course as course
    where course.id = p_context_course_id
      and course.owner_account_id = v_actor_account_id
      and course.archived_at is null
    for key share;

    if not found then
      raise exception 'assistant_context_not_found' using errcode = 'P0002';
    end if;
  end if;

  if p_context_lesson_id is not null
    and not exists (
      select 1
      from public.lesson as lesson
      where lesson.id = p_context_lesson_id
        and lesson.course_id = p_context_course_id
    )
  then
    raise exception 'assistant_context_not_found' using errcode = 'P0002';
  end if;

  insert into public.assistant_conversation (
    owner_account_id,
    title,
    context_course_id,
    context_lesson_id
  )
  values (
    v_actor_account_id,
    btrim(p_title),
    p_context_course_id,
    p_context_lesson_id
  )
  returning * into v_conversation;

  return public.assistant_conversation_projection(
    v_conversation.id,
    v_actor_account_id
  );
end
$$;


--
-- Name: current_account_auth_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_account_auth_context() RETURNS TABLE(account_id uuid, auth_user_id uuid, display_name text, locale text, timezone text, has_pin boolean, sessions_invalid_before timestamp with time zone, verified_email text, can_author_educator_courses boolean, avatar_kind text, avatar_preset_key text, avatar_storage_path text, avatar_revision integer, avatar_updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    account.id,
    account.auth_user_id,
    account.display_name,
    account.locale,
    account.timezone,
    security.pin_hash is not null,
    security.sessions_invalid_before,
    case
      when auth_user.email_confirmed_at is not null
        and lower(coalesce(auth_user.email, ''))
          not like '%@learners.shidao.internal'
        and lower(coalesce(auth_user.email, ''))
          not like '%.shidao.internal'
        then auth_user.email::text
      else null
    end,
    account.can_author_educator_courses,
    account.avatar_kind,
    account.avatar_preset_key,
    account.avatar_storage_path,
    account.avatar_revision,
    account.avatar_updated_at
  from public.account as account
  left join public.account_security as security
    on security.account_id = account.id
  join auth.users as auth_user
    on auth_user.id = account.auth_user_id
  where account.auth_user_id = (select auth.uid())
    and account.status in ('active', 'provisional')
  limit 1;
$$;


--
-- Name: current_account_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_account_id() RETURNS uuid
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select account.id
  from public.account
  where account.auth_user_id = (select auth.uid())
  limit 1;
$$;


--
-- Name: current_owned_learner_profile_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_owned_learner_profile_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select profile.id
  from public.account as account
  join public.learner_profile as profile on profile.account_id = account.id
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  limit 1;
$$;


--
-- Name: current_session_invalid_before(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_session_invalid_before() RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select security.sessions_invalid_before
  from public.account as account
  join public.account_security as security on security.account_id = account.id
  where account.auth_user_id = (select auth.uid())
  limit 1;
$$;


--
-- Name: delete_draft_learning_records_for_lesson_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_draft_learning_records_for_lesson_run() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.learning_record as record
  where record.lesson_run_id = old.id
    and record.occurred_at is null;

  return old;
end
$$;


--
-- Name: delete_draft_observations_for_lesson_component(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_draft_observations_for_lesson_component() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  delete from public.lesson_component_observation as observation
  using public.learning_record as record
  where record.id = observation.learning_record_id
    and record.occurred_at is null
    and observation.lesson_component_id = old.id;

  return old;
end
$$;


--
-- Name: delete_empty_offline_learner_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_empty_offline_learner_profile(p_learner_profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile public.learner_profile%rowtype;
begin
  select profile.* into v_profile
  from public.learner_profile as profile
  join public.teacher_learner as relation
    on relation.learner_profile_id = profile.id
   and relation.teacher_account_id = v_actor_account_id
  where profile.id = p_learner_profile_id
  for update of profile;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  if v_profile.account_id is not null
    or exists (select 1 from public.learning_record where learner_profile_id = v_profile.id)
    or exists (select 1 from public.teacher_learner where learner_profile_id = v_profile.id and teacher_account_id <> v_actor_account_id)
    or exists (select 1 from public.learner_group_member where learner_profile_id = v_profile.id)
    or exists (select 1 from public.course_learner where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_profile_share_code where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_claim_invitation where source_learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_connection_request where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_observer_invitation where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_observer_grant where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_ai_consent where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_identity_reconciliation where learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_profile_alias where target_learner_profile_id = v_profile.id)
    or exists (select 1 from public.learner_profile_merge where source_learner_profile_id = v_profile.id or target_learner_profile_id = v_profile.id)
  then
    raise exception 'learner_profile_not_empty' using errcode = '55000';
  end if;
  perform public.append_learner_identity_audit(
    'offline_learner_profile_deleted', v_actor_account_id, null,
    v_profile.id, null, null, '{}'::jsonb
  );
  delete from public.learner_profile where id = v_profile.id;
end
$$;


--
-- Name: delete_learner_group(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_learner_group(p_learner_group_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_owner_account_id uuid;
begin
  if v_actor_user_id is null then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  select account.id
  into v_owner_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = p_learner_group_id
    and course.owner_account_id = v_owner_account_id
  order by course.id
  for update of course;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id
    and learner_group.owner_account_id = v_owner_account_id
  for update of learner_group;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  -- Cascades remove only this collection's member and Course links. Learner
  -- profiles, LearningRecords, and frozen LessonRun drafts remain untouched.
  delete from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id;

  return true;
end
$$;


--
-- Name: delete_lesson_component(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lesson_component(p_component_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_deleted_count integer;
begin
  if v_actor_user_id is null then
    return false;
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    return false;
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    return false;
  end if;

  perform component.id
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update of component;

  perform run.id
  from public.lesson_run as run
  where run.lesson_id = v_lesson_id
  order by run.id
  for update of run;

  perform record.id
  from public.learning_record as record
  join public.lesson_run as run on run.id = record.lesson_run_id
  where run.lesson_id = v_lesson_id
  order by record.id
  for update of record;

  perform slide.id
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update of slide;

  delete from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  get diagnostics v_deleted_count = row_count;
  return v_deleted_count = 1;
end
$$;


--
-- Name: delete_lesson_with_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_lesson_with_history(p_lesson_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
begin
  if v_actor_user_id is null then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = p_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform component.id
  from public.lesson_component as component
  where component.lesson_id = p_lesson_id
  order by component.id
  for update of component;

  perform run.id
  from public.lesson_run as run
  where run.lesson_id = p_lesson_id
  order by run.id
  for update of run;

  perform record.id
  from public.learning_record as record
  where record.source_lesson_id = p_lesson_id
    or record.lesson_run_id in (
      select run.id
      from public.lesson_run as run
      where run.lesson_id = p_lesson_id
    )
  order by record.id
  for update of record;

  update public.learning_record as record
  set lesson_run_id = null,
      source_lesson_id = null
  where record.occurred_at is not null
    and (
      record.source_lesson_id = p_lesson_id
      or record.lesson_run_id in (
        select run.id
        from public.lesson_run as run
        where run.lesson_id = p_lesson_id
      )
    );

  delete from public.lesson as lesson
  where lesson.id = p_lesson_id;

  return true;
end
$$;


--
-- Name: detach_archived_teacher_learner_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detach_archived_teacher_learner_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.archived_at is null and new.archived_at is not null then
    delete from public.course_learner as course_learner
    using public.course as course
    where course.id = course_learner.course_id
      and course.owner_account_id = new.teacher_account_id
      and course_learner.learner_profile_id = new.learner_profile_id;

    delete from public.learner_group_member as member
    using public.learner_group as learner_group
    where learner_group.id = member.learner_group_id
      and learner_group.owner_account_id = new.teacher_account_id
      and member.learner_profile_id = new.learner_profile_id;
  end if;

  return new;
end
$$;


--
-- Name: duplicate_course_admin(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duplicate_course_admin(p_actor_account_id uuid, p_source_course_id uuid, p_target_course_id uuid, p_target_title text, p_id_map jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_source_course public.course%rowtype;
  v_lesson_count integer;
  v_component_count integer;
  v_slide_count integer;
  v_objective_count integer;
  v_objective_created_at timestamptz;
begin
  if p_actor_account_id is null
    or p_source_course_id is null
    or p_target_course_id is null
    or (
      p_target_title is not null
      and (
        btrim(p_target_title) = ''
        or char_length(btrim(p_target_title)) > 160
      )
    )
    or p_id_map is null
    or jsonb_typeof(p_id_map) <> 'object'
  then
    raise exception 'course_duplicate_invalid'
      using errcode = '22023';
  end if;

  select course.*
  into v_source_course
  from public.course as course
  where course.id = p_source_course_id
    and course.owner_account_id = p_actor_account_id
  for update;

  if not found then
    raise exception 'course_duplicate_source_not_found'
      using errcode = 'P0002';
  end if;

  -- Match publication and all LA-M2 authoring mutations: the source Course is
  -- the parent serialization lock, followed by Account and descendants.
  perform 1
  from public.account as account
  where account.id = p_actor_account_id
    and account.status = 'active'
  for update;

  if not found then
    raise exception 'course_duplicate_actor_not_active'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.course as course
    where course.id = p_target_course_id
  ) then
    raise exception 'course_duplicate_target_id_conflict'
      using errcode = '23505';
  end if;

  perform 1
  from public.lesson as lesson
  where lesson.course_id = p_source_course_id
  order by lesson.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  join public.lesson as lesson on lesson.id = slide.lesson_id
  where lesson.course_id = p_source_course_id
  order by slide.id
  for update of slide;

  perform 1
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  where lesson.course_id = p_source_course_id
  order by component.id
  for update of component;

  perform 1
  from public.learning_objective as objective
  where objective.course_id = p_source_course_id
  order by objective.created_at, objective.id
  for share of objective;

  perform 1
  from public.course_attachment as attachment
  where attachment.course_id = p_source_course_id
  order by attachment.id
  for update;

  if exists (
    select 1
    from public.course_attachment as attachment
    join public.stored_file as stored_file
      on stored_file.id = attachment.stored_file_id
    where attachment.course_id = p_source_course_id
      and stored_file.owner_account_id <> p_actor_account_id
  ) then
    raise exception 'course_duplicate_attachment_owner_mismatch'
      using errcode = '42501';
  end if;

  if not (p_id_map ? 'objectives') then
    p_id_map := p_id_map || jsonb_build_object('objectives', '[]'::jsonb);
  end if;

  if (p_id_map - array[
      'objectives', 'lessons', 'components', 'slides'
    ]) <> '{}'::jsonb
    or jsonb_typeof(p_id_map -> 'objectives') <> 'array'
    or jsonb_typeof(p_id_map -> 'lessons') <> 'array'
    or jsonb_typeof(p_id_map -> 'components') <> 'array'
    or jsonb_typeof(p_id_map -> 'slides') <> 'array'
  then
    raise exception 'course_duplicate_id_map_shape_invalid'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'components') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    where jsonb_typeof(item.value) <> 'object'
      or (item.value - array['ref', 'id']) <> '{}'::jsonb
      or not (item.value ? 'ref')
      or not (item.value ? 'id')
  ) then
    raise exception 'course_duplicate_id_map_shape_invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into v_objective_count
  from public.learning_objective as objective
  where objective.course_id = p_source_course_id;

  select count(*)::integer
  into v_lesson_count
  from public.lesson as lesson
  where lesson.course_id = p_source_course_id;

  select count(*)::integer
  into v_component_count
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  where lesson.course_id = p_source_course_id;

  select count(*)::integer
  into v_slide_count
  from public.lesson_student_slide as slide
  join public.lesson as lesson on lesson.id = slide.lesson_id
  where lesson.course_id = p_source_course_id;

  if jsonb_array_length(p_id_map -> 'objectives') <> v_objective_count
    or jsonb_array_length(p_id_map -> 'lessons') <> v_lesson_count
    or jsonb_array_length(p_id_map -> 'components') <> v_component_count
    or jsonb_array_length(p_id_map -> 'slides') <> v_slide_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    ) <> v_objective_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    ) <> v_objective_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    ) <> v_lesson_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    ) <> v_lesson_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'components') as item(value)
    ) <> v_component_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'components') as item(value)
    ) <> v_component_count
    or (
      select count(distinct (item.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    ) <> v_slide_count
    or (
      select count(distinct (item.value ->> 'id')::uuid)
      from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    ) <> v_slide_count
  then
    raise exception 'course_duplicate_id_map_not_exact'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.learning_objective as source_objective
    where source_objective.course_id = p_source_course_id
      and not exists (
        select 1
        from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
        where (item.value ->> 'ref')::uuid = source_objective.id
      )
  ) or exists (
    select 1
    from public.lesson as source_lesson
    where source_lesson.course_id = p_source_course_id
      and not exists (
        select 1
        from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
        where (item.value ->> 'ref')::uuid = source_lesson.id
      )
  ) or exists (
    select 1
    from public.lesson_component as source_component
    join public.lesson as source_lesson
      on source_lesson.id = source_component.lesson_id
    where source_lesson.course_id = p_source_course_id
      and not exists (
        select 1
        from jsonb_array_elements(p_id_map -> 'components') as item(value)
        where (item.value ->> 'ref')::uuid = source_component.id
      )
  ) or exists (
    select 1
    from public.lesson_student_slide as source_slide
    join public.lesson as source_lesson
      on source_lesson.id = source_slide.lesson_id
    where source_lesson.course_id = p_source_course_id
      and not exists (
        select 1
        from jsonb_array_elements(p_id_map -> 'slides') as item(value)
        where (item.value ->> 'ref')::uuid = source_slide.id
      )
  ) then
    raise exception 'course_duplicate_id_map_not_exact'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'objectives') as item(value)
    join public.learning_objective as objective
      on objective.id = (item.value ->> 'id')::uuid
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'lessons') as item(value)
    join public.lesson as lesson
      on lesson.id = (item.value ->> 'id')::uuid
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'components') as item(value)
    join public.lesson_component as component
      on component.id = (item.value ->> 'id')::uuid
  ) or exists (
    select 1
    from jsonb_array_elements(p_id_map -> 'slides') as item(value)
    join public.lesson_student_slide as slide
      on slide.id = (item.value ->> 'id')::uuid
  ) then
    raise exception 'course_duplicate_target_id_conflict'
      using errcode = '23505';
  end if;

  insert into public.course (
    id,
    owner_account_id,
    title,
    subject,
    goal,
    level,
    audience_description,
    target_lesson_count,
    teacher_preferences,
    audience_type,
    settings,
    assembled_at,
    archived_at,
    created_at,
    updated_at
  )
  values (
    p_target_course_id,
    p_actor_account_id,
    coalesce(
      btrim(p_target_title),
      concat(left(v_source_course.title, 150), ' — копия')
    ),
    v_source_course.subject,
    v_source_course.goal,
    v_source_course.level,
    v_source_course.audience_description,
    v_source_course.target_lesson_count,
    v_source_course.teacher_preferences,
    'none',
    v_source_course.settings,
    v_source_course.assembled_at,
    null,
    clock_timestamp(),
    clock_timestamp()
  );

  v_objective_created_at := clock_timestamp();

  insert into public.learning_objective (
    id,
    course_id,
    title,
    description,
    archived_at,
    created_at,
    updated_at
  )
  select
    objective_map.id,
    p_target_course_id,
    source_objective.title,
    source_objective.description,
    null,
    v_objective_created_at
      + interval '1 microsecond' * (source_objective.copy_position - 1),
    v_objective_created_at
      + interval '1 microsecond' * (source_objective.copy_position - 1)
  from (
    select
      objective.*,
      row_number() over (
        order by objective.created_at, objective.id
      )::integer as copy_position
    from public.learning_objective as objective
    where objective.course_id = p_source_course_id
  ) as source_objective
  join jsonb_to_recordset(p_id_map -> 'objectives') as objective_map(
    ref uuid,
    id uuid
  ) on objective_map.ref = source_objective.id
  order by source_objective.copy_position;

  insert into public.course_attachment (
    course_id,
    stored_file_id,
    created_at,
    updated_at
  )
  select
    p_target_course_id,
    source_attachment.stored_file_id,
    clock_timestamp(),
    clock_timestamp()
  from public.course_attachment as source_attachment
  where source_attachment.course_id = p_source_course_id;

  insert into public.lesson (
    id,
    course_id,
    position,
    title,
    summary,
    estimated_duration_minutes,
    settings,
    created_at,
    updated_at
  )
  select
    lesson_map.id,
    p_target_course_id,
    source_lesson.position,
    source_lesson.title,
    source_lesson.summary,
    source_lesson.estimated_duration_minutes,
    source_lesson.settings,
    clock_timestamp(),
    clock_timestamp()
  from public.lesson as source_lesson
  join jsonb_to_recordset(p_id_map -> 'lessons') as lesson_map(
    ref uuid,
    id uuid
  ) on lesson_map.ref = source_lesson.id
  where source_lesson.course_id = p_source_course_id;

  insert into public.lesson_student_slide (
    id,
    lesson_id,
    position,
    created_at,
    updated_at
  )
  select
    slide_map.id,
    lesson_map.id,
    source_slide.position,
    clock_timestamp(),
    clock_timestamp()
  from public.lesson_student_slide as source_slide
  join public.lesson as source_lesson
    on source_lesson.id = source_slide.lesson_id
  join jsonb_to_recordset(p_id_map -> 'lessons') as lesson_map(
    ref uuid,
    id uuid
  ) on lesson_map.ref = source_lesson.id
  join jsonb_to_recordset(p_id_map -> 'slides') as slide_map(
    ref uuid,
    id uuid
  ) on slide_map.ref = source_slide.id
  where source_lesson.course_id = p_source_course_id;

  insert into public.lesson_component (
    id,
    lesson_id,
    position,
    type_key,
    schema_version,
    payload,
    placement_config,
    visibility,
    student_slide_id,
    primary_learning_objective_id,
    activity_role,
    created_at,
    updated_at
  )
  select
    component_map.id,
    lesson_map.id,
    source_component.position,
    source_component.type_key,
    source_component.schema_version,
    source_component.payload,
    source_component.placement_config,
    source_component.visibility,
    slide_map.id,
    objective_map.id,
    source_component.activity_role,
    clock_timestamp(),
    clock_timestamp()
  from public.lesson_component as source_component
  join public.lesson as source_lesson
    on source_lesson.id = source_component.lesson_id
  join jsonb_to_recordset(p_id_map -> 'lessons') as lesson_map(
    ref uuid,
    id uuid
  ) on lesson_map.ref = source_lesson.id
  join jsonb_to_recordset(p_id_map -> 'components') as component_map(
    ref uuid,
    id uuid
  ) on component_map.ref = source_component.id
  left join jsonb_to_recordset(p_id_map -> 'slides') as slide_map(
    ref uuid,
    id uuid
  ) on slide_map.ref = source_component.student_slide_id
  left join jsonb_to_recordset(p_id_map -> 'objectives') as objective_map(
    ref uuid,
    id uuid
  ) on objective_map.ref = source_component.primary_learning_objective_id
  where source_lesson.course_id = p_source_course_id;

  update public.learning_objective as objective
  set archived_at = source_objective.archived_at
  from public.learning_objective as source_objective
  join jsonb_to_recordset(p_id_map -> 'objectives') as objective_map(
    ref uuid,
    id uuid
  ) on objective_map.ref = source_objective.id
  where source_objective.course_id = p_source_course_id
    and source_objective.archived_at is not null
    and objective.id = objective_map.id;

  return jsonb_build_object('courseId', p_target_course_id);
end
$$;


--
-- Name: duplicate_course_with_attestation_admin(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duplicate_course_with_attestation_admin(p_actor_account_id uuid, p_source_course_id uuid, p_target_course_id uuid, p_target_title text, p_id_map jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if exists (
    select 1
    from public.course as course
    where course.id = p_source_course_id
      and course.owner_account_id = p_actor_account_id
      and course.learning_audience = 'educators'
  ) then
    raise exception 'educator_course_duplicate_forbidden'
      using errcode = '42501';
  end if;

  v_result := public.duplicate_course_admin(
    p_actor_account_id,
    p_source_course_id,
    p_target_course_id,
    p_target_title,
    p_id_map
  );

  return v_result || jsonb_build_object('learningAudience', 'children');
end
$$;


--
-- Name: educator_course_author_can_mutate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.educator_course_author_can_mutate(p_course_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce((
    select course.learning_audience = 'children'
      or (
        account.status = 'active'
        and account.can_author_educator_courses
      )
    from public.course as course
    join public.account as account on account.id = course.owner_account_id
    where course.id = p_course_id
  ), false);
$$;


--
-- Name: emit_lesson_run_communication_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_lesson_run_communication_notifications() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
  v_course_title text;
  v_lesson_title text;
  v_owner_account_id uuid;
  v_event_revision text;
  v_audience_dedupe_key text;
  v_latest_audience_dedupe_key text;
  v_current_learner_account_ids uuid[] := '{}'::uuid[];
  v_previous_learner_account_ids uuid[] := '{}'::uuid[];
  v_schedule_fact_changed boolean := false;
  v_roster_changed boolean := false;
  v_removed_account_id uuid;
  v_learner_body text;
  v_recipient record;
  v_total_count integer;
  v_present_count integer;
  v_repeat_count integer;
  v_record record;
begin
  select
    course.id,
    course.title,
    lesson.title,
    course.owner_account_id
  into
    v_course_id,
    v_course_title,
    v_lesson_title,
    v_owner_account_id
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  where lesson.id = new.lesson_id;

  if not found then
    return null;
  end if;

  select coalesce(
    array_agg(audience.account_id order by audience.account_id),
    '{}'::uuid[]
  )
  into v_current_learner_account_ids
  from (
    select distinct learner_account.id as account_id
    from public.learning_record as record
    join public.learner_profile as profile
      on profile.id = record.learner_profile_id
    join public.account as learner_account
      on learner_account.id = profile.account_id
     and learner_account.status = 'active'
    where record.lesson_run_id = new.id
      and record.superseded_by_record_id is null
      and learner_account.id <> v_owner_account_id
  ) as audience;

  select notification.dedupe_key
  into v_latest_audience_dedupe_key
  from public.system_notification as notification
  where notification.event_type in (
      'lesson_run.scheduled',
      'lesson_run.rescheduled'
    )
    and notification.payload ->> 'lessonRunId' = new.id::text
  order by notification.id desc
  limit 1;

  if v_latest_audience_dedupe_key is not null then
    select coalesce(
      array_agg(audience.account_id order by audience.account_id),
      '{}'::uuid[]
    )
    into v_previous_learner_account_ids
    from (
      select distinct notification.recipient_account_id as account_id
      from public.system_notification as notification
      join public.account as learner_account
        on learner_account.id = notification.recipient_account_id
       and learner_account.status = 'active'
      where notification.dedupe_key = v_latest_audience_dedupe_key
        and notification.event_type in (
          'lesson_run.scheduled',
          'lesson_run.rescheduled'
        )
        and notification.payload ->> 'recipientKind' = 'learner'
        and notification.recipient_account_id <> v_owner_account_id
    ) as audience;
  end if;

  if tg_op = 'UPDATE' then
    v_schedule_fact_changed :=
      new.scheduled_at is distinct from old.scheduled_at
      or new.planned_duration_minutes is distinct from
        old.planned_duration_minutes;
  end if;
  v_roster_changed := v_current_learner_account_ids is distinct from
    v_previous_learner_account_ids;

  v_event_revision := md5(
    concat_ws(
      ':',
      new.id::text,
      new.scheduled_at::text,
      new.planned_duration_minutes::text,
      new.cancelled_at::text,
      new.ended_at::text,
      new.updated_at::text,
      array_to_string(v_current_learner_account_ids, ',')
    )
  );

  if tg_op = 'INSERT' then
    v_audience_dedupe_key := 'lesson_run:scheduled:'
      || new.id::text || ':' || v_event_revision;

    for v_recipient in
      select participant.account_id, participant.recipient_kind
      from (
        select v_owner_account_id as account_id, 'owner'::text as recipient_kind
        union
        select learner.account_id, 'learner'::text
        from unnest(v_current_learner_account_ids) as learner(account_id)
      ) as participant
    loop
      perform public.append_system_notification_internal(
        v_recipient.account_id,
        'lesson_run.scheduled',
        'success',
        'Урок назначен',
        'Урок «' || v_lesson_title || '» назначен.',
        jsonb_build_object(
          'courseId', v_course_id,
          'lessonId', new.lesson_id,
          'lessonRunId', new.id,
          'courseTitle', v_course_title,
          'lessonTitle', v_lesson_title,
          'scheduledAt', new.scheduled_at,
          'plannedDurationMinutes', new.planned_duration_minutes,
          'recipientKind', v_recipient.recipient_kind
        ),
        v_audience_dedupe_key,
        new.created_at
      );
    end loop;
  elsif new.cancelled_at is null
    and new.ended_at is null
    and (v_schedule_fact_changed or v_roster_changed)
  then
    v_audience_dedupe_key := 'lesson_run:rescheduled:'
      || new.id::text || ':' || v_event_revision;

    for v_recipient in
      select participant.account_id, participant.recipient_kind
      from (
        select v_owner_account_id as account_id, 'owner'::text as recipient_kind
        union
        select learner.account_id, 'learner'::text
        from unnest(v_current_learner_account_ids) as learner(account_id)
      ) as participant
    loop
      perform public.append_system_notification_internal(
        v_recipient.account_id,
        'lesson_run.rescheduled',
        'info',
        'Урок изменён',
        'Параметры урока «' || v_lesson_title || '» обновлены.',
        jsonb_build_object(
          'courseId', v_course_id,
          'lessonId', new.lesson_id,
          'lessonRunId', new.id,
          'courseTitle', v_course_title,
          'lessonTitle', v_lesson_title,
          'scheduledAt', new.scheduled_at,
          'previousScheduledAt', old.scheduled_at,
          'plannedDurationMinutes', new.planned_duration_minutes,
          'previousPlannedDurationMinutes', old.planned_duration_minutes,
          'scheduledAtChanged',
            new.scheduled_at is distinct from old.scheduled_at,
          'plannedDurationChanged',
            new.planned_duration_minutes is distinct from
              old.planned_duration_minutes,
          'audienceChanged', v_roster_changed,
          'recipientKind', v_recipient.recipient_kind
        ),
        v_audience_dedupe_key,
        new.updated_at
      );
    end loop;

    for v_removed_account_id in
      select previous.account_id
      from unnest(v_previous_learner_account_ids) as previous(account_id)
      where not previous.account_id = any(v_current_learner_account_ids)
      order by previous.account_id
    loop
      perform public.append_system_notification_internal(
        v_removed_account_id,
        'lesson_run.removed_from_schedule',
        'warning',
        'Урок больше не назначен',
        'Урок «' || v_lesson_title || '» больше вам не назначен.',
        jsonb_build_object(
          'courseId', v_course_id,
          'lessonId', new.lesson_id,
          'lessonRunId', new.id,
          'courseTitle', v_course_title,
          'lessonTitle', v_lesson_title,
          'scheduledAt', new.scheduled_at,
          'previousScheduledAt', old.scheduled_at,
          'plannedDurationMinutes', new.planned_duration_minutes,
          'previousPlannedDurationMinutes', old.planned_duration_minutes,
          'recipientKind', 'removed_learner',
          'changeKind', 'removed_from_schedule'
        ),
        v_audience_dedupe_key,
        new.updated_at
      );
    end loop;
  end if;

  if tg_op = 'UPDATE'
    and new.cancelled_at is not null
    and old.cancelled_at is null
  then
    -- cancel_lesson_run intentionally removes draft LearningRecords before it
    -- updates the run. The latest committed scheduling fact is therefore the
    -- durable, exact audience snapshot for cancellation delivery.
    for v_recipient in
      select participant.account_id, participant.recipient_kind
      from (
        select v_owner_account_id as account_id, 'owner'::text as recipient_kind
        union
        select learner.account_id, 'learner'::text
        from unnest(v_previous_learner_account_ids) as learner(account_id)
      ) as participant
    loop
      perform public.append_system_notification_internal(
        v_recipient.account_id,
        'lesson_run.cancelled',
        'warning',
        'Урок отменён',
        'Урок «' || v_lesson_title || '» отменён.',
        jsonb_build_object(
          'courseId', v_course_id,
          'lessonId', new.lesson_id,
          'lessonRunId', new.id,
          'courseTitle', v_course_title,
          'lessonTitle', v_lesson_title,
          'scheduledAt', new.scheduled_at,
          'cancelledAt', new.cancelled_at,
          'recipientKind', v_recipient.recipient_kind
        ),
        'lesson_run:cancelled:' || new.id::text || ':' || v_event_revision,
        new.cancelled_at
      );
    end loop;
  end if;

  if tg_op = 'UPDATE'
    and new.ended_at is not null
    and old.ended_at is null
  then
    select
      count(*),
      count(*) filter (where record.was_present),
      count(*) filter (where record.was_present and record.needs_repeat)
    into v_total_count, v_present_count, v_repeat_count
    from public.learning_record as record
    where record.lesson_run_id = new.id
      and record.occurred_at is not null
      and record.superseded_by_record_id is null;

    perform public.append_system_notification_internal(
      v_owner_account_id,
      'lesson_run.completed_owner',
      'success',
      'Урок завершён',
      'Урок «' || v_lesson_title || '» завершён. Присутствовали '
        || v_present_count::text || ' из ' || v_total_count::text || '.',
      jsonb_build_object(
        'courseId', v_course_id,
        'lessonId', new.lesson_id,
        'lessonRunId', new.id,
        'courseTitle', v_course_title,
        'lessonTitle', v_lesson_title,
        'endedAt', new.ended_at,
        'actualDurationMinutes', new.actual_duration_minutes,
        'learnerCount', v_total_count,
        'presentCount', v_present_count,
        'needsRepeatCount', v_repeat_count,
        'recipientKind', 'owner'
      ),
      'lesson_run:completed_owner:' || new.id::text || ':' || v_event_revision,
      new.ended_at
    );

    for v_record in
      select
        learner_account.id as account_id,
        record.was_present,
        record.needs_repeat,
        record.actual_duration_minutes_at_time,
        case
          when record.shared_with_learner_at is not null
            then record.teacher_comment
          else null
        end as shared_comment
      from public.learning_record as record
      join public.learner_profile as profile
        on profile.id = record.learner_profile_id
      join public.account as learner_account
        on learner_account.id = profile.account_id
       and learner_account.status = 'active'
      where record.lesson_run_id = new.id
        and record.occurred_at is not null
        and record.superseded_by_record_id is null
        and learner_account.id <> v_owner_account_id
    loop
      v_learner_body := 'Урок «' || v_lesson_title || '» завершён. '
        || case
          when v_record.was_present then 'Вы присутствовали. '
          else 'Вы отсутствовали. '
        end
        || case
          when v_record.needs_repeat then 'Материал нужно повторить. '
          else 'Повторение не требуется. '
        end
        || case
          when v_record.actual_duration_minutes_at_time is null
            then 'Длительность не указана.'
          else 'Длительность: '
            || v_record.actual_duration_minutes_at_time::text || ' мин.'
        end
        || case
          when v_record.shared_comment is null
            or btrim(v_record.shared_comment) = ''
            then ''
          else ' Комментарий преподавателя: ' || v_record.shared_comment
        end;

      perform public.append_system_notification_internal(
        v_record.account_id,
        'lesson_run.completed_learner',
        'success',
        'Урок завершён',
        v_learner_body,
        jsonb_build_object(
          'courseId', v_course_id,
          'lessonId', new.lesson_id,
          'lessonRunId', new.id,
          'courseTitle', v_course_title,
          'lessonTitle', v_lesson_title,
          'endedAt', new.ended_at,
          'wasPresent', v_record.was_present,
          'needsRepeat', v_record.needs_repeat,
          'actualDurationMinutes', v_record.actual_duration_minutes_at_time,
          'sharedComment', v_record.shared_comment,
          'recipientKind', 'learner'
        ),
        'lesson_run:completed_learner:' || new.id::text || ':' || v_event_revision,
        new.ended_at
      );
    end loop;
  end if;

  return null;
end
$$;


--
-- Name: enforce_account_exactly_one_learner_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_account_exactly_one_learner_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
begin
  for v_account_id in
    select distinct candidate.account_id
    from (
      select case when tg_table_name = 'account' and tg_op <> 'DELETE'
        then (to_jsonb(new) ->> 'id')::uuid
        when tg_table_name = 'learner_profile' and tg_op <> 'DELETE'
        then (to_jsonb(new) ->> 'account_id')::uuid end as account_id
      union all
      select case when tg_table_name = 'account' and tg_op <> 'INSERT'
        then (to_jsonb(old) ->> 'id')::uuid
        when tg_table_name = 'learner_profile' and tg_op <> 'INSERT'
        then (to_jsonb(old) ->> 'account_id')::uuid end
    ) as candidate
    where candidate.account_id is not null
  loop
    if exists (
      select 1
      from public.account as account
      where account.id = v_account_id
        and account.status in ('active', 'provisional')
    ) and (
      select count(*)
      from public.learner_profile as profile
      where profile.account_id = v_account_id
    ) <> 1 then
      raise exception 'account_requires_exactly_one_learner_profile'
        using errcode = '23514';
    end if;
  end loop;

  return null;
end
$$;


--
-- Name: enforce_course_learner_group_same_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_course_learner_group_same_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.course as course
    join public.learner_group as learner_group
      on learner_group.id = new.learner_group_id
    where course.id = new.course_id
      and course.owner_account_id = learner_group.owner_account_id
  ) then
    raise exception
      'course_learner_group_owner_mismatch'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: enforce_course_learner_teacher_relation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_course_learner_teacher_relation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.course as course
    join public.teacher_learner as teacher_learner
      on teacher_learner.teacher_account_id = course.owner_account_id
     and teacher_learner.learner_profile_id = new.learner_profile_id
     and teacher_learner.archived_at is null
    where course.id = new.course_id
  ) then
    raise exception
      'course_learner_teacher_relation_missing'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: enforce_course_publication_account_storage_quota(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_course_publication_account_storage_quota() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_owner_account_id uuid;
  v_existing_snapshot_bytes bigint;
  v_existing_asset_bytes bigint;
  v_candidate_bytes bigint;
begin
  if tg_table_name = 'course_publication_revision' then
    select publication.owner_account_id
    into v_owner_account_id
    from public.course_publication as publication
    where publication.id = new.publication_id;

    v_candidate_bytes := octet_length(new.snapshot::text)::bigint;
  elsif tg_table_name = 'course_publication_asset' then
    select publication.owner_account_id
    into v_owner_account_id
    from public.course_publication_revision as revision
    join public.course_publication as publication
      on publication.id = revision.publication_id
    where revision.id = new.revision_id;

    v_candidate_bytes := new.size_bytes;
  else
    raise exception 'course_publication_quota_table_not_supported'
      using errcode = '55000';
  end if;

  if v_owner_account_id is null or v_candidate_bytes is null then
    raise exception 'course_publication_quota_owner_not_found'
      using errcode = '23503';
  end if;

  perform 1
  from public.account as account
  where account.id = v_owner_account_id
  for update;

  if not found then
    raise exception 'course_publication_quota_owner_not_found'
      using errcode = '23503';
  end if;

  select coalesce(
    sum(octet_length(revision.snapshot::text)::bigint),
    0
  )
  into v_existing_snapshot_bytes
  from public.course_publication_revision as revision
  join public.course_publication as publication
    on publication.id = revision.publication_id
  where publication.owner_account_id = v_owner_account_id;

  select coalesce(sum(asset.size_bytes), 0)
  into v_existing_asset_bytes
  from public.course_publication_asset as asset
  join public.course_publication_revision as revision
    on revision.id = asset.revision_id
  join public.course_publication as publication
    on publication.id = revision.publication_id
  where publication.owner_account_id = v_owner_account_id;

  if v_existing_snapshot_bytes
      + v_existing_asset_bytes
      + v_candidate_bytes > 5368709120
  then
    raise exception 'course_publication_account_quota_exceeded'
      using errcode = 'P0001';
  end if;

  return new;
end
$$;


--
-- Name: enforce_course_publication_revision_asset_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_course_publication_revision_asset_limits() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_asset_count integer;
  v_total_bytes bigint;
begin
  select count(*)::integer, coalesce(sum(asset.size_bytes), 0)
  into v_asset_count, v_total_bytes
  from public.course_publication_asset as asset
  where asset.revision_id = new.revision_id;

  if v_asset_count > 24 or v_total_bytes > 125829120 then
    raise exception 'course_publication_revision_asset_limit_exceeded'
      using errcode = '54000';
  end if;

  return new;
end
$$;


--
-- Name: enforce_learner_group_member_teacher_relation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_learner_group_member_teacher_relation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.learner_group as learner_group
    join public.teacher_learner as teacher_learner
      on teacher_learner.teacher_account_id = learner_group.owner_account_id
     and teacher_learner.learner_profile_id = new.learner_profile_id
     and teacher_learner.archived_at is null
    where learner_group.id = new.learner_group_id
  ) then
    raise exception
      'learner_group_member_teacher_relation_missing'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: enforce_learning_record_producer_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_learning_record_producer_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.recorded_by_account_id is distinct from old.recorded_by_account_id then
    raise exception
      'learning_record_producer_is_immutable'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: enforce_lesson_student_screen_invariants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_lesson_student_screen_invariants() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_lesson_id uuid;
begin
  for v_lesson_id in
    select distinct candidate.lesson_id
    from (
      select case when tg_op <> 'DELETE' then new.lesson_id end as lesson_id
      union all
      select case when tg_op <> 'INSERT' then old.lesson_id end
    ) as candidate
    where candidate.lesson_id is not null
  loop
    -- During ON DELETE CASCADE the parent Lesson may already be gone.
    if not exists (
      select 1 from public.lesson where lesson.id = v_lesson_id
    ) then
      continue;
    end if;

    if exists (
      select 1
      from public.lesson_component as component
      left join public.lesson_student_slide as slide
        on slide.id = component.student_slide_id
      where component.lesson_id = v_lesson_id
        and (
          (component.visibility = 'staff_only'
            and component.student_slide_id is not null)
          or
          (component.visibility = 'learner_visible'
            and (
              component.student_slide_id is null
              or slide.id is null
              or slide.lesson_id <> component.lesson_id
            ))
        )
    ) then
      raise exception
        'lesson_student_screen_assignment_inconsistent'
        using errcode = '23514';
    end if;

    if exists (
      select 1
      from public.lesson_student_slide as slide
      where slide.lesson_id = v_lesson_id
        and not exists (
          select 1
          from public.lesson_component as component
          where component.student_slide_id = slide.id
            and component.visibility = 'learner_visible'
        )
    ) then
      raise exception
        'lesson_student_screen_contains_empty_slide'
        using errcode = '23514';
    end if;

    if exists (
      select 1
      from public.lesson_student_slide as slide
      where slide.lesson_id = v_lesson_id
      group by slide.lesson_id
      having min(slide.position) <> 1
        or max(slide.position) <> count(*)
        or count(distinct slide.position) <> count(*)
    ) then
      raise exception
        'lesson_student_slide_positions_are_not_dense'
        using errcode = '23514';
    end if;

    if exists (
      with visible_components as (
        select
          component.position,
          slide.position as slide_position,
          lag(slide.position) over (
            order by component.position
          ) as previous_slide_position
        from public.lesson_component as component
        join public.lesson_student_slide as slide
          on slide.id = component.student_slide_id
        where component.lesson_id = v_lesson_id
          and component.visibility = 'learner_visible'
      )
      select 1
      from visible_components
      where previous_slide_position > slide_position
    ) then
      raise exception
        'lesson_student_slide_order_conflict'
        using errcode = '23514';
    end if;
  end loop;

  return null;
end
$$;


--
-- Name: execute_learner_profile_merge_for_actor(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_learner_profile_merge_for_actor(p_merge_operation_id uuid, p_actor_account_id uuid, p_preview_fingerprint text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.learner_profile_merge%rowtype;
  v_preview jsonb;
  v_source_id uuid;
  v_target_id uuid;
  v_pair record;
  v_projection_key record;
  v_projection_at timestamptz;
  v_override_conflict_count integer := 0;
begin
  select operation.* into v_operation
  from public.learner_profile_merge as operation
  where operation.id = p_merge_operation_id;
  if not found or v_operation.subject_account_id <> p_actor_account_id then
    raise exception 'learner_profile_merge_not_found' using errcode = 'P0002';
  end if;
  if v_operation.status = 'completed' then
    return v_operation.target_learner_profile_id;
  end if;

  v_source_id := v_operation.source_learner_profile_id;
  v_target_id := v_operation.target_learner_profile_id;
  perform public.lock_learning_activity_learners(
    array[v_source_id, v_target_id]
  );

  perform 1 from public.account as account
  where account.id = p_actor_account_id
  for update of account;
  perform 1 from public.learner_profile as profile
  where profile.id in (v_source_id, v_target_id)
  order by profile.id
  for update of profile;
  perform 1 from public.learner_profile_merge as operation
  where operation.id = p_merge_operation_id
  for update of operation;

  select operation.* into v_operation
  from public.learner_profile_merge as operation
  where operation.id = p_merge_operation_id;
  if v_operation.status = 'completed' then
    return v_operation.target_learner_profile_id;
  end if;
  if v_operation.subject_account_id <> p_actor_account_id
    or v_operation.source_learner_profile_id <> v_source_id
    or v_operation.target_learner_profile_id <> v_target_id
  then
    raise exception 'learner_profile_merge_preview_stale'
      using errcode = '40001';
  end if;

  perform course.id
  from public.course as course
  where course.id in (
    select direct.course_id
    from public.course_learner as direct
    where direct.learner_profile_id in (v_source_id, v_target_id)
    union
    select course_group.course_id
    from public.course_learner_group as course_group
    join public.learner_group_member as member
      on member.learner_group_id = course_group.learner_group_id
    where member.learner_profile_id in (v_source_id, v_target_id)
  )
  order by course.id
  for update of course;
  perform learner_group.id
  from public.learner_group as learner_group
  where learner_group.id in (
    select member.learner_group_id
    from public.learner_group_member as member
    where member.learner_profile_id in (v_source_id, v_target_id)
  )
  order by learner_group.id
  for update of learner_group;
  perform 1 from public.teacher_learner as relation
  where relation.learner_profile_id in (v_source_id, v_target_id)
  order by relation.teacher_account_id, relation.learner_profile_id
  for update of relation;
  perform 1 from public.course_learner as direct
  where direct.learner_profile_id in (v_source_id, v_target_id)
  order by direct.course_id, direct.learner_profile_id
  for update of direct;
  perform 1 from public.learner_group_member as member
  where member.learner_profile_id in (v_source_id, v_target_id)
  order by member.learner_group_id, member.learner_profile_id
  for update of member;
  perform run.id
  from public.lesson_run as run
  where run.id in (
    select record.lesson_run_id
    from public.learning_record as record
    where record.learner_profile_id in (v_source_id, v_target_id)
      and record.lesson_run_id is not null
  )
  order by run.id
  for update of run;
  perform 1 from public.learning_record as record
  where record.learner_profile_id in (v_source_id, v_target_id)
  order by coalesce(record.lesson_run_id, record.id), record.id
  for update of record;
  perform 1 from public.learning_evidence as evidence
  where evidence.learner_profile_id in (v_source_id, v_target_id)
  order by evidence.id
  for update of evidence;
  perform link.learning_evidence_id
  from public.learner_objective_state_evidence as link
  join public.learner_objective_state as state
    on state.id = link.learner_objective_state_id
  where state.learner_profile_id in (v_source_id, v_target_id)
  order by link.learner_objective_state_id, link.position
  for update of link;
  perform 1 from public.learner_objective_state as state
  where state.learner_profile_id in (v_source_id, v_target_id)
  order by
    state.recorded_by_account_id,
    state.source_course_id_at_time,
    state.source_learning_objective_id_at_time
  for update of state;
  perform 1 from public.learner_recommendation_override as override_row
  where override_row.learner_profile_id in (v_source_id, v_target_id)
  order by
    override_row.recorded_by_account_id,
    override_row.source_course_id_at_time,
    override_row.source_learning_objective_id_at_time,
    override_row.id
  for update of override_row;
  perform 1 from public.learner_observer_grant as grant_row
  where grant_row.learner_profile_id = v_source_id
  order by grant_row.id
  for update of grant_row;
  perform 1 from public.learner_ai_consent as consent
  where consent.learner_profile_id = v_source_id
  order by consent.id
  for update of consent;

  v_preview := public.learner_profile_merge_preview_for_actor(
    p_merge_operation_id,
    p_actor_account_id
  );
  if not coalesce((v_preview ->> 'canConfirm')::boolean, false) then
    raise exception 'learner_profile_merge_blocked' using errcode = '55000';
  end if;
  if p_preview_fingerprint is null
    or p_preview_fingerprint <> v_preview ->> 'previewFingerprint'
  then
    raise exception 'learner_profile_merge_preview_stale'
      using errcode = '40001';
  end if;
  if v_operation.learning_activity_scope_fingerprint is null
    or v_operation.learning_activity_scope_fingerprint is distinct from
      public.learning_activity_scope_fingerprint(
        array[v_source_id, v_target_id]
      )
  then
    raise exception 'learner_profile_merge_preview_stale'
      using errcode = '40001';
  end if;

  insert into public.learner_profile_merge_private_detail (
    merge_operation_id,
    teacher_account_id,
    discarded_source_display_name
  )
  select p_merge_operation_id, source.teacher_account_id, source.display_name
  from public.teacher_learner as source
  join public.teacher_learner as target
    on target.teacher_account_id = source.teacher_account_id
   and target.learner_profile_id = v_target_id
  where source.learner_profile_id = v_source_id
  on conflict do nothing;

  update public.teacher_learner as target
  set archived_at = case
        when target.archived_at is null or source.archived_at is null then null
        else greatest(target.archived_at, source.archived_at)
      end
  from public.teacher_learner as source
  where target.learner_profile_id = v_target_id
    and source.learner_profile_id = v_source_id
    and source.teacher_account_id = target.teacher_account_id;

  delete from public.teacher_learner as source
  using public.teacher_learner as target
  where source.learner_profile_id = v_source_id
    and target.learner_profile_id = v_target_id
    and target.teacher_account_id = source.teacher_account_id;

  update public.teacher_learner
  set learner_profile_id = v_target_id
  where learner_profile_id = v_source_id;

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select learner_group_id, v_target_id
  from public.learner_group_member
  where learner_profile_id = v_source_id
  on conflict do nothing;
  delete from public.learner_group_member
  where learner_profile_id = v_source_id;

  insert into public.course_learner (course_id, learner_profile_id)
  select course_id, v_target_id
  from public.course_learner
  where learner_profile_id = v_source_id
  on conflict do nothing;
  delete from public.course_learner
  where learner_profile_id = v_source_id;

  -- Keep the most recent explicit decision for a duplicate stable key.
  with ranked as (
    select
      override_row.id,
      row_number() over (
        partition by
          override_row.recorded_by_account_id,
          override_row.source_course_id_at_time,
          override_row.source_learning_objective_id_at_time
        order by override_row.updated_at desc, override_row.id desc
      ) as preference_rank
    from public.learner_recommendation_override as override_row
    where override_row.learner_profile_id in (v_source_id, v_target_id)
  )
  delete from public.learner_recommendation_override as override_row
  using ranked
  where override_row.id = ranked.id
    and ranked.preference_rank > 1;
  get diagnostics v_override_conflict_count = row_count;

  update public.learner_recommendation_override as override_row
  set learner_objective_state_id = null
  where override_row.learner_profile_id in (v_source_id, v_target_id);

  delete from public.learner_objective_state as state
  where state.learner_profile_id in (v_source_id, v_target_id);

  for v_pair in
    select
      source_record.id as source_record_id,
      target_record.id as target_record_id,
      source_record.lesson_run_id
    from public.learning_record as source_record
    join public.learning_record as target_record
      on target_record.lesson_run_id = source_record.lesson_run_id
     and target_record.learner_profile_id = v_target_id
    where source_record.learner_profile_id = v_source_id
      and source_record.lesson_run_id is not null
      and source_record.occurred_at is not null
      and source_record.superseded_by_record_id is null
      and target_record.occurred_at is not null
      and target_record.superseded_by_record_id is null
    order by source_record.lesson_run_id, source_record.id
  loop
    update public.learning_record
    set lesson_run_id = null,
        superseded_by_record_id = v_pair.target_record_id
    where id = v_pair.source_record_id;

    insert into public.learner_profile_merge_conflict (
      merge_operation_id,
      lesson_run_id,
      primary_record_id,
      superseded_record_id,
      resolution
    ) values (
      p_merge_operation_id,
      v_pair.lesson_run_id,
      v_pair.target_record_id,
      v_pair.source_record_id,
      'keep_target_primary'
    ) on conflict do nothing;
  end loop;

  perform set_config('app.learner_identity_merge', 'on', true);
  update public.learning_record
  set learner_profile_id = v_target_id
  where learner_profile_id = v_source_id;

  update public.learner_recommendation_override
  set learner_profile_id = v_target_id
  where learner_profile_id = v_source_id;

  update public.learner_claim_invitation
  set status = 'revoked', revoked_at = now()
  where source_learner_profile_id = v_source_id
    and id is distinct from v_operation.invitation_id
    and status in ('pending', 'bound');

  insert into public.learner_profile_alias (
    source_learner_profile_id,
    target_learner_profile_id,
    merge_operation_id
  ) values (
    v_source_id, v_target_id, p_merge_operation_id
  ) on conflict (source_learner_profile_id) do nothing;

  v_projection_at := clock_timestamp();
  for v_projection_key in
    select distinct
      evidence.recorded_by_account_id,
      evidence.source_learning_objective_id_at_time
    from public.learning_evidence as evidence
    join public.learning_record as record
      on record.id = evidence.learning_record_id
    where evidence.learner_profile_id = v_target_id
      and evidence.superseded_by_evidence_id is null
      and record.superseded_by_record_id is null
    order by
      evidence.recorded_by_account_id,
      evidence.source_learning_objective_id_at_time
  loop
    perform public.rebuild_learner_objective_state_for_actor(
      v_projection_key.recorded_by_account_id,
      v_target_id,
      v_projection_key.source_learning_objective_id_at_time,
      v_projection_at
    );
  end loop;

  perform set_config('app.learner_profile_link_mutation', 'on', true);
  delete from public.learner_profile where id = v_source_id;

  update public.learner_profile_merge
  set status = 'completed', completed_at = now()
  where id = p_merge_operation_id;

  update public.learner_claim_invitation
  set status = 'accepted', accepted_at = now()
  where id = v_operation.invitation_id
    and status in ('pending', 'bound');

  perform public.append_learner_identity_audit(
    'learner_profile_merge_completed',
    p_actor_account_id,
    p_actor_account_id,
    v_target_id,
    v_source_id,
    p_merge_operation_id,
    jsonb_build_object(
      'conflictCount', jsonb_array_length(v_preview -> 'conflicts'),
      'learningActivityOverrideConflictCount', v_override_conflict_count,
      'learningActivityProjectionVersion', 1,
      'projectionVersion', 1
    )
  );

  return v_target_id;
end
$$;


--
-- Name: get_my_assistant_conversation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_assistant_conversation(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_result jsonb;
begin
  if v_actor_account_id is null or p_conversation_id is null then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  v_result := public.assistant_conversation_projection(
    p_conversation_id,
    v_actor_account_id
  );

  if v_result is null then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  return v_result;
end
$$;


--
-- Name: get_my_authored_course_attestation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_authored_course_attestation(p_course_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_attestation public.course_attestation%rowtype;
begin
  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
    and account.can_author_educator_courses;

  if not found then
    raise exception 'educator_course_authoring_not_allowed'
      using errcode = '42501';
  end if;

  perform 1
  from public.course as course
  where course.id = p_course_id
    and course.owner_account_id = v_account_id
    and course.archived_at is null
    and course.learning_audience = 'educators';

  if not found then
    raise exception 'course_attestation_course_not_found'
      using errcode = 'P0002';
  end if;

  select attestation.*
  into v_attestation
  from public.course_attestation as attestation
  where attestation.course_id = p_course_id;

  if not found then
    return null;
  end if;

  return jsonb_build_object(
    'version', v_attestation.version,
    'title', v_attestation.title,
    'description', v_attestation.description,
    'passingScorePercent', v_attestation.passing_score_percent,
    'questions', v_attestation.questions
  );
end
$$;


--
-- Name: get_my_course_publication_attestation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_course_publication_attestation(p_publication_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_publication public.course_publication%rowtype;
  v_attestation public.course_publication_attestation%rowtype;
  v_attempt public.course_attestation_attempt%rowtype;
  v_award public.course_attestation_award%rowtype;
  v_certified boolean := false;
  v_attempt_found boolean := false;
  v_questions jsonb;
begin
  if p_publication_id is null then
    raise exception 'course_attestation_not_found'
      using errcode = 'P0002';
  end if;

  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active';

  if not found then
    raise exception 'course_attestation_account_not_active'
      using errcode = '42501';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id
  where publication.id = p_publication_id
    and publication.status = 'published'
    and publication.learning_audience = 'educators'
    and publication.is_shidao
    and publication.approved_revision_id is not null
    and owner_account.status = 'active'
    and exists (
      select 1
      from public.educator_course_revision_review as review
      where review.publication_id = publication.id
        and review.revision_id = publication.approved_revision_id
        and review.status = 'approved'
    );

  if not found then
    raise exception 'course_attestation_not_found'
      using errcode = 'P0002';
  end if;

  select attestation.*
  into v_attestation
  from public.course_publication_attestation as attestation
  where attestation.publication_id = v_publication.id
    and attestation.revision_id = v_publication.approved_revision_id;

  if not found then
    raise exception 'course_attestation_not_found'
      using errcode = 'P0002';
  end if;

  if not coalesce((
    public.build_course_publication_progress_admin(
      v_account_id,
      v_publication.id,
      v_attestation.revision_id
    ) ->> 'complete'
  )::boolean, false) then
    raise exception 'course_attestation_lessons_incomplete'
      using errcode = '55000';
  end if;

  select award.*
  into v_award
  from public.course_attestation_award as award
  where award.account_id = v_account_id
    and award.publication_id = v_publication.id
    and award.revision_id = v_attestation.revision_id;
  v_certified := found;

  if v_certified then
    select attempt.*
    into strict v_attempt
    from public.course_attestation_attempt as attempt
    where attempt.id = v_award.attempt_id;
    v_attempt_found := true;
  else
    select attempt.*
    into v_attempt
    from public.course_attestation_attempt as attempt
    where attempt.account_id = v_account_id
      and attempt.publication_id = v_publication.id
      and attempt.revision_id = v_attestation.revision_id
    order by attempt.completed_at desc, attempt.id desc
    limit 1;
    v_attempt_found := found;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', question.value ->> 'id',
        'prompt', question.value ->> 'prompt',
        'options', question.value -> 'options',
        'selectedOptionId', case
          when v_attempt_found then
            v_attempt.selected_option_by_question_id
              ->> (question.value ->> 'id')
          else null
        end,
        'correctOptionId', case
          when v_certified then question.value ->> 'correctOptionId'
          else null
        end,
        'explanation', case
          when v_certified then question.value ->> 'explanation'
          else null
        end
      )
      order by question.position
    ),
    '[]'::jsonb
  )
  into v_questions
  from jsonb_array_elements(v_attestation.questions) with ordinality
    as question(value, position);

  return jsonb_build_object(
    'publicationId', v_publication.id,
    'revisionId', v_attestation.revision_id,
    'title', v_attestation.title,
    'description', v_attestation.description,
    'passingScorePercent', v_attestation.passing_score_percent,
    'version', v_attestation.version,
    'questions', v_questions,
    'attempt', case
      when v_attempt_found then jsonb_build_object(
        'id', v_attempt.id,
        'scorePercent', v_attempt.score_percent,
        'passed', v_attempt.passed,
        'completedAt', v_attempt.completed_at,
        'selectedOptionByQuestionId',
          v_attempt.selected_option_by_question_id
      )
      else null
    end,
    'certified', v_certified
  );
end
$$;


--
-- Name: get_my_course_publication_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_course_publication_progress(p_publication_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_revision_id uuid;
begin
  if p_publication_id is null then
    raise exception 'educator_course_revision_not_available'
      using errcode = 'P0002';
  end if;

  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active';

  if not found then
    raise exception 'course_progress_account_not_active'
      using errcode = '42501';
  end if;

  select publication.approved_revision_id
  into v_revision_id
  from public.course_publication as publication
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id
  join public.educator_course_revision_review as review
    on review.publication_id = publication.id
   and review.revision_id = publication.approved_revision_id
   and review.status = 'approved'
  where publication.id = p_publication_id
    and publication.status = 'published'
    and publication.learning_audience = 'educators'
    and publication.is_shidao
    and publication.approved_revision_id is not null
    and owner_account.status = 'active';

  if not found then
    raise exception 'educator_course_revision_not_available'
      using errcode = 'P0002';
  end if;

  return public.build_course_publication_progress_admin(
    v_account_id,
    p_publication_id,
    v_revision_id
  );
end
$$;


--
-- Name: get_my_learning_activity_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_learning_activity_profile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile_id uuid;
  v_generated_at timestamptz := clock_timestamp();
begin
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  perform public.lock_learning_activity_learners(array[v_profile_id]);
  perform 1 from public.learner_profile as profile
  where profile.id = v_profile_id
    and profile.account_id = v_actor_account_id
  for update of profile;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  perform public.refresh_learning_activity_states_for_profile(
    v_profile_id,
    null,
    v_generated_at
  );
  return public.safe_learning_activity_profile_projection(
    v_profile_id,
    v_generated_at
  );
end
$$;


--
-- Name: get_my_learning_history(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_learning_history(p_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid := public.current_owned_learner_profile_id();
begin
  if v_profile_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  return public.learner_safe_history_projection(v_profile_id, p_cursor, p_limit);
end
$$;


--
-- Name: get_my_learning_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_learning_profile() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile public.learner_profile%rowtype;
  v_pending jsonb;
  v_unlink_preview jsonb;
begin
  select profile.* into v_profile
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', request.id, 'direction', 'incoming', 'status', request.status,
    'method', request.method,
    'counterpartyLabel', teacher.display_name,
    'localDisplayName', request.local_display_name,
    'learnerProfileId', v_profile.id,
    'expiresAt', request.expires_at, 'createdAt', request.created_at,
    'acceptedAt', request.accepted_at
  ) order by request.created_at desc), '[]'::jsonb)
  into v_pending
  from public.learner_connection_request as request
  join public.account as teacher on teacher.id = request.teacher_account_id
  where request.learner_profile_id = v_profile.id
    and request.status in ('pending', 'bound')
    and request.expires_at > now();
  v_unlink_preview := public.learner_safe_unlink_preview_for_actor(
    v_actor_account_id
  );
  return jsonb_build_object(
    'learnerProfileId', v_profile.id,
    'displayName', v_profile.display_name,
    'createdAt', v_profile.created_at,
    'mergedLineageCount', (
      select count(*)::integer from public.learner_profile_alias as alias
      where alias.target_learner_profile_id = v_profile.id
    ),
    'canSafeUnlink', (v_unlink_preview ->> 'canUnlink')::boolean,
    'pendingConnections', v_pending
  );
end
$$;


--
-- Name: get_my_learning_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_learning_progress() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid := public.current_owned_learner_profile_id();
begin
  if v_profile_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  return public.learner_progress_projection(v_profile_id);
end
$$;


--
-- Name: get_observed_learner_activity_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_observed_learner_activity_profile(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_grant_id uuid;
  v_generated_at timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if v_actor_account_id is null or p_learner_profile_id is null then
    raise exception 'observed_learner_profile_not_found'
      using errcode = 'P0002';
  end if;

  -- The advisory lock comes before the canonical Profile; Profile remains
  -- before Grant, matching merge/erasure and closing revoke/read races.
  perform public.lock_learning_activity_learners(
    array[p_learner_profile_id]
  );
  perform 1
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id
  for update of profile;
  if not found then
    raise exception 'observed_learner_profile_not_found'
      using errcode = 'P0002';
  end if;
  select grant_row.id into v_grant_id
  from public.learner_observer_grant as grant_row
  where grant_row.observer_account_id = v_actor_account_id
    and grant_row.learner_profile_id = p_learner_profile_id
    and grant_row.status = 'active'
  for share of grant_row;
  if not found then
    raise exception 'observed_learner_profile_not_found'
      using errcode = 'P0002';
  end if;

  perform public.refresh_learning_activity_states_for_profile(
    p_learner_profile_id,
    null,
    v_generated_at
  );
  v_result := public.safe_learning_activity_profile_projection(
    p_learner_profile_id,
    v_generated_at
  );
  perform public.append_learner_identity_audit(
    'learner_observer_activity_profile_read',
    v_actor_account_id,
    null,
    p_learner_profile_id,
    null,
    null,
    jsonb_build_object(
      'projectionVersion', 1,
      'stateCap', 200,
      'evidenceReferenceCap', 5
    )
  );
  return v_result;
end
$$;


--
-- Name: get_observed_learner_history(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_observed_learner_history(p_learner_profile_id uuid, p_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_grant_id uuid;
begin
  -- Hold the canonical profile before the grant, matching erasure's lock
  -- order. A read that wins completes and its audit row is subsequently
  -- pseudonymized by erasure; a read that loses observes the deleted profile
  -- and cannot append a post-erasure UUID.
  perform 1
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id
  for share of profile;
  if not found then
    raise exception 'observed_learner_profile_not_found' using errcode = 'P0002';
  end if;
  select grant_row.id into v_grant_id
  from public.learner_observer_grant as grant_row
  where grant_row.observer_account_id = v_actor_account_id
    and grant_row.learner_profile_id = p_learner_profile_id
    and grant_row.status = 'active'
  for share of grant_row;
  if not found then
    raise exception 'observed_learner_profile_not_found' using errcode = 'P0002';
  end if;
  perform public.append_learner_identity_audit(
    'learner_observer_history_read', v_actor_account_id, null,
    p_learner_profile_id, null, null,
    jsonb_build_object('projectionVersion', 1)
  );
  return public.learner_safe_history_projection(p_learner_profile_id, p_cursor, p_limit);
end
$$;


