--
-- Name: get_teacher_learner_activity_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_learner_activity_profile(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile_id uuid :=
    public.resolve_learner_profile_alias(p_learner_profile_id);
  v_generated_at timestamptz := clock_timestamp();
begin
  if v_actor_account_id is null or v_profile_id is null then
    raise exception 'learner_activity_profile_not_found'
      using errcode = 'P0002';
  end if;

  perform public.lock_learning_activity_learners(array[v_profile_id]);
  perform 1 from public.learner_profile as profile
  where profile.id = v_profile_id
  for update of profile;
  if not found then
    raise exception 'learner_activity_profile_not_found'
      using errcode = 'P0002';
  end if;
  perform 1 from public.teacher_learner as relation
  where relation.teacher_account_id = v_actor_account_id
    and relation.learner_profile_id = v_profile_id
  for share of relation;
  if not found then
    raise exception 'learner_activity_profile_not_found'
      using errcode = 'P0002';
  end if;

  perform public.refresh_learning_activity_states_for_profile(
    v_profile_id,
    v_actor_account_id,
    v_generated_at
  );
  return public.teacher_learning_activity_profile_projection(
    v_profile_id,
    v_actor_account_id,
    v_generated_at
  );
end
$$;


--
-- Name: get_teacher_learning_record_correction_history(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_learning_record_correction_history(p_active_learning_record_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_learner_profile_ids uuid[];
  v_input_count integer;
  v_visible_count integer;
  v_items jsonb;
  v_event_count integer;
begin
  v_input_count := cardinality(p_active_learning_record_ids);
  if v_actor_account_id is null
    or p_active_learning_record_ids is null
    or v_input_count not between 1 and 200
    or array_position(p_active_learning_record_ids, null) is not null
    or (
      select count(distinct submitted.id)
      from unnest(p_active_learning_record_ids) as submitted(id)
    ) <> v_input_count
  then
    raise exception 'learning_record_correction_history_invalid'
      using errcode = '22023';
  end if;

  select
    count(*),
    array_agg(
      distinct record.learner_profile_id
      order by record.learner_profile_id
    )
  into v_visible_count, v_learner_profile_ids
  from public.learning_record as record
  where record.id = any(p_active_learning_record_ids)
    and record.recorded_by_account_id = v_actor_account_id
    and record.occurred_at is not null
    and record.superseded_by_record_id is null;

  if v_visible_count <> v_input_count then
    raise exception 'learning_record_correction_history_not_found'
      using errcode = 'P0002';
  end if;

  perform public.lock_learning_activity_learners(v_learner_profile_ids);

  perform profile.id
  from public.learner_profile as profile
  where profile.id = any(v_learner_profile_ids)
  order by profile.id
  for share of profile;

  select count(*)
  into v_visible_count
  from public.learning_record as record
  where record.id = any(p_active_learning_record_ids)
    and record.recorded_by_account_id = v_actor_account_id
    and record.occurred_at is not null
    and record.superseded_by_record_id is null;

  if v_visible_count <> v_input_count then
    raise exception 'learning_record_correction_history_not_found'
      using errcode = 'P0002';
  end if;

  with recursive lineage as (
    select
      active.id as active_learning_record_id,
      active.id as learning_record_id,
      0 as depth
    from public.learning_record as active
    where active.id = any(p_active_learning_record_ids)
      and active.recorded_by_account_id = v_actor_account_id
      and active.superseded_by_record_id is null

    union all

    select
      lineage.active_learning_record_id,
      current_record.corrected_from_record_id,
      lineage.depth + 1
    from lineage
    join public.learning_record as current_record
      on current_record.id = lineage.learning_record_id
     and current_record.recorded_by_account_id = v_actor_account_id
    where current_record.corrected_from_record_id is not null
      -- Return cap 200 plus one explicit ancestor/event lookahead so a chain
      -- longer than the visible window cannot report truncated=false.
      and lineage.depth < 201
  ), events as materialized (
    select
      lineage.active_learning_record_id,
      corrected_record.id as learning_record_id,
      corrected_record.corrected_from_record_id,
      corrected_observation.id as observation_id,
      corrected_observation.corrected_from_observation_id,
      corrected_observation.component_position_at_time,
      corrected_observation.component_label_at_time,
      prior_observation.rating as old_rating,
      corrected_observation.rating as new_rating,
      prior_observation.private_note as old_private_note,
      corrected_observation.private_note as new_private_note,
      corrected_record.correction_reason,
      corrected_record.corrected_at
    from lineage
    join public.learning_record as corrected_record
      on corrected_record.id = lineage.learning_record_id
     and corrected_record.recorded_by_account_id = v_actor_account_id
    join public.lesson_component_observation as corrected_observation
      on corrected_observation.learning_record_id = corrected_record.id
     and corrected_observation.recorded_by_account_id =
       v_actor_account_id
     and corrected_observation.corrected_from_observation_id is not null
    join public.lesson_component_observation as prior_observation
      on prior_observation.id =
        corrected_observation.corrected_from_observation_id
     and prior_observation.recorded_by_account_id = v_actor_account_id
    where corrected_record.corrected_from_record_id is not null
      and (
        corrected_observation.rating,
        corrected_observation.private_note
      ) is distinct from (
        prior_observation.rating,
        prior_observation.private_note
      )
  ), bounded as materialized (
    select events.*
    from events
    order by
      events.corrected_at desc,
      events.learning_record_id,
      events.observation_id
    limit 201
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'activeLearningRecordId', bounded.active_learning_record_id,
          'learningRecordId', bounded.learning_record_id,
          'correctedFromLearningRecordId',
            bounded.corrected_from_record_id,
          'observationId', bounded.observation_id,
          'correctedFromObservationId',
            bounded.corrected_from_observation_id,
          'componentPositionAtTime', bounded.component_position_at_time,
          'componentLabelAtTime', bounded.component_label_at_time,
          'oldRating', bounded.old_rating,
          'newRating', bounded.new_rating,
          'oldPrivateNote', bounded.old_private_note,
          'newPrivateNote', bounded.new_private_note,
          'correctionReason', bounded.correction_reason,
          'correctedAt', bounded.corrected_at
        )
        order by
          bounded.corrected_at desc,
          bounded.learning_record_id,
          bounded.observation_id
      ) filter (where bounded.ordinal <= 200),
      '[]'::jsonb
    ),
    count(*)
  into v_items, v_event_count
  from (
    select
      bounded.*,
      row_number() over (
        order by
          bounded.corrected_at desc,
          bounded.learning_record_id,
          bounded.observation_id
      ) as ordinal
    from bounded
  ) as bounded;

  return jsonb_build_object(
    'items', v_items,
    'truncated', v_event_count > 200
  );
end
$$;


--
-- Name: guard_account_profile_link_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_account_profile_link_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if coalesce(current_setting('app.learner_profile_link_mutation', true), '') = 'on'
    or pg_trigger_depth() > 1
  then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if (tg_op = 'INSERT' and new.account_id is not null)
    or (tg_op = 'UPDATE' and new.account_id is distinct from old.account_id)
    or (tg_op = 'DELETE' and old.account_id is not null)
  then
    raise exception 'learner_profile_account_link_requires_supported_workflow'
      using errcode = '42501';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: guard_course_archive_invariants(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_archive_invariants() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.archived_at is null and new.archived_at is not null then
    if exists (
      select 1
      from public.course_publication as publication
      where publication.source_course_id = old.id
        and publication.status = 'published'
    ) then
      raise exception 'course_is_published'
        using errcode = '55000';
    end if;

    if exists (
      select 1
      from public.lesson as lesson
      join public.lesson_run as run on run.lesson_id = lesson.id
      where lesson.course_id = old.id
        and run.ended_at is null
        and run.cancelled_at is null
    ) then
      raise exception 'course_has_open_lesson_runs'
        using errcode = '55000';
    end if;
  end if;

  return new;
end
$$;


--
-- Name: guard_course_attestation_attempt_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_attestation_attempt_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_publication public.course_publication%rowtype;
  v_revision public.course_publication_revision%rowtype;
  v_attestation public.course_publication_attestation%rowtype;
  v_question_count integer;
  v_correct_answer_count integer;
begin
  select publication.*
  into v_publication
  from public.course_publication as publication
  where publication.id = new.publication_id
    and publication.status = 'published'
    and publication.learning_audience = 'educators'
    and publication.is_shidao
    and publication.approved_revision_id = new.revision_id
  for share;

  select revision.*
  into v_revision
  from public.course_publication_revision as revision
  where revision.publication_id = new.publication_id
    and revision.id = new.revision_id
    and revision.license_code = 'shidao_official_learning_v1'
  for share;

  select attestation.*
  into v_attestation
  from public.course_publication_attestation as attestation
  where attestation.publication_id = new.publication_id
    and attestation.revision_id = new.revision_id
  for share;

  if v_publication.id is null
    or v_revision.id is null
    or v_attestation.revision_id is null
    or not exists (
      select 1
      from public.educator_course_revision_review as review
      where review.publication_id = new.publication_id
        and review.revision_id = new.revision_id
        and review.status = 'approved'
    )
    or new.assessment_version <> v_attestation.version
    or new.passing_score_percent <> v_attestation.passing_score_percent
    or new.course_title
      <> v_revision.snapshot -> 'course' ->> 'title'
    or new.course_subject
      <> v_revision.snapshot -> 'course' ->> 'subject'
    or new.assessment_title <> v_attestation.title
    or new.publisher_display_name <> v_publication.publisher_display_name
  then
    raise exception 'course_attestation_attempt_snapshot_mismatch'
      using errcode = '23514';
  end if;

  if not coalesce((
    public.build_course_publication_progress_admin(
      new.account_id,
      new.publication_id,
      new.revision_id
    ) ->> 'complete'
  )::boolean, false) then
    raise exception 'course_attestation_lessons_incomplete'
      using errcode = '55000';
  end if;

  v_question_count := jsonb_array_length(v_attestation.questions);
  if new.question_count <> v_question_count
    or not public.course_attestation_selected_answers_are_valid(
      new.selected_option_by_question_id,
      v_question_count
    )
    or exists (
      select 1
      from jsonb_array_elements(v_attestation.questions) as question(value)
      where not (
        new.selected_option_by_question_id ? (question.value ->> 'id')
      )
        or not exists (
          select 1
          from jsonb_array_elements(
            question.value -> 'options'
          ) as option(value)
          where option.value ->> 'id'
            = new.selected_option_by_question_id
              ->> (question.value ->> 'id')
        )
    )
    or exists (
      select 1
      from jsonb_object_keys(
        new.selected_option_by_question_id
      ) as submitted(question_id)
      where not exists (
        select 1
        from jsonb_array_elements(v_attestation.questions) as question(value)
        where question.value ->> 'id' = submitted.question_id
      )
    )
  then
    raise exception 'course_attestation_attempt_answers_mismatch'
      using errcode = '23514';
  end if;

  select count(*)::integer
  into v_correct_answer_count
  from jsonb_array_elements(v_attestation.questions) as question(value)
  where new.selected_option_by_question_id ->> (question.value ->> 'id')
    = question.value ->> 'correctOptionId';

  if new.correct_answer_count <> v_correct_answer_count then
    raise exception 'course_attestation_attempt_score_mismatch'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_attestation_award_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_attestation_award_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_attempt public.course_attestation_attempt%rowtype;
begin
  select attempt.*
  into v_attempt
  from public.course_attestation_attempt as attempt
  where attempt.id = new.attempt_id
    and attempt.account_id = new.account_id
    and attempt.publication_id = new.publication_id
    and attempt.revision_id = new.revision_id
  for share;

  if not found
    or not v_attempt.passed
    or new.assessment_version <> v_attempt.assessment_version
    or new.course_title <> v_attempt.course_title
    or new.course_subject <> v_attempt.course_subject
    or new.assessment_title <> v_attempt.assessment_title
    or new.publisher_display_name <> v_attempt.publisher_display_name
    or new.score_percent <> v_attempt.score_percent
    or new.passing_score_percent <> v_attempt.passing_score_percent
  then
    raise exception 'course_attestation_award_attempt_mismatch'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_attestation_live_definition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_attestation_live_definition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_learning_audience text;
  v_archived_at timestamptz;
begin
  select course.learning_audience, course.archived_at
  into v_learning_audience, v_archived_at
  from public.course as course
  where course.id = new.course_id
  for update of course;

  if not found
    or v_archived_at is not null
    or v_learning_audience <> 'educators'
  then
    raise exception 'course_attestation_requires_active_educator_course'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_audience_type(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_audience_type() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expected_type text;
begin
  v_expected_type := case
    when exists (
      select 1
      from public.course_learner as course_learner
      where course_learner.course_id = new.id
    ) or exists (
      select 1
      from public.course_learner_group as course_group
      where course_group.course_id = new.id
    ) then 'learner_profile'
    else 'none'
  end;

  if new.audience_type <> v_expected_type then
    raise exception
      'course_audience_type_is_derived'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_educator_authoring(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_educator_authoring() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_owner_account_id uuid;
  v_learning_audience text;
begin
  if tg_op = 'INSERT' then
    v_owner_account_id := new.owner_account_id;
    v_learning_audience := new.learning_audience;
  else
    if new.learning_audience <> old.learning_audience then
      raise exception 'course_learning_audience_immutable'
        using errcode = '23514';
    end if;

    v_owner_account_id := new.owner_account_id;
    v_learning_audience := new.learning_audience;
  end if;

  if v_learning_audience = 'educators' and not exists (
    select 1
    from public.account as account
    where account.id = v_owner_account_id
      and account.status = 'active'
      and account.can_author_educator_courses
  ) then
    raise exception 'educator_course_authoring_not_allowed'
      using errcode = '42501';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_learning_audience_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_learning_audience_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.learning_audience = 'educators'
    and new.learning_audience = 'children'
    and exists (
      select 1
      from public.course_attestation as attestation
      where attestation.course_id = old.id
    )
  then
    raise exception 'course_attestation_must_be_removed_first'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_publication_active_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_publication_active_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_archived_at timestamptz;
begin
  if new.status = 'published' and new.source_course_id is not null then
    select course.archived_at
    into v_archived_at
    from public.course as course
    where course.id = new.source_course_id
    for update of course;

    if not found or v_archived_at is not null then
      raise exception 'course_publication_source_not_found'
        using errcode = 'P0002';
    end if;
  end if;

  return new;
end
$$;


--
-- Name: guard_course_publication_approved_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_publication_approved_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.approved_revision_id is null then
    return new;
  end if;

  if new.learning_audience <> 'educators'
    or not new.is_shidao
    or not exists (
      select 1
      from public.educator_course_revision_review as review
      join public.course_publication_attestation as attestation
        on attestation.publication_id = review.publication_id
       and attestation.revision_id = review.revision_id
      where review.publication_id = new.id
        and review.revision_id = new.approved_revision_id
        and review.status = 'approved'
    )
  then
    raise exception 'educator_course_approved_revision_invalid'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_course_publication_progress_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_publication_progress_integrity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_publication_id uuid := new.publication_id;
  v_revision_id uuid := new.revision_id;
  v_lesson_ref uuid;
begin
  if tg_table_name = 'course_publication_self_enrollment' then
    v_lesson_ref := new.last_opened_lesson_ref;
  else
    v_lesson_ref := new.lesson_ref;
  end if;

  perform 1
  from public.course_publication as publication
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id
  join public.educator_course_revision_review as review
    on review.publication_id = publication.id
   and review.revision_id = v_revision_id
   and review.status = 'approved'
  where publication.id = v_publication_id
    and publication.approved_revision_id = v_revision_id
    and publication.status = 'published'
    and publication.learning_audience = 'educators'
    and publication.is_shidao
    and owner_account.status = 'active';

  if not found then
    raise exception 'educator_course_revision_not_available'
      using errcode = 'P0002';
  end if;

  if v_lesson_ref is not null
    and not public.course_publication_revision_has_lesson_ref(
      v_publication_id,
      v_revision_id,
      v_lesson_ref
    )
  then
    raise exception 'course_publication_lesson_not_found'
      using errcode = 'P0002';
  end if;

  return new;
end
$$;


--
-- Name: guard_educator_course_audience_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_educator_course_audience_assignment() RETURNS trigger
