--
-- Name: guard_learning_evidence_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_learning_evidence_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if coalesce(
      current_setting('app.learner_identity_erasure', true), ''
    ) <> 'on' then
      raise exception 'learning_evidence_immutable'
        using errcode = '55000';
    end if;
    return old;
  end if;

  if (new.id,
      new.recorded_by_account_id,
      new.learning_record_id,
      new.source_observation_id,
      new.source_course_id_at_time,
      new.source_lesson_id_at_time,
      new.source_lesson_run_id_at_time,
      new.source_component_id_at_time,
      new.source_learning_objective_id_at_time,
      new.course_title_at_time,
      new.lesson_title_at_time,
      new.subject_at_time,
      new.component_type_at_time,
      new.component_label_at_time,
      new.component_visibility_at_time,
      new.objective_title_at_time,
      new.criterion_at_time,
      new.direction,
      new.support,
      new.observed_at,
      new.finalized_at,
      new.materialized_at,
      new.evidence_version,
      new.eligibility_policy_version,
      new.reason_code,
      new.supersedes_evidence_id,
      new.created_at)
    is distinct from
      (old.id,
       old.recorded_by_account_id,
       old.learning_record_id,
       old.source_observation_id,
       old.source_course_id_at_time,
       old.source_lesson_id_at_time,
       old.source_lesson_run_id_at_time,
       old.source_component_id_at_time,
       old.source_learning_objective_id_at_time,
       old.course_title_at_time,
       old.lesson_title_at_time,
       old.subject_at_time,
       old.component_type_at_time,
       old.component_label_at_time,
       old.component_visibility_at_time,
       old.objective_title_at_time,
       old.criterion_at_time,
       old.direction,
       old.support,
       old.observed_at,
       old.finalized_at,
       old.materialized_at,
       old.evidence_version,
       old.eligibility_policy_version,
       old.reason_code,
       old.supersedes_evidence_id,
       old.created_at)
  then
    raise exception 'learning_evidence_immutable'
      using errcode = '55000';
  end if;

  -- Live references are deliberately disposable.  Their FK actions may only
  -- clear a reference when the authored Component/Objective is deleted; no
  -- workflow may retarget a fact or resurrect a cleared live reference.
  if new.lesson_component_id is distinct from old.lesson_component_id
    and not (
      old.lesson_component_id is not null
      and new.lesson_component_id is null
    )
  then
    raise exception 'learning_evidence_immutable'
      using errcode = '55000';
  end if;

  if new.learning_objective_id is distinct from old.learning_objective_id
    and not (
      old.learning_objective_id is not null
      and new.learning_objective_id is null
    )
  then
    raise exception 'learning_evidence_immutable'
      using errcode = '55000';
  end if;

  if new.learner_profile_id is distinct from old.learner_profile_id
    and coalesce(
      current_setting('app.learner_identity_merge', true), ''
    ) <> 'on'
  then
    raise exception 'learning_evidence_immutable'
      using errcode = '55000';
  end if;

  if new.superseded_by_evidence_id is distinct from
      old.superseded_by_evidence_id
    and coalesce(
      current_setting('app.learning_activity_materialization', true), ''
    ) <> 'on'
  then
    raise exception 'learning_evidence_immutable'
      using errcode = '55000';
  end if;

  return new;
end
$$;


--
-- Name: guard_lesson_component_learning_alignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_lesson_component_learning_alignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_component_course_id uuid;
  v_objective_course_id uuid;
  v_objective_archived_at timestamptz;
begin
  select lesson.course_id
  into v_component_course_id
  from public.lesson as lesson
  where lesson.id = new.lesson_id;

  if not found then
    raise exception 'lesson_component_learning_alignment_invalid'
      using errcode = '23503';
  end if;

  if new.primary_learning_objective_id is not null then
    select objective.course_id, objective.archived_at
    into v_objective_course_id, v_objective_archived_at
    from public.learning_objective as objective
    where objective.id = new.primary_learning_objective_id
    for key share of objective;

    if not found then
      raise exception 'lesson_component_learning_objective_not_found'
        using errcode = '23503';
    end if;

    if v_objective_course_id <> v_component_course_id then
      raise exception 'lesson_component_learning_objective_cross_course'
        using errcode = '23514';
    end if;

    if v_objective_archived_at is not null
      and (
        tg_op = 'INSERT'
        or old.primary_learning_objective_id
          is distinct from new.primary_learning_objective_id
      )
    then
      raise exception 'lesson_component_learning_objective_archived'
        using errcode = '23514';
    end if;
  end if;

  if new.activity_role = 'survey'
    and new.type_key <> 'single_choice_poll'
  then
    raise exception 'lesson_component_activity_role_unsupported'
      using errcode = '23514';
  end if;

  if new.activity_role in ('practice', 'assessment')
    and new.type_key not in (
      'matching_game',
      'choice_quiz',
      'fill_blanks',
      'word_bank',
      'sequence',
      'categorize',
      'free_response',
      'word_builder'
    )
  then
    raise exception 'lesson_component_activity_role_unsupported'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: guard_lesson_course_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_lesson_course_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.course_id is distinct from new.course_id then
    raise exception 'lesson_course_move_forbidden'
      using errcode = '55000';
  end if;

  return new;
end
$$;


--
-- Name: guard_lesson_run_active_course(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_lesson_run_active_course() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
  v_archived_at timestamptz;
  v_learning_audience text;
begin
  if new.ended_at is null and new.cancelled_at is null then
    select lesson.course_id
    into v_course_id
    from public.lesson as lesson
    where lesson.id = new.lesson_id;

    if not found then
      raise exception 'lesson_not_found'
        using errcode = 'P0002';
    end if;

    select course.archived_at, course.learning_audience
    into v_archived_at, v_learning_audience
    from public.course as course
    where course.id = v_course_id
    for update of course;

    if not found or v_archived_at is not null then
      raise exception 'lesson_not_found'
        using errcode = 'P0002';
    end if;

    if v_learning_audience = 'educators' then
      raise exception 'educator_course_lesson_run_forbidden'
        using errcode = '23514';
    end if;
  end if;

  return new;
end
$$;


--
-- Name: handle_auth_user_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_auth_user_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.account%rowtype;
begin
  perform set_config('app.learner_profile_link_mutation', 'on', true);

  insert into public.account as target (
    auth_user_id,
    display_name,
    status
  )
  values (
    new.id,
    coalesce(
      nullif(btrim(new.raw_user_meta_data ->> 'full_name'), ''),
      nullif(btrim(new.raw_user_meta_data ->> 'name'), ''),
      nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
      'Пользователь'
    ),
    case
      when new.raw_app_meta_data ->> 'identity_status' = 'provisional'
        then 'provisional'
      else 'active'
    end
  )
  on conflict (auth_user_id) do update
    set display_name = target.display_name
  returning target.* into v_account;

  insert into public.account_security (account_id)
  values (v_account.id)
  on conflict (account_id) do nothing;

  insert into public.account_preference (account_id)
  values (v_account.id)
  on conflict (account_id) do nothing;

  if not exists (
    select 1 from public.learner_profile as profile
    where profile.account_id = v_account.id
  ) then
    insert into public.learner_profile (display_name, account_id)
    values (v_account.display_name, v_account.id);
  end if;

  return new;
end
$$;


--
-- Name: invalidate_learner_ai_consent_on_course_group_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_on_course_group_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid;
begin
  if tg_op = 'DELETE' then
    for v_profile_id in
      select member.learner_profile_id
      from public.learner_group_member as member
      where member.learner_group_id = old.learner_group_id
    loop
      perform public.invalidate_learner_ai_consent_scope(
        old.course_id, v_profile_id
      );
    end loop;
  elsif old.course_id is distinct from new.course_id
    or old.learner_group_id is distinct from new.learner_group_id
  then
    for v_profile_id in
      select member.learner_profile_id
      from public.learner_group_member as member
      where member.learner_group_id = old.learner_group_id
    loop
      perform public.invalidate_learner_ai_consent_scope(
        old.course_id, v_profile_id
      );
    end loop;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: invalidate_learner_ai_consent_on_course_owner_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_on_course_owner_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid;
begin
  if new.owner_account_id is distinct from old.owner_account_id then
    for v_profile_id in
      select distinct consent.learner_profile_id
      from public.learner_ai_consent as consent
      where consent.course_id = new.id
        and consent.status in ('pending', 'active')
    loop
      perform public.invalidate_learner_ai_consent_scope(new.id, v_profile_id);
    end loop;
  end if;
  return new;
end
$$;


--
-- Name: invalidate_learner_ai_consent_on_direct_audience_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_on_direct_audience_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    perform public.invalidate_learner_ai_consent_scope(
      old.course_id, old.learner_profile_id
    );
  elsif old.course_id is distinct from new.course_id
    or old.learner_profile_id is distinct from new.learner_profile_id
  then
    perform public.invalidate_learner_ai_consent_scope(
      old.course_id, old.learner_profile_id
    );
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: invalidate_learner_ai_consent_on_group_member_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_on_group_member_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
begin
  if tg_op = 'DELETE' then
    for v_course_id in
      select course_group.course_id
      from public.course_learner_group as course_group
