      );
    end loop;
  elsif old.learner_group_id is distinct from new.learner_group_id
    or old.learner_profile_id is distinct from new.learner_profile_id
  then
    for v_course_id in
      select course_group.course_id
      from public.course_learner_group as course_group
      where course_group.learner_group_id = old.learner_group_id
    loop
      perform public.invalidate_learner_ai_consent_scope(
        v_course_id, old.learner_profile_id
      );
    end loop;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


--
-- Name: invalidate_learner_ai_consent_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_learner_ai_consent_scope(p_course_id uuid, p_learner_profile_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_subject_account_id uuid;
  v_consent public.learner_ai_consent%rowtype;
begin
  select profile.account_id into v_subject_account_id
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id;

  for v_consent in
    update public.learner_ai_consent as consent
    set status = 'invalid',
        revision = consent.revision + 1,
        revoked_at = now(),
        updated_at = now()
    where consent.course_id = p_course_id
      and consent.learner_profile_id = p_learner_profile_id
      and consent.status in ('pending', 'active')
      and (
        not exists (
          select 1 from public.course as course
          where course.id = consent.course_id
            and course.owner_account_id = consent.owner_account_id
        )
        or not public.course_has_effective_learner(
          consent.course_id, consent.learner_profile_id
        )
      )
    returning consent.*
  loop
    perform public.append_learner_identity_audit(
      'learner_ai_consent_invalidated', v_actor_account_id,
      v_subject_account_id, v_consent.learner_profile_id,
      null, v_consent.id,
      jsonb_build_object(
        'revision', v_consent.revision,
        'projectionVersion', 1
      )
    );
  end loop;
end
$$;


--
-- Name: learner_erasure_state_for_actor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_erasure_state_for_actor(p_actor_account_id uuid, p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with lineage as materialized (
    select p_learner_profile_id as id
    union
    select alias.source_learner_profile_id
    from public.learner_profile_alias as alias
    where alias.target_learner_profile_id = p_learner_profile_id
  ), scope_entries as (
    select 'profile:' || lineage.id::text as entry from lineage
    union all
    select 'record:' || record.id::text
      from public.learning_record as record
      join lineage on lineage.id = record.learner_profile_id
    union all
    select 'teacher:' || relation.teacher_account_id::text || ':'
      || relation.learner_profile_id::text || ':'
      || (relation.archived_at is not null)::text
      from public.teacher_learner as relation
      join lineage on lineage.id = relation.learner_profile_id
    union all
    select 'group:' || member.learner_group_id::text || ':'
      || member.learner_profile_id::text
      from public.learner_group_member as member
      join lineage on lineage.id = member.learner_profile_id
    union all
    select 'course:' || direct.course_id::text || ':'
      || direct.learner_profile_id::text
      from public.course_learner as direct
      join lineage on lineage.id = direct.learner_profile_id
    union all
    select 'share:' || code.id::text || ':' || code.status
      from public.learner_profile_share_code as code
      join lineage on lineage.id = code.learner_profile_id
    union all
    select 'claim:' || invitation.id::text || ':' || invitation.status
      from public.learner_claim_invitation as invitation
      join lineage on lineage.id = invitation.source_learner_profile_id
    union all
    select 'connection:' || request.id::text || ':' || request.status
      from public.learner_connection_request as request
      join lineage on lineage.id = request.learner_profile_id
    union all
    select 'observer-invitation:' || invitation.id::text || ':' || invitation.status
      from public.learner_observer_invitation as invitation
      join lineage on lineage.id = invitation.learner_profile_id
    union all
    select 'observer-grant:' || grant_row.id::text || ':' || grant_row.status
      from public.learner_observer_grant as grant_row
      join lineage on lineage.id = grant_row.learner_profile_id
    union all
    select 'ai:' || consent.id::text || ':' || consent.status || ':'
      || consent.revision::text
      from public.learner_ai_consent as consent
      join lineage on lineage.id = consent.learner_profile_id
    union all
    select 'recovery-delegate:' || delegate.id::text || ':' || delegate.status
      from public.learner_credential_recovery_delegate as delegate
      where delegate.subject_account_id = p_actor_account_id
    union all
    select 'alias:' || alias.source_learner_profile_id::text || ':'
      || alias.target_learner_profile_id::text || ':' || alias.merge_operation_id::text
      from public.learner_profile_alias as alias
      where alias.source_learner_profile_id in (select id from lineage)
        or alias.target_learner_profile_id = p_learner_profile_id
    union all
    select 'merge:' || operation.id::text || ':' || operation.status
      from public.learner_profile_merge as operation
      where operation.source_learner_profile_id in (select id from lineage)
        or operation.target_learner_profile_id = p_learner_profile_id
  )
  select jsonb_build_object(
    'accountId', p_actor_account_id,
    'currentLearnerProfileId', p_learner_profile_id,
    'lineageProfileCount', (select count(*) from lineage),
    'learningRecordCount', (
      select count(*) from public.learning_record as record
      join lineage on lineage.id = record.learner_profile_id
    ),
    'teacherRelationCount', (
      select count(*) from public.teacher_learner as relation
      join lineage on lineage.id = relation.learner_profile_id
    ),
    'groupMembershipCount', (
      select count(*) from public.learner_group_member as member
      join lineage on lineage.id = member.learner_profile_id
    ),
    'courseAudienceCount', (
      select count(*) from public.course_learner as direct
      join lineage on lineage.id = direct.learner_profile_id
    ),
    'invitationCount',
      (select count(*) from public.learner_claim_invitation as invitation
        join lineage on lineage.id = invitation.source_learner_profile_id)
      + (select count(*) from public.learner_connection_request as request
        join lineage on lineage.id = request.learner_profile_id)
      + (select count(*) from public.learner_observer_invitation as invitation
        join lineage on lineage.id = invitation.learner_profile_id),
    'observerGrantCount', (
      select count(*) from public.learner_observer_grant as grant_row
      join lineage on lineage.id = grant_row.learner_profile_id
    ),
    'aiConsentCount', (
      select count(*) from public.learner_ai_consent as consent
      join lineage on lineage.id = consent.learner_profile_id
    ),
    'recoveryDelegateCount', (
      select count(*)
      from public.learner_credential_recovery_delegate as delegate
      where delegate.subject_account_id = p_actor_account_id
    ),
    'scopeState', encode(extensions.digest(
      coalesce((select string_agg(entry, E'\n' order by entry) from scope_entries), ''),
      'sha256'
    ), 'hex')
  );
$$;


--
-- Name: learner_identity_rate_limit_hit(text, bytea, integer, interval, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_identity_rate_limit_hit(p_scope text, p_key_digest bytea, p_limit integer, p_window interval, p_block interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_window_started_at timestamptz;
  v_hit_count integer;
  v_blocked_until timestamptz;
begin
  if p_scope is null or btrim(p_scope) = '' or char_length(p_scope) > 80
    or p_key_digest is null or octet_length(p_key_digest) <> 32
    or p_limit < 1 or p_limit > 10000
    or p_window <= interval '0 seconds'
    or p_window > interval '1 day'
    or p_block <= interval '0 seconds'
    or p_block > interval '7 days'
  then
    raise exception 'learner_identity_rate_limit_invalid' using errcode = '22023';
  end if;

  v_window_started_at := date_bin(p_window, clock_timestamp(), '2000-01-01'::timestamptz);

  insert into public.learner_identity_rate_limit as target (
    scope, key_digest, window_started_at, hit_count
  ) values (
    btrim(p_scope), p_key_digest, v_window_started_at, 1
  )
  on conflict (scope, key_digest, window_started_at) do update
    set hit_count = least(target.hit_count + 1, 100000),
        blocked_until = case
          when target.hit_count + 1 > p_limit
            then greatest(
              coalesce(target.blocked_until, '-infinity'::timestamptz),
              clock_timestamp() + p_block
            )
          else target.blocked_until
        end,
        updated_at = now()
  returning hit_count, blocked_until into v_hit_count, v_blocked_until;

  return v_hit_count <= p_limit
    and (v_blocked_until is null or v_blocked_until <= clock_timestamp());
end
$$;


--
-- Name: learner_profile_merge_preview_for_actor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_profile_merge_preview_for_actor(p_merge_operation_id uuid, p_actor_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.learner_profile_merge%rowtype;
  v_payload jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_conflicts jsonb;
  v_fingerprint bytea;
  v_finalized_count integer;
  v_teacher_count integer;
  v_group_count integer;
  v_course_count integer;
  v_initial_source_id uuid;
  v_initial_target_id uuid;
  v_update_count integer;
begin
  select operation.* into v_operation
  from public.learner_profile_merge as operation
  where operation.id = p_merge_operation_id;

  if not found or v_operation.subject_account_id <> p_actor_account_id then
    raise exception 'learner_profile_merge_not_found'
      using errcode = 'P0002';
  end if;
  v_initial_source_id := v_operation.source_learner_profile_id;
  v_initial_target_id := v_operation.target_learner_profile_id;
  if v_operation.status = 'completed' then
    return v_operation.preview_payload;
  end if;
  if v_operation.status = 'cancelled' or v_operation.expires_at <= now() then
    raise exception 'learner_profile_merge_not_available'
      using errcode = '55000';
  end if;

  perform 1
  from public.learner_profile as profile
  where profile.id in (
    v_operation.source_learner_profile_id,
    v_operation.target_learner_profile_id
  )
  order by profile.id
  for update of profile;

  -- Cancellation locks the operation first.  Preview deliberately follows
  -- the established Profile -> Operation order, then re-reads terminal state
  -- under the row lock so a concurrent cancel can never be resurrected.
  select operation.* into v_operation
  from public.learner_profile_merge as operation
  where operation.id = p_merge_operation_id
  for update of operation;
  if not found
    or v_operation.subject_account_id <> p_actor_account_id
    or v_operation.source_learner_profile_id <> v_initial_source_id
    or v_operation.target_learner_profile_id <> v_initial_target_id
  then
    raise exception 'learner_profile_merge_not_found'
      using errcode = 'P0002';
  end if;
  if v_operation.status = 'completed' then
    return v_operation.preview_payload;
  end if;
  if v_operation.status = 'cancelled' or v_operation.expires_at <= now() then
    raise exception 'learner_profile_merge_not_available'
      using errcode = '55000';
  end if;

  if not exists (
    select 1 from public.learner_profile as source
    where source.id = v_operation.source_learner_profile_id
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'source_missing',
      'message', 'Исходный профиль уже недоступен.',
      'count', null
    ));
  elsif exists (
    select 1 from public.learner_profile as source
    where source.id = v_operation.source_learner_profile_id
      and source.account_id is not null
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'source_is_claimed',
      'message', 'Объединение двух аккаунтов недоступно.',
      'count', 1
    ));
  end if;

  if not exists (
    select 1 from public.learner_profile as target
    where target.id = v_operation.target_learner_profile_id
      and target.account_id = p_actor_account_id
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'target_not_owned',
      'message', 'Целевой профиль не принадлежит вам.',
      'count', 1
    ));
  end if;

  if exists (
    select 1 from public.learner_profile_alias as alias
    where alias.target_learner_profile_id =
      v_operation.source_learner_profile_id
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'source_has_merge_lineage',
      'message', 'Профиль уже содержит объединённую историю.',
      'count', null
    ));
  end if;

  if exists (
    select 1 from public.learning_record as record
    where record.learner_profile_id in (
      v_operation.source_learner_profile_id,
      v_operation.target_learner_profile_id
    )
      and record.occurred_at is null
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'draft_records',
      'message', 'Сначала завершите или отмените открытые проведения.',
      'count', (
        select count(*)
        from public.learning_record as record
        where record.learner_profile_id in (
          v_operation.source_learner_profile_id,
          v_operation.target_learner_profile_id
        )
          and record.occurred_at is null
      )
    ));
  end if;

  if exists (
    select 1
    from public.learning_record as record
    join public.lesson_run as run on run.id = record.lesson_run_id
    where record.learner_profile_id in (
      v_operation.source_learner_profile_id,
      v_operation.target_learner_profile_id
    )
      and run.ended_at is null
      and run.cancelled_at is null
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'open_lesson_runs',
      'message', 'Сначала закройте все проведения.',
      'count', null
    ));
  end if;

  if exists (
    select 1 from public.learner_observer_grant as grant_row
    where grant_row.learner_profile_id =
      v_operation.source_learner_profile_id
      and grant_row.status = 'active'
  ) or exists (
    select 1 from public.learner_ai_consent as consent
    where consent.learner_profile_id =
      v_operation.source_learner_profile_id
      and consent.status in ('pending', 'active')
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'source_has_dependent_grants',
      'message', 'Отзовите доступы и согласия исходного профиля.',
      'count', null
    ));
  end if;

  select count(*)::integer into v_finalized_count
  from public.learning_record as record
  where record.learner_profile_id = v_operation.source_learner_profile_id
    and record.occurred_at is not null;
  select count(*)::integer into v_teacher_count
  from public.teacher_learner
  where learner_profile_id = v_operation.source_learner_profile_id;
  select count(*)::integer into v_group_count
  from public.learner_group_member
  where learner_profile_id = v_operation.source_learner_profile_id;
  select count(*)::integer into v_course_count
  from public.course_learner
  where learner_profile_id = v_operation.source_learner_profile_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'occurredOn', source_record.occurred_at::date,
    'resolution', 'keep_target_primary'
  ) order by source_record.occurred_at, source_record.id), '[]'::jsonb)
  into v_conflicts
  from public.learning_record as source_record
  join public.learning_record as target_record
    on target_record.lesson_run_id = source_record.lesson_run_id
   and target_record.learner_profile_id =
     v_operation.target_learner_profile_id
   and target_record.superseded_by_record_id is null
  where source_record.learner_profile_id =
      v_operation.source_learner_profile_id
    and source_record.lesson_run_id is not null
    and source_record.occurred_at is not null
    and source_record.superseded_by_record_id is null
    and target_record.occurred_at is not null;

  v_payload := jsonb_build_object(
    'operationId', v_operation.id,
    'sourceLearnerProfileId', v_operation.source_learner_profile_id,
    'targetLearnerProfileId', v_operation.target_learner_profile_id,
    'finalizedRecordCount', v_finalized_count,
    'teacherRelationCount', v_teacher_count,
    'groupMembershipCount', v_group_count,
    'courseAudienceCount', v_course_count,
    'conflicts', v_conflicts,
    'blockers', v_blockers,
    'canConfirm', jsonb_array_length(v_blockers) = 0,
    'expiresAt', v_operation.expires_at
  );
  v_fingerprint := extensions.digest(v_payload::text, 'sha256');
  v_payload := v_payload || jsonb_build_object(
    'previewFingerprint', encode(v_fingerprint, 'hex')
  );

  update public.learner_profile_merge as operation
  set preview_fingerprint = v_fingerprint,
      preview_payload = v_payload,
      status = case when jsonb_array_length(v_blockers) = 0
        then 'ready' else 'pending' end
  where operation.id = v_operation.id
    and operation.status in ('pending', 'ready');
  get diagnostics v_update_count = row_count;
  if v_update_count <> 1 then
    raise exception 'learner_profile_merge_not_available'
      using errcode = '55000';
  end if;

  return v_payload;
end
$$;


--
-- Name: learner_progress_projection(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_progress_projection(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with records as (
    select record.*
    from public.learning_record as record
    where record.learner_profile_id = p_learner_profile_id
      and record.occurred_at is not null
      and record.superseded_by_record_id is null
  ), subjects as (
    select
      coalesce(nullif(btrim(subject_at_time), ''), 'Без предмета') as subject,
      count(*)::integer as completed_run_count,
      count(*) filter (where was_present)::integer as attended_run_count,
      count(*) filter (where needs_repeat is true)::integer as repeat_recommended_count,
      case
        when count(actual_duration_minutes_at_time) filter (where was_present) = 0 then null
        else sum(actual_duration_minutes_at_time) filter (where was_present)::integer
      end as known_actual_duration_minutes
    from records
    group by coalesce(nullif(btrim(subject_at_time), ''), 'Без предмета')
  )
  select jsonb_build_object(
    'finalizedRunCount', count(*)::integer,
    'attendedRunCount', count(*) filter (where was_present)::integer,
    'repeatRecommendedCount', count(*) filter (where needs_repeat is true)::integer,
    'knownActualDurationMinutes', case
      when count(actual_duration_minutes_at_time) filter (where was_present) = 0 then null
      else sum(actual_duration_minutes_at_time) filter (where was_present)::integer
    end,
    'knownActualDurationRunCount', count(actual_duration_minutes_at_time)
      filter (where was_present)::integer,
    'lastActivityAt', max(occurred_at),
    'subjects', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'subject', subject,
          'completedRunCount', completed_run_count,
          'attendedRunCount', attended_run_count,
          'repeatRecommendedCount', repeat_recommended_count,
          'knownActualDurationMinutes', known_actual_duration_minutes
        ) order by subject
      ) from subjects
    ), '[]'::jsonb)
  )
  from records;
$$;


--
-- Name: learner_safe_history_projection(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_safe_history_projection(p_learner_profile_id uuid, p_cursor text DEFAULT NULL::text, p_limit integer DEFAULT 25) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 50);
  v_cursor_occurred_at timestamptz;
  v_cursor_id uuid;
  v_items jsonb;
  v_next_cursor text;
begin
  if p_cursor is not null then
    select record.occurred_at, record.id
    into v_cursor_occurred_at, v_cursor_id
    from public.learning_record as record
    where record.learner_profile_id = p_learner_profile_id
      and record.occurred_at is not null
      and record.superseded_by_record_id is null
      and encode(
        extensions.digest(record.id::text || ':' || record.occurred_at::text, 'sha256'),
        'hex'
      ) = p_cursor
    limit 1;

    if not found then
      raise exception 'learning_history_cursor_invalid' using errcode = '22023';
    end if;
  end if;

  with page as (
    select record.*
    from public.learning_record as record
    where record.learner_profile_id = p_learner_profile_id
      and record.occurred_at is not null
      and record.superseded_by_record_id is null
      and (
        v_cursor_id is null
        or (record.occurred_at, record.id) < (v_cursor_occurred_at, v_cursor_id)
      )
    order by record.occurred_at desc, record.id desc
    limit v_limit + 1
  ), visible as (
    select * from page
    order by occurred_at desc, id desc
    limit v_limit
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'key', encode(
          extensions.digest(id::text || ':' || occurred_at::text, 'sha256'),
          'hex'
        ),
        'occurredAt', occurred_at,
        'courseTitle', course_title_at_time,
        'lessonTitle', lesson_title_at_time,
        'subject', subject_at_time,
        'wasPresent', was_present,
        'needsRepeat', needs_repeat,
        'actualDurationMinutes', actual_duration_minutes_at_time,
        'comment', case
          when shared_with_learner_at is not null then jsonb_build_object(
            'text', teacher_comment,
            'sharedAt', shared_with_learner_at
          )
          else 'null'::jsonb
        end
      ) order by occurred_at desc, id desc
    ),
    '[]'::jsonb
  ) into v_items
  from visible;

  with page as (
    select record.id, record.occurred_at,
      row_number() over (order by record.occurred_at desc, record.id desc) as rn
    from public.learning_record as record
    where record.learner_profile_id = p_learner_profile_id
      and record.occurred_at is not null
      and record.superseded_by_record_id is null
      and (
        v_cursor_id is null
        or (record.occurred_at, record.id) < (v_cursor_occurred_at, v_cursor_id)
      )
    order by record.occurred_at desc, record.id desc
    limit v_limit + 1
  )
  select encode(
    extensions.digest(previous.id::text || ':' || previous.occurred_at::text, 'sha256'),
    'hex'
  ) into v_next_cursor
  from page as overflow
  join page as previous on previous.rn = v_limit
  where overflow.rn = v_limit + 1;

  return jsonb_build_object(
    'items', v_items,
    'nextCursor', v_next_cursor
  );
end
$$;


--
-- Name: learner_safe_unlink_preview_for_actor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_safe_unlink_preview_for_actor(p_actor_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_id uuid;
  v_blockers jsonb := '[]'::jsonb;
  v_base jsonb;
  v_fingerprint text;
begin
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = p_actor_account_id;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.learning_record where learner_profile_id = v_profile_id) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'learning_history_exists', 'message', 'В профиле есть учебная история.',
      'count', (select count(*) from public.learning_record where learner_profile_id = v_profile_id)
    ));
  end if;
  if exists (select 1 from public.learner_profile_alias where target_learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_profile_merge where target_learner_profile_id = v_profile_id and status = 'completed')
  then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'merge_lineage_exists', 'message', 'Объединённый профиль нельзя разделить.', 'count', null
    ));
  end if;
  if exists (select 1 from public.learner_group_member where learner_profile_id = v_profile_id)
    or exists (select 1 from public.course_learner where learner_profile_id = v_profile_id)
    or exists (select 1 from public.learner_observer_grant where learner_profile_id = v_profile_id and status = 'active')
    or exists (select 1 from public.learner_observer_invitation
      where learner_profile_id = v_profile_id
        and status in ('pending','bound') and expires_at > now())
    or exists (select 1 from public.learner_ai_consent
      where learner_profile_id = v_profile_id
        and status in ('pending','active') and expires_at > now())
    or exists (select 1 from public.learner_claim_invitation
      where source_learner_profile_id = v_profile_id
        and status in ('pending','bound') and expires_at > now())
    or exists (select 1 from public.learner_connection_request
      where learner_profile_id = v_profile_id
        and status in ('pending', 'bound') and expires_at > now())
    or exists (select 1 from public.learner_identity_reconciliation
      where learner_profile_id = v_profile_id
        and status in ('pending', 'needs_review'))
    or exists (select 1 from public.learner_profile_share_code
      where learner_profile_id = v_profile_id
        and status = 'active' and expires_at > now())
    or exists (select 1 from public.learner_profile_merge
      where (source_learner_profile_id = v_profile_id
          or target_learner_profile_id = v_profile_id)
        and status in ('pending','ready') and expires_at > now())
  then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'dependent_access_exists', 'message', 'Сначала удалите назначения, наблюдателей и согласия.', 'count', null
    ));
  end if;
  v_base := jsonb_build_object(
    'accountId', p_actor_account_id,
    'learnerProfileId', v_profile_id,
    'blockers', v_blockers,
    'canUnlink', jsonb_array_length(v_blockers) = 0
  );
  v_fingerprint := encode(extensions.digest(v_base::text, 'sha256'), 'hex');
  return jsonb_build_object(
    'previewFingerprint', v_fingerprint,
    'canUnlink', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'generatedAt', now()
  );
end
$$;


--
-- Name: learning_activity_scope_fingerprint(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learning_activity_scope_fingerprint(p_learner_profile_ids uuid[]) RETURNS bytea
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with profiles as materialized (
    select distinct submitted.id
    from unnest(coalesce(p_learner_profile_ids, '{}'::uuid[]))
      as submitted(id)
    where submitted.id is not null
  ), entries as (
    select 'record:' || record.id::text || ':'
      || record.learner_profile_id::text || ':'
      || coalesce(record.lesson_run_id::text, '-') || ':'
      || coalesce(record.superseded_by_record_id::text, '-') || ':'
      || coalesce(record.corrected_from_record_id::text, '-') || ':'
      || record.updated_at::text as entry
    from public.learning_record as record
    join profiles on profiles.id = record.learner_profile_id
    union all
    select 'observation:' || observation.id::text || ':'
      || observation.learning_record_id::text || ':'
      || coalesce(observation.superseded_by_observation_id::text, '-') || ':'
      || coalesce(observation.corrected_from_observation_id::text, '-') || ':'
      || observation.updated_at::text
    from public.lesson_component_observation as observation
    join public.learning_record as record
      on record.id = observation.learning_record_id
    join profiles on profiles.id = record.learner_profile_id
    union all
    select 'evidence:' || evidence.id::text || ':'
      || evidence.learner_profile_id::text || ':'
      || coalesce(evidence.superseded_by_evidence_id::text, '-') || ':'
      || coalesce(evidence.supersedes_evidence_id::text, '-')
    from public.learning_evidence as evidence
    join profiles on profiles.id = evidence.learner_profile_id
    union all
    select 'state:' || state.id::text || ':'
      || state.learner_profile_id::text || ':'
      || state.source_course_id_at_time::text || ':'
      || state.source_learning_objective_id_at_time::text || ':'
      || state.policy_version::text || ':' || state.updated_at::text
    from public.learner_objective_state as state
    join profiles on profiles.id = state.learner_profile_id
    union all
    select 'override:' || override_row.id::text || ':'
      || override_row.learner_profile_id::text || ':'
      || override_row.source_course_id_at_time::text || ':'
      || override_row.source_learning_objective_id_at_time::text || ':'
      || override_row.action || ':'
      || coalesce(override_row.recommendation_type, '-') || ':'
      || override_row.updated_at::text
    from public.learner_recommendation_override as override_row
    join profiles on profiles.id = override_row.learner_profile_id
  )
  select extensions.digest(
    coalesce(string_agg(entries.entry, E'\n' order by entries.entry), ''),
    'sha256'
  )
  from entries;
$$;


--
-- Name: list_course_publication_catalog_admin(uuid, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_course_publication_catalog_admin(p_actor_account_id uuid, p_q text, p_subject text, p_level text, p_offset integer, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if p_actor_account_id is null
    or p_q is null
    or char_length(btrim(p_q)) > 160
    or p_subject is null
    or char_length(btrim(p_subject)) > 160
    or p_level is null
    or char_length(btrim(p_level)) > 240
    or p_offset is null
    or p_offset < 0
    or p_limit is null
    or p_limit < 1
    or p_limit > 50
  then
    raise exception 'course_publication_catalog_query_invalid'
      using errcode = '22023';
  end if;

  perform 1
  from public.account as account
  where account.id = p_actor_account_id
    and account.status = 'active';

  if not found then
    raise exception 'course_publication_catalog_actor_not_active'
      using errcode = '42501';
  end if;

  with filtered as (
    select publication.*
    from public.course_publication as publication
    join public.account as owner_account
      on owner_account.id = publication.owner_account_id
    where publication.status = 'published'
      and owner_account.status = 'active'
      and (
        btrim(p_q) = ''
        or position(
          lower(btrim(p_q)) in lower(concat_ws(
            ' ',
            publication.title,
            publication.subject,
            publication.goal,
            publication.level,
            publication.audience_description,
            publication.publisher_display_name
          ))
        ) > 0
      )
      and (
        btrim(p_subject) = ''
        or lower(btrim(publication.subject)) = lower(btrim(p_subject))
      )
      and (
        btrim(p_level) = ''
        or lower(btrim(publication.level)) = lower(btrim(p_level))
      )
  ),
  page_plus_one as materialized (
    select publication.*
    from filtered as publication
    order by
      publication.is_shidao desc,
      publication.published_at desc,
      publication.id desc
    offset p_offset
    limit p_limit + 1
  ),
  page_rows as (
    select publication.*
    from page_plus_one as publication
    order by
      publication.is_shidao desc,
      publication.published_at desc,
      publication.id desc
    limit p_limit
  ),
  subject_values_all as (
    select min(btrim(publication.subject)) as value
    from public.course_publication as publication
    join public.account as owner_account
      on owner_account.id = publication.owner_account_id
    where publication.status = 'published'
      and owner_account.status = 'active'
      and btrim(publication.subject) <> ''
    group by lower(btrim(publication.subject))
  ),
  subject_values as materialized (
    select value
    from subject_values_all
    order by
      case
        when btrim(p_subject) <> ''
          and lower(value) = lower(btrim(p_subject))
          then 0
        else 1
      end,
      lower(value),
      value
    limit 100
  ),
  level_values_all as (
    select min(btrim(publication.level)) as value
    from public.course_publication as publication
    join public.account as owner_account
      on owner_account.id = publication.owner_account_id
    where publication.status = 'published'
      and owner_account.status = 'active'
      and btrim(publication.level) <> ''
    group by lower(btrim(publication.level))
  ),
  level_values as materialized (
    select value
    from level_values_all
    order by
      case
        when btrim(p_level) <> ''
          and lower(value) = lower(btrim(p_level))
          then 0
        else 1
      end,
      lower(value),
      value
    limit 100
  )
  select jsonb_build_object(
    'courses', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'publicationId', publication.id,
          'sourceCourseId', case
            when publication.owner_account_id = p_actor_account_id
              then publication.source_course_id
            else null
          end,
          'title', publication.title,
          'subject', publication.subject,
          'goal', publication.goal,
          'level', publication.level,
          'audienceDescription', publication.audience_description,
          'targetLessonCount', publication.target_lesson_count,
          'lessonCount', publication.lesson_count,
          'materialCount', publication.material_count,
          'publishedAt', publication.published_at,
          'author', jsonb_build_object(
            'displayName', publication.publisher_display_name,
            'isShiDao', publication.is_shidao,
            'isCurrentUser',
              publication.owner_account_id = p_actor_account_id
          )
        )
        order by
          publication.is_shidao desc,
          publication.published_at desc,
          publication.id desc
      )
      from page_rows as publication
    ), '[]'::jsonb),
    'facets', jsonb_build_object(
      'subjects', coalesce((
        select jsonb_agg(value order by lower(value), value)
        from subject_values
      ), '[]'::jsonb),
      'levels', coalesce((
        select jsonb_agg(value order by lower(value), value)
        from level_values
      ), '[]'::jsonb)
    ),
    'nextOffset', case
      when (select count(*) from page_plus_one) > p_limit
        then p_offset + p_limit
      else null
    end
  )
  into v_result;

  return v_result;
end
$$;


--
-- Name: list_course_publication_catalog_v2_admin(uuid, text, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_course_publication_catalog_v2_admin(p_actor_account_id uuid, p_q text, p_learning_audience text, p_subject text, p_level text, p_offset integer, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
begin
  if p_actor_account_id is null
    or p_q is null
    or char_length(btrim(p_q)) > 160
    or p_learning_audience not in ('children', 'educators')
    or p_subject is null
    or char_length(btrim(p_subject)) > 160
    or p_level is null
    or char_length(btrim(p_level)) > 240
    or p_offset is null
    or p_offset < 0
    or p_limit is null
    or p_limit < 1
    or p_limit > 50
  then
    raise exception 'course_publication_catalog_query_invalid'
      using errcode = '22023';
  end if;

  perform 1
  from public.account as account
  where account.id = p_actor_account_id
    and account.status = 'active';

  if not found then
    raise exception 'course_publication_catalog_actor_not_active'
      using errcode = '42501';
  end if;

  with catalog_rows as materialized (
    select
      publication.id,
      publication.source_course_id,
      publication.owner_account_id,
      publication.publisher_display_name,
      publication.is_shidao,
      publication.learning_audience,
      case
        when publication.learning_audience = 'educators'
          then revision.published_at
        else publication.published_at
      end as published_at,
      revision.id as revision_id,
      revision.snapshot -> 'course' ->> 'title' as title,
      revision.snapshot -> 'course' ->> 'subject' as subject,
      revision.snapshot -> 'course' ->> 'goal' as goal,
      revision.snapshot -> 'course' ->> 'level' as level,
      revision.snapshot -> 'course' ->> 'audienceDescription'
        as audience_description,
      (revision.snapshot -> 'course' ->> 'targetLessonCount')::integer
        as target_lesson_count,
      jsonb_array_length(revision.snapshot -> 'lessons') as lesson_count,
      jsonb_array_length(revision.snapshot -> 'materials') as material_count
    from public.course_publication as publication
    join public.account as owner_account
      on owner_account.id = publication.owner_account_id
     and owner_account.status = 'active'
    join public.course_publication_revision as revision
      on revision.publication_id = publication.id
     and revision.id = case
       when publication.learning_audience = 'educators'
         then publication.approved_revision_id
       else publication.current_revision_id
     end
    left join public.educator_course_revision_review as review
      on review.publication_id = publication.id
     and review.revision_id = revision.id
    where publication.status = 'published'
      and publication.learning_audience = p_learning_audience
      and (
        publication.learning_audience = 'children'
        or (
          publication.is_shidao
          and publication.approved_revision_id is not null
          and review.status = 'approved'
          and revision.license_code = 'shidao_official_learning_v1'
          and exists (
            select 1
            from public.course_publication_attestation as attestation
            where attestation.publication_id = publication.id
              and attestation.revision_id = revision.id
          )
        )
      )
  ),
  filtered as materialized (
    select catalog.*
    from catalog_rows as catalog
    where (
      btrim(p_q) = ''
      or position(
        lower(btrim(p_q)) in lower(concat_ws(
          ' ',
          catalog.title,
          catalog.subject,
          catalog.goal,
          catalog.level,
          catalog.audience_description,
          catalog.publisher_display_name
        ))
      ) > 0
    )
      and (
        btrim(p_subject) = ''
        or lower(btrim(catalog.subject)) = lower(btrim(p_subject))
      )
      and (
        btrim(p_level) = ''
        or lower(btrim(catalog.level)) = lower(btrim(p_level))
      )
  ),
  page_plus_one as materialized (
    select catalog.*
    from filtered as catalog
    order by catalog.is_shidao desc, catalog.published_at desc, catalog.id desc
    offset p_offset
    limit p_limit + 1
  ),
  page_rows as materialized (
    select catalog.*
    from page_plus_one as catalog
    order by catalog.is_shidao desc, catalog.published_at desc, catalog.id desc
    limit p_limit
  ),
  subject_values as materialized (
    select min(btrim(catalog.subject)) as value
    from catalog_rows as catalog
    where btrim(catalog.subject) <> ''
    group by lower(btrim(catalog.subject))
    order by lower(min(btrim(catalog.subject))), min(btrim(catalog.subject))
    limit 100
  ),
  level_values as materialized (
    select min(btrim(catalog.level)) as value
    from catalog_rows as catalog
    where btrim(catalog.level) <> ''
    group by lower(btrim(catalog.level))
    order by lower(min(btrim(catalog.level))), min(btrim(catalog.level))
    limit 100
  )
  select jsonb_build_object(
    'courses', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'publicationId', catalog.id,
          'sourceCourseId', case
            when catalog.owner_account_id = p_actor_account_id
              then catalog.source_course_id
            else null
          end,
          'learningAudience', catalog.learning_audience,
          'title', catalog.title,
          'subject', catalog.subject,
          'goal', catalog.goal,
          'level', catalog.level,
          'audienceDescription', catalog.audience_description,
          'targetLessonCount', catalog.target_lesson_count,
          'lessonCount', catalog.lesson_count,
          'materialCount', catalog.material_count,
          'publishedAt', catalog.published_at,
          'author', jsonb_build_object(
            'displayName', catalog.publisher_display_name,
            'isShiDao', catalog.is_shidao,
            'isCurrentUser', catalog.owner_account_id = p_actor_account_id
          )
        )
        order by catalog.is_shidao desc,
          catalog.published_at desc,
          catalog.id desc
      )
      from page_rows as catalog
    ), '[]'::jsonb),
    'facets', jsonb_build_object(
      'subjects', coalesce((
        select jsonb_agg(value order by lower(value), value)
        from subject_values
      ), '[]'::jsonb),
      'levels', coalesce((
        select jsonb_agg(value order by lower(value), value)
        from level_values
      ), '[]'::jsonb)
    ),
    'nextOffset', case
      when (select count(*) from page_plus_one) > p_limit
        then p_offset + p_limit
      else null
    end
  )
  into v_result;

  return v_result;
end
$$;


--
-- Name: list_learner_connection_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_learner_connection_requests() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile_id uuid := public.current_owned_learner_profile_id();
  v_result jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', request.id,
    'direction', case when request.teacher_account_id = v_actor_account_id then 'outgoing' else 'incoming' end,
    'status', case when request.status = 'pending' and request.expires_at <= now() then 'expired' else request.status end,
    'method', request.method,
    'counterpartyLabel', case
      when request.teacher_account_id = v_actor_account_id
        then coalesce(profile.display_name, 'Приглашение по email')
      else teacher.display_name
    end,
    'localDisplayName', request.local_display_name,
    'learnerProfileId', request.learner_profile_id,
    'expiresAt', request.expires_at,
    'createdAt', request.created_at,
    'acceptedAt', request.accepted_at
  ) order by request.created_at desc), '[]'::jsonb)
  into v_result
  from public.learner_connection_request as request
  join public.account as teacher on teacher.id = request.teacher_account_id
  left join public.learner_profile as profile on profile.id = request.learner_profile_id
  where request.teacher_account_id = v_actor_account_id
    or (request.learner_profile_id = v_profile_id and request.method <> 'email')
    or request.recipient_account_id = v_actor_account_id;
  return v_result;
end
$$;


--
-- Name: list_learner_profile_invitations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_learner_profile_invitations(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_result jsonb;
begin
  if not exists (
    select 1 from public.teacher_learner as relation
    where relation.teacher_account_id = v_actor_account_id
      and relation.learner_profile_id = p_learner_profile_id
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', invitation.id, 'kind', invitation.kind,
    'status', case when invitation.status in ('pending','bound') and invitation.expires_at <= now()
      then 'expired' else invitation.status end,
    'learnerProfileId', invitation.source_learner_profile_id,
    'learnerLabel', profile.display_name,
    'inviterLabel', inviter.display_name,
    'expiresAt', invitation.expires_at, 'createdAt', invitation.created_at,
    'acceptedAt', invitation.accepted_at
  ) order by invitation.created_at desc), '[]'::jsonb)
  into v_result
  from public.learner_claim_invitation as invitation
  join public.account as inviter on inviter.id = invitation.inviter_account_id
  left join public.learner_profile as profile on profile.id = invitation.source_learner_profile_id
  where invitation.source_learner_profile_id = p_learner_profile_id
    and invitation.inviter_account_id = v_actor_account_id;
  return v_result;
end
$$;


--
-- Name: list_my_assistant_conversations(boolean, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_assistant_conversations(p_include_archived boolean DEFAULT false, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_items jsonb;
begin
  if v_actor_account_id is null then
    raise exception 'assistant_account_not_found' using errcode = 'P0002';
  end if;

  if p_include_archived is null
    or p_limit is null
    or p_limit < 1
    or p_limit > 50
  then
    raise exception 'assistant_conversation_query_invalid'
      using errcode = '22023';
  end if;

  select coalesce(
    jsonb_agg(
      public.assistant_conversation_projection(
        conversation.id,
        v_actor_account_id
      )
      order by coalesce(
        conversation.last_turn_at,
        conversation.created_at
      ) desc,
      conversation.id desc
    ),
    '[]'::jsonb
  )
  into v_items
  from (
    select conversation.*
    from public.assistant_conversation as conversation
    where conversation.owner_account_id = v_actor_account_id
      and (p_include_archived or conversation.archived_at is null)
    order by coalesce(
      conversation.last_turn_at,
      conversation.created_at
    ) desc,
    conversation.id desc
    limit p_limit
  ) as conversation;

  return jsonb_build_object('items', v_items);
end
$$;


--
-- Name: list_my_assistant_turns(uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_assistant_turns(p_conversation_id uuid, p_before_turn_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_items jsonb;
  v_has_more boolean;
  v_next_cursor bigint;
begin
  if v_actor_account_id is null
    or p_conversation_id is null
    or p_limit is null
    or p_limit < 1
    or p_limit > 50
    or (p_before_turn_id is not null and p_before_turn_id < 1)
    or not exists (
      select 1
      from public.assistant_conversation as conversation
      where conversation.id = p_conversation_id
        and conversation.owner_account_id = v_actor_account_id
    )
  then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  with page as materialized (
    select turn.id
    from public.assistant_turn as turn
    where turn.conversation_id = p_conversation_id
      and (p_before_turn_id is null or turn.id < p_before_turn_id)
    order by turn.id desc
    limit p_limit + 1
  ),
  visible as (
    select page.id
    from page
    order by page.id desc
    limit p_limit
  )
  select
    coalesce(
      jsonb_agg(
        public.assistant_turn_projection(visible.id)
        order by visible.id
      ),
      '[]'::jsonb
    ),
    (select count(*) > p_limit from page),
    case
      when (select count(*) > p_limit from page) then min(visible.id)
      else null
    end
  into v_items, v_has_more, v_next_cursor
  from visible;

  return jsonb_build_object(
    'items', v_items,
    'nextCursor', case
      when v_has_more then to_jsonb(v_next_cursor)
      else 'null'::jsonb
    end
  );
end
$$;


--
-- Name: list_my_communication_inbox(timestamp with time zone, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_communication_inbox(p_cursor_activity_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_kind text DEFAULT NULL::text, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 30) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_actor_created_at timestamptz;
  v_items jsonb;
  v_system_item jsonb;
  v_has_more boolean;
  v_next_activity_at timestamptz;
  v_next_kind text;
  v_next_id text;
  v_total_unread bigint;
begin
  if v_actor_account_id is null then
    raise exception 'communication_account_not_found' using errcode = 'P0002';
  end if;

  if p_limit is null or p_limit < 1 or p_limit > 50
    or not (
      (
        p_cursor_activity_at is null
        and p_cursor_kind is null
        and p_cursor_id is null
      )
      or (
        p_cursor_activity_at is not null
        and p_cursor_kind in ('direct', 'course', 'assistant')
        and p_cursor_id is not null
        and btrim(p_cursor_id) <> ''
        and char_length(p_cursor_id) <= 80
      )
    )
  then
    raise exception 'communication_inbox_cursor_invalid' using errcode = '22023';
  end if;

  select account.created_at
  into v_actor_created_at
  from public.account as account
  where account.id = v_actor_account_id;

  with candidates as materialized (
    select
      coalesce(thread.last_message_at, thread.created_at) as activity_at,
      thread.kind,
      thread.id::text as item_id,
      case
        when thread.kind = 'direct' then jsonb_build_object(
          'id', thread.id,
          'kind', 'direct',
          'title', projection.value -> 'title',
          'preview', projection.value -> 'preview',
          'lastActivityAt', coalesce(thread.last_message_at, thread.created_at),
          'unreadCount', projection.value -> 'unreadCount',
          'pinned', false,
          'threadId', thread.id,
          'lastMessageId', thread.last_message_id,
          'canSend', projection.value -> 'canSend',
          'directLearnerProfileId',
            projection.value -> 'directLearnerProfileId'
        )
        else jsonb_build_object(
          'id', thread.id,
          'kind', 'course',
          'title', projection.value -> 'title',
          'preview', projection.value -> 'preview',
          'lastActivityAt', coalesce(thread.last_message_at, thread.created_at),
          'unreadCount', projection.value -> 'unreadCount',
          'pinned', false,
          'threadId', thread.id,
          'lastMessageId', thread.last_message_id,
          'canSend', projection.value -> 'canSend',
          'courseId', thread.course_id
        )
      end as item,
      coalesce((projection.value ->> 'unreadCount')::bigint, 0) as unread_count
    from public.communication_thread as thread
    cross join lateral (
      select public.communication_thread_projection(
        thread.id,
        v_actor_account_id
      ) as value
    ) as projection
    where public.communication_thread_is_accessible(
        thread.id,
        v_actor_account_id,
        false
      )
    union all
    select
      coalesce(conversation.last_turn_at, conversation.created_at),
      'assistant'::text,
      conversation.id::text,
      jsonb_build_object(
        'id', conversation.id,
        'kind', 'assistant',
        'title', conversation.title,
        'preview', last_turn.body,
        'lastActivityAt', coalesce(
          conversation.last_turn_at,
          conversation.created_at
        ),
        'unreadCount', (
          select count(*)
          from public.assistant_turn as unread_turn
          where unread_turn.conversation_id = conversation.id
            and unread_turn.role = 'assistant'
            and unread_turn.id > conversation.last_read_assistant_turn_id
        ),
        'pinned', false,
        'conversationId', conversation.id,
        'contextCourseId', conversation.context_course_id,
        'contextLessonId', conversation.context_lesson_id
      ),
      (
        select count(*)
        from public.assistant_turn as unread_turn
        where unread_turn.conversation_id = conversation.id
          and unread_turn.role = 'assistant'
          and unread_turn.id > conversation.last_read_assistant_turn_id
      )
    from public.assistant_conversation as conversation
    left join public.assistant_turn as last_turn
      on last_turn.id = conversation.last_turn_id
     and last_turn.conversation_id = conversation.id
    where conversation.owner_account_id = v_actor_account_id
      and conversation.archived_at is null
  ),
  filtered as (
    select candidates.*
    from candidates
    where p_cursor_activity_at is null
      or candidates.activity_at < p_cursor_activity_at
      or (
        candidates.activity_at = p_cursor_activity_at
        and candidates.kind < p_cursor_kind
      )
      or (
        candidates.activity_at = p_cursor_activity_at
        and candidates.kind = p_cursor_kind
        and candidates.item_id < p_cursor_id
      )
  ),
  page as materialized (
    select filtered.*
    from filtered
    order by activity_at desc, kind desc, item_id desc
    limit p_limit + 1
  ),
  visible as (
    select page.*
    from page
    order by activity_at desc, kind desc, item_id desc
    limit p_limit
  )
  select
    coalesce(
      jsonb_agg(
        visible.item
        order by visible.activity_at desc, visible.kind desc, visible.item_id desc
      ),
      '[]'::jsonb
    ),
    (select count(*) > p_limit from page)
  into v_items, v_has_more
  from visible;

  if v_has_more then
    with candidates as materialized (
      select
        coalesce(thread.last_message_at, thread.created_at) as activity_at,
        thread.kind,
        thread.id::text as item_id
      from public.communication_thread as thread
      where public.communication_thread_is_accessible(
          thread.id,
          v_actor_account_id,
          false
        )
      union all
      select
        coalesce(conversation.last_turn_at, conversation.created_at),
        'assistant'::text,
        conversation.id::text
      from public.assistant_conversation as conversation
      where conversation.owner_account_id = v_actor_account_id
        and conversation.archived_at is null
    ),
    filtered as (
      select candidates.*
      from candidates
      where p_cursor_activity_at is null
        or candidates.activity_at < p_cursor_activity_at
        or (
          candidates.activity_at = p_cursor_activity_at
          and candidates.kind < p_cursor_kind
        )
        or (
          candidates.activity_at = p_cursor_activity_at
          and candidates.kind = p_cursor_kind
          and candidates.item_id < p_cursor_id
        )
    ),
    visible as (
      select filtered.*
      from filtered
      order by activity_at desc, kind desc, item_id desc
      limit p_limit
    )
    select activity_at, kind, item_id
    into v_next_activity_at, v_next_kind, v_next_id
    from visible
    order by activity_at, kind, item_id
    limit 1;
  end if;

  select jsonb_build_object(
    'id', 'system',
    'kind', 'system',
    'title', 'ShiDao',
    'preview', latest.body,
    'lastActivityAt', coalesce(latest.occurred_at, v_actor_created_at),
    'lastNotificationId', latest.id,
    'unreadCount', (
      select count(*)
      from public.system_notification as notification
      where notification.recipient_account_id = v_actor_account_id
        and notification.read_at is null
    ),
    'pinned', true
  )
  into v_system_item
  from (select 1) as one
  left join lateral (
    select notification.id, notification.body, notification.occurred_at
    from public.system_notification as notification
    where notification.recipient_account_id = v_actor_account_id
    order by notification.id desc
    limit 1
  ) as latest on true;

  select
    coalesce((
      select sum(
        case
          when state.account_id is null then 0
          else (
            select count(*)
            from public.communication_message as message
            where message.thread_id = thread.id
              and message.id > state.last_read_message_id
              and message.sender_account_id <> v_actor_account_id
          )
        end
      )
      from public.communication_thread as thread
      left join public.communication_read_state as state
        on state.thread_id = thread.id
       and state.account_id = v_actor_account_id
      where public.communication_thread_is_accessible(
          thread.id,
          v_actor_account_id,
          false
        )
    ), 0)
    + coalesce((
      select count(*)
      from public.assistant_turn as turn
      join public.assistant_conversation as conversation
        on conversation.id = turn.conversation_id
      where conversation.owner_account_id = v_actor_account_id
        and conversation.archived_at is null
        and turn.role = 'assistant'
        and turn.id > conversation.last_read_assistant_turn_id
    ), 0)
    + coalesce((
      select count(*)
      from public.system_notification as notification
      where notification.recipient_account_id = v_actor_account_id
        and notification.read_at is null
    ), 0)
  into v_total_unread;

  if p_cursor_activity_at is null then
    v_items := jsonb_build_array(v_system_item) || v_items;
  end if;

  return jsonb_build_object(
    'items', v_items,
    'nextCursor', case
      when v_has_more then jsonb_build_object(
        'activityAt', v_next_activity_at,
        'kind', v_next_kind,
        'id', v_next_id
      )
      else 'null'::jsonb
    end,
    'totalUnread', v_total_unread
  );
end
$$;


--
-- Name: list_my_communication_messages(uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_communication_messages(p_thread_id uuid, p_before_message_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_items jsonb;
  v_has_more boolean;
  v_next_cursor bigint;
begin
  if v_actor_account_id is null
    or p_thread_id is null
    or p_limit is null
    or p_limit < 1
    or p_limit > 50
    or (p_before_message_id is not null and p_before_message_id < 1)
    or not public.communication_thread_is_accessible(
      p_thread_id,
      v_actor_account_id,
      false
    )
  then
    raise exception 'communication_thread_not_found' using errcode = 'P0002';
  end if;

  with page as materialized (
    select message.id
    from public.communication_message as message
    where message.thread_id = p_thread_id
      and (
        p_before_message_id is null
        or message.id < p_before_message_id
      )
    order by message.id desc
    limit p_limit + 1
  ),
  visible as (
    select page.id
    from page
    order by page.id desc
    limit p_limit
  )
  select
    coalesce(
      jsonb_agg(
        public.communication_message_projection(
          visible.id,
          v_actor_account_id
        )
        order by visible.id
      ),
      '[]'::jsonb
    ),
    (select count(*) > p_limit from page),
    case
      when (select count(*) > p_limit from page) then min(visible.id)
      else null
    end
  into v_items, v_has_more, v_next_cursor
  from visible;

  return jsonb_build_object(
    'items', v_items,
    'nextCursor', case
      when v_has_more then to_jsonb(v_next_cursor)
      else 'null'::jsonb
    end
  );
end
$$;


--
-- Name: list_my_course_publication_attestations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_course_publication_attestations() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_result jsonb;
begin
  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active';

  if not found then
    raise exception 'course_attestation_account_not_active'
      using errcode = '42501';
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'publicationId', award.publication_id,
        'revisionId', award.revision_id,
        'courseTitle', award.course_title,
        'courseSubject', award.course_subject,
        'assessmentTitle', award.assessment_title,
        'publisherDisplayName', award.publisher_display_name,
        'scorePercent', award.score_percent,
        'passingScorePercent', award.passing_score_percent,
        'completedAt', attempt.completed_at,
        'assessmentVersion', award.assessment_version,
        'isCurrentRevision',
          publication.approved_revision_id = award.revision_id,
        'publicationAvailable',
          publication.status = 'published'
          and publication.learning_audience = 'educators'
          and publication.is_shidao
          and publication.approved_revision_id = award.revision_id
          and owner_account.status = 'active'
      )
      order by award.issued_at desc, award.id desc
    ),
    '[]'::jsonb
  )
  into v_result
  from (
    select award.*
    from public.course_attestation_award as award
    where award.account_id = v_account_id
    order by award.issued_at desc, award.id desc
    limit 200
  ) as award
  join public.course_attestation_attempt as attempt
    on attempt.id = award.attempt_id
  join public.course_publication as publication
    on publication.id = award.publication_id
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id;

  return v_result;
end
$$;


--
-- Name: list_my_learner_ai_consents(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_learner_ai_consents() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_profile_id uuid := public.current_owned_learner_profile_id();
  v_result jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', consent.id,
    'learnerProfileId', consent.learner_profile_id,
    'courseId', consent.course_id,
    'courseTitle', course.title,
    'ownerLabel', owner.display_name,
    'purpose', consent.purpose,
    'status', case
      when course.owner_account_id <> consent.owner_account_id
        or not public.course_has_effective_learner(consent.course_id, consent.learner_profile_id)
        then 'invalid'
      when consent.status in ('pending','active') and consent.expires_at <= now()
        then 'expired'
      else consent.status
    end,
    'revision', consent.revision,
    'expiresAt', consent.expires_at,
    'createdAt', consent.created_at,
    'grantedAt', consent.granted_at,
    'revokedAt', consent.revoked_at
  ) order by consent.created_at desc), '[]'::jsonb)
  into v_result
  from public.learner_ai_consent as consent
  join public.course as course on course.id = consent.course_id
  join public.account as owner on owner.id = consent.owner_account_id
  where consent.learner_profile_id = v_profile_id
    and v_actor_account_id is not null;
  return v_result;
end
$$;


--
-- Name: list_my_learner_credential_recovery_delegates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_learner_credential_recovery_delegates() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_result jsonb;
begin
  if v_actor_account_id is null then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'grantId', delegate.id,
    'delegateLabel', account.display_name,
    'status', delegate.status,
    'grantedAt', delegate.granted_at,
    'revokedAt', delegate.revoked_at
  ) order by delegate.created_at desc), '[]'::jsonb)
  into v_result
  from public.learner_credential_recovery_delegate as delegate
  join public.account as account on account.id = delegate.delegate_account_id
  where delegate.subject_account_id = v_actor_account_id;
  return v_result;
end
$$;


--
-- Name: list_my_learner_observer_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_learner_observer_overview() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
begin
  if v_actor_account_id is null then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  return public.list_my_learner_observer_overview_for_actor(v_actor_account_id);
end
$$;


--
-- Name: list_my_learner_observer_overview_for_actor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_learner_observer_overview_for_actor(p_actor_account_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'grants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', grant_row.id,
        'learnerProfileId', grant_row.learner_profile_id,
        'subjectLabel', subject.display_name,
        'observerLabel', observer.display_name,
        'relationshipLabel', grant_row.relationship_label,
        'direction', case when grant_row.observer_account_id = p_actor_account_id
          then 'observing' else 'observed_by' end,
        'createdAt', grant_row.created_at
      ) order by grant_row.created_at desc)
      from public.learner_observer_grant as grant_row
      join public.account as subject on subject.id = grant_row.subject_account_id
      join public.account as observer on observer.id = grant_row.observer_account_id
      where grant_row.status = 'active'
        and (grant_row.subject_account_id = p_actor_account_id
          or grant_row.observer_account_id = p_actor_account_id)
    ), '[]'::jsonb),
    'invitations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', invitation.id,
        'direction', case when invitation.subject_account_id = p_actor_account_id
          then 'outgoing' else 'incoming' end,
        'status', case when invitation.status in ('pending','bound') and invitation.expires_at <= now()
          then 'expired' else invitation.status end,
        'subjectLabel', subject.display_name,
        'observerLabel', case when invitation.recipient_account_id is null
          then 'Приглашённый наблюдатель'
          else observer.display_name end,
        'relationshipLabel', invitation.relationship_label,
        'expiresAt', invitation.expires_at,
        'createdAt', invitation.created_at
      ) order by invitation.created_at desc)
      from public.learner_observer_invitation as invitation
      join public.account as subject on subject.id = invitation.subject_account_id
      left join public.account as observer on observer.id = invitation.recipient_account_id
      where invitation.subject_account_id = p_actor_account_id
        or invitation.recipient_account_id = p_actor_account_id
    ), '[]'::jsonb)
  );
$$;


--
-- Name: list_my_message_targets(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_message_targets(p_q text DEFAULT NULL::text, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_query text := lower(btrim(coalesce(p_q, '')));
  v_direct jsonb;
  v_courses jsonb;
begin
  if v_actor_account_id is null then
    raise exception 'communication_account_not_found' using errcode = 'P0002';
  end if;

  if p_limit is null or p_limit < 1 or p_limit > 50
    or char_length(v_query) > 160
  then
    raise exception 'communication_target_query_invalid' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(target.item order by target.label, target.profile_id), '[]'::jsonb)
  into v_direct
  from (
    select
      relation.display_name as label,
      profile.id as profile_id,
      jsonb_build_object(
        'learnerProfileId', profile.id,
        'title', relation.display_name,
        'existingThreadId', thread.id
      ) as item
    from public.teacher_learner as relation
    join public.learner_profile as profile
      on profile.id = relation.learner_profile_id
    join public.account as learner_account
      on learner_account.id = profile.account_id
     and learner_account.status = 'active'
    left join public.communication_thread as thread
      on thread.kind = 'direct'
     and thread.direct_account_low_id = least(
       v_actor_account_id,
       learner_account.id
     )
     and thread.direct_account_high_id = greatest(
       v_actor_account_id,
       learner_account.id
     )
    where relation.teacher_account_id = v_actor_account_id
      and relation.archived_at is null
      and learner_account.id <> v_actor_account_id
      and (
        v_query = ''
        or lower(relation.display_name) like '%' || v_query || '%'
      )
    order by relation.display_name, profile.id
    limit p_limit
  ) as target;

  select coalesce(jsonb_agg(target.item order by target.title, target.course_id), '[]'::jsonb)
  into v_courses
  from (
    select
      course.title,
      course.id as course_id,
      jsonb_build_object(
        'courseId', course.id,
        'title', course.title,
        'existingThreadId', thread.id
      ) as item
    from public.course as course
    left join public.communication_thread as thread
      on thread.kind = 'course'
     and thread.course_id = course.id
    where course.learning_audience = 'children'
      and course.archived_at is null
      and public.communication_course_account_is_member(
        course.id,
        v_actor_account_id
      )
      and (
        v_query = ''
        or lower(course.title) like '%' || v_query || '%'
      )
    order by course.title, course.id
    limit p_limit
  ) as target;

  return jsonb_build_object('direct', v_direct, 'courses', v_courses);
end
$$;


--
-- Name: list_my_observed_learner_profiles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_observed_learner_profiles() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_result jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', grant_row.id,
    'learnerProfileId', grant_row.learner_profile_id,
    'subjectLabel', subject.display_name,
    'observerLabel', observer.display_name,
    'relationshipLabel', grant_row.relationship_label,
    'direction', 'observing',
    'createdAt', grant_row.created_at
  ) order by lower(subject.display_name), grant_row.id), '[]'::jsonb)
  into v_result
  from public.learner_observer_grant as grant_row
  join public.account as subject on subject.id = grant_row.subject_account_id
  join public.account as observer on observer.id = grant_row.observer_account_id
  where grant_row.observer_account_id = v_actor_account_id
    and grant_row.status = 'active';
  return v_result;
end
$$;


--
-- Name: list_my_system_notifications(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_my_system_notifications(p_before_notification_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_items jsonb;
  v_has_more boolean;
  v_next_cursor bigint;
begin
  if v_actor_account_id is null
    or p_limit is null
    or p_limit < 1
    or p_limit > 50
    or (
      p_before_notification_id is not null
      and p_before_notification_id < 1
    )
  then
    raise exception 'system_notification_query_invalid' using errcode = '22023';
  end if;

  with page as materialized (
    select notification.id
    from public.system_notification as notification
    where notification.recipient_account_id = v_actor_account_id
      and (
        p_before_notification_id is null
        or notification.id < p_before_notification_id
      )
    order by notification.id desc
    limit p_limit + 1
  ),
  visible as (
    select page.id
    from page
    order by page.id desc
    limit p_limit
  )
  select
    coalesce(
      jsonb_agg(
        public.system_notification_projection(visible.id)
        order by visible.id
      ),
      '[]'::jsonb
    ),
    (select count(*) > p_limit from page),
    case
      when (select count(*) > p_limit from page) then min(visible.id)
      else null
    end
  into v_items, v_has_more, v_next_cursor
  from visible;

  return jsonb_build_object(
    'items', v_items,
    'nextCursor', case
      when v_has_more then to_jsonb(v_next_cursor)
      else 'null'::jsonb
    end
  );
end
$$;


--
-- Name: list_recoverable_learner_credentials(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_recoverable_learner_credentials(p_actor_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_result jsonb;
begin
  if v_actor_account_id is null then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'grantId', delegate.id,
    'learnerLabel', subject.display_name,
    'childAccountLogin', alias.normalized_login,
    'canReset', delegate.status = 'active' and subject.status = 'active',
    'grantedAt', delegate.granted_at
  ) order by subject.display_name, delegate.id), '[]'::jsonb)
  into v_result
  from public.learner_credential_recovery_delegate as delegate
  join public.account as subject on subject.id = delegate.subject_account_id
  left join public.account_login_alias as alias
    on alias.account_id = subject.id
   and alias.kind = 'login'
   and alias.revoked_at is null
  where delegate.delegate_account_id = v_actor_account_id
    and delegate.status = 'active';
  return v_result;
end
$$;


--
-- Name: list_teacher_learner_directory(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_teacher_learner_directory(p_status text DEFAULT 'active'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_result jsonb;
begin
  if p_status not in ('active', 'archived') then
    raise exception 'teacher_learner_status_invalid' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'learnerProfileId', relation.learner_profile_id,
    'teacherAccountId', relation.teacher_account_id,
    'displayName', relation.display_name,
    'archivedAt', relation.archived_at,
    'identityState', case
      when profile.account_id is not null and exists (
        select 1 from public.learner_profile_alias as alias
        where alias.target_learner_profile_id = profile.id
      ) then 'merged'
      when profile.account_id is not null then 'claimed'
      when exists (
        select 1 from public.learner_claim_invitation as invitation
        where invitation.source_learner_profile_id = profile.id
          and invitation.status in ('pending', 'bound')
      ) then 'pending'
      else 'offline'
    end,
    'pendingRequestCount', (
      select count(*)::integer from public.learner_claim_invitation as invitation
      where invitation.source_learner_profile_id = profile.id
        and invitation.status in ('pending', 'bound')
    ),
    'canInvite', profile.account_id is null,
    'canPermanentlyDelete', profile.account_id is null
      and not exists (select 1 from public.learning_record as record where record.learner_profile_id = profile.id)
      and not exists (select 1 from public.teacher_learner as other where other.learner_profile_id = profile.id and other.teacher_account_id <> v_actor_account_id)
      and not exists (select 1 from public.learner_group_member where learner_profile_id = profile.id)
      and not exists (select 1 from public.course_learner where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_profile_share_code where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_claim_invitation where source_learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_connection_request where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_observer_invitation where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_observer_grant where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_ai_consent where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_identity_reconciliation where learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_profile_alias where target_learner_profile_id = profile.id)
      and not exists (select 1 from public.learner_profile_merge where source_learner_profile_id = profile.id or target_learner_profile_id = profile.id),
    'createdAt', relation.created_at,
    'updatedAt', relation.updated_at
  ) order by lower(relation.display_name), relation.learner_profile_id), '[]'::jsonb)
  into v_result
  from public.teacher_learner as relation
  join public.learner_profile as profile on profile.id = relation.learner_profile_id
  where relation.teacher_account_id = v_actor_account_id
    and ((p_status = 'active' and relation.archived_at is null)
      or (p_status = 'archived' and relation.archived_at is not null));
  return v_result;
end
$$;


--
-- Name: lock_learning_activity_learners(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_learning_activity_learners(p_learner_profile_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_learner_profile_id uuid;
begin
  if p_learner_profile_ids is null
    or array_position(p_learner_profile_ids, null) is not null
  then
    raise exception 'learning_activity_learner_lock_invalid'
      using errcode = '22023';
  end if;

  for v_learner_profile_id in
    select distinct submitted.id
    from unnest(p_learner_profile_ids) as submitted(id)
    order by submitted.id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'shidao-learning-activity-v1:' || v_learner_profile_id::text,
        0
      )
    );
  end loop;
end
$$;


--
-- Name: mark_communication_thread_read(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_communication_thread_read(p_thread_id uuid, p_through_message_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_target_message_id bigint;
begin
  if v_actor_account_id is null
    or p_thread_id is null
    or not public.communication_thread_is_accessible(
      p_thread_id,
      v_actor_account_id,
      false
    )
  then
    raise exception 'communication_thread_not_found' using errcode = 'P0002';
  end if;

  if p_through_message_id is null then
    select coalesce(thread.last_message_id, 0)
    into v_target_message_id
    from public.communication_thread as thread
    where thread.id = p_thread_id;
  else
    select message.id
    into v_target_message_id
    from public.communication_message as message
    where message.id = p_through_message_id
      and message.thread_id = p_thread_id;

    if not found then
      raise exception 'communication_message_not_found' using errcode = 'P0002';
    end if;
  end if;

  insert into public.communication_read_state (
    thread_id,
    account_id,
    last_read_message_id
  )
  values (p_thread_id, v_actor_account_id, v_target_message_id)
  on conflict (thread_id, account_id) do update
    set last_read_message_id = greatest(
          public.communication_read_state.last_read_message_id,
          excluded.last_read_message_id
        ),
        updated_at = now();

  select state.last_read_message_id
  into v_target_message_id
  from public.communication_read_state as state
  where state.thread_id = p_thread_id
    and state.account_id = v_actor_account_id;

  return jsonb_build_object(
    'markedThroughId', case
      when v_target_message_id = 0 then null
      else v_target_message_id
    end,
    'unreadCount', (
      select count(*)
      from public.communication_message as message
      where message.thread_id = p_thread_id
        and message.id > v_target_message_id
        and message.sender_account_id <> v_actor_account_id
    )
  );
end
$$;


--
-- Name: mark_my_assistant_conversation_read(uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_assistant_conversation_read(p_conversation_id uuid, p_through_turn_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_target_turn_id bigint;
  v_marked_turn_id bigint;
begin
  if v_actor_account_id is null or p_conversation_id is null then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  if p_through_turn_id is null then
    select coalesce(conversation.last_assistant_turn_id, 0)
    into v_target_turn_id
    from public.assistant_conversation as conversation
    where conversation.id = p_conversation_id
      and conversation.owner_account_id = v_actor_account_id
    for update;
  else
    select turn.id
    into v_target_turn_id
    from public.assistant_turn as turn
    join public.assistant_conversation as conversation
      on conversation.id = turn.conversation_id
    where turn.id = p_through_turn_id
      and turn.conversation_id = p_conversation_id
      and conversation.owner_account_id = v_actor_account_id;
  end if;

  if not found then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  select coalesce(max(turn.id), 0)
  into v_marked_turn_id
  from public.assistant_turn as turn
  where turn.conversation_id = p_conversation_id
    and turn.role = 'assistant'
    and turn.id <= v_target_turn_id;

  update public.assistant_conversation as conversation
  set last_read_assistant_turn_id = greatest(
        conversation.last_read_assistant_turn_id,
        v_marked_turn_id
      ),
      updated_at = now()
  where conversation.id = p_conversation_id
    and conversation.owner_account_id = v_actor_account_id
  returning conversation.last_read_assistant_turn_id
    into v_marked_turn_id;

  return jsonb_build_object(
    'markedThroughId', case when v_marked_turn_id = 0 then null else v_marked_turn_id end,
    'unreadCount', (
      select count(*)
      from public.assistant_turn as turn
      where turn.conversation_id = p_conversation_id
        and turn.role = 'assistant'
        and turn.id > v_marked_turn_id
    )
  );
end
$$;


--
-- Name: mark_my_system_notifications_read(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_my_system_notifications_read(p_through_notification_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_target_notification_id bigint;
begin
  if v_actor_account_id is null then
    raise exception 'system_notification_account_not_found'
      using errcode = 'P0002';
  end if;

  if p_through_notification_id is null then
    select max(notification.id)
    into v_target_notification_id
    from public.system_notification as notification
    where notification.recipient_account_id = v_actor_account_id;
  else
    select notification.id
    into v_target_notification_id
    from public.system_notification as notification
    where notification.id = p_through_notification_id
      and notification.recipient_account_id = v_actor_account_id;

    if not found then
      raise exception 'system_notification_not_found' using errcode = 'P0002';
    end if;
  end if;

  if v_target_notification_id is not null then
    update public.system_notification as notification
    set read_at = coalesce(
      notification.read_at,
      greatest(now(), notification.occurred_at)
    )
    where notification.recipient_account_id = v_actor_account_id
      and notification.id <= v_target_notification_id
      and notification.read_at is null;
  end if;

  return jsonb_build_object(
    'markedThroughId', v_target_notification_id,
    'unreadCount', (
      select count(*)
      from public.system_notification as notification
      where notification.recipient_account_id = v_actor_account_id
        and notification.read_at is null
    )
  );
end
$$;


--
-- Name: materialize_learning_evidence_for_records(uuid[], timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_learning_evidence_for_records(p_learning_record_ids uuid[], p_materialized_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_learning_record_ids is null
    or p_materialized_at is null
    or array_position(p_learning_record_ids, null) is not null
  then
    raise exception 'learning_evidence_materialization_invalid'
      using errcode = '22023';
  end if;

  if cardinality(p_learning_record_ids) = 0 then
    return;
  end if;

  perform set_config(
    'app.learning_activity_materialization',
    'on',
    true
  );

  insert into public.learning_evidence (
    learner_profile_id,
    recorded_by_account_id,
    learning_record_id,
    source_observation_id,
    source_course_id_at_time,
    source_lesson_id_at_time,
    source_lesson_run_id_at_time,
    source_component_id_at_time,
    source_learning_objective_id_at_time,
    lesson_component_id,
    learning_objective_id,
    course_title_at_time,
    lesson_title_at_time,
    subject_at_time,
    component_type_at_time,
    component_label_at_time,
    component_visibility_at_time,
    objective_title_at_time,
    criterion_at_time,
    direction,
    support,
    observed_at,
    finalized_at,
    materialized_at,
    evidence_version,
    eligibility_policy_version,
    reason_code,
    supersedes_evidence_id
  )
  select
    record.learner_profile_id,
    record.recorded_by_account_id,
    record.id,
    observation.id,
    record.source_course_id_at_time,
    record.source_lesson_id_at_time,
    record.source_lesson_run_id_at_time,
    observation.source_lesson_component_id_at_time,
    observation.source_learning_objective_id_at_time,
    observation.lesson_component_id,
    observation.learning_objective_id,
    btrim(record.course_title_at_time),
    btrim(record.lesson_title_at_time),
    nullif(btrim(record.subject_at_time), ''),
    btrim(observation.component_type_key_at_time),
    btrim(observation.component_label_at_time),
    case when observation.component_visibility_at_time = 'learner_visible'
      then 'learner_visible' else 'staff_only' end,
    btrim(observation.learning_objective_title_at_time),
    btrim(observation.observable_criterion_at_time),
    case when observation.rating = 'not_yet'
      then 'negative' else 'positive' end,
    case observation.rating
      when 'independent' then 'independent'
      when 'with_support' then 'with_support'
      else null
    end,
    observation.observed_at,
    record.occurred_at,
    greatest(
      p_materialized_at,
      observation.observed_at,
      record.occurred_at
    ),
    1,
    1,
    case observation.rating
      when 'independent' then 'independent_positive_evidence'
      when 'with_support' then 'supported_positive_evidence'
      else 'not_yet_negative_evidence'
    end,
    prior_evidence.id
  from public.learning_record as record
  join public.lesson_component_observation as observation
    on observation.learning_record_id = record.id
   and observation.recorded_by_account_id = record.recorded_by_account_id
  left join public.learning_evidence as prior_evidence
    on prior_evidence.source_observation_id =
      observation.corrected_from_observation_id
  where record.id = any(p_learning_record_ids)
    and record.occurred_at is not null
    and record.was_present
    and record.superseded_by_record_id is null
    and observation.superseded_by_observation_id is null
    and record.source_course_id_at_time is not null
    and record.source_lesson_id_at_time is not null
    and record.source_lesson_run_id_at_time is not null
    and record.course_title_at_time is not null
    and char_length(btrim(record.course_title_at_time)) between 1 and 240
    and record.lesson_title_at_time is not null
    and char_length(btrim(record.lesson_title_at_time)) between 1 and 240
    and (
      record.subject_at_time is null
      or char_length(btrim(record.subject_at_time)) between 1 and 240
    )
    and observation.source_learning_objective_id_at_time is not null
    and observation.learning_objective_title_at_time is not null
    and char_length(
      btrim(observation.learning_objective_title_at_time)
    ) between 1 and 240
    and char_length(
      btrim(observation.observable_criterion_at_time)
    ) between 1 and 500
    and observation.entry_method in ('direct', 'bulk_confirmed')
    and observation.rating in ('independent', 'with_support', 'not_yet')
  order by record.id, observation.id
  on conflict (source_observation_id) do nothing;

  update public.learning_evidence as old_evidence
  set superseded_by_evidence_id = new_evidence.id
  from public.learning_evidence as new_evidence
  where new_evidence.learning_record_id = any(p_learning_record_ids)
    and new_evidence.supersedes_evidence_id = old_evidence.id
    and old_evidence.superseded_by_evidence_id is distinct from new_evidence.id;
end
$$;


--
-- Name: open_course_communication_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_course_communication_thread(p_course_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_thread_id uuid;
begin
  if v_actor_account_id is null or p_course_id is null then
    raise exception 'communication_course_not_found' using errcode = 'P0002';
  end if;

  perform course.id
  from public.course as course
  join public.account as owner_account
    on owner_account.id = course.owner_account_id
   and owner_account.status = 'active'
  where course.id = p_course_id
    and course.learning_audience = 'children'
  for key share of course;

  if not found
    or not public.communication_course_account_is_member(
      p_course_id,
      v_actor_account_id
    )
  then
    raise exception 'communication_course_not_found' using errcode = 'P0002';
  end if;

  insert into public.communication_thread (kind, course_id)
  values ('course', p_course_id)
  on conflict (course_id) where kind = 'course' do nothing;

  select thread.id
  into v_thread_id
  from public.communication_thread as thread
  where thread.kind = 'course'
    and thread.course_id = p_course_id;

  return public.communication_thread_projection(
    v_thread_id,
    v_actor_account_id
  );
end
$$;


--
-- Name: open_direct_communication_thread(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_direct_communication_thread(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_profile_id uuid;
  v_other_account_id uuid;
  v_low_account_id uuid;
  v_high_account_id uuid;
  v_thread_id uuid;
begin
  if v_actor_account_id is null or p_learner_profile_id is null then
    raise exception 'communication_target_not_found' using errcode = 'P0002';
  end if;

  v_profile_id := public.resolve_teacher_learner_profile_alias(
    (select auth.uid()),
    p_learner_profile_id
  );

  select profile.account_id
  into v_other_account_id
  from public.teacher_learner as relation
  join public.learner_profile as profile
    on profile.id = relation.learner_profile_id
  join public.account as learner_account
    on learner_account.id = profile.account_id
   and learner_account.status = 'active'
  where relation.teacher_account_id = v_actor_account_id
    and relation.learner_profile_id = v_profile_id
    and relation.archived_at is null;

  if not found or v_other_account_id = v_actor_account_id then
    raise exception 'communication_target_not_found' using errcode = 'P0002';
  end if;

  v_low_account_id := least(v_actor_account_id, v_other_account_id);
  v_high_account_id := greatest(v_actor_account_id, v_other_account_id);

  perform account.id
  from public.account as account
  where account.id in (v_low_account_id, v_high_account_id)
    and account.status = 'active'
  order by account.id
  for key share;

  if not public.communication_direct_link_is_active(
    v_low_account_id,
    v_high_account_id
  ) then
    raise exception 'communication_target_not_found' using errcode = 'P0002';
  end if;

  insert into public.communication_thread (
    kind,
    direct_account_low_id,
    direct_account_high_id
  )
  values ('direct', v_low_account_id, v_high_account_id)
  on conflict (direct_account_low_id, direct_account_high_id)
    where kind = 'direct'
  do nothing;

  select thread.id
  into v_thread_id
  from public.communication_thread as thread
  where thread.kind = 'direct'
    and thread.direct_account_low_id = v_low_account_id
    and thread.direct_account_high_id = v_high_account_id;

  perform public.communication_seed_read_states(v_thread_id, 0);

  return public.communication_thread_projection(
    v_thread_id,
    v_actor_account_id
  );
end
$$;


--
-- Name: preview_email_learner_connection_request(uuid, uuid, bytea, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_email_learner_connection_request(p_actor_auth_user_id uuid, p_connection_request_id uuid, p_token_digest bytea, p_recipient_email_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_profile_id uuid;
  v_request public.learner_connection_request%rowtype;
begin
  if octet_length(p_token_digest) <> 32 or octet_length(p_recipient_email_digest) <> 32 then
    raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
  end if;
  if not public.learner_identity_rate_limit_hit(
    'connection_email_preview',
    extensions.digest(
      coalesce(v_actor_account_id::text, '') || ':' || p_connection_request_id::text,
      'sha256'
    ),
    60, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id
  for update of profile;
  select request.* into v_request
  from public.learner_connection_request as request
  where request.id = p_connection_request_id
    and request.method = 'email'
    and request.token_digest = p_token_digest
    and request.recipient_email_digest = p_recipient_email_digest
    and (request.recipient_account_id is null or request.recipient_account_id = v_actor_account_id)
  for update of request;
  if not found or v_profile_id is null then
    raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
  end if;
  if v_request.status in ('accepted', 'rejected')
    and v_request.recipient_account_id = v_actor_account_id
  then
    return jsonb_build_object(
      'id', v_request.id,
      'kind', 'connection',
      'title', 'Добавление в список учеников',
      'status', v_request.status,
      'inviterLabel', (select display_name from public.account where id = v_request.teacher_account_id),
      'relationshipLabel', null,
      'expiresAt', v_request.expires_at,
      'canAccept', false
    );
  end if;
  if v_request.status <> 'pending' or v_request.expires_at <= now() then
    raise exception 'learner_connection_request_not_found' using errcode = 'P0002';
  end if;
  update public.learner_connection_request
  set recipient_account_id = v_actor_account_id,
      learner_profile_id = v_profile_id
  where id = v_request.id
  returning * into v_request;
  return jsonb_build_object(
    'id', v_request.id,
    'kind', 'connection',
    'title', 'Добавление в список учеников',
    'status', v_request.status,
    'inviterLabel', (select display_name from public.account where id = v_request.teacher_account_id),
    'relationshipLabel', null,
    'expiresAt', v_request.expires_at,
    'canAccept', true
  );
end
$$;


--
-- Name: preview_email_learner_observer_invitation(uuid, uuid, bytea, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_email_learner_observer_invitation(p_actor_auth_user_id uuid, p_invitation_id uuid, p_token_digest bytea, p_recipient_email_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_invitation public.learner_observer_invitation%rowtype;
begin
  if v_actor_account_id is null
    or octet_length(p_token_digest) <> 32
    or octet_length(p_recipient_email_digest) <> 32
  then
    raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
  end if;
  if not public.learner_identity_rate_limit_hit(
    'observer_invitation_preview',
    extensions.digest(
      v_actor_account_id::text || ':' || p_invitation_id::text,
      'sha256'
    ),
    60, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  select invitation.* into v_invitation
  from public.learner_observer_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.token_digest = p_token_digest
    and invitation.recipient_email_digest = p_recipient_email_digest
    and invitation.subject_account_id <> v_actor_account_id
    and (invitation.recipient_account_id is null
      or invitation.recipient_account_id = v_actor_account_id)
  for update of invitation;
  if not found then
    raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
  end if;
  if v_invitation.status in ('accepted', 'rejected')
    and v_invitation.recipient_account_id = v_actor_account_id
  then
    return jsonb_build_object(
      'id', v_invitation.id,
      'kind', 'observer',
      'title', (select display_name from public.account where id = v_invitation.subject_account_id),
      'status', v_invitation.status,
      'inviterLabel', (select display_name from public.account where id = v_invitation.subject_account_id),
      'relationshipLabel', v_invitation.relationship_label,
      'expiresAt', v_invitation.expires_at,
      'canAccept', false
    );
  end if;
  if v_invitation.status not in ('pending', 'bound')
    or v_invitation.expires_at <= now()
  then
    raise exception 'learner_observer_invitation_not_found' using errcode = 'P0002';
  end if;
  update public.learner_observer_invitation
  set recipient_account_id = v_actor_account_id,
      status = 'bound'
  where id = v_invitation.id returning * into v_invitation;
  perform public.append_learner_identity_audit(
    'learner_observer_invitation_previewed', v_actor_account_id,
    v_invitation.subject_account_id, v_invitation.learner_profile_id,
    null, v_invitation.id, jsonb_build_object('projectionVersion', 1)
  );
  return jsonb_build_object(
    'id', v_invitation.id,
    'kind', 'observer',
    'title', (select display_name from public.account where id = v_invitation.subject_account_id),
    'status', v_invitation.status,
    'inviterLabel', (select display_name from public.account where id = v_invitation.subject_account_id),
    'relationshipLabel', v_invitation.relationship_label,
    'expiresAt', v_invitation.expires_at,
    'canAccept', true
  );
end
$$;


--
-- Name: preview_learner_profile_invitation(uuid, uuid, bytea, bytea); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_learner_profile_invitation(p_actor_auth_user_id uuid, p_invitation_id uuid, p_token_digest bytea, p_recipient_email_digest bytea) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_target_profile_id uuid;
  v_source_profile public.learner_profile%rowtype;
  v_invitation public.learner_claim_invitation%rowtype;
  v_operation_id uuid;
  v_operation public.learner_profile_merge%rowtype;
  v_merge_preview jsonb;
begin
  if v_actor_account_id is null
    or octet_length(p_token_digest) <> 32
    or octet_length(p_recipient_email_digest) <> 32
  then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;
  if not public.learner_identity_rate_limit_hit(
    'profile_invitation_preview',
    extensions.digest(
      v_actor_account_id::text || ':' || p_invitation_id::text,
      'sha256'
    ),
    60, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  select invitation.* into v_invitation
  from public.learner_claim_invitation as invitation
  where invitation.id = p_invitation_id
    and invitation.token_digest = p_token_digest
    and invitation.recipient_email_digest = p_recipient_email_digest
    and (invitation.recipient_account_id is null
      or invitation.recipient_account_id = v_actor_account_id)
  for update of invitation;
  if not found then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;

  if v_invitation.status in ('accepted', 'rejected')
    and v_invitation.recipient_account_id = v_actor_account_id
  then
    select operation.* into v_operation
    from public.learner_profile_merge as operation
    where operation.invitation_id = v_invitation.id;
    return jsonb_build_object(
      'invitation', jsonb_build_object(
        'id', v_invitation.id,
        'kind', v_invitation.kind,
        'status', v_invitation.status,
        'learnerProfileId', coalesce(
          v_operation.target_learner_profile_id,
          v_invitation.source_learner_profile_id
        ),
        'learnerLabel', coalesce((
          select profile.display_name from public.learner_profile as profile
          where profile.id = v_operation.target_learner_profile_id
        ), 'Учебный профиль'),
        'inviterLabel', (
          select account.display_name from public.account as account
          where account.id = v_invitation.inviter_account_id
        ),
        'expiresAt', v_invitation.expires_at,
        'createdAt', v_invitation.created_at,
        'acceptedAt', v_invitation.accepted_at
      ),
      'mergePreview', v_operation.preview_payload,
      'completed', v_invitation.status = 'accepted',
      'childAccountLogin', case when v_invitation.kind = 'child_activation' then (
        select alias.normalized_login
        from public.account_login_alias as alias
        where alias.account_id = v_operation.subject_account_id
          and alias.revoked_at is null
        order by alias.created_at desc limit 1
      ) else null end,
      'observerInvitationId', case when v_invitation.kind = 'child_activation' then (
        select observer_invitation.id
        from public.learner_observer_invitation as observer_invitation
        where observer_invitation.learner_profile_id = v_operation.target_learner_profile_id
          and observer_invitation.subject_account_id = v_operation.subject_account_id
          and observer_invitation.recipient_account_id = v_actor_account_id
        order by observer_invitation.created_at desc limit 1
      ) else null end
    );
  end if;

  if v_invitation.status not in ('pending', 'bound')
    or v_invitation.expires_at <= now()
  then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;
  select profile.* into v_source_profile
  from public.learner_profile as profile
  where profile.id = v_invitation.source_learner_profile_id
    and profile.account_id is null
  for update of profile;
  if not found then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;
  select profile.id into v_target_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id
  for update of profile;
  if not found or v_target_profile_id = v_source_profile.id then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;

  update public.learner_claim_invitation
  set recipient_account_id = v_actor_account_id,
      status = 'bound'
  where id = v_invitation.id
  returning * into v_invitation;

  if v_invitation.kind = 'claim' then
    select operation.id into v_operation_id
    from public.learner_profile_merge as operation
    where operation.invitation_id = v_invitation.id;
    if not found then
      insert into public.learner_profile_merge (
        source_learner_profile_id, target_learner_profile_id,
        invitation_id, requested_by_account_id, subject_account_id,
        expires_at
      ) values (
        v_source_profile.id, v_target_profile_id,
        v_invitation.id, v_invitation.inviter_account_id, v_actor_account_id,
        least(v_invitation.expires_at, now() + interval '1 day')
      ) returning id into v_operation_id;
    end if;
    v_merge_preview := public.learner_profile_merge_preview_for_actor(
      v_operation_id, v_actor_account_id
    );
  end if;

  perform public.append_learner_identity_audit(
    'learner_profile_invitation_previewed', v_actor_account_id,
    v_actor_account_id, v_source_profile.id, v_target_profile_id,
    v_invitation.id,
    jsonb_build_object('kind', v_invitation.kind, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'invitation', jsonb_build_object(
      'id', v_invitation.id, 'kind', v_invitation.kind,
      'status', v_invitation.status,
      'learnerProfileId', v_source_profile.id,
      'learnerLabel', v_source_profile.display_name,
      'inviterLabel', (select display_name from public.account where id = v_invitation.inviter_account_id),
      'expiresAt', v_invitation.expires_at, 'createdAt', v_invitation.created_at,
      'acceptedAt', v_invitation.accepted_at
    ),
    'mergePreview', v_merge_preview,
    'completed', false,
    'childAccountLogin', null
  );
end
$$;


