--
-- Name: publish_course_revision_admin(uuid, uuid, uuid, uuid, text, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_course_revision_admin(p_actor_account_id uuid, p_source_course_id uuid, p_publication_id uuid, p_revision_id uuid, p_content_sha256 text, p_snapshot jsonb, p_asset_manifest jsonb, p_rights_confirmed boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_course public.course%rowtype;
  v_publisher_display_name text;
  v_publication public.course_publication%rowtype;
  v_revision public.course_publication_revision%rowtype;
  v_revision_number integer;
  v_lesson_count integer;
  v_component_count integer;
  v_objective_count integer;
  v_slide_count integer;
  v_asset_count integer;
  v_asset_total_bytes bigint;
  v_existing_snapshot_bytes bigint;
  v_existing_asset_bytes bigint;
  v_candidate_storage_bytes bigint;
  v_asset_id_map jsonb;
  v_snapshot_course jsonb;
  v_snapshot_version integer;
begin
  if p_actor_account_id is null
    or p_source_course_id is null
    or p_publication_id is null
    or p_revision_id is null
    or p_content_sha256 is null
    or p_content_sha256 !~ '^[0-9a-f]{64}$'
    or p_rights_confirmed is distinct from true
    or p_snapshot is null
    or jsonb_typeof(p_snapshot) <> 'object'
    or p_asset_manifest is null
    or jsonb_typeof(p_asset_manifest) <> 'array'
  then
    raise exception 'course_publication_publish_invalid'
      using errcode = '22023';
  end if;

  v_snapshot_version := case
    when p_snapshot ->> 'schemaVersion' in ('1', '2')
      then (p_snapshot ->> 'schemaVersion')::integer
    else null
  end;

  if v_snapshot_version is null
    or (
      v_snapshot_version = 1
      and (
        (p_snapshot - array['schemaVersion', 'course', 'lessons', 'materials'])
          <> '{}'::jsonb
        or not (p_snapshot ?& array[
          'schemaVersion', 'course', 'lessons', 'materials'
        ])
      )
    )
    or (
      v_snapshot_version = 2
      and (
        (p_snapshot - array[
          'schemaVersion', 'course', 'objectives', 'lessons', 'materials'
        ]) <> '{}'::jsonb
        or not (p_snapshot ?& array[
          'schemaVersion', 'course', 'objectives', 'lessons', 'materials'
        ])
        or jsonb_typeof(p_snapshot -> 'objectives') <> 'array'
      )
    )
    or jsonb_typeof(p_snapshot -> 'course') <> 'object'
    or jsonb_typeof(p_snapshot -> 'lessons') <> 'array'
    or jsonb_typeof(p_snapshot -> 'materials') <> 'array'
  then
    raise exception 'course_publication_snapshot_shape_invalid'
      using errcode = '22023';
  end if;

  select course.*
  into v_course
  from public.course as course
  where course.id = p_source_course_id
    and course.owner_account_id = p_actor_account_id
  for update;

  if not found then
    raise exception 'course_publication_source_not_found'
      using errcode = 'P0002';
  end if;

  select account.display_name
  into v_publisher_display_name
  from public.account as account
  where account.id = p_actor_account_id
    and account.status = 'active'
  for update;

  if not found then
    raise exception 'course_publication_actor_not_active'
      using errcode = '42501';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  where publication.source_course_id = p_source_course_id
  for update;

  if found and v_publication.id <> p_publication_id then
    raise exception 'course_publication_id_conflict'
      using errcode = '23505';
  end if;

  if v_publication.id is not null then
    select revision.*
    into strict v_revision
    from public.course_publication_revision as revision
    where revision.id = v_publication.current_revision_id;
  end if;

  perform 1
  from public.lesson as lesson
  where lesson.course_id = p_source_course_id
  order by lesson.id
  for update;

  perform 1
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  where lesson.course_id = p_source_course_id
  order by component.id
  for update of component;

  perform 1
  from public.learning_objective as objective
  where objective.course_id = p_source_course_id
  order by objective.created_at, objective.id
  for share of objective;

  perform 1
  from public.lesson_student_slide as slide
  join public.lesson as lesson on lesson.id = slide.lesson_id
  where lesson.course_id = p_source_course_id
  order by slide.id
  for update of slide;

  perform 1
  from public.course_attachment as attachment
  where attachment.course_id = p_source_course_id
  order by attachment.id
  for update;

  perform 1
  from public.stored_file as stored_file
  join public.course_attachment as attachment
    on attachment.stored_file_id = stored_file.id
  where attachment.course_id = p_source_course_id
  order by stored_file.id
  for share of stored_file;

  v_snapshot_course := p_snapshot -> 'course';

  if (v_snapshot_course - array[
      'title',
      'subject',
      'goal',
      'level',
      'audienceDescription',
      'targetLessonCount'
    ]) <> '{}'::jsonb
    or not (v_snapshot_course ?& array[
      'title',
      'subject',
      'goal',
      'level',
      'audienceDescription',
      'targetLessonCount'
    ])
    or v_snapshot_course ->> 'title' is distinct from v_course.title
    or coalesce(v_snapshot_course ->> 'subject', '')
      is distinct from coalesce(v_course.subject, '')
    or coalesce(v_snapshot_course ->> 'goal', '')
      is distinct from coalesce(v_course.goal, '')
    or coalesce(v_snapshot_course ->> 'level', '')
      is distinct from coalesce(v_course.level, '')
    or coalesce(v_snapshot_course ->> 'audienceDescription', '')
      is distinct from coalesce(v_course.audience_description, '')
    or coalesce(v_snapshot_course -> 'targetLessonCount', 'null'::jsonb)
      is distinct from coalesce(to_jsonb(v_course.target_lesson_count), 'null'::jsonb)
  then
    raise exception 'course_publication_course_snapshot_mismatch'
      using errcode = '23514';
  end if;

  select count(*)::integer
  into v_objective_count
  from public.learning_objective as objective
  where objective.course_id = p_source_course_id;

  if v_snapshot_version = 1 then
    if v_objective_count <> 0
      or exists (
        select 1
        from public.lesson_component as component
        join public.lesson as lesson on lesson.id = component.lesson_id
        where lesson.course_id = p_source_course_id
          and (
            component.primary_learning_objective_id is not null
            or component.activity_role is not null
          )
      )
    then
      raise exception 'course_publication_snapshot_version_too_old'
        using errcode = '23514';
    end if;
  elsif jsonb_array_length(p_snapshot -> 'objectives') <> v_objective_count
    or exists (
      select 1
      from jsonb_array_elements(p_snapshot -> 'objectives')
        as submitted(value)
      where jsonb_typeof(submitted.value) <> 'object'
        or (submitted.value - array[
          'ref',
          'position',
          'title',
          'description',
          'archivedAt'
        ]) <> '{}'::jsonb
        or not (submitted.value ?& array[
          'ref',
          'position',
          'title',
          'description',
          'archivedAt'
        ])
        or jsonb_typeof(submitted.value -> 'ref') <> 'string'
        or jsonb_typeof(submitted.value -> 'position') <> 'number'
        or jsonb_typeof(submitted.value -> 'title') <> 'string'
        or coalesce(jsonb_typeof(submitted.value -> 'description'), 'null')
          not in ('string', 'null')
        or coalesce(jsonb_typeof(submitted.value -> 'archivedAt'), 'null')
          not in ('string', 'null')
        or char_length(btrim(submitted.value ->> 'title'))
          not between 2 and 240
        or (
          jsonb_typeof(submitted.value -> 'description') = 'string'
          and (
            btrim(submitted.value ->> 'description') = ''
            or char_length(btrim(submitted.value ->> 'description')) > 2000
          )
        )
    )
    or (
      select count(distinct (submitted.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_snapshot -> 'objectives')
        as submitted(value)
    ) <> v_objective_count
    or (
      select count(distinct (submitted.value ->> 'position')::integer)
      from jsonb_array_elements(p_snapshot -> 'objectives')
        as submitted(value)
    ) <> v_objective_count
    or exists (
      with ordered_objective as (
        select
          objective.*,
          row_number() over (
            order by objective.created_at, objective.id
          )::integer as position
        from public.learning_objective as objective
        where objective.course_id = p_source_course_id
      )
      select 1
      from ordered_objective as objective
      left join lateral (
        select submitted.value
        from jsonb_array_elements(p_snapshot -> 'objectives')
          as submitted(value)
        where (submitted.value ->> 'position')::integer = objective.position
        limit 1
      ) as submitted on true
      where submitted.value is null
        or submitted.value ->> 'title' is distinct from objective.title
        or nullif(submitted.value ->> 'description', '')
          is distinct from objective.description
        or case
          when jsonb_typeof(submitted.value -> 'archivedAt') = 'string'
            then (submitted.value ->> 'archivedAt')::timestamptz
          else null
        end is distinct from objective.archived_at
    )
  then
    raise exception 'course_publication_objective_snapshot_mismatch'
      using errcode = '23514';
  end if;

  select count(*)::integer
  into v_lesson_count
  from public.lesson as lesson
  where lesson.course_id = p_source_course_id;

  if v_lesson_count < 1
    or jsonb_array_length(p_snapshot -> 'lessons') <> v_lesson_count
  then
    raise exception 'course_publication_requires_lessons'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted(value)
    where jsonb_typeof(submitted.value) <> 'object'
      or (submitted.value - array[
        'ref',
        'position',
        'title',
        'summary',
        'estimatedDurationMinutes',
        'components',
        'slides'
      ]) <> '{}'::jsonb
      or not (submitted.value ?& array[
        'ref',
        'position',
        'title',
        'summary',
        'estimatedDurationMinutes',
        'components',
        'slides'
      ])
      or jsonb_typeof(submitted.value -> 'components') <> 'array'
      or jsonb_typeof(submitted.value -> 'slides') <> 'array'
  ) then
    raise exception 'course_publication_lesson_snapshot_invalid'
      using errcode = '22023';
  end if;

  if (
    select count(distinct (submitted.value ->> 'ref')::uuid)
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted(value)
  ) <> v_lesson_count
  or exists (
    select 1
    from public.lesson as lesson
    left join lateral (
      select submitted.value
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted(value)
      where (submitted.value ->> 'position')::integer = lesson.position
      limit 1
    ) as submitted on true
    where lesson.course_id = p_source_course_id
      and (
        submitted.value is null
        or (submitted.value ->> 'position')::integer <> lesson.position
        or submitted.value ->> 'title' is distinct from lesson.title
        or coalesce(submitted.value ->> 'summary', '')
          is distinct from coalesce(lesson.summary, '')
        or coalesce(
          submitted.value -> 'estimatedDurationMinutes',
          'null'::jsonb
        ) is distinct from coalesce(
          to_jsonb(lesson.estimated_duration_minutes),
          'null'::jsonb
        )
      )
  ) then
    raise exception 'course_publication_lesson_snapshot_mismatch'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
    cross join lateral jsonb_array_elements(
      submitted_lesson.value -> 'components'
    ) as submitted_component(value)
    where jsonb_typeof(submitted_component.value) <> 'object'
      or (
        v_snapshot_version = 1
        and (
          (submitted_component.value - array[
            'ref',
            'position',
            'typeKey',
            'schemaVersion',
            'payload',
            'placement',
            'visibility',
            'studentSlideRef'
          ]) <> '{}'::jsonb
          or not (submitted_component.value ?& array[
            'ref',
            'position',
            'typeKey',
            'schemaVersion',
            'payload',
            'placement',
            'visibility',
            'studentSlideRef'
          ])
        )
      )
      or (
        v_snapshot_version = 2
        and (
          (submitted_component.value - array[
            'ref',
            'position',
            'typeKey',
            'schemaVersion',
            'payload',
            'placement',
            'visibility',
            'studentSlideRef',
            'primaryObjectiveRef',
            'activityRole'
          ]) <> '{}'::jsonb
          or not (submitted_component.value ?& array[
            'ref',
            'position',
            'typeKey',
            'schemaVersion',
            'payload',
            'placement',
            'visibility',
            'studentSlideRef',
            'primaryObjectiveRef',
            'activityRole'
          ])
          or coalesce(
            jsonb_typeof(submitted_component.value -> 'primaryObjectiveRef'),
            'null'
          ) not in ('string', 'null')
          or coalesce(
            jsonb_typeof(submitted_component.value -> 'activityRole'),
            'null'
          ) not in ('string', 'null')
          or (
            jsonb_typeof(submitted_component.value -> 'activityRole') =
              'string'
            and submitted_component.value ->> 'activityRole'
              not in ('practice', 'assessment', 'survey')
          )
        )
      )
      or jsonb_typeof(submitted_component.value -> 'payload') <> 'object'
      or jsonb_typeof(submitted_component.value -> 'placement') <> 'object'
  ) then
    raise exception 'course_publication_component_snapshot_invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into v_component_count
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  where lesson.course_id = p_source_course_id;

  if (
    select count(*)
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
    cross join lateral jsonb_array_elements(
      submitted_lesson.value -> 'components'
    ) as submitted_component(value)
  ) <> v_component_count
  or (
    select count(distinct (submitted_component.value ->> 'ref')::uuid)
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
    cross join lateral jsonb_array_elements(
      submitted_lesson.value -> 'components'
    ) as submitted_component(value)
  ) <> v_component_count
  or exists (
    select 1
    from public.lesson_component as component
    join public.lesson as lesson on lesson.id = component.lesson_id
    left join lateral (
      select submitted_component.value
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'components'
      ) as submitted_component(value)
      where (submitted_lesson.value ->> 'position')::integer = lesson.position
        and (submitted_component.value ->> 'position')::integer
          = component.position
      limit 1
    ) as submitted on true
    left join public.lesson_student_slide as source_slide
      on source_slide.id = component.student_slide_id
    left join lateral (
      select submitted_slide.value
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'slides'
      ) as submitted_slide(value)
      where source_slide.id is not null
        and (submitted_lesson.value ->> 'position')::integer = lesson.position
        and (submitted_slide.value ->> 'position')::integer
          = source_slide.position
      limit 1
    ) as submitted_slide on true
    left join lateral (
      select ordered.position
      from (
        select
          objective.id,
          row_number() over (
            order by objective.created_at, objective.id
          )::integer as position
        from public.learning_objective as objective
        where objective.course_id = p_source_course_id
      ) as ordered
      where ordered.id = component.primary_learning_objective_id
      limit 1
    ) as source_objective on true
    left join lateral (
      select submitted_objective.value
      from jsonb_array_elements(
        case
          when v_snapshot_version = 2 then p_snapshot -> 'objectives'
          else '[]'::jsonb
        end
      ) as submitted_objective(value)
      where source_objective.position is not null
        and (submitted_objective.value ->> 'position')::integer
          = source_objective.position
      limit 1
    ) as submitted_objective on true
    where lesson.course_id = p_source_course_id
      and (
        submitted.value is null
        or (submitted.value ->> 'position')::integer <> component.position
        or submitted.value ->> 'typeKey' is distinct from component.type_key
        or (submitted.value ->> 'schemaVersion')::integer
          <> component.schema_version
        or submitted.value -> 'placement'
          is distinct from component.placement_config
        or submitted.value ->> 'visibility'
          is distinct from component.visibility
        or coalesce(submitted.value ->> 'studentSlideRef', '')
          is distinct from coalesce(
            submitted_slide.value ->> 'ref',
            ''
          )
        or (
          v_snapshot_version = 2
          and coalesce(submitted.value ->> 'primaryObjectiveRef', '')
            is distinct from coalesce(
              submitted_objective.value ->> 'ref',
              ''
            )
        )
        or (
          v_snapshot_version = 2
          and nullif(submitted.value ->> 'activityRole', '')
            is distinct from component.activity_role
        )
        or (
          component.type_key not in ('image', 'slideshow', 'file')
          and submitted.value -> 'payload' is distinct from component.payload
        )
      )
  ) then
    raise exception 'course_publication_component_snapshot_mismatch'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
    cross join lateral jsonb_array_elements(
      submitted_lesson.value -> 'slides'
    ) as submitted_slide(value)
    where jsonb_typeof(submitted_slide.value) <> 'object'
      or (submitted_slide.value - array['ref', 'position']) <> '{}'::jsonb
      or not (submitted_slide.value ?& array['ref', 'position'])
  ) then
    raise exception 'course_publication_slide_snapshot_invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into v_slide_count
  from public.lesson_student_slide as slide
  join public.lesson as lesson on lesson.id = slide.lesson_id
  where lesson.course_id = p_source_course_id;

  if (
    select count(*)
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
    cross join lateral jsonb_array_elements(
      submitted_lesson.value -> 'slides'
    ) as submitted_slide(value)
  ) <> v_slide_count
  or (
    select count(distinct (submitted_slide.value ->> 'ref')::uuid)
    from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
    cross join lateral jsonb_array_elements(
      submitted_lesson.value -> 'slides'
    ) as submitted_slide(value)
  ) <> v_slide_count
  or exists (
    select 1
    from public.lesson_student_slide as slide
    join public.lesson as lesson on lesson.id = slide.lesson_id
    left join lateral (
      select submitted_slide.value
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'slides'
      ) as submitted_slide(value)
      where (submitted_lesson.value ->> 'position')::integer = lesson.position
        and (submitted_slide.value ->> 'position')::integer = slide.position
      limit 1
    ) as submitted on true
    where lesson.course_id = p_source_course_id
      and (
        submitted.value is null
        or (submitted.value ->> 'position')::integer <> slide.position
      )
  ) then
    raise exception 'course_publication_slide_snapshot_mismatch'
      using errcode = '23514';
  end if;

  if (
    select count(*) <> count(distinct authored.ref)
    from (
      select (submitted_objective.value ->> 'ref')::uuid as ref
      from jsonb_array_elements(
        case
          when v_snapshot_version = 2 then p_snapshot -> 'objectives'
          else '[]'::jsonb
        end
      ) as submitted_objective(value)
      union all
      select (submitted_lesson.value ->> 'ref')::uuid as ref
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      union all
      select (submitted_component.value ->> 'ref')::uuid
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'components'
      ) as submitted_component(value)
      union all
      select (submitted_slide.value ->> 'ref')::uuid
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'slides'
      ) as submitted_slide(value)
    ) as authored(ref)
  ) then
    raise exception 'course_publication_authored_refs_not_unique'
      using errcode = '22023';
  end if;

  -- Republish the immutable current revision without requiring a second set of
  -- copied objects. Equality of both the caller hash and canonical snapshot is
  -- required so a forged hash cannot select stale catalog content.
  if v_publication.id is not null
    and v_revision.content_sha256 = p_content_sha256
    and v_revision.snapshot = p_snapshot
  then
    v_asset_count := jsonb_array_length(p_snapshot -> 'materials');

    if jsonb_array_length(p_asset_manifest) <> 0
      or v_asset_count > 24
      or exists (
        select 1
        from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
        where jsonb_typeof(material.value) <> 'object'
          or (material.value - array[
            'ref',
            'originalFilename',
            'mimeType',
            'sizeBytes',
            'checksumSha256'
          ]) <> '{}'::jsonb
          or not (material.value ?& array[
            'ref',
            'originalFilename',
            'mimeType',
            'sizeBytes',
            'checksumSha256'
          ])
      )
    then
      raise exception 'course_publication_idempotent_assets_invalid'
        using errcode = '22023';
    end if;

    -- A byte-equal snapshot is acknowledged only if the live Course still has
    -- exactly the attachment set and ready StoredFile metadata captured by the
    -- immutable revision. This closes the service-read -> RPC detach race.
    if (
      select count(*)
      from public.course_publication_asset as asset
      where asset.revision_id = v_revision.id
    ) <> v_asset_count
    or (
      select count(*)
      from public.course_attachment as attachment
      where attachment.course_id = p_source_course_id
    ) <> v_asset_count
    or (
      select count(distinct (material.value ->> 'ref')::uuid)
      from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
    ) <> v_asset_count
    or exists (
      select 1
      from public.course_publication_asset as asset
      left join public.course_attachment as attachment
        on attachment.course_id = p_source_course_id
        and attachment.stored_file_id = asset.source_stored_file_id
      left join public.stored_file as stored_file
        on stored_file.id = asset.source_stored_file_id
      left join lateral (
        select material.value
        from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
        where (material.value ->> 'ref')::uuid = asset.id
        limit 1
      ) as material on true
      where asset.revision_id = v_revision.id
        and (
          asset.source_stored_file_id is null
          or attachment.id is null
          or stored_file.id is null
          or stored_file.owner_account_id <> p_actor_account_id
          or stored_file.status <> 'ready'
          or stored_file.original_filename
            is distinct from asset.original_filename
          or stored_file.mime_type is distinct from asset.mime_type
          or stored_file.size_bytes is distinct from asset.size_bytes
          or stored_file.checksum_sha256
            is distinct from asset.checksum_sha256
          or material.value is null
          or material.value ->> 'originalFilename'
            is distinct from asset.original_filename
          or material.value ->> 'mimeType' is distinct from asset.mime_type
          or (material.value ->> 'sizeBytes')::bigint
            is distinct from asset.size_bytes
          or material.value ->> 'checksumSha256'
            is distinct from asset.checksum_sha256
          or not exists (
            select 1
            from storage.objects as object
            where object.bucket_id = asset.storage_bucket
              and object.name = asset.storage_path
          )
        )
    )
    then
      raise exception 'course_publication_idempotent_assets_mismatch'
        using errcode = '23514';
    end if;

    select coalesce(
      jsonb_object_agg(
        asset.source_stored_file_id::text,
        to_jsonb(asset.id::text)
      ) filter (where asset.source_stored_file_id is not null),
      '{}'::jsonb
    )
    into v_asset_id_map
    from public.course_publication_asset as asset
    where asset.revision_id = v_revision.id;

    if not public.course_publication_snapshot_payloads_match(
      p_source_course_id,
      p_snapshot,
      v_asset_id_map
    ) then
      raise exception 'course_publication_component_payload_mismatch'
        using errcode = '23514';
    end if;

    update public.course_publication as publication
    set title = v_snapshot_course ->> 'title',
        subject = v_snapshot_course ->> 'subject',
        goal = v_snapshot_course ->> 'goal',
        level = v_snapshot_course ->> 'level',
        audience_description = v_snapshot_course ->> 'audienceDescription',
        target_lesson_count =
          (v_snapshot_course ->> 'targetLessonCount')::integer,
        lesson_count = v_lesson_count,
        material_count = jsonb_array_length(p_snapshot -> 'materials'),
        source_content_updated_at =
          v_course.publication_content_updated_at,
        status = 'published',
        unpublished_at = null,
        updated_at = clock_timestamp()
    where publication.id = v_publication.id
    returning publication.* into v_publication;

    return jsonb_build_object(
      'publicationId', v_publication.id,
      'sourceCourseId', v_publication.source_course_id,
      'status', v_publication.status,
      'currentRevisionId', v_revision.id,
      'publishedAt', v_publication.published_at,
      'updatedAt', v_publication.updated_at,
      'sourceCourseUpdatedAt', v_revision.source_course_updated_at,
      'sourceContentUpdatedAt', v_publication.source_content_updated_at,
      'contentSha256', v_revision.content_sha256
    );
  end if;

  if v_publication.id is not null
    and v_revision.content_sha256 = p_content_sha256
  then
    raise exception 'course_publication_current_hash_snapshot_mismatch'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
    where jsonb_typeof(material.value) <> 'object'
      or (material.value - array[
        'ref',
        'originalFilename',
        'mimeType',
        'sizeBytes',
        'checksumSha256'
      ]) <> '{}'::jsonb
      or not (material.value ?& array[
        'ref',
        'originalFilename',
        'mimeType',
        'sizeBytes',
        'checksumSha256'
      ])
  ) or exists (
    select 1
    from jsonb_array_elements(p_asset_manifest) as asset(value)
    where jsonb_typeof(asset.value) <> 'object'
      or (asset.value - array[
        'publicationAssetId',
        'sourceStoredFileId',
        'originalFilename',
        'mimeType',
        'sizeBytes',
        'checksumSha256',
        'storageBucket',
        'storagePath'
      ]) <> '{}'::jsonb
      or not (asset.value ?& array[
        'publicationAssetId',
        'sourceStoredFileId',
        'originalFilename',
        'mimeType',
        'sizeBytes',
        'checksumSha256',
        'storageBucket',
        'storagePath'
      ])
  ) then
    raise exception 'course_publication_asset_manifest_shape_invalid'
      using errcode = '22023';
  end if;

  v_asset_count := jsonb_array_length(p_asset_manifest);
  if v_asset_count > 24
    or jsonb_array_length(p_snapshot -> 'materials') <> v_asset_count
    or (
      select count(*)
      from public.course_attachment as attachment
      where attachment.course_id = p_source_course_id
    ) <> v_asset_count
  then
    raise exception 'course_publication_asset_limit_exceeded'
      using errcode = '54000';
  end if;

  select coalesce(sum(asset."sizeBytes"), 0)
  into v_asset_total_bytes
  from jsonb_to_recordset(p_asset_manifest) as asset(
    "publicationAssetId" uuid,
    "sourceStoredFileId" uuid,
    "originalFilename" text,
    "mimeType" text,
    "sizeBytes" bigint,
    "checksumSha256" text,
    "storageBucket" text,
    "storagePath" text
  );

  if v_asset_total_bytes > 125829120
    or (
      select count(distinct asset."publicationAssetId")
      from jsonb_to_recordset(p_asset_manifest) as asset(
        "publicationAssetId" uuid,
        "sourceStoredFileId" uuid
      )
    ) <> v_asset_count
    or (
      select count(distinct asset."sourceStoredFileId")
      from jsonb_to_recordset(p_asset_manifest) as asset(
        "publicationAssetId" uuid,
        "sourceStoredFileId" uuid
      )
    ) <> v_asset_count
  then
    raise exception 'course_publication_asset_manifest_not_exact'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_asset_manifest) as asset(
      "publicationAssetId" uuid,
      "sourceStoredFileId" uuid,
      "originalFilename" text,
      "mimeType" text,
      "sizeBytes" bigint,
      "checksumSha256" text,
      "storageBucket" text,
      "storagePath" text
    )
    left join public.course_attachment as attachment
      on attachment.course_id = p_source_course_id
      and attachment.stored_file_id = asset."sourceStoredFileId"
    left join public.stored_file as stored_file
      on stored_file.id = asset."sourceStoredFileId"
    left join lateral (
      select material.value
      from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
      where (material.value ->> 'ref')::uuid = asset."publicationAssetId"
      limit 1
    ) as material on true
    where attachment.id is null
      or stored_file.id is null
      or stored_file.owner_account_id <> p_actor_account_id
      or stored_file.status <> 'ready'
      or stored_file.original_filename is distinct from asset."originalFilename"
      or stored_file.mime_type is distinct from asset."mimeType"
      or stored_file.size_bytes is distinct from asset."sizeBytes"
      or stored_file.checksum_sha256 is distinct from asset."checksumSha256"
      or asset."sizeBytes" <= 0
      or asset."sizeBytes" > 10485760
      or asset."checksumSha256" !~ '^[0-9a-f]{64}$'
      or asset."storageBucket" <> 'course-publication-assets'
      or asset."storagePath" <> concat(
        p_publication_id::text,
        '/revisions/',
        p_revision_id::text,
        '/assets/',
        asset."publicationAssetId"::text
      )
      or material.value is null
      or material.value ->> 'originalFilename'
        is distinct from asset."originalFilename"
      or material.value ->> 'mimeType' is distinct from asset."mimeType"
      or (material.value ->> 'sizeBytes')::bigint
        is distinct from asset."sizeBytes"
      or material.value ->> 'checksumSha256'
        is distinct from asset."checksumSha256"
      or not exists (
        select 1
        from storage.objects as object
        where object.bucket_id = 'course-publication-assets'
          and object.name = asset."storagePath"
      )
  ) then
    raise exception 'course_publication_asset_manifest_mismatch'
      using errcode = '23514';
  end if;

  if (
    select count(distinct (material.value ->> 'ref')::uuid)
    from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
  ) <> v_asset_count
  or (
    select count(*) <> count(distinct all_ref.ref)
    from (
      select (submitted_objective.value ->> 'ref')::uuid as ref
      from jsonb_array_elements(
        case
          when v_snapshot_version = 2 then p_snapshot -> 'objectives'
          else '[]'::jsonb
        end
      ) as submitted_objective(value)
      union all
      select (submitted_lesson.value ->> 'ref')::uuid as ref
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      union all
      select (submitted_component.value ->> 'ref')::uuid
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'components'
      ) as submitted_component(value)
      union all
      select (submitted_slide.value ->> 'ref')::uuid
      from jsonb_array_elements(p_snapshot -> 'lessons') as submitted_lesson(value)
      cross join lateral jsonb_array_elements(
        submitted_lesson.value -> 'slides'
      ) as submitted_slide(value)
      union all
      select (material.value ->> 'ref')::uuid
      from jsonb_array_elements(p_snapshot -> 'materials') as material(value)
    ) as all_ref(ref)
  )
  then
    raise exception 'course_publication_material_manifest_not_exact'
      using errcode = '22023';
  end if;

  select coalesce(
    jsonb_object_agg(
      asset."sourceStoredFileId"::text,
      to_jsonb(asset."publicationAssetId"::text)
    ),
    '{}'::jsonb
  )
  into v_asset_id_map
  from jsonb_to_recordset(p_asset_manifest) as asset(
    "publicationAssetId" uuid,
    "sourceStoredFileId" uuid
  );

  if not public.course_publication_snapshot_payloads_match(
    p_source_course_id,
    p_snapshot,
    v_asset_id_map
  ) then
    raise exception 'course_publication_component_payload_mismatch'
      using errcode = '23514';
  end if;

  -- The Account row was locked above, so concurrent publications for this
  -- owner cannot both observe the same remaining quota. This branch is only
  -- reached for a new immutable revision; idempotent republish returned before
  -- it and consumes no additional quota.
  v_candidate_storage_bytes :=
    octet_length(p_snapshot::text)::bigint + v_asset_total_bytes;

  select coalesce(
    sum(octet_length(revision.snapshot::text)::bigint),
    0
  )
  into v_existing_snapshot_bytes
  from public.course_publication_revision as revision
  join public.course_publication as publication
    on publication.id = revision.publication_id
  where publication.owner_account_id = p_actor_account_id;

  select coalesce(sum(asset.size_bytes), 0)
  into v_existing_asset_bytes
  from public.course_publication_asset as asset
  join public.course_publication_revision as revision
    on revision.id = asset.revision_id
  join public.course_publication as publication
    on publication.id = revision.publication_id
  where publication.owner_account_id = p_actor_account_id;

  if v_existing_snapshot_bytes
      + v_existing_asset_bytes
      + v_candidate_storage_bytes > 5368709120
  then
    raise exception 'course_publication_account_quota_exceeded'
      using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from public.course_publication_revision as revision
    where revision.id = p_revision_id
  ) then
    raise exception 'course_publication_revision_id_conflict'
      using errcode = '23505';
  end if;

  select coalesce(max(revision.revision_number), 0) + 1
  into v_revision_number
  from public.course_publication_revision as revision
  where revision.publication_id = p_publication_id;

  if v_publication.id is null then
    insert into public.course_publication (
      id,
      source_course_id,
      owner_account_id,
      publisher_display_name,
      is_shidao,
      title,
      subject,
      goal,
      level,
      audience_description,
      target_lesson_count,
      lesson_count,
      material_count,
      status,
      current_revision_id,
      source_content_updated_at,
      published_at,
      unpublished_at,
      created_at,
      updated_at
    )
    values (
      p_publication_id,
      p_source_course_id,
      p_actor_account_id,
      v_publisher_display_name,
      false,
      v_snapshot_course ->> 'title',
      v_snapshot_course ->> 'subject',
      v_snapshot_course ->> 'goal',
      v_snapshot_course ->> 'level',
      v_snapshot_course ->> 'audienceDescription',
      (v_snapshot_course ->> 'targetLessonCount')::integer,
      v_lesson_count,
      v_asset_count,
      'published',
      p_revision_id,
      v_course.publication_content_updated_at,
      clock_timestamp(),
      null,
      clock_timestamp(),
      clock_timestamp()
    )
    returning * into v_publication;
  end if;

  insert into public.course_publication_revision (
    id,
    publication_id,
    revision_number,
    source_course_updated_at,
    content_sha256,
    snapshot,
    rights_confirmed_at,
    license_code,
    published_at
  )
  values (
    p_revision_id,
    p_publication_id,
    v_revision_number,
    v_course.publication_content_updated_at,
    p_content_sha256,
    p_snapshot,
    clock_timestamp(),
    'shidao_catalog_reuse_v1',
    clock_timestamp()
  )
  returning * into v_revision;

  insert into public.course_publication_asset (
    id,
    revision_id,
    source_stored_file_id,
    storage_bucket,
    storage_path,
    original_filename,
    mime_type,
    size_bytes,
    checksum_sha256
  )
  select
    asset."publicationAssetId",
    p_revision_id,
    asset."sourceStoredFileId",
    asset."storageBucket",
    asset."storagePath",
    asset."originalFilename",
    asset."mimeType",
    asset."sizeBytes",
    asset."checksumSha256"
  from jsonb_to_recordset(p_asset_manifest) as asset(
    "publicationAssetId" uuid,
    "sourceStoredFileId" uuid,
    "originalFilename" text,
    "mimeType" text,
    "sizeBytes" bigint,
    "checksumSha256" text,
    "storageBucket" text,
    "storagePath" text
  );

  update public.course_publication as publication
  set title = v_snapshot_course ->> 'title',
      subject = v_snapshot_course ->> 'subject',
      goal = v_snapshot_course ->> 'goal',
      level = v_snapshot_course ->> 'level',
      audience_description = v_snapshot_course ->> 'audienceDescription',
      target_lesson_count =
        (v_snapshot_course ->> 'targetLessonCount')::integer,
      lesson_count = v_lesson_count,
      material_count = v_asset_count,
      current_revision_id = p_revision_id,
      source_content_updated_at = v_course.publication_content_updated_at,
      status = 'published',
      unpublished_at = null,
      updated_at = clock_timestamp()
  where publication.id = p_publication_id
    and publication.owner_account_id = p_actor_account_id
  returning publication.* into v_publication;

  if not found then
    raise exception 'course_publication_update_conflict'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'publicationId', v_publication.id,
    'sourceCourseId', v_publication.source_course_id,
    'status', v_publication.status,
    'currentRevisionId', v_revision.id,
    'publishedAt', v_publication.published_at,
    'updatedAt', v_publication.updated_at,
    'sourceCourseUpdatedAt', v_revision.source_course_updated_at,
    'sourceContentUpdatedAt', v_publication.source_content_updated_at,
    'contentSha256', v_revision.content_sha256
  );
end
$_$;


--
-- Name: publish_course_revision_with_attestation_admin(uuid, uuid, uuid, uuid, text, jsonb, jsonb, boolean, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_course_revision_with_attestation_admin(p_actor_account_id uuid, p_source_course_id uuid, p_publication_id uuid, p_revision_id uuid, p_content_sha256 text, p_snapshot jsonb, p_asset_manifest jsonb, p_rights_confirmed boolean, p_learning_audience text, p_attestation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course public.course%rowtype;
  v_live public.course_attestation%rowtype;
  v_persisted public.course_publication_attestation%rowtype;
  v_publication public.course_publication%rowtype;
  v_live_json jsonb;
  v_result jsonb;
  v_actual_revision_id uuid;
  v_review_status text;
begin
  if p_learning_audience not in ('children', 'educators') then
    raise exception 'course_learning_audience_invalid'
      using errcode = '22023';
  end if;

  select course.*
  into v_course
  from public.course as course
  join public.account as account
    on account.id = course.owner_account_id
  where course.id = p_source_course_id
    and course.owner_account_id = p_actor_account_id
    and course.archived_at is null
    and account.status = 'active'
    and (
      p_learning_audience = 'children'
      or account.can_author_educator_courses
    )
  for update of course, account;

  if not found then
    if p_learning_audience = 'educators' then
      raise exception 'educator_course_authoring_not_allowed'
        using errcode = '42501';
    end if;
    raise exception 'course_publication_source_not_found'
      using errcode = 'P0002';
  end if;

  if v_course.learning_audience <> p_learning_audience then
    raise exception 'course_publication_learning_audience_mismatch'
      using errcode = '23514';
  end if;

  if p_learning_audience = 'educators' and exists (
    select 1
    from public.course_publication as publication
    join public.course_publication_revision as revision
      on revision.publication_id = publication.id
     and revision.id = publication.current_revision_id
    join public.educator_course_revision_review as review
      on review.publication_id = publication.id
     and review.revision_id = publication.current_revision_id
    where publication.source_course_id = p_source_course_id
      and publication.owner_account_id = p_actor_account_id
      and review.status = 'pending'
      and (
        revision.content_sha256 <> p_content_sha256
        or revision.snapshot is distinct from p_snapshot
      )
  ) then
    raise exception 'educator_course_review_already_pending'
      using errcode = '55000';
  end if;

  select attestation.*
  into v_live
  from public.course_attestation as attestation
  where attestation.course_id = p_source_course_id
  for share;

  if found then
    v_live_json := jsonb_build_object(
      'version', v_live.version,
      'title', v_live.title,
      'description', v_live.description,
      'passingScorePercent', v_live.passing_score_percent,
      'questions', v_live.questions
    );
  end if;

  if p_learning_audience = 'children' then
    if v_live.course_id is not null
      or (
        p_attestation is not null
        and jsonb_typeof(p_attestation) <> 'null'
      )
    then
      raise exception 'child_course_attestation_forbidden'
        using errcode = '23514';
    end if;
  elsif v_live.course_id is null
    or p_attestation is null
    or jsonb_typeof(p_attestation) <> 'object'
    or (p_attestation - array[
      'version',
      'title',
      'description',
      'passingScorePercent',
      'questions'
    ]) <> '{}'::jsonb
    or not (p_attestation ?& array[
      'version',
      'title',
      'description',
      'passingScorePercent',
      'questions'
    ])
    or not public.course_attestation_definition_is_valid(
      (p_attestation ->> 'version')::integer,
      p_attestation ->> 'title',
      p_attestation ->> 'description',
      (p_attestation ->> 'passingScorePercent')::integer,
      p_attestation -> 'questions'
    )
    or p_attestation is distinct from v_live_json
  then
    raise exception 'course_publication_attestation_mismatch'
      using errcode = '23514';
  end if;

  v_result := public.publish_course_revision_admin(
    p_actor_account_id,
    p_source_course_id,
    p_publication_id,
    p_revision_id,
    p_content_sha256,
    p_snapshot,
    p_asset_manifest,
    p_rights_confirmed
  );
  v_actual_revision_id := (v_result ->> 'currentRevisionId')::uuid;

  if p_learning_audience = 'educators' then
    perform 1
    from public.course_publication_revision as revision
    where revision.publication_id = p_publication_id
      and revision.id = v_actual_revision_id
      and revision.license_code = 'shidao_official_learning_v1';

    if not found then
      raise exception 'educator_course_revision_license_invalid'
        using errcode = '23514';
    end if;

    insert into public.course_publication_attestation (
      revision_id,
      publication_id,
      version,
      title,
      description,
      passing_score_percent,
      questions,
      created_at
    )
    values (
      v_actual_revision_id,
      p_publication_id,
      v_live.version,
      v_live.title,
      v_live.description,
      v_live.passing_score_percent,
      v_live.questions,
      clock_timestamp()
    )
    on conflict (revision_id) do nothing;

    select attestation.*
    into strict v_persisted
    from public.course_publication_attestation as attestation
    where attestation.revision_id = v_actual_revision_id;

    if v_persisted.publication_id <> p_publication_id
      or v_persisted.version <> v_live.version
      or v_persisted.title <> v_live.title
      or v_persisted.description <> v_live.description
      or v_persisted.passing_score_percent <> v_live.passing_score_percent
      or v_persisted.questions is distinct from v_live.questions
    then
      raise exception 'course_publication_attestation_revision_conflict'
        using errcode = '23514';
    end if;

    insert into public.educator_course_revision_review (
      revision_id,
      publication_id,
      status,
      submitted_by_account_id,
      submitted_at,
      updated_at
    )
    values (
      v_actual_revision_id,
      p_publication_id,
      'pending',
      p_actor_account_id,
      clock_timestamp(),
      clock_timestamp()
    )
    on conflict (revision_id) do update
    set status = case
          when educator_course_revision_review.status = 'approved'
            then 'approved'
          else 'pending'
        end,
        submitted_by_account_id = excluded.submitted_by_account_id,
        reviewed_by_account_id = case
          when educator_course_revision_review.status = 'approved'
            then educator_course_revision_review.reviewed_by_account_id
          else null
        end,
        review_feedback = case
          when educator_course_revision_review.status = 'approved'
            then educator_course_revision_review.review_feedback
          else null
        end,
        submitted_at = case
          when educator_course_revision_review.status = 'approved'
            then educator_course_revision_review.submitted_at
          else excluded.submitted_at
        end,
        reviewed_at = case
          when educator_course_revision_review.status = 'approved'
            then educator_course_revision_review.reviewed_at
          else null
        end,
        updated_at = excluded.updated_at
    where educator_course_revision_review.status <> 'approved';

    update public.course_publication as publication
    set learning_audience = 'educators',
        is_shidao = true
    where publication.id = p_publication_id
      and publication.current_revision_id = v_actual_revision_id;

    if not found then
      raise exception 'course_publication_update_conflict'
        using errcode = '40001';
    end if;

    select review.status
    into strict v_review_status
    from public.educator_course_revision_review as review
    where review.revision_id = v_actual_revision_id;
  else
    if exists (
      select 1
      from public.course_publication_attestation as attestation
      where attestation.revision_id = v_actual_revision_id
    ) then
      raise exception 'course_publication_attestation_revision_conflict'
        using errcode = '23514';
    end if;

    update public.course_publication as publication
    set learning_audience = 'children'
    where publication.id = p_publication_id
      and publication.current_revision_id = v_actual_revision_id;

    if not found then
      raise exception 'course_publication_update_conflict'
        using errcode = '40001';
    end if;
  end if;

  select publication.*
  into strict v_publication
  from public.course_publication as publication
  where publication.id = p_publication_id;

  return v_result || jsonb_build_object(
    'status', v_publication.status,
    'learningAudience', p_learning_audience,
    'reviewStatus', v_review_status,
    'reviewRevisionId', case
      when p_learning_audience = 'educators'
        then v_actual_revision_id
      else null
    end,
    'approvedRevisionId', v_publication.approved_revision_id
  );
exception
  when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'course_publication_attestation_mismatch'
      using errcode = '23514';
end
$$;


--
-- Name: rebuild_learner_objective_state_for_actor(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_learner_objective_state_for_actor(p_recorded_by_account_id uuid, p_learner_profile_id uuid, p_source_learning_objective_id_at_time uuid, p_as_of timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_latest public.learning_evidence%rowtype;
  v_independent_run_count integer;
  v_status text;
  v_reason_code text;
  v_reason_text text;
  v_freshness_due_at timestamptz;
  v_state_id uuid;
  v_evidence_ids uuid[];
  v_current_evidence_ids uuid[];
begin
  if p_recorded_by_account_id is null
    or p_learner_profile_id is null
    or p_source_learning_objective_id_at_time is null
    or p_as_of is null
  then
    raise exception 'learner_objective_state_rebuild_invalid'
      using errcode = '22023';
  end if;

  perform public.lock_learning_activity_learners(
    array[p_learner_profile_id]
  );

  perform 1
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id
  for update of profile;

  if not found then
    delete from public.learner_objective_state as state
    where state.recorded_by_account_id = p_recorded_by_account_id
      and state.learner_profile_id = p_learner_profile_id
      and state.source_learning_objective_id_at_time =
        p_source_learning_objective_id_at_time;
    return null;
  end if;

  select evidence.*
  into v_latest
  from public.learning_evidence as evidence
  join public.learning_record as record
    on record.id = evidence.learning_record_id
   and record.recorded_by_account_id = evidence.recorded_by_account_id
  where evidence.recorded_by_account_id = p_recorded_by_account_id
    and evidence.learner_profile_id = p_learner_profile_id
    and evidence.source_learning_objective_id_at_time =
      p_source_learning_objective_id_at_time
    and evidence.superseded_by_evidence_id is null
    and record.occurred_at is not null
    and record.superseded_by_record_id is null
  order by evidence.observed_at desc, evidence.id desc
  limit 1;

  if not found then
    delete from public.learner_objective_state as state
    where state.recorded_by_account_id = p_recorded_by_account_id
      and state.learner_profile_id = p_learner_profile_id
      and state.source_learning_objective_id_at_time =
        p_source_learning_objective_id_at_time;
    return null;
  end if;

  select count(distinct evidence.source_lesson_run_id_at_time)
  into v_independent_run_count
  from public.learning_evidence as evidence
  join public.learning_record as record
    on record.id = evidence.learning_record_id
   and record.recorded_by_account_id = evidence.recorded_by_account_id
  where evidence.recorded_by_account_id = p_recorded_by_account_id
    and evidence.learner_profile_id = p_learner_profile_id
    and evidence.source_learning_objective_id_at_time =
      p_source_learning_objective_id_at_time
    and evidence.superseded_by_evidence_id is null
    and record.superseded_by_record_id is null
    and evidence.direction = 'positive'
    and evidence.support = 'independent';

  if v_latest.direction = 'negative' then
    v_status := 'forming';
    v_reason_code := 'latest_not_yet';
    v_reason_text :=
      'В последнем наблюдении пока не получилось — навык ещё формируется.';
    v_freshness_due_at := null;
    v_evidence_ids := array[v_latest.id];
  elsif v_latest.support = 'with_support' then
    v_status := 'forming';
    v_reason_code := 'latest_with_support';
    v_reason_text :=
      'В последнем наблюдении получилось с поддержкой — навык ещё формируется.';
    v_freshness_due_at := null;
    v_evidence_ids := array[v_latest.id];
  elsif v_independent_run_count < 2 then
    v_status := 'forming';
    v_reason_code := 'independent_opportunities_missing';
    v_reason_text :=
      'Есть самостоятельное выполнение, но нужно подтверждение в другом занятии.';
    v_freshness_due_at := null;
    v_evidence_ids := array[v_latest.id];
  else
    v_freshness_due_at := v_latest.observed_at + interval '90 days';
    if p_as_of >= v_freshness_due_at then
      v_status := 'recheck_due';
      v_reason_code := 'confirmed_evidence_stale';
      v_reason_text :=
        'Подтверждение навыка устарело по сроку свежести — его пора перепроверить.';
    else
      v_status := 'confirmed';
      v_reason_code := 'multiple_independent_opportunities';
      v_reason_text :=
        'Навык подтверждён самостоятельными наблюдениями в разных занятиях.';
    end if;

    select array_agg(
      selected.id order by selected.observed_at desc, selected.id desc
    )
    into v_evidence_ids
    from (
      select per_run.id, per_run.observed_at
      from (
        select distinct on (evidence.source_lesson_run_id_at_time)
          evidence.id,
          evidence.observed_at,
          evidence.source_lesson_run_id_at_time
        from public.learning_evidence as evidence
        join public.learning_record as record
          on record.id = evidence.learning_record_id
         and record.recorded_by_account_id = evidence.recorded_by_account_id
        where evidence.recorded_by_account_id = p_recorded_by_account_id
          and evidence.learner_profile_id = p_learner_profile_id
          and evidence.source_learning_objective_id_at_time =
            p_source_learning_objective_id_at_time
          and evidence.superseded_by_evidence_id is null
          and record.superseded_by_record_id is null
          and evidence.direction = 'positive'
          and evidence.support = 'independent'
        order by
          evidence.source_lesson_run_id_at_time,
          evidence.observed_at desc,
          evidence.id desc
      ) as per_run
      order by per_run.observed_at desc, per_run.id desc
      limit 2
    ) as selected
    ;
  end if;

  insert into public.learner_objective_state (
    recorded_by_account_id,
    learner_profile_id,
    learning_objective_id,
    source_learning_objective_id_at_time,
    source_course_id_at_time,
    course_title_at_time,
    subject_at_time,
    objective_title_at_time,
    status,
    reason_code,
    reason_text,
    policy_version,
    evaluated_at,
    last_evidence_at,
    freshness_due_at
  ) values (
    p_recorded_by_account_id,
    p_learner_profile_id,
    v_latest.learning_objective_id,
    v_latest.source_learning_objective_id_at_time,
    v_latest.source_course_id_at_time,
    v_latest.course_title_at_time,
    v_latest.subject_at_time,
    v_latest.objective_title_at_time,
    v_status,
    v_reason_code,
    v_reason_text,
    1,
    p_as_of,
    v_latest.observed_at,
    v_freshness_due_at
  )
  on conflict (
    recorded_by_account_id,
    learner_profile_id,
    source_course_id_at_time,
    source_learning_objective_id_at_time
  ) do update
  set learning_objective_id = excluded.learning_objective_id,
      course_title_at_time = excluded.course_title_at_time,
      subject_at_time = excluded.subject_at_time,
      objective_title_at_time = excluded.objective_title_at_time,
      status = excluded.status,
      reason_code = excluded.reason_code,
      reason_text = excluded.reason_text,
      policy_version = excluded.policy_version,
      evaluated_at = excluded.evaluated_at,
      last_evidence_at = excluded.last_evidence_at,
      freshness_due_at = excluded.freshness_due_at
  where (
    learner_objective_state.learning_objective_id,
    learner_objective_state.course_title_at_time,
    learner_objective_state.subject_at_time,
    learner_objective_state.objective_title_at_time,
    learner_objective_state.status,
      learner_objective_state.reason_code,
      learner_objective_state.reason_text,
      learner_objective_state.policy_version,
      learner_objective_state.last_evidence_at,
      learner_objective_state.freshness_due_at
  ) is distinct from (
    excluded.learning_objective_id,
    excluded.course_title_at_time,
    excluded.subject_at_time,
    excluded.objective_title_at_time,
    excluded.status,
      excluded.reason_code,
      excluded.reason_text,
      excluded.policy_version,
      excluded.last_evidence_at,
      excluded.freshness_due_at
  )
  returning id into v_state_id;

  if v_state_id is null then
    select state.id
    into v_state_id
    from public.learner_objective_state as state
    where state.recorded_by_account_id = p_recorded_by_account_id
      and state.learner_profile_id = p_learner_profile_id
      and state.source_course_id_at_time =
        v_latest.source_course_id_at_time
      and state.source_learning_objective_id_at_time =
        p_source_learning_objective_id_at_time
    for update of state;
  end if;

  select array_agg(link.learning_evidence_id order by link.position)
  into v_current_evidence_ids
  from public.learner_objective_state_evidence as link
  where link.learner_objective_state_id = v_state_id;

  if coalesce(v_current_evidence_ids, '{}'::uuid[])
    is distinct from coalesce(v_evidence_ids, '{}'::uuid[])
  then
    update public.learner_objective_state as state
    set evaluated_at = p_as_of
    where state.id = v_state_id
      and state.evaluated_at is distinct from p_as_of;

    delete from public.learner_objective_state_evidence as link
    where link.learner_objective_state_id = v_state_id;

    insert into public.learner_objective_state_evidence (
      learner_objective_state_id,
      learning_evidence_id,
      recorded_by_account_id,
      learner_profile_id,
      source_course_id_at_time,
      source_learning_objective_id_at_time,
      position
    )
    select
      v_state_id,
      submitted.id,
      p_recorded_by_account_id,
      p_learner_profile_id,
      v_latest.source_course_id_at_time,
      p_source_learning_objective_id_at_time,
      submitted.position::integer
    from unnest(v_evidence_ids) with ordinality as submitted(id, position)
    order by submitted.position;
  end if;

  update public.learner_recommendation_override as override_row
  set learner_objective_state_id = v_state_id
  where override_row.recorded_by_account_id = p_recorded_by_account_id
    and override_row.learner_profile_id = p_learner_profile_id
    and override_row.source_course_id_at_time =
      v_latest.source_course_id_at_time
    and override_row.source_learning_objective_id_at_time =
      p_source_learning_objective_id_at_time
    and override_row.learner_objective_state_id is distinct from v_state_id;

  return v_state_id;
end
$$;


--
-- Name: rebuild_learner_objective_states(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_learner_objective_states(p_learner_profile_id uuid, p_source_learning_objective_id_at_time uuid, p_as_of timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_state_id uuid;
  v_as_of timestamptz := clock_timestamp();
begin
  if v_actor_account_id is null
    or p_learner_profile_id is null
    or p_source_learning_objective_id_at_time is null
    or p_as_of is null
  then
    raise exception 'learner_objective_state_not_found'
      using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.teacher_learner as relation
    where relation.teacher_account_id = v_actor_account_id
      and relation.learner_profile_id = p_learner_profile_id
  ) then
    raise exception 'learner_objective_state_not_found'
      using errcode = 'P0002';
  end if;

  v_state_id := public.rebuild_learner_objective_state_for_actor(
    v_actor_account_id,
    p_learner_profile_id,
    p_source_learning_objective_id_at_time,
    v_as_of
  );

  return jsonb_build_object(
    'rebuilt', true,
    'stateId', v_state_id,
    'policyVersion', 1,
    'evaluatedAt', v_as_of
  );
end
$$;


--
-- Name: recompute_communication_thread_after_message_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_communication_thread_after_message_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_latest public.communication_message%rowtype;
  v_has_latest boolean;
begin
  select message.*
  into v_latest
  from public.communication_message as message
  where message.thread_id = old.thread_id
  order by message.id desc
  limit 1;

  v_has_latest := found;

  update public.communication_thread as thread
  set last_message_id = case when v_has_latest then v_latest.id else null end,
      last_message_at = case
        when v_has_latest then v_latest.created_at
        else null
      end
  where thread.id = old.thread_id
    and thread.last_message_id = old.id;

  return null;
end
$$;


--
-- Name: refresh_learning_activity_states_for_profile(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_learning_activity_states_for_profile(p_learner_profile_id uuid, p_recorded_by_account_id uuid, p_as_of timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_key record;
begin
  if p_learner_profile_id is null or p_as_of is null then
    raise exception 'learning_activity_profile_refresh_invalid'
      using errcode = '22023';
  end if;

  perform public.lock_learning_activity_learners(
    array[p_learner_profile_id]
  );
  perform 1
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id
  for update of profile;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  for v_key in
    select distinct candidate.recorded_by_account_id,
      candidate.source_learning_objective_id_at_time
    from (
      select
        evidence.recorded_by_account_id,
        evidence.source_learning_objective_id_at_time
      from public.learning_evidence as evidence
      where evidence.learner_profile_id = p_learner_profile_id
        and evidence.superseded_by_evidence_id is null
        and (
          p_recorded_by_account_id is null
          or evidence.recorded_by_account_id = p_recorded_by_account_id
        )
      union
      select
        state.recorded_by_account_id,
        state.source_learning_objective_id_at_time
      from public.learner_objective_state as state
      where state.learner_profile_id = p_learner_profile_id
        and (
          p_recorded_by_account_id is null
          or state.recorded_by_account_id = p_recorded_by_account_id
        )
    ) as candidate
    order by
      candidate.recorded_by_account_id,
      candidate.source_learning_objective_id_at_time
  loop
    perform public.rebuild_learner_objective_state_for_actor(
      v_key.recorded_by_account_id,
      p_learner_profile_id,
      v_key.source_learning_objective_id_at_time,
      p_as_of
    );
  end loop;
end
$$;


--
-- Name: reject_course_attestation_immutable_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_course_attestation_immutable_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'course_attestation_immutable_row'
    using errcode = '55000';
end
$$;


--
-- Name: reject_course_publication_immutable_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_course_publication_immutable_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'course_publication_asset'
    and (to_jsonb(old) -> 'source_stored_file_id') <> 'null'::jsonb
    and (to_jsonb(new) -> 'source_stored_file_id') = 'null'::jsonb
    and (to_jsonb(new) - 'source_stored_file_id')
      = (to_jsonb(old) - 'source_stored_file_id')
  then
    -- ON DELETE SET NULL preserves an immutable publication blob while
    -- recording that its live-source provenance row has been removed.
    return new;
  end if;

  raise exception 'course_publication_immutable_row'
    using errcode = '55000';
end
$$;


--
-- Name: reject_educator_course_revision_admin(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_educator_course_revision_admin(p_publication_id uuid, p_revision_id uuid, p_reviewer_account_id uuid DEFAULT NULL::uuid, p_review_feedback text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_publication public.course_publication%rowtype;
  v_review public.educator_course_revision_review%rowtype;
  v_feedback text := nullif(btrim(p_review_feedback), '');
begin
  if p_publication_id is null
    or p_revision_id is null
    or (v_feedback is not null and char_length(v_feedback) > 2000)
  then
    raise exception 'educator_course_review_input_invalid'
      using errcode = '22023';
  end if;

  if p_reviewer_account_id is not null and not exists (
    select 1
    from public.account as account
    where account.id = p_reviewer_account_id
      and account.status = 'active'
  ) then
    raise exception 'educator_course_reviewer_not_active'
      using errcode = '42501';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  where publication.id = p_publication_id
    and publication.learning_audience = 'educators'
    and publication.is_shidao
  for update;

  if not found then
    raise exception 'educator_course_review_not_found'
      using errcode = 'P0002';
  end if;

  if v_publication.current_revision_id <> p_revision_id then
    raise exception 'educator_course_review_revision_stale'
      using errcode = '40001';
  end if;

  update public.educator_course_revision_review as review
  set status = 'rejected',
      reviewed_by_account_id = p_reviewer_account_id,
      review_feedback = v_feedback,
      reviewed_at = clock_timestamp(),
      updated_at = clock_timestamp()
  where review.publication_id = p_publication_id
    and review.revision_id = p_revision_id
    and review.status = 'pending'
  returning review.* into v_review;

  if not found then
    raise exception 'educator_course_review_not_pending'
      using errcode = '55000';
  end if;

  return jsonb_build_object(
    'publicationId', v_publication.id,
    'status', v_publication.status,
    'reviewStatus', v_review.status,
    'reviewRevisionId', v_review.revision_id,
    'approvedRevisionId', v_publication.approved_revision_id,
    'reviewFeedback', v_review.review_feedback
  );
end
$$;


--
-- Name: remap_course_publication_component_assets(text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remap_course_publication_component_assets(p_type_key text, p_payload jsonb, p_asset_id_map jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_source_id text;
  v_target_id text;
  v_slides jsonb;
begin
  if p_payload is null
    or jsonb_typeof(p_payload) <> 'object'
    or p_asset_id_map is null
    or jsonb_typeof(p_asset_id_map) <> 'object'
  then
    raise exception 'course_publication_asset_remap_invalid'
      using errcode = '22023';
  end if;

  if p_type_key in ('image', 'file') then
    v_source_id := p_payload ->> 'storedFileId';
    if v_source_id is null or v_source_id = '' then
      return p_payload;
    end if;

    v_target_id := p_asset_id_map ->> v_source_id;
    if v_target_id is null then
      raise exception 'course_publication_asset_map_incomplete'
        using errcode = '22023';
    end if;

    return jsonb_set(
      p_payload,
      '{storedFileId}',
      to_jsonb(v_target_id),
      false
    );
  end if;

  if p_type_key = 'slideshow' then
    if jsonb_typeof(p_payload -> 'slides') <> 'array' then
      raise exception 'course_publication_slideshow_payload_invalid'
        using errcode = '22023';
    end if;

    select coalesce(
      jsonb_agg(
        slide.value || jsonb_build_object(
          'storedFileId',
          case
            when jsonb_typeof(slide.value -> 'storedFileId') = 'null'
              then 'null'::jsonb
            else to_jsonb(
              coalesce(
                p_asset_id_map ->> (slide.value ->> 'storedFileId'),
                '__missing__'
              )
            )
          end
        )
        order by slide.ordinality
      ),
      '[]'::jsonb
    )
    into v_slides
    from jsonb_array_elements(p_payload -> 'slides')
      with ordinality as slide(value, ordinality);

    if v_slides @> '[{"storedFileId":"__missing__"}]'::jsonb then
      raise exception 'course_publication_asset_map_incomplete'
        using errcode = '22023';
    end if;

    return jsonb_set(p_payload, '{slides}', v_slides, false);
  end if;

  return p_payload;
end
$$;


--
-- Name: reorder_lesson_component(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_lesson_component(p_component_id uuid, p_new_position integer) RETURNS TABLE(id uuid, lesson_id uuid, type_key text, schema_version integer, "position" integer, payload jsonb, placement_config jsonb, visibility text, student_slide_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_old_position integer;
  v_component_count integer;
  v_visibility text;
  v_student_slide_id uuid;
  v_current_slide_position integer;
  v_previous_slide_position integer;
  v_next_slide_position integer;
  v_clamped_slide_position integer;
  v_clamped_slide_id uuid;
begin
  if v_actor_user_id is null then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_new_position is null or p_new_position < 1 then
    raise exception
      'component_position_out_of_range'
      using errcode = '22023';
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  select
    component.position,
    component.visibility,
    component.student_slide_id
  into v_old_position, v_visibility, v_student_slide_id
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  select count(*)::integer
  into v_component_count
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id;

  if p_new_position > v_component_count then
    raise exception
      'component_position_out_of_range'
      using errcode = '22023';
  end if;

  if p_new_position < v_old_position then
    update public.lesson_component as component
    set position = component.position + 1
    where component.lesson_id = v_lesson_id
      and component.position >= p_new_position
      and component.position < v_old_position;
  elsif p_new_position > v_old_position then
    update public.lesson_component as component
    set position = component.position - 1
    where component.lesson_id = v_lesson_id
      and component.position > v_old_position
      and component.position <= p_new_position;
  end if;

  update public.lesson_component as component
  set position = p_new_position
  where component.id = p_component_id;

  if v_visibility = 'learner_visible' then
    select slide.position
    into v_current_slide_position
    from public.lesson_student_slide as slide
    where slide.id = v_student_slide_id
      and slide.lesson_id = v_lesson_id;

    select slide.position
    into v_previous_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position < p_new_position
    order by component.position desc
    limit 1;

    select slide.position
    into v_next_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position > p_new_position
    order by component.position
    limit 1;

    v_clamped_slide_position := v_current_slide_position;

    if v_previous_slide_position is not null
      and v_clamped_slide_position < v_previous_slide_position
    then
      v_clamped_slide_position := v_previous_slide_position;
    end if;

    if v_next_slide_position is not null
      and v_clamped_slide_position > v_next_slide_position
    then
      v_clamped_slide_position := v_next_slide_position;
    end if;

    if v_clamped_slide_position <> v_current_slide_position then
      select slide.id
      into v_clamped_slide_id
      from public.lesson_student_slide as slide
      where slide.lesson_id = v_lesson_id
        and slide.position = v_clamped_slide_position;

      update public.lesson_component as component
      set student_slide_id = v_clamped_slide_id
      where component.id = p_component_id;
    end if;
  end if;

  return query
  select
    component.id,
    component.lesson_id,
    component.type_key,
    component.schema_version,
    component.position,
    component.payload,
    component.placement_config,
    component.visibility,
    component.student_slide_id,
    component.created_at,
    component.updated_at
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;
end
$$;


--
-- Name: replace_course_audience(uuid, uuid[], uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_course_audience(p_course_id uuid, p_direct_learner_profile_ids uuid[] DEFAULT '{}'::uuid[], p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_direct_ids uuid[];
  v_group_ids uuid[];
  v_effective_count integer;
begin
  if v_actor_user_id is null then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  if array_position(p_direct_learner_profile_ids, null) is not null
    or array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_direct_learner_profile_ids, '{}'::uuid[])) > 200
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'course_audience_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = p_course_id
    and course.owner_account_id = v_teacher_account_id
  for update of course;

  if not found then
    raise exception 'course_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_direct_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_direct_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_teacher_account_id
  order by learner_group.id
  for update of learner_group;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_teacher_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_direct_ids)
    and teacher_learner.archived_at is null
  order by teacher_learner.learner_profile_id
  for update of teacher_learner;

  if cardinality(v_direct_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_direct_ids)
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select count(*)
  into v_effective_count
  from (
    select requested.id
    from unnest(v_direct_ids) as requested(id)
    union
    select member.learner_profile_id
    from public.learner_group_member as member
    join public.teacher_learner as teacher_learner
      on teacher_learner.teacher_account_id = v_teacher_account_id
     and teacher_learner.learner_profile_id = member.learner_profile_id
     and teacher_learner.archived_at is null
    where member.learner_group_id = any(v_group_ids)
  ) as effective;

  if v_effective_count > 200 then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  delete from public.course_learner as course_learner
  where course_learner.course_id = p_course_id
    and not (course_learner.learner_profile_id = any(v_direct_ids));

  insert into public.course_learner (course_id, learner_profile_id)
  select p_course_id, requested.id
  from unnest(v_direct_ids) as requested(id)
  on conflict (course_id, learner_profile_id) do nothing;

  delete from public.course_learner_group as course_group
  where course_group.course_id = p_course_id
    and not (course_group.learner_group_id = any(v_group_ids));

  insert into public.course_learner_group (course_id, learner_group_id)
  select p_course_id, requested.id
  from unnest(v_group_ids) as requested(id)
  on conflict (course_id, learner_group_id) do nothing;

  return true;
end
$$;


--
-- Name: replace_course_learners(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_course_learners(p_course_id uuid, p_learner_profile_ids uuid[]) RETURNS SETOF public.teacher_learner
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_group_ids uuid[];
  v_teacher_account_id uuid;
begin
  select course.owner_account_id
  into v_teacher_account_id
  from public.course as course
  where course.id = p_course_id;

  select coalesce(
    array_agg(course_group.learner_group_id order by course_group.learner_group_id),
    '{}'::uuid[]
  )
  into v_group_ids
  from public.course_learner_group as course_group
  where course_group.course_id = p_course_id;

  perform public.replace_course_audience(
    p_course_id,
    coalesce(p_learner_profile_ids, '{}'::uuid[]),
    v_group_ids
  );

  return query
  select teacher_learner.*
  from public.teacher_learner as teacher_learner
  join public.course_learner as course_learner
    on course_learner.learner_profile_id = teacher_learner.learner_profile_id
  where course_learner.course_id = p_course_id
    and teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.archived_at is null
  order by teacher_learner.display_name, teacher_learner.learner_profile_id;
end
$$;


--
-- Name: replace_my_course_attestation(uuid, text, text, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_my_course_attestation(p_course_id uuid, p_title text, p_description text, p_passing_score_percent integer, p_questions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_existing public.course_attestation%rowtype;
  v_attestation public.course_attestation%rowtype;
  v_next_version integer;
  v_title text := btrim(p_title);
  v_description text := btrim(p_description);
begin
  if p_course_id is null then
    raise exception 'course_attestation_input_invalid'
      using errcode = '22023';
  end if;

  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
    and account.can_author_educator_courses
  for update;

  if not found then
    raise exception 'educator_course_authoring_not_allowed'
      using errcode = '42501';
  end if;

  perform 1
  from public.course as course
  where course.id = p_course_id
    and course.owner_account_id = v_account_id
    and course.archived_at is null
    and course.learning_audience = 'educators'
  for update of course;

  if not found then
    raise exception 'course_attestation_course_not_found'
      using errcode = 'P0002';
  end if;

  select attestation.*
  into v_existing
  from public.course_attestation as attestation
  where attestation.course_id = p_course_id
  for update;

  v_next_version := case when found then v_existing.version + 1 else 1 end;

  if not public.course_attestation_definition_is_valid(
    v_next_version,
    v_title,
    v_description,
    p_passing_score_percent,
    p_questions
  ) then
    raise exception 'course_attestation_definition_invalid'
      using errcode = '22023';
  end if;

  insert into public.course_attestation (
    course_id,
    version,
    title,
    description,
    passing_score_percent,
    questions,
    created_at,
    updated_at
  )
  values (
    p_course_id,
    v_next_version,
    v_title,
    v_description,
    p_passing_score_percent,
    p_questions,
    clock_timestamp(),
    clock_timestamp()
  )
  on conflict (course_id) do update
  set version = excluded.version,
      title = excluded.title,
      description = excluded.description,
      passing_score_percent = excluded.passing_score_percent,
      questions = excluded.questions,
      updated_at = excluded.updated_at
  returning * into v_attestation;

  return jsonb_build_object(
    'version', v_attestation.version,
    'title', v_attestation.title,
    'description', v_attestation.description,
    'passingScorePercent', v_attestation.passing_score_percent,
    'questions', v_attestation.questions
  );
end
$$;


--
-- Name: request_learner_ai_consent(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_learner_ai_consent(p_course_id uuid, p_learner_profile_id uuid, p_purpose text, p_expires_in_days integer DEFAULT 90) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_subject_account_id uuid;
  v_consent public.learner_ai_consent%rowtype;
begin
  if p_purpose is null or btrim(p_purpose) = ''
    or char_length(btrim(p_purpose)) > 400
    or p_expires_in_days not between 1 and 365
  then
    raise exception 'learner_ai_consent_request_invalid' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.course as course
    where course.id = p_course_id and course.owner_account_id = v_actor_account_id
  ) or not public.course_has_effective_learner(p_course_id, p_learner_profile_id)
  then
    raise exception 'learner_ai_consent_scope_not_found' using errcode = 'P0002';
  end if;
  select profile.account_id into v_subject_account_id
  from public.learner_profile as profile
  where profile.id = p_learner_profile_id;
  if v_subject_account_id is null then
    raise exception 'learner_ai_consent_subject_unclaimed' using errcode = '55000';
  end if;
  insert into public.learner_ai_consent as target (
    learner_profile_id, course_id, owner_account_id, purpose,
    status, revision, expires_at
  ) values (
    p_learner_profile_id, p_course_id, v_actor_account_id, btrim(p_purpose),
    'pending', 1, now() + make_interval(days => p_expires_in_days)
  ) on conflict (learner_profile_id, course_id, owner_account_id) do update
    set purpose = excluded.purpose,
        status = 'pending',
        revision = target.revision + 1,
        expires_at = excluded.expires_at,
        granted_at = null,
        revoked_at = null
  returning * into v_consent;
  perform public.append_learner_identity_audit(
    'learner_ai_consent_requested', v_actor_account_id,
    v_subject_account_id, p_learner_profile_id, null, v_consent.id,
    jsonb_build_object('revision', v_consent.revision, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'id', v_consent.id,
    'learnerProfileId', v_consent.learner_profile_id,
    'courseId', v_consent.course_id,
    'courseTitle', (select title from public.course where id = v_consent.course_id),
    'ownerLabel', (select display_name from public.account where id = v_consent.owner_account_id),
    'purpose', v_consent.purpose,
    'status', v_consent.status,
    'revision', v_consent.revision,
    'expiresAt', v_consent.expires_at,
    'createdAt', v_consent.created_at,
    'grantedAt', v_consent.granted_at,
    'revokedAt', v_consent.revoked_at
  );
end
$$;


--
-- Name: reset_recoverable_learner_credentials(uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_recoverable_learner_credentials(p_actor_auth_user_id uuid, p_grant_id uuid, p_new_child_login text, p_raw_pin text, p_reauthenticated_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.reset_recoverable_learner_credentials_impl(
    p_actor_auth_user_id, p_grant_id,
    p_new_child_login, p_raw_pin,
    p_reauthenticated_at, p_idempotency_key
  );
end
$$;


--
-- Name: reset_recoverable_learner_credentials_impl(uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_recoverable_learner_credentials_impl(p_actor_auth_user_id uuid, p_grant_id uuid, p_new_child_login text, p_raw_pin text, p_reauthenticated_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_delegate public.learner_credential_recovery_delegate%rowtype;
  v_subject public.account%rowtype;
  v_profile_id uuid;
  v_pin_hash text;
  v_cutoff timestamptz := clock_timestamp();
  v_result jsonb;
begin
  if v_actor_account_id is null
    or p_grant_id is null
    or p_idempotency_key is null
    or p_new_child_login is null
    or lower(btrim(p_new_child_login)) !~ '^[[:alnum:]_.-]{3,80}$'
    or p_raw_pin is null or p_raw_pin !~ '^\d{4,8}$'
    or p_reauthenticated_at is null
    or p_reauthenticated_at < clock_timestamp() - interval '5 minutes'
    or p_reauthenticated_at > clock_timestamp() + interval '1 minute'
  then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;

  select delegate.* into v_delegate
  from public.learner_credential_recovery_delegate as delegate
  where delegate.id = p_grant_id
    and delegate.delegate_account_id = v_actor_account_id
    and delegate.status = 'active'
  for update of delegate;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;

  if v_delegate.last_reset_idempotency_key = p_idempotency_key
    and v_delegate.last_reset_result is not null
  then
    return v_delegate.last_reset_result;
  end if;

  if not public.learner_identity_rate_limit_hit(
    'credential_recovery_reset',
    extensions.digest(
      v_actor_account_id::text || ':' || p_grant_id::text,
      'sha256'
    ),
    5, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;

  select account.* into v_subject
  from public.account as account
  where account.id = v_delegate.subject_account_id
    and account.status = 'active'
  for update of account;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_subject.id
  for update of profile;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;

  update public.account_login_alias as alias
  set normalized_login = lower(btrim(p_new_child_login)),
      revoked_at = null,
      updated_at = now()
  where alias.account_id = v_subject.id
    and alias.kind = 'login';
  if not found then
    insert into public.account_login_alias (
      account_id, normalized_login, kind
    ) values (
      v_subject.id, lower(btrim(p_new_child_login)), 'login'
    );
  end if;

  v_pin_hash := extensions.crypt(p_raw_pin, extensions.gen_salt('bf'));
  insert into public.account_security as security (
    account_id, pin_hash, pin_failed_attempts, pin_created_at,
    pin_updated_at, sessions_invalid_before
  ) values (
    v_subject.id, v_pin_hash, 0, now(), now(), v_cutoff
  ) on conflict (account_id) do update
    set pin_hash = excluded.pin_hash,
        pin_failed_attempts = 0,
        pin_locked_until = null,
        pin_created_at = coalesce(security.pin_created_at, now()),
        pin_updated_at = now(),
        sessions_invalid_before = greatest(
          coalesce(security.sessions_invalid_before, '-infinity'::timestamptz),
          v_cutoff
        );

  v_result := jsonb_build_object(
    'grantId', v_delegate.id,
    'learnerLabel', v_subject.display_name,
    'childAccountLogin', lower(btrim(p_new_child_login)),
    'completed', true
  );
  update public.learner_credential_recovery_delegate
  set last_reset_idempotency_key = p_idempotency_key,
      last_reset_result = v_result,
      updated_at = now()
  where id = v_delegate.id;
  perform public.append_learner_identity_audit(
    'learner_credentials_recovered', v_actor_account_id,
    v_subject.id, v_profile_id, null, v_delegate.id,
    jsonb_build_object('projectionVersion', 1)
  );
  return v_result;
exception
  when unique_violation then
    raise exception 'learner_recovery_login_unavailable' using errcode = '23505';
end
$_$;


--
-- Name: resolve_account_login_alias(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_account_login_alias(p_identifier text) RETURNS TABLE(auth_user_id uuid, auth_email text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select account.auth_user_id, auth_user.email::text
  from public.account_login_alias as alias
  join public.account as account on account.id = alias.account_id
  join auth.users as auth_user on auth_user.id = account.auth_user_id
  where alias.normalized_login = lower(btrim(p_identifier))
    and alias.revoked_at is null
    and account.status = 'active'
  limit 1;
$$;


--
-- Name: resolve_learner_profile_alias(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_learner_profile_alias(p_learner_profile_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (
      select alias.target_learner_profile_id
      from public.learner_profile_alias as alias
      where alias.source_learner_profile_id = p_learner_profile_id
    ),
    (
      select profile.id
      from public.learner_profile as profile
      where profile.id = p_learner_profile_id
    )
  );
$$;


--
-- Name: resolve_teacher_learner_profile_alias(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_teacher_learner_profile_alias(p_actor_auth_user_id uuid, p_learner_profile_id uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_target_id uuid := public.resolve_learner_profile_alias(p_learner_profile_id);
begin
  if v_target_id is null or not exists (
    select 1 from public.teacher_learner as relation
    where relation.teacher_account_id = v_actor_account_id
      and relation.learner_profile_id = v_target_id
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  return v_target_id;
end
$$;


--
-- Name: restore_teacher_learner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_teacher_learner(p_learner_profile_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_relation public.teacher_learner%rowtype;
  v_profile public.learner_profile%rowtype;
begin
  update public.teacher_learner as relation
  set archived_at = null
  where relation.teacher_account_id = v_actor_account_id
    and relation.learner_profile_id = public.resolve_learner_profile_alias(p_learner_profile_id)
    and relation.archived_at is not null
  returning relation.* into v_relation;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;
  select * into v_profile from public.learner_profile where id = v_relation.learner_profile_id;
  perform public.append_learner_identity_audit(
    'teacher_learner_restored', v_actor_account_id, v_profile.account_id,
    v_profile.id, null, null, '{}'::jsonb
  );
  return jsonb_build_object(
    'learnerProfileId', v_relation.learner_profile_id,
    'teacherAccountId', v_relation.teacher_account_id,
    'displayName', v_relation.display_name,
    'archivedAt', v_relation.archived_at,
    'identityState', case
      when v_profile.account_id is null then 'offline'
      when exists (
        select 1 from public.learner_profile_alias as alias
        where alias.target_learner_profile_id = v_profile.id
      ) then 'merged'
      else 'claimed'
    end,
    'pendingRequestCount', 0,
    'canInvite', v_profile.account_id is null,
    'canPermanentlyDelete', false,
    'createdAt', v_relation.created_at,
    'updatedAt', v_relation.updated_at
  );
end
$$;


--
-- Name: revoke_learner_profile_invitation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_learner_profile_invitation(p_invitation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_invitation public.learner_claim_invitation%rowtype;
begin
  if not public.learner_identity_rate_limit_hit(
    'profile_invitation_revoke',
    extensions.digest(
      coalesce(v_actor_account_id::text, '') || ':' || p_invitation_id::text,
      'sha256'
    ),
    30, interval '1 hour', interval '1 hour'
  ) then
    raise exception 'learner_identity_rate_limited' using errcode = 'P0001';
  end if;
  update public.learner_claim_invitation as invitation
  set status = 'revoked', revoked_at = now(), token_digest = token_digest
  where invitation.id = p_invitation_id
    and invitation.inviter_account_id = v_actor_account_id
    and invitation.status in ('pending', 'bound')
  returning invitation.* into v_invitation;
  if not found then
    raise exception 'learner_profile_invitation_not_found' using errcode = 'P0002';
  end if;
  update public.learner_profile_merge
  set status = 'cancelled', cancelled_at = now()
  where invitation_id = v_invitation.id and status in ('pending', 'ready');
  perform public.append_learner_identity_audit(
    'learner_profile_invitation_revoked', v_actor_account_id,
    v_invitation.recipient_account_id, v_invitation.source_learner_profile_id,
    null, v_invitation.id,
    jsonb_build_object('kind', v_invitation.kind, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'id', v_invitation.id, 'kind', v_invitation.kind,
    'status', v_invitation.status,
    'learnerProfileId', v_invitation.source_learner_profile_id,
    'learnerLabel', coalesce((select display_name from public.learner_profile where id = v_invitation.source_learner_profile_id), 'Учебный профиль'),
    'inviterLabel', (select display_name from public.account where id = v_actor_account_id),
    'expiresAt', v_invitation.expires_at, 'createdAt', v_invitation.created_at,
    'acceptedAt', v_invitation.accepted_at
  );
end
$$;


--
-- Name: revoke_my_learner_credential_recovery_delegate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_my_learner_credential_recovery_delegate(p_grant_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_delegate public.learner_credential_recovery_delegate%rowtype;
begin
  select delegate.* into v_delegate
  from public.learner_credential_recovery_delegate as delegate
  where delegate.id = p_grant_id
    and delegate.subject_account_id = v_actor_account_id
  for update of delegate;
  if not found then
    raise exception 'learner_credential_recovery_not_found' using errcode = 'P0002';
  end if;
  if v_delegate.status = 'active' then
    update public.learner_credential_recovery_delegate as delegate
    set status = 'revoked', revoked_at = now(), updated_at = now()
    where delegate.id = v_delegate.id
    returning delegate.* into v_delegate;
    perform public.append_learner_identity_audit(
      'learner_credential_recovery_delegate_revoked',
      v_actor_account_id, v_actor_account_id,
      public.current_owned_learner_profile_id(), null, v_delegate.id,
      jsonb_build_object('projectionVersion', 1)
    );
  end if;
  return jsonb_build_object(
    'grantId', v_delegate.id,
    'status', v_delegate.status,
    'revokedAt', v_delegate.revoked_at
  );
end
$$;


--
-- Name: revoke_user_sessions(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions(p_user_id uuid, p_cutoff timestamp with time zone DEFAULT now()) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return public.revoke_user_sessions_impl(p_user_id, p_cutoff);
end
$$;


--
-- Name: revoke_user_sessions_impl(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_user_sessions_impl(p_user_id uuid, p_cutoff timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_cutoff timestamptz;
begin
  if p_user_id is null or p_cutoff is null then
    raise exception 'session_revocation_invalid' using errcode = '22023';
  end if;

  update public.account_security as security
  set sessions_invalid_before = greatest(
        coalesce(security.sessions_invalid_before, '-infinity'::timestamptz),
        p_cutoff
      )
  from public.account as account
  where account.id = security.account_id
    and account.auth_user_id = p_user_id
  returning security.sessions_invalid_before into v_cutoff;

  return v_cutoff;
end
$$;


--
-- Name: rotate_my_learner_share_code(uuid, bytea, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_my_learner_share_code(p_actor_auth_user_id uuid, p_code_digest bytea, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.account_id_for_auth_user(p_actor_auth_user_id);
  v_profile_id uuid;
  v_row public.learner_profile_share_code%rowtype;
  v_expired_code public.learner_profile_share_code%rowtype;
begin
  if v_actor_account_id is null
    or p_code_digest is null or octet_length(p_code_digest) <> 32
    or p_expires_at <= now() or p_expires_at > now() + interval '30 days'
  then
    raise exception 'learner_share_code_invalid' using errcode = '22023';
  end if;
  select profile.id into v_profile_id
  from public.learner_profile as profile
  where profile.account_id = v_actor_account_id
  for update of profile;
  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  for v_expired_code in
    update public.learner_profile_share_code as code
    set status = 'expired'
    where code.learner_profile_id = v_profile_id
      and code.status = 'active' and code.expires_at <= now()
    returning code.*
  loop
    perform public.append_learner_identity_audit(
      'learner_share_code_expired', v_actor_account_id, v_actor_account_id,
      v_profile_id, null, v_expired_code.id,
      jsonb_build_object(
        'expiredAt', v_expired_code.expires_at,
        'projectionVersion', 1
      )
    );
  end loop;
  update public.learner_profile_share_code
  set status = 'revoked', revoked_at = now()
  where learner_profile_id = v_profile_id and status = 'active';
  insert into public.learner_profile_share_code (
    learner_profile_id, code_digest, expires_at
  ) values (v_profile_id, p_code_digest, p_expires_at)
  returning * into v_row;
  perform public.append_learner_identity_audit(
    'learner_share_code_rotated', v_actor_account_id, v_actor_account_id,
    v_profile_id, null, v_row.id,
    jsonb_build_object('expiresAt', p_expires_at, 'projectionVersion', 1)
  );
  return jsonb_build_object(
    'expiresAt', v_row.expires_at,
    'createdAt', v_row.created_at
  );
end
$$;


--
-- Name: safe_learning_activity_profile_projection(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safe_learning_activity_profile_projection(p_learner_profile_id uuid, p_generated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with candidate as (
    select
      state.id as state_id,
      state.recorded_by_account_id,
      state.source_learning_objective_id_at_time,
      state.source_course_id_at_time,
      state.course_title_at_time,
      state.subject_at_time,
      state.objective_title_at_time,
      state.status,
      state.reason_code,
      state.reason_text,
      state.evaluated_at,
      state.last_evidence_at,
      state.freshness_due_at,
      override_row.action as override_action,
      override_row.recommendation_type as override_type,
      true as has_data
    from public.learner_objective_state as state
    left join public.learner_recommendation_override as override_row
      on override_row.recorded_by_account_id =
        state.recorded_by_account_id
     and override_row.learner_profile_id = state.learner_profile_id
     and override_row.source_course_id_at_time =
        state.source_course_id_at_time
     and override_row.source_learning_objective_id_at_time =
        state.source_learning_objective_id_at_time
    where state.learner_profile_id = p_learner_profile_id

    union all

    select
      null::uuid,
      course.owner_account_id,
      objective.id,
      course.id,
      btrim(course.title),
      nullif(btrim(course.subject), ''),
      btrim(objective.title),
      'no_data'::text,
      'no_eligible_evidence'::text,
      'Пока нет подходящих наблюдений по этой учебной цели.'::text,
      greatest(course.updated_at, objective.updated_at),
      null::timestamptz,
      null::timestamptz,
      null::text,
      null::text,
      false
    from public.course as course
    join public.learning_objective as objective
      on objective.course_id = course.id
     and objective.archived_at is null
    where course.archived_at is null
      and public.course_has_effective_learner(
        course.id,
        p_learner_profile_id
      )
      and not exists (
        select 1
        from public.learner_objective_state as state
        where state.learner_profile_id = p_learner_profile_id
          and state.source_course_id_at_time = course.id
          and state.source_learning_objective_id_at_time = objective.id
      )
  ), bounded as (
    select candidate.*
    from candidate
    order by
      candidate.has_data desc,
      candidate.evaluated_at desc,
      candidate.course_title_at_time,
      candidate.objective_title_at_time,
      candidate.recorded_by_account_id,
      candidate.source_course_id_at_time,
      candidate.source_learning_objective_id_at_time,
      candidate.state_id nulls last
    limit 200
  ), projected as (
    select
      bounded.*,
      'las_' || encode(
        extensions.digest(
          case when bounded.state_id is null
            then 'no-data-v1:' || p_learner_profile_id::text || ':'
              || bounded.source_course_id_at_time::text || ':'
              || bounded.source_learning_objective_id_at_time::text
            else 'state-v1:' || p_learner_profile_id::text || ':'
              || bounded.state_id::text
          end,
          'sha256'
        ),
        'hex'
      ) as opaque_state_key,
      coalesce(evidence_projection.items, '[]'::jsonb)
        as evidence_items,
      coalesce(evidence_projection.keys, '[]'::jsonb)
        as evidence_keys
    from bounded
    left join lateral (
      select
        jsonb_agg(item.payload order by item.position) as items,
        jsonb_agg(to_jsonb(item.opaque_key) order by item.position) as keys
      from (
        select
          link.position,
          'lae_' || encode(
            extensions.digest(
              'evidence-v1:' || p_learner_profile_id::text || ':'
                || evidence.id::text,
              'sha256'
            ),
            'hex'
          ) as opaque_key,
          jsonb_build_object(
            'key', 'lae_' || encode(
              extensions.digest(
                'evidence-v1:' || p_learner_profile_id::text || ':'
                  || evidence.id::text,
                'sha256'
              ),
              'hex'
            ),
            'direction', evidence.direction,
            'support', evidence.support,
            'observedAt', evidence.observed_at,
            'evidenceAt', evidence.materialized_at,
            'courseTitle', evidence.course_title_at_time,
            'lessonTitle', evidence.lesson_title_at_time,
            'componentLabel', case
              when evidence.component_visibility_at_time = 'learner_visible'
                then evidence.component_label_at_time
              else 'Служебный компонент преподавателя'
            end,
            'objectiveTitle', evidence.objective_title_at_time,
            'criterion', case
              when evidence.component_visibility_at_time = 'learner_visible'
                then evidence.criterion_at_time
              else 'Служебный критерий преподавателя'
            end
          ) as payload
        from public.learner_objective_state_evidence as link
        join public.learning_evidence as evidence
          on evidence.id = link.learning_evidence_id
        where link.learner_objective_state_id = bounded.state_id
        order by link.position
        limit 5
      ) as item
    ) as evidence_projection on bounded.state_id is not null
  )
  select jsonb_build_object(
    'projectionVersion', 1,
    'generatedAt', p_generated_at,
    'states', coalesce(
      jsonb_agg(
        jsonb_build_object(
          'key', projected.opaque_state_key,
          'courseTitle', projected.course_title_at_time,
          'subject', projected.subject_at_time,
          'objectiveTitle', projected.objective_title_at_time,
          'state', projected.status,
          'reasonCode', projected.reason_code,
          'reasonText', projected.reason_text,
          'evaluatedAt', projected.evaluated_at,
          'lastEvidenceAt', projected.last_evidence_at,
          'freshnessDueAt', projected.freshness_due_at,
          'evidenceReferences', projected.evidence_items,
          'recommendation', case
            when projected.state_id is null
              or projected.override_action = 'dismiss'
              then null::jsonb
            else jsonb_build_object(
              'type', case
                when projected.override_action = 'replace'
                  then projected.override_type
                when projected.reason_code = 'latest_not_yet' then 'repeat'
                when projected.reason_code = 'latest_with_support'
                  then 'try_without_support'
                when projected.reason_code =
                  'independent_opportunities_missing'
                  then 'apply_in_new_context'
                when projected.reason_code =
                  'multiple_independent_opportunities'
                  then 'move_forward'
                else 'recheck_freshness'
              end,
              'reasonCode', case projected.reason_code
                when 'latest_not_yet' then 'repeat_after_not_yet'
                when 'latest_with_support'
                  then 'try_without_support_after_supported_success'
                when 'independent_opportunities_missing'
                  then 'apply_in_new_context_after_one_independent_opportunity'
                when 'multiple_independent_opportunities'
                  then 'move_forward_after_confirmation'
                else 'recheck_due_to_freshness'
              end,
              'reasonText', case
                when projected.override_action = 'replace' then
                  case projected.override_type
                    when 'repeat' then
                      'Повторите материал и попробуйте ещё раз.'
                    when 'try_without_support' then
                      'Попробуйте выполнить навык без подсказки.'
                    when 'apply_in_new_context' then
                      'Примените навык в новом контексте.'
                    when 'move_forward' then
                      'Можно переходить к следующему материалу.'
                    else
                      'Перепроверьте навык, чтобы обновить подтверждение.'
                  end
                when projected.reason_code = 'latest_not_yet' then
                  'Пока не получилось — повторите материал и попробуйте ещё раз.'
                when projected.reason_code = 'latest_with_support' then
                  'Получилось с поддержкой — следующим шагом попробуйте без подсказки.'
                when projected.reason_code =
                  'independent_opportunities_missing' then
                  'Получилось самостоятельно один раз — примените навык в новом контексте.'
                when projected.reason_code =
                  'multiple_independent_opportunities' then
                  'Навык подтверждён в нескольких занятиях — можно переходить дальше.'
                else
                  'Подтверждение давно не обновлялось — пора перепроверить навык.'
              end,
              'source', case when projected.override_action = 'replace'
                then 'teacher_override' else 'rule' end,
              'generatedAt', projected.evaluated_at,
              'evidenceReferenceKeys', projected.evidence_keys
            )
          end
        ) order by
          projected.has_data desc,
          projected.evaluated_at desc,
          projected.course_title_at_time,
          projected.objective_title_at_time,
          projected.recorded_by_account_id,
          projected.source_course_id_at_time,
          projected.source_learning_objective_id_at_time,
          projected.state_id nulls last
      ),
      '[]'::jsonb
    )
  )
  from projected;
$$;


--
-- Name: lesson_component_observation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lesson_component_observation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learning_record_id uuid NOT NULL,
    lesson_component_id uuid,
    source_lesson_component_id_at_time uuid NOT NULL,
    component_position_at_time integer NOT NULL,
    component_type_key_at_time text NOT NULL,
    component_label_at_time text NOT NULL,
    observable_criterion_at_time text NOT NULL,
    rating text NOT NULL,
    entry_method text NOT NULL,
    private_note text,
    observed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    recorded_by_account_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    learning_objective_id uuid,
    source_learning_objective_id_at_time uuid,
    learning_objective_title_at_time text,
    corrected_from_observation_id uuid,
    superseded_by_observation_id uuid,
    component_visibility_at_time text,
    CONSTRAINT lesson_component_observation_correction_shape_check CHECK ((((corrected_from_observation_id IS NULL) OR (corrected_from_observation_id <> id)) AND ((superseded_by_observation_id IS NULL) OR (superseded_by_observation_id <> id)))),
    CONSTRAINT lesson_component_observation_criterion_check CHECK (((btrim(observable_criterion_at_time) <> ''::text) AND (char_length(btrim(observable_criterion_at_time)) <= 500))),
    CONSTRAINT lesson_component_observation_entry_method_check CHECK ((entry_method = ANY (ARRAY['direct'::text, 'bulk_confirmed'::text]))),
    CONSTRAINT lesson_component_observation_label_check CHECK (((btrim(component_label_at_time) <> ''::text) AND (char_length(btrim(component_label_at_time)) <= 500))),
    CONSTRAINT lesson_component_observation_live_source_check CHECK (((lesson_component_id IS NULL) OR (lesson_component_id = source_lesson_component_id_at_time))),
    CONSTRAINT lesson_component_observation_objective_context_check CHECK ((((source_learning_objective_id_at_time IS NULL) AND (learning_objective_title_at_time IS NULL) AND (learning_objective_id IS NULL)) OR ((source_learning_objective_id_at_time IS NOT NULL) AND (learning_objective_title_at_time IS NOT NULL) AND (btrim(learning_objective_title_at_time) <> ''::text) AND (char_length(btrim(learning_objective_title_at_time)) <= 240) AND ((learning_objective_id IS NULL) OR (learning_objective_id = source_learning_objective_id_at_time))))),
    CONSTRAINT lesson_component_observation_position_check CHECK ((component_position_at_time > 0)),
    CONSTRAINT lesson_component_observation_private_note_check CHECK (((private_note IS NULL) OR ((btrim(private_note) <> ''::text) AND (char_length(btrim(private_note)) <= 500)))),
    CONSTRAINT lesson_component_observation_rating_check CHECK ((rating = ANY (ARRAY['independent'::text, 'with_support'::text, 'not_yet'::text]))),
    CONSTRAINT lesson_component_observation_type_key_check CHECK (((btrim(component_type_key_at_time) <> ''::text) AND (char_length(btrim(component_type_key_at_time)) <= 80))),
    CONSTRAINT lesson_component_observation_visibility_at_time_check CHECK (((component_visibility_at_time IS NULL) OR (component_visibility_at_time = ANY (ARRAY['learner_visible'::text, 'staff_only'::text]))))
);


--
-- Name: save_lesson_component_observations(uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_lesson_component_observations(p_lesson_run_id uuid, p_lesson_component_id uuid, p_component_label_at_time text, p_observable_criterion_at_time text, p_entry_method text, p_observations jsonb) RETURNS SETOF public.lesson_component_observation
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_actor_account_id uuid;
  v_lesson_id uuid;
  v_component public.lesson_component%rowtype;
  v_objective public.learning_objective%rowtype;
  v_run public.lesson_run%rowtype;
  v_locked_record_count integer;
  v_observed_at timestamptz;
  v_has_rating boolean;
begin
  if v_actor_user_id is null
    or p_lesson_run_id is null
    or p_lesson_component_id is null
    or p_component_label_at_time is null
    or btrim(p_component_label_at_time) = ''
    or char_length(btrim(p_component_label_at_time)) > 500
    or p_entry_method is null
    or p_entry_method not in ('direct', 'bulk_confirmed')
    or p_observations is null
    or jsonb_typeof(p_observations) <> 'array'
    or jsonb_array_length(p_observations) not between 1 and 200
  then
    raise exception 'lesson_component_observations_invalid'
      using errcode = '22023';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_observations) as submitted(value)
    where jsonb_typeof(submitted.value) is distinct from 'object'
      or (submitted.value - array[
        'learningRecordId', 'rating', 'privateNote'
      ]) <> '{}'::jsonb
      or not (submitted.value ? 'learningRecordId')
      or jsonb_typeof(submitted.value -> 'learningRecordId')
        is distinct from 'string'
      or (submitted.value ->> 'learningRecordId') !~*
        '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or not (submitted.value ? 'rating')
      or coalesce(jsonb_typeof(submitted.value -> 'rating'), 'null')
        not in ('string', 'null')
      or (
        jsonb_typeof(submitted.value -> 'rating') = 'string'
        and submitted.value ->> 'rating'
          not in ('independent', 'with_support', 'not_yet')
      )
      or (
        submitted.value ? 'privateNote'
        and coalesce(jsonb_typeof(submitted.value -> 'privateNote'), 'null')
          not in ('string', 'null')
      )
      or (
        jsonb_typeof(submitted.value -> 'privateNote') = 'string'
        and char_length(btrim(submitted.value ->> 'privateNote')) > 500
      )
      or (
        coalesce(jsonb_typeof(submitted.value -> 'rating'), 'null') = 'null'
        and nullif(btrim(submitted.value ->> 'privateNote'), '') is not null
      )
  ) then
    raise exception 'lesson_component_observation_entry_invalid'
      using errcode = '22023';
  end if;

  if (
    select count(*)
    from jsonb_array_elements(p_observations)
  ) <> (
    select count(distinct (submitted.value ->> 'learningRecordId')::uuid)
    from jsonb_array_elements(p_observations) as submitted(value)
  ) then
    raise exception 'lesson_component_observation_record_duplicate'
      using errcode = '22023';
  end if;

  select exists (
    select 1
    from jsonb_array_elements(p_observations) as submitted(value)
    where jsonb_typeof(submitted.value -> 'rating') = 'string'
  ) into v_has_rating;

  if v_has_rating and (
    p_observable_criterion_at_time is null
    or btrim(p_observable_criterion_at_time) = ''
    or char_length(btrim(p_observable_criterion_at_time)) > 500
  ) then
    raise exception 'lesson_component_observation_criterion_required'
      using errcode = '22023';
  end if;

  select course.owner_account_id, lesson.id
  into v_actor_account_id, v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_lesson_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_component_observation_not_found'
      using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  where lesson.id = v_lesson_id
  for update of lesson;

  select component.*
  into v_component
  from public.lesson_component as component
  where component.id = p_lesson_component_id
    and component.lesson_id = v_lesson_id
  for update of component;

  if not found then
    raise exception 'lesson_component_observation_not_found'
      using errcode = 'P0002';
  end if;

  if v_component.primary_learning_objective_id is not null then
    select objective.*
    into v_objective
    from public.learning_objective as objective
    where objective.id = v_component.primary_learning_objective_id
    for key share of objective;

    if not found then
      raise exception 'lesson_component_learning_objective_not_found'
        using errcode = '55000';
    end if;
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.id = p_lesson_run_id
    and run.lesson_id = v_lesson_id
  for update of run;

  if not found then
    raise exception 'lesson_component_observation_not_found'
      using errcode = 'P0002';
  end if;

  if v_run.cancelled_at is not null or v_run.ended_at is not null then
    raise exception 'lesson_run_not_open' using errcode = '55000';
  end if;

  if v_run.started_at is null or not v_run.started_at_is_actual then
    raise exception 'lesson_run_not_started' using errcode = '55000';
  end if;

  perform record.id
  from public.learning_record as record
  join jsonb_array_elements(p_observations) as submitted(value)
    on record.id = (submitted.value ->> 'learningRecordId')::uuid
  where record.lesson_run_id = v_run.id
    and record.recorded_by_account_id = v_actor_account_id
    and record.occurred_at is null
  order by record.id
  for update of record;

  get diagnostics v_locked_record_count = row_count;
  if v_locked_record_count <> jsonb_array_length(p_observations) then
    raise exception 'lesson_component_observation_not_found'
      using errcode = 'P0002';
  end if;

  -- Linearize the at-time timestamp only after Lesson -> Component ->
  -- Objective -> Run -> LearningRecord state is locked and validated.
  v_observed_at := clock_timestamp();

  if v_has_rating then
    update public.lesson_component_observation as observation
    set lesson_component_id = v_component.id,
        component_position_at_time = v_component.position,
        component_type_key_at_time = btrim(v_component.type_key),
        component_label_at_time = btrim(p_component_label_at_time),
        observable_criterion_at_time =
          btrim(p_observable_criterion_at_time),
        learning_objective_id = v_objective.id,
        source_learning_objective_id_at_time = v_objective.id,
        learning_objective_title_at_time = btrim(v_objective.title)
    from jsonb_array_elements(p_observations) as submitted(value)
    where observation.learning_record_id =
        (submitted.value ->> 'learningRecordId')::uuid
      and observation.recorded_by_account_id = v_actor_account_id
      and observation.source_lesson_component_id_at_time = v_component.id
      and jsonb_typeof(submitted.value -> 'rating') = 'string';
  end if;

  delete from public.lesson_component_observation as observation
  using jsonb_array_elements(p_observations) as submitted(value)
  where observation.learning_record_id =
      (submitted.value ->> 'learningRecordId')::uuid
    and observation.recorded_by_account_id = v_actor_account_id
    and observation.source_lesson_component_id_at_time = v_component.id
    and coalesce(jsonb_typeof(submitted.value -> 'rating'), 'null') = 'null';

  if v_has_rating then
    insert into public.lesson_component_observation (
      learning_record_id,
      lesson_component_id,
      source_lesson_component_id_at_time,
      component_position_at_time,
      component_type_key_at_time,
      component_label_at_time,
      observable_criterion_at_time,
      learning_objective_id,
      source_learning_objective_id_at_time,
      learning_objective_title_at_time,
      rating,
      entry_method,
      private_note,
      observed_at,
      recorded_by_account_id
    )
    select
      (submitted.value ->> 'learningRecordId')::uuid,
      v_component.id,
      v_component.id,
      v_component.position,
      btrim(v_component.type_key),
      btrim(p_component_label_at_time),
      btrim(p_observable_criterion_at_time),
      v_objective.id,
      v_objective.id,
      case when v_objective.id is null then null else btrim(v_objective.title) end,
      submitted.value ->> 'rating',
      p_entry_method,
      nullif(btrim(submitted.value ->> 'privateNote'), ''),
      v_observed_at,
      v_actor_account_id
    from jsonb_array_elements(p_observations) as submitted(value)
    where jsonb_typeof(submitted.value -> 'rating') = 'string'
    on conflict (
      learning_record_id,
      source_lesson_component_id_at_time
    ) do update
    set lesson_component_id = excluded.lesson_component_id,
        component_position_at_time = excluded.component_position_at_time,
        component_type_key_at_time = excluded.component_type_key_at_time,
        component_label_at_time = excluded.component_label_at_time,
        observable_criterion_at_time =
          excluded.observable_criterion_at_time,
        learning_objective_id = excluded.learning_objective_id,
        source_learning_objective_id_at_time =
          excluded.source_learning_objective_id_at_time,
        learning_objective_title_at_time =
          excluded.learning_objective_title_at_time,
        rating = excluded.rating,
        entry_method = excluded.entry_method,
        private_note = excluded.private_note,
        observed_at = excluded.observed_at;
  end if;

  return query
  select observation.*
  from public.lesson_component_observation as observation
  join public.learning_record as record
    on record.id = observation.learning_record_id
  where record.lesson_run_id = v_run.id
    and observation.recorded_by_account_id = v_actor_account_id
    and observation.source_lesson_component_id_at_time = v_component.id
  order by observation.learning_record_id;
end
$_$;


--
-- Name: schedule_lesson_run(uuid, timestamp with time zone, integer, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_lesson_run(p_lesson_id uuid, p_scheduled_at timestamp with time zone, p_planned_duration_minutes integer DEFAULT NULL::integer, p_learner_profile_ids uuid[] DEFAULT NULL::uuid[], p_expected_lesson_run_id uuid DEFAULT NULL::uuid) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_course_id uuid;
  v_duration_minutes integer;
  v_selected_ids uuid[];
  v_run public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  if p_scheduled_at is null then
    raise exception
      'lesson_run_scheduled_at_required'
      using errcode = '22023';
  end if;

  if p_planned_duration_minutes is not null
    and p_planned_duration_minutes not between 5 and 480
  then
    raise exception
      'lesson_run_duration_invalid'
      using errcode = '22023';
  end if;

  if p_learner_profile_ids is not null
    and array_position(p_learner_profile_ids, null) is not null
  then
    raise exception
      'learner_profile_ids_must_not_contain_null'
      using errcode = '22023';
  end if;

  if cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200 then
    raise exception
      'lesson_run_audience_too_large'
      using errcode = '22023';
  end if;

  select course.owner_account_id, course.id
  into v_teacher_account_id, v_course_id
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = p_lesson_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.account as account
  where account.id = v_teacher_account_id
    and account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = v_course_id
    and course.owner_account_id = v_teacher_account_id
  for update of course;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select coalesce(
    p_planned_duration_minutes,
    case
      when lesson.estimated_duration_minutes between 5 and 480
        then lesson.estimated_duration_minutes
      else null
    end,
    60
  )
  into v_duration_minutes
  from public.lesson as lesson
  where lesson.id = p_lesson_id
    and lesson.course_id = v_course_id
  for update of lesson;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.lesson_id = p_lesson_id
    and run.ended_at is null
    and run.cancelled_at is null
  for update of run;

  if p_expected_lesson_run_id is not null
    and (
      v_run.id is null
      or v_run.id <> p_expected_lesson_run_id
    )
  then
    raise exception
      'lesson_run_changed'
      using errcode = '55000';
  end if;

  if v_run.id is not null and v_run.started_at is not null then
    raise exception
      'lesson_run_already_started'
      using errcode = '55000';
  end if;

  if v_run.id is not null then
    perform 1
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
    order by record.id
    for update of record;

    if exists (
      select 1
      from public.learning_record as record
      where record.lesson_run_id = v_run.id
        and record.occurred_at is not null
    ) then
      raise exception
        'lesson_run_contains_finalized_records'
        using errcode = '55000';
    end if;
  end if;

  if p_learner_profile_ids is null and v_run.id is not null then
    select coalesce(
      array_agg(record.learner_profile_id order by record.learner_profile_id),
      '{}'::uuid[]
    )
    into v_selected_ids
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  elsif p_learner_profile_ids is null then
    select coalesce(array_agg(effective.id order by effective.id), '{}'::uuid[])
    into v_selected_ids
    from (
      select course_learner.learner_profile_id as id
      from public.course_learner as course_learner
      join public.teacher_learner as teacher_learner
        on teacher_learner.teacher_account_id = v_teacher_account_id
       and teacher_learner.learner_profile_id = course_learner.learner_profile_id
       and teacher_learner.archived_at is null
      where course_learner.course_id = v_course_id
      union
      select member.learner_profile_id as id
      from public.course_learner_group as course_group
      join public.learner_group_member as member
        on member.learner_group_id = course_group.learner_group_id
      join public.teacher_learner as teacher_learner
        on teacher_learner.teacher_account_id = v_teacher_account_id
       and teacher_learner.learner_profile_id = member.learner_profile_id
       and teacher_learner.archived_at is null
      where course_group.course_id = v_course_id
    ) as effective;
  else
    select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
    into v_selected_ids
    from (
      select distinct requested_id as id
      from unnest(p_learner_profile_ids) as requested(requested_id)
    ) as requested;

    if exists (
      select 1
      from unnest(v_selected_ids) as requested(id)
      left join (
        select course_learner.learner_profile_id as id
        from public.course_learner as course_learner
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = course_learner.learner_profile_id
         and teacher_learner.archived_at is null
        where course_learner.course_id = v_course_id
        union
        select member.learner_profile_id as id
        from public.course_learner_group as course_group
        join public.learner_group_member as member
          on member.learner_group_id = course_group.learner_group_id
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = member.learner_profile_id
         and teacher_learner.archived_at is null
        where course_group.course_id = v_course_id
        union
        select record.learner_profile_id as id
        from public.learning_record as record
        where v_run.id is not null
          and record.lesson_run_id = v_run.id
          and record.occurred_at is null
          and record.recorded_by_account_id = v_teacher_account_id
      ) as allowed on allowed.id = requested.id
      where allowed.id is null
    ) then
      raise exception
        'learner_profile_not_in_course'
        using errcode = 'P0002';
    end if;
  end if;

  if cardinality(v_selected_ids) = 0 then
    raise exception
      'lesson_run_requires_expected_learner'
      using errcode = '23514';
  end if;

  if cardinality(v_selected_ids) > 200 then
    raise exception
      'lesson_run_audience_too_large'
      using errcode = '22023';
  end if;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_selected_ids)
  order by teacher_learner.learner_profile_id
  for key share of teacher_learner;

  if cardinality(v_selected_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_selected_ids)
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if v_run.id is not null then
    update public.lesson_run as run
    set scheduled_at = p_scheduled_at,
        planned_duration_minutes = v_duration_minutes
    where run.id = v_run.id
    returning run.* into v_run;

    delete from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  else
    insert into public.lesson_run (
      lesson_id,
      scheduled_at,
      planned_duration_minutes
    )
    values (
      p_lesson_id,
      p_scheduled_at,
      v_duration_minutes
    )
    returning * into v_run;
  end if;

  insert into public.learning_record (
    learner_profile_id,
    recorded_by_account_id,
    lesson_run_id,
    source_course_id,
    source_lesson_id
  )
  select
    selected.id,
    v_teacher_account_id,
    v_run.id,
    v_course_id,
    p_lesson_id
  from unnest(v_selected_ids) as selected(id);

  return v_run;
end
$$;


--
-- Name: schedule_lesson_run_if_unchanged(uuid, timestamp with time zone, integer, uuid, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_lesson_run_if_unchanged(p_lesson_id uuid, p_scheduled_at timestamp with time zone, p_planned_duration_minutes integer, p_expected_lesson_run_id uuid, p_expected_lesson_run_updated_at timestamp with time zone, p_expected_learner_profile_ids uuid[]) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_course_id uuid;
  v_expected_learner_profile_ids uuid[];
  v_current_learner_profile_ids uuid[];
  v_run public.lesson_run%rowtype;
  v_result public.lesson_run%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  if p_lesson_id is null
    or p_scheduled_at is null
    or p_planned_duration_minutes is null
    or p_planned_duration_minutes not between 5 and 480
    or p_expected_learner_profile_ids is null
    or array_position(p_expected_learner_profile_ids, null) is not null
    or cardinality(p_expected_learner_profile_ids) > 200
    or (
      (p_expected_lesson_run_id is null)
      <> (p_expected_lesson_run_updated_at is null)
    )
  then
    raise exception 'lesson_run_guard_invalid' using errcode = '22023';
  end if;

  select coalesce(
    array_agg(requested.id order by requested.id),
    '{}'::uuid[]
  )
  into v_expected_learner_profile_ids
  from unnest(p_expected_learner_profile_ids) as requested(id);

  if cardinality(v_expected_learner_profile_ids) <> (
    select count(distinct requested.id)
    from unnest(p_expected_learner_profile_ids) as requested(id)
  ) then
    raise exception 'lesson_run_guard_invalid' using errcode = '22023';
  end if;

  select course.owner_account_id, course.id
  into v_teacher_account_id, v_course_id
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = p_lesson_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  -- Match schedule_lesson_run's lock order. Supported Course audience and
  -- group-member mutations take the same Account/Course locks, while the Run
  -- row plus its FK-protected records freeze the existing draft roster.
  perform 1
  from public.account as account
  where account.id = v_teacher_account_id
    and account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = v_course_id
    and course.owner_account_id = v_teacher_account_id
  for update of course;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  where lesson.id = p_lesson_id
    and lesson.course_id = v_course_id
  for update of lesson;

  if not found then
    raise exception 'lesson_not_found' using errcode = 'P0002';
  end if;

  select run.*
  into v_run
  from public.lesson_run as run
  where run.lesson_id = p_lesson_id
    and run.ended_at is null
    and run.cancelled_at is null
  for update of run;

  if v_run.id is not null then
    perform record.id
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
    order by record.id
    for update of record;

    select coalesce(
      array_agg(record.learner_profile_id order by record.learner_profile_id),
      '{}'::uuid[]
    )
    into v_current_learner_profile_ids
    from public.learning_record as record
    where record.lesson_run_id = v_run.id
      and record.occurred_at is null;
  else
    -- The Course row serializes direct/group link replacement. Locking every
    -- currently linked Group blocks new member inserts through its FK, while
    -- member/relation row locks also close legacy delete/archive paths that do
    -- not acquire the old Course lock before changing effective membership.
    perform learner_group.id
    from public.learner_group as learner_group
    join public.course_learner_group as course_group
      on course_group.learner_group_id = learner_group.id
    where course_group.course_id = v_course_id
    order by learner_group.id
    for update of learner_group;

    perform member.learner_group_id, member.learner_profile_id
    from public.learner_group_member as member
    join public.course_learner_group as course_group
      on course_group.learner_group_id = member.learner_group_id
    where course_group.course_id = v_course_id
    order by member.learner_group_id, member.learner_profile_id
    for update of member;

    perform teacher_learner.learner_profile_id
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id in (
        select course_learner.learner_profile_id
        from public.course_learner as course_learner
        where course_learner.course_id = v_course_id
        union
        select member.learner_profile_id
        from public.course_learner_group as course_group
        join public.learner_group_member as member
          on member.learner_group_id = course_group.learner_group_id
        where course_group.course_id = v_course_id
      )
    order by teacher_learner.learner_profile_id
    for update of teacher_learner;

    select coalesce(
      array_agg(effective.id order by effective.id),
      '{}'::uuid[]
    )
    into v_current_learner_profile_ids
    from (
      select course_learner.learner_profile_id as id
      from public.course_learner as course_learner
      join public.teacher_learner as teacher_learner
        on teacher_learner.teacher_account_id = v_teacher_account_id
       and teacher_learner.learner_profile_id =
         course_learner.learner_profile_id
       and teacher_learner.archived_at is null
      where course_learner.course_id = v_course_id
      union
      select member.learner_profile_id as id
      from public.course_learner_group as course_group
      join public.learner_group_member as member
        on member.learner_group_id = course_group.learner_group_id
      join public.teacher_learner as teacher_learner
        on teacher_learner.teacher_account_id = v_teacher_account_id
       and teacher_learner.learner_profile_id = member.learner_profile_id
       and teacher_learner.archived_at is null
      where course_group.course_id = v_course_id
    ) as effective;
  end if;

  if p_expected_lesson_run_id is null then
    if v_run.id is not null
      or v_current_learner_profile_ids is distinct from
        v_expected_learner_profile_ids
    then
      raise exception 'lesson_run_changed' using errcode = '55000';
    end if;

    select scheduled.*
    into v_result
    from public.schedule_lesson_run(
      p_lesson_id,
      p_scheduled_at,
      p_planned_duration_minutes,
      v_expected_learner_profile_ids,
      null
    ) as scheduled;
  else
    if v_run.id is null
      or v_run.id <> p_expected_lesson_run_id
      or v_run.updated_at is distinct from p_expected_lesson_run_updated_at
      or v_run.started_at is not null
      or v_current_learner_profile_ids is distinct from
        v_expected_learner_profile_ids
    then
      raise exception 'lesson_run_changed' using errcode = '55000';
    end if;

    select scheduled.*
    into v_result
    from public.schedule_lesson_run(
      p_lesson_id,
      p_scheduled_at,
      p_planned_duration_minutes,
      null,
      p_expected_lesson_run_id
    ) as scheduled;
  end if;

  return v_result;
end
$$;


--
-- Name: send_communication_message(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_communication_message(p_thread_id uuid, p_body text, p_client_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
  v_thread public.communication_thread%rowtype;
  v_existing public.communication_message%rowtype;
  v_message public.communication_message%rowtype;
begin
  if v_actor_account_id is null
    or p_thread_id is null
    or p_client_message_id is null
    or p_body is null
    or btrim(p_body) = ''
    or char_length(btrim(p_body)) > 6000
  then
    raise exception 'communication_message_invalid' using errcode = '22023';
  end if;

  select thread.*
  into v_thread
  from public.communication_thread as thread
  where thread.id = p_thread_id;

  if not found then
    raise exception 'communication_thread_not_found' using errcode = 'P0002';
  end if;

  if v_thread.kind = 'direct' then
    perform account.id
    from public.account as account
    where account.id in (
      v_thread.direct_account_low_id,
      v_thread.direct_account_high_id
    )
    order by account.id
    for key share;
  else
    perform course.id
    from public.course as course
    where course.id = v_thread.course_id
    for key share;
  end if;

  select thread.*
  into v_thread
  from public.communication_thread as thread
  where thread.id = p_thread_id
  for update;

  if not public.communication_thread_is_accessible(
    v_thread.id,
    v_actor_account_id,
    true
  ) then
    raise exception 'communication_thread_not_found' using errcode = 'P0002';
  end if;

  select message.*
  into v_existing
  from public.communication_message as message
  where message.sender_account_id = v_actor_account_id
    and message.client_message_id = p_client_message_id;

  if found then
    if v_existing.thread_id <> p_thread_id
      or v_existing.body <> btrim(p_body)
    then
      raise exception 'communication_message_idempotency_conflict'
        using errcode = '23505';
    end if;

    return public.communication_message_projection(
      v_existing.id,
      v_actor_account_id
    );
  end if;

  perform public.communication_seed_read_states(
    v_thread.id,
    coalesce(v_thread.last_message_id, 0)
  );

  insert into public.communication_message (
    thread_id,
    sender_account_id,
    client_message_id,
    body
  )
  values (
    v_thread.id,
    v_actor_account_id,
    p_client_message_id,
    btrim(p_body)
  )
  returning * into v_message;

  update public.communication_thread as thread
  set last_message_id = v_message.id,
      last_message_at = v_message.created_at
  where thread.id = v_thread.id;

  insert into public.communication_read_state (
    thread_id,
    account_id,
    last_read_message_id,
    updated_at
  )
  values (
    v_thread.id,
    v_actor_account_id,
    v_message.id,
    v_message.created_at
  )
  on conflict (thread_id, account_id) do update
    set last_read_message_id = greatest(
          public.communication_read_state.last_read_message_id,
          excluded.last_read_message_id
        ),
        updated_at = excluded.updated_at;

  return public.communication_message_projection(
    v_message.id,
    v_actor_account_id
  );
end
$$;


--
-- Name: set_course_publication_content_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_course_publication_content_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.publication_content_updated_at := clock_timestamp();
    return new;
  end if;

  if pg_trigger_depth() > 1 then
    return new;
  end if;

  new.publication_content_updated_at := old.publication_content_updated_at;

  if new.title is distinct from old.title
    or new.subject is distinct from old.subject
    or new.goal is distinct from old.goal
    or new.level is distinct from old.level
    or new.audience_description is distinct from old.audience_description
    or new.target_lesson_count is distinct from old.target_lesson_count
    or new.learning_audience is distinct from old.learning_audience
  then
    new.publication_content_updated_at := clock_timestamp();
  end if;

  return new;
end
$$;


--
-- Name: set_course_publication_revision_license_on_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_course_publication_revision_license_on_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_learning_audience text;
begin
  select course.learning_audience
  into v_learning_audience
  from public.course_publication as publication
  join public.course as course
    on course.id = publication.source_course_id
   and course.owner_account_id = publication.owner_account_id
  join public.account as account
    on account.id = publication.owner_account_id
   and account.status = 'active'
  where publication.id = new.publication_id
    and course.archived_at is null
    and (
      course.learning_audience = 'children'
      or account.can_author_educator_courses
    )
  for share of publication, course, account;

  if not found then
    raise exception 'course_publication_revision_source_not_authorized'
      using errcode = '42501';
  end if;

  if v_learning_audience = 'educators' then
    new.license_code := 'shidao_official_learning_v1';
  elsif v_learning_audience = 'children' then
    if new.license_code <> 'shidao_catalog_reuse_v1' then
      raise exception 'child_course_publication_license_invalid'
        using errcode = '23514';
    end if;
  else
    raise exception 'course_publication_learning_audience_invalid'
      using errcode = '23514';
  end if;

  return new;
end
$$;


--
-- Name: set_current_account_avatar(uuid, text, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_account_avatar(p_actor_auth_user_id uuid, p_avatar_kind text, p_avatar_preset_key text, p_avatar_storage_path text, p_expected_revision integer) RETURNS TABLE(avatar_kind text, avatar_preset_key text, avatar_revision integer, avatar_updated_at timestamp with time zone, previous_storage_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_account public.account%rowtype;
  v_previous_storage_path text;
begin
  if p_actor_auth_user_id is null then
    raise exception 'account_avatar_not_found' using errcode = 'P0002';
  end if;

  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'account_avatar_invalid' using errcode = '22023';
  end if;

  select account.*
  into v_account
  from public.account as account
  where account.auth_user_id = p_actor_auth_user_id
    and account.status in ('active', 'provisional')
  for update of account;

  if not found then
    raise exception 'account_avatar_not_found' using errcode = 'P0002';
  end if;

  if v_account.avatar_revision <> p_expected_revision then
    raise exception 'account_avatar_stale' using errcode = '40001';
  end if;

  if p_avatar_kind = 'preset' then
    if p_avatar_preset_key is null
      or p_avatar_preset_key <> all(array[
        'sd-avatar-v1-01',
        'sd-avatar-v1-02',
        'sd-avatar-v1-03',
        'sd-avatar-v1-04',
        'sd-avatar-v1-05',
        'sd-avatar-v1-06',
        'sd-avatar-v1-07',
        'sd-avatar-v1-08',
        'sd-avatar-v1-09',
        'sd-avatar-v1-10',
        'sd-avatar-v1-11',
        'sd-avatar-v1-12',
        'sd-avatar-v1-13',
        'sd-avatar-v1-14',
        'sd-avatar-v1-15',
        'sd-avatar-v1-16',
        'sd-avatar-v1-17',
        'sd-avatar-v1-18',
        'sd-avatar-v1-19',
        'sd-avatar-v1-20'
      ]::text[])
      or p_avatar_storage_path is not null
    then
      raise exception 'account_avatar_invalid' using errcode = '22023';
    end if;
  elsif p_avatar_kind = 'custom' then
    if p_avatar_preset_key is not null
      or p_avatar_storage_path is null
      or p_avatar_storage_path !~ (
        '^' || v_account.id::text ||
        '/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.webp$'
      )
    then
      raise exception 'account_avatar_invalid' using errcode = '22023';
    end if;

    if not exists (
      select 1
      from storage.objects as object
      where object.bucket_id = 'profile-avatars'
        and object.name = p_avatar_storage_path
    ) then
      raise exception 'account_avatar_object_not_found'
        using errcode = 'P0002';
    end if;
  else
    raise exception 'account_avatar_invalid' using errcode = '22023';
  end if;

  v_previous_storage_path := v_account.avatar_storage_path;

  update public.account as account
  set avatar_kind = p_avatar_kind,
      avatar_preset_key = case
        when p_avatar_kind = 'preset' then p_avatar_preset_key
        else null
      end,
      avatar_storage_path = case
        when p_avatar_kind = 'custom' then p_avatar_storage_path
        else null
      end,
      avatar_revision = account.avatar_revision + 1,
      avatar_updated_at = clock_timestamp()
  where account.id = v_account.id
  returning account.* into v_account;

  return query
  select
    v_account.avatar_kind,
    v_account.avatar_preset_key,
    v_account.avatar_revision,
    v_account.avatar_updated_at,
    case
      when v_previous_storage_path is distinct from
        v_account.avatar_storage_path
        then v_previous_storage_path
      else null
    end;
end
$_$;


--
-- Name: FUNCTION set_current_account_avatar(p_actor_auth_user_id uuid, p_avatar_kind text, p_avatar_preset_key text, p_avatar_storage_path text, p_expected_revision integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_current_account_avatar(p_actor_auth_user_id uuid, p_avatar_kind text, p_avatar_preset_key text, p_avatar_storage_path text, p_expected_revision integer) IS 'Revision-aware server-only Account avatar switch; validates actor, path and private object existence.';


--
-- Name: set_current_account_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_account_pin(p_actor_auth_user_id uuid, p_raw_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.set_current_account_pin_impl(p_actor_auth_user_id, p_raw_pin);
end
$$;


--
-- Name: set_current_account_pin_impl(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_current_account_pin_impl(p_actor_auth_user_id uuid, p_raw_pin text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_account_id uuid;
  v_pin_hash text;
begin
  if p_actor_auth_user_id is null
    or p_raw_pin is null
    or p_raw_pin !~ '^\d{4,8}$'
  then
    raise exception 'account_pin_invalid' using errcode = '22023';
  end if;

  select account.id into v_account_id
  from public.account as account
  where account.auth_user_id = p_actor_auth_user_id
    and account.status in ('active', 'provisional')
  for update of account;

  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;

  v_pin_hash := extensions.crypt(p_raw_pin, extensions.gen_salt('bf'));

  insert into public.account_security as target (
    account_id, pin_hash, pin_created_at, pin_updated_at
  ) values (
    v_account_id, v_pin_hash, now(), now()
  )
  on conflict (account_id) do update
    set pin_hash = excluded.pin_hash,
        pin_failed_attempts = 0,
        pin_locked_until = null,
        pin_created_at = coalesce(target.pin_created_at, now()),
        pin_updated_at = now();

end
$_$;


--
-- Name: set_learner_recommendation_override(uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_learner_recommendation_override(p_learner_profile_id uuid, p_source_learning_objective_id_at_time uuid, p_action text, p_recommendation_type text, p_private_reason text, p_expected_state_updated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.current_account_id();
  v_state public.learner_objective_state%rowtype;
  v_updated_at timestamptz := clock_timestamp();
  v_persisted_updated_at timestamptz;
begin
  if v_actor_account_id is null
    or p_learner_profile_id is null
    or p_source_learning_objective_id_at_time is null
    or p_action not in ('replace', 'dismiss', 'clear')
    or p_expected_state_updated_at is null
    or (
      p_action = 'replace'
      and (
        p_recommendation_type not in (
          'repeat',
          'try_without_support',
          'apply_in_new_context',
          'move_forward',
          'recheck_freshness'
        )
        or p_private_reason is null
        or char_length(btrim(p_private_reason)) not between 1 and 500
      )
    )
    or (
      p_action = 'dismiss'
      and (
        p_recommendation_type is not null
        or p_private_reason is null
        or char_length(btrim(p_private_reason)) not between 1 and 500
      )
    )
    or (
      p_action = 'clear'
      and (p_recommendation_type is not null or p_private_reason is not null)
    )
  then
    raise exception 'learner_recommendation_override_invalid'
      using errcode = '22023';
  end if;

  perform public.lock_learning_activity_learners(
    array[p_learner_profile_id]
  );

  if not exists (
    select 1
    from public.teacher_learner as relation
    where relation.teacher_account_id = v_actor_account_id
      and relation.learner_profile_id = p_learner_profile_id
  ) then
    raise exception 'learner_recommendation_override_not_found'
      using errcode = 'P0002';
  end if;

  select state.*
  into v_state
  from public.learner_objective_state as state
  where state.recorded_by_account_id = v_actor_account_id
    and state.learner_profile_id = p_learner_profile_id
    and state.source_learning_objective_id_at_time =
      p_source_learning_objective_id_at_time
    -- The rolling client calls this token `updatedAt`, while the public
    -- teacher DTO exposes it as `evaluatedAt`.  Rebuild changes the token only
    -- when status/reason/evidence membership changes, including freshness.
    and state.evaluated_at = p_expected_state_updated_at
  for update of state;

  if not found then
    raise exception 'learner_recommendation_override_state_changed'
      using errcode = '40001';
  end if;

  if p_action = 'clear' then
    delete from public.learner_recommendation_override as override_row
    where override_row.learner_objective_state_id = v_state.id
      and override_row.recorded_by_account_id = v_actor_account_id;
  else
    insert into public.learner_recommendation_override (
      learner_objective_state_id,
      recorded_by_account_id,
      learner_profile_id,
      source_course_id_at_time,
      source_learning_objective_id_at_time,
      action,
      recommendation_type,
      private_reason
    ) values (
      v_state.id,
      v_actor_account_id,
      v_state.learner_profile_id,
      v_state.source_course_id_at_time,
      v_state.source_learning_objective_id_at_time,
      p_action,
      p_recommendation_type,
      btrim(p_private_reason)
    )
    on conflict (
      recorded_by_account_id,
      learner_profile_id,
      source_course_id_at_time,
      source_learning_objective_id_at_time
    ) do update
    set learner_objective_state_id = excluded.learner_objective_state_id,
        action = excluded.action,
        recommendation_type = excluded.recommendation_type,
        private_reason = excluded.private_reason,
        recorded_by_account_id = excluded.recorded_by_account_id,
        learner_profile_id = excluded.learner_profile_id,
        source_course_id_at_time = excluded.source_course_id_at_time,
        source_learning_objective_id_at_time =
          excluded.source_learning_objective_id_at_time,
        updated_at = v_updated_at
    returning learner_recommendation_override.updated_at
    into v_persisted_updated_at;
  end if;

  return jsonb_build_object(
    'action', p_action,
    'stateId', v_state.id,
    'updatedAt', coalesce(v_persisted_updated_at, v_updated_at)
  );
end
$$;


--
-- Name: set_lesson_component_student_screen(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_lesson_component_student_screen(p_component_id uuid, p_mode text, p_slide_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, lesson_id uuid, type_key text, schema_version integer, "position" integer, payload jsonb, placement_config jsonb, visibility text, student_slide_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_lesson_id uuid;
  v_component_position integer;
  v_previous_slide_position integer;
  v_next_slide_position integer;
  v_target_slide_position integer;
  v_target_slide_id uuid;
  v_insert_position integer;
begin
  if v_actor_user_id is null then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_mode is null or p_mode not in ('hide', 'existing', 'new') then
    raise exception
      'student_screen_mode_invalid'
      using errcode = '22023';
  end if;

  if (p_mode = 'existing' and p_slide_id is null)
    or (p_mode <> 'existing' and p_slide_id is not null)
  then
    raise exception
      'student_screen_slide_argument_invalid'
      using errcode = '22023';
  end if;

  select component.lesson_id
  into v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  -- Parent-row serialization gives assignment and reorder one lock order per
  -- Lesson, including when callers target different components.
  perform 1
  from public.lesson as lesson
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where lesson.id = v_lesson_id
    and account.auth_user_id = v_actor_user_id
  for update of lesson;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson_component as component
  where component.lesson_id = v_lesson_id
  order by component.id
  for update;

  perform 1
  from public.lesson_student_slide as slide
  where slide.lesson_id = v_lesson_id
  order by slide.id
  for update;

  select component.position
  into v_component_position
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id;

  if not found then
    raise exception 'component_not_found' using errcode = 'P0002';
  end if;

  if p_mode = 'hide' then
    update public.lesson_component as component
    set visibility = 'staff_only',
        student_slide_id = null
    where component.id = p_component_id;
  else
    select slide.position
    into v_previous_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position < v_component_position
    order by component.position desc
    limit 1;

    select slide.position
    into v_next_slide_position
    from public.lesson_component as component
    join public.lesson_student_slide as slide
      on slide.id = component.student_slide_id
    where component.lesson_id = v_lesson_id
      and component.id <> p_component_id
      and component.visibility = 'learner_visible'
      and component.position > v_component_position
    order by component.position
    limit 1;

    if p_mode = 'existing' then
      select slide.position
      into v_target_slide_position
      from public.lesson_student_slide as slide
      where slide.id = p_slide_id
        and slide.lesson_id = v_lesson_id;

      if not found then
        raise exception
          'student_slide_not_found'
          using errcode = 'P0002';
      end if;

      if (
        v_previous_slide_position is not null
        and v_target_slide_position < v_previous_slide_position
      ) or (
        v_next_slide_position is not null
        and v_target_slide_position > v_next_slide_position
      ) then
        raise exception
          'student_slide_target_out_of_order'
          using errcode = '23514';
      end if;

      v_target_slide_id := p_slide_id;
    else
      if v_previous_slide_position is not null
        and v_next_slide_position is not null
        and v_previous_slide_position = v_next_slide_position
      then
        raise exception
          'student_slide_cannot_split_group'
          using errcode = '23514';
      end if;

      v_insert_position := case
        when v_next_slide_position is not null
          then v_next_slide_position
        when v_previous_slide_position is not null
          then v_previous_slide_position + 1
        else 1
      end;

      update public.lesson_student_slide as slide
      set position = slide.position + 1
      where slide.lesson_id = v_lesson_id
        and slide.position >= v_insert_position;

      insert into public.lesson_student_slide as inserted_slide (
        lesson_id,
        position
      )
      values (v_lesson_id, v_insert_position)
      returning inserted_slide.id into v_target_slide_id;
    end if;

    update public.lesson_component as component
    set visibility = 'learner_visible',
        student_slide_id = v_target_slide_id
    where component.id = p_component_id;
  end if;

  return query
  select
    component.id,
    component.lesson_id,
    component.type_key,
    component.schema_version,
    component.position,
    component.payload,
    component.placement_config,
    component.visibility,
    component.student_slide_id,
    component.created_at,
    component.updated_at
  from public.lesson_component as component
  where component.id = p_component_id;
end
$$;


--
-- Name: set_my_course_publication_lesson_progress(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_course_publication_lesson_progress(p_publication_id uuid, p_expected_revision_id uuid, p_lesson_ref uuid, p_completed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_revision_id uuid;
begin
  if p_publication_id is null
    or p_expected_revision_id is null
    or p_lesson_ref is null
    or p_completed is null
  then
    raise exception 'course_progress_input_invalid'
      using errcode = '22023';
  end if;

  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  for update;

  if not found then
    raise exception 'course_progress_account_not_active'
      using errcode = '42501';
  end if;

  select publication.approved_revision_id
  into v_revision_id
  from public.course_publication as publication
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id
  join public.educator_course_revision_review as review
    on review.publication_id = publication.id
   and review.revision_id = publication.approved_revision_id
   and review.status = 'approved'
  where publication.id = p_publication_id
    and publication.status = 'published'
    and publication.learning_audience = 'educators'
    and publication.is_shidao
    and publication.approved_revision_id is not null
    and owner_account.status = 'active'
  for update of publication;

  if not found then
    raise exception 'educator_course_revision_not_available'
      using errcode = 'P0002';
  end if;

  if v_revision_id <> p_expected_revision_id then
    raise exception 'course_progress_revision_stale'
      using errcode = '40001';
  end if;

  if not public.course_publication_revision_has_lesson_ref(
    p_publication_id,
    v_revision_id,
    p_lesson_ref
  ) then
    raise exception 'course_publication_lesson_not_found'
      using errcode = 'P0002';
  end if;

  insert into public.course_publication_self_enrollment (
    account_id,
    publication_id,
    revision_id,
    last_opened_lesson_ref,
    updated_at
  )
  values (
    v_account_id,
    p_publication_id,
    v_revision_id,
    p_lesson_ref,
    clock_timestamp()
  )
  on conflict (account_id, publication_id, revision_id) do update
  set last_opened_lesson_ref = excluded.last_opened_lesson_ref,
      updated_at = excluded.updated_at;

  if p_completed then
    insert into public.course_publication_lesson_completion (
      account_id,
      publication_id,
      revision_id,
      lesson_ref
    )
    values (
      v_account_id,
      p_publication_id,
      v_revision_id,
      p_lesson_ref
    )
    on conflict (account_id, publication_id, revision_id, lesson_ref)
      do nothing;
  else
    delete from public.course_publication_lesson_completion as completion
    where completion.account_id = v_account_id
      and completion.publication_id = p_publication_id
      and completion.revision_id = v_revision_id
      and completion.lesson_ref = p_lesson_ref;
  end if;

  return public.build_course_publication_progress_admin(
    v_account_id,
    p_publication_id,
    v_revision_id
  );
end
$$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: start_lesson_run(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_lesson_run(p_lesson_run_id uuid, p_started_at timestamp with time zone DEFAULT now()) RETURNS public.lesson_run
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_run public.lesson_run%rowtype;
begin
  if (select auth.uid()) is null or p_started_at is null then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;

  select run.* into v_run
  from public.lesson_run as run
  join public.lesson as lesson on lesson.id = run.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where run.id = p_lesson_run_id
    and account.auth_user_id = (select auth.uid())
  for update of run;

  if not found then
    raise exception 'lesson_run_not_found' using errcode = 'P0002';
  end if;
  if v_run.cancelled_at is not null or v_run.ended_at is not null then
    raise exception 'lesson_run_not_open' using errcode = '55000';
  end if;

  if v_run.started_at is null or not v_run.started_at_is_actual then
    update public.lesson_run as run
    set started_at = p_started_at,
        started_at_is_actual = true
    where run.id = p_lesson_run_id
    returning run.* into v_run;
  end if;
  return v_run;
end
$$;


--
-- Name: submit_my_course_publication_attestation(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_my_course_publication_attestation(p_publication_id uuid, p_expected_revision_id uuid, p_selected_option_by_question_id jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_publication public.course_publication%rowtype;
  v_attestation public.course_publication_attestation%rowtype;
  v_revision public.course_publication_revision%rowtype;
  v_existing_award_id uuid;
  v_attempt public.course_attestation_attempt%rowtype;
  v_question_count integer;
  v_correct_answer_count integer;
  v_score_percent integer;
  v_passed boolean;
begin
  if p_publication_id is null
    or p_expected_revision_id is null
    or p_selected_option_by_question_id is null
    or jsonb_typeof(p_selected_option_by_question_id) <> 'object'
  then
    raise exception 'course_attestation_answers_invalid'
      using errcode = '22023';
  end if;

  select account.id
  into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  for update;

  if not found then
    raise exception 'course_attestation_account_not_active'
      using errcode = '42501';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  join public.account as owner_account
    on owner_account.id = publication.owner_account_id
  where publication.id = p_publication_id
    and publication.status = 'published'
    and publication.learning_audience = 'educators'
    and publication.is_shidao
    and publication.approved_revision_id is not null
    and owner_account.status = 'active'
    and exists (
      select 1
      from public.educator_course_revision_review as review
      where review.publication_id = publication.id
        and review.revision_id = publication.approved_revision_id
        and review.status = 'approved'
    )
  for update of publication;

  if not found then
    raise exception 'course_attestation_not_found'
      using errcode = 'P0002';
  end if;

  if v_publication.approved_revision_id <> p_expected_revision_id then
    raise exception 'course_attestation_revision_stale'
      using errcode = '40001';
  end if;

  select attestation.*
  into v_attestation
  from public.course_publication_attestation as attestation
  where attestation.publication_id = v_publication.id
    and attestation.revision_id = v_publication.approved_revision_id
  for share;

  if not found then
    raise exception 'course_attestation_not_found'
      using errcode = 'P0002';
  end if;

  if v_attestation.revision_id <> p_expected_revision_id then
    raise exception 'course_attestation_revision_stale'
      using errcode = '40001';
  end if;

  select revision.*
  into strict v_revision
  from public.course_publication_revision as revision
  where revision.publication_id = v_publication.id
    and revision.id = v_attestation.revision_id
  for share;

  if not coalesce((
    public.build_course_publication_progress_admin(
      v_account_id,
      v_publication.id,
      v_attestation.revision_id
    ) ->> 'complete'
  )::boolean, false) then
    raise exception 'course_attestation_lessons_incomplete'
      using errcode = '55000';
  end if;

  select award.id
  into v_existing_award_id
  from public.course_attestation_award as award
  where award.account_id = v_account_id
    and award.publication_id = v_publication.id
    and award.revision_id = v_attestation.revision_id;

  if found then
    return public.get_my_course_publication_attestation(p_publication_id);
  end if;

  if (
    select count(*)
    from public.course_attestation_attempt as attempt
    where attempt.account_id = v_account_id
      and attempt.revision_id = v_attestation.revision_id
      and attempt.completed_at >= clock_timestamp() - interval '15 minutes'
  ) >= 5 then
    raise exception 'course_attestation_attempt_rate_limited'
      using errcode = 'P0004';
  end if;

  v_question_count := jsonb_array_length(v_attestation.questions);

  if not public.course_attestation_selected_answers_are_valid(
    p_selected_option_by_question_id,
    v_question_count
  )
    or exists (
      select 1
      from jsonb_array_elements(v_attestation.questions) as question(value)
      where not (
        p_selected_option_by_question_id ? (question.value ->> 'id')
      )
        or not exists (
          select 1
          from jsonb_array_elements(
            question.value -> 'options'
          ) as option(value)
          where option.value ->> 'id'
            = p_selected_option_by_question_id
              ->> (question.value ->> 'id')
        )
    )
    or exists (
      select 1
      from jsonb_object_keys(
        p_selected_option_by_question_id
      ) as submitted(question_id)
      where not exists (
        select 1
        from jsonb_array_elements(v_attestation.questions) as question(value)
        where question.value ->> 'id' = submitted.question_id
      )
    )
  then
    raise exception 'course_attestation_answers_invalid'
      using errcode = '22023';
  end if;

  select count(*)::integer
  into v_correct_answer_count
  from jsonb_array_elements(v_attestation.questions) as question(value)
  where p_selected_option_by_question_id ->> (question.value ->> 'id')
    = question.value ->> 'correctOptionId';

  v_score_percent := floor(
    v_correct_answer_count::numeric * 100 / v_question_count
  )::integer;
  v_passed := v_score_percent >= v_attestation.passing_score_percent;

  insert into public.course_attestation_attempt (
    account_id,
    publication_id,
    revision_id,
    assessment_version,
    selected_option_by_question_id,
    question_count,
    correct_answer_count,
    score_percent,
    passed,
    course_title,
    course_subject,
    assessment_title,
    publisher_display_name,
    passing_score_percent,
    completed_at
  )
  values (
    v_account_id,
    v_publication.id,
    v_attestation.revision_id,
    v_attestation.version,
    p_selected_option_by_question_id,
    v_question_count,
    v_correct_answer_count,
    v_score_percent,
    v_passed,
    v_revision.snapshot -> 'course' ->> 'title',
    v_revision.snapshot -> 'course' ->> 'subject',
    v_attestation.title,
    v_publication.publisher_display_name,
    v_attestation.passing_score_percent,
    clock_timestamp()
  )
  returning * into v_attempt;

  if v_passed then
    insert into public.course_attestation_award (
      account_id,
      publication_id,
      revision_id,
      attempt_id,
      assessment_version,
      course_title,
      course_subject,
      assessment_title,
      publisher_display_name,
      score_percent,
      passing_score_percent,
      issued_at
    )
    values (
      v_account_id,
      v_publication.id,
      v_attestation.revision_id,
      v_attempt.id,
      v_attestation.version,
      v_revision.snapshot -> 'course' ->> 'title',
      v_revision.snapshot -> 'course' ->> 'subject',
      v_attestation.title,
      v_publication.publisher_display_name,
      v_score_percent,
      v_attestation.passing_score_percent,
      v_attempt.completed_at
    );
  end if;

  return public.get_my_course_publication_attestation(p_publication_id);
end
$$;


--
-- Name: sync_course_audience_type_from_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_course_audience_type_from_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
begin
  for v_course_id in
    select distinct candidate.course_id
    from (
      select case when tg_op <> 'DELETE' then new.course_id end as course_id
      union all
      select case when tg_op <> 'INSERT' then old.course_id end
    ) as candidate
    where candidate.course_id is not null
    order by candidate.course_id
  loop
    update public.course as course
    set audience_type = case
      when exists (
        select 1
        from public.course_learner as course_learner
        where course_learner.course_id = v_course_id
      ) or exists (
        select 1
        from public.course_learner_group as course_group
        where course_group.course_id = v_course_id
      ) then 'learner_profile'
      else 'none'
    end
    where course.id = v_course_id;
  end loop;

  return null;
end
$$;


--
-- Name: sync_provisional_account_from_auth_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_provisional_account_from_auth_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_raw_invitation_id text :=
    new.raw_app_meta_data ->> 'activation_invitation_id';
  v_invitation_id uuid;
  v_auth_xmin xid;
  v_updated_count integer;
begin
  if (new.raw_app_meta_data ->> 'identity_status')
      is distinct from 'provisional'
    or coalesce(lower(new.email), '')
      !~ '^[0-9a-f]{64}@learners[.]shidao[.]internal$'
    or coalesce(v_raw_invitation_id, '')
      !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then
    return new;
  end if;

  v_invitation_id := v_raw_invitation_id::uuid;

  if not exists (
    select 1
    from public.learner_claim_invitation as invitation
    join public.learner_profile as source
      on source.id = invitation.source_learner_profile_id
    where invitation.id = v_invitation_id
      and invitation.kind = 'child_activation'
      and invitation.status in ('pending', 'bound')
      and invitation.expires_at > clock_timestamp()
      and source.account_id is null
  ) then
    return new;
  end if;

  select auth_user.xmin into v_auth_xmin
  from auth.users as auth_user
  where auth_user.id = new.id;

  update public.account as account
  set status = 'provisional'
  where account.auth_user_id = new.id
    and account.status = 'active'
    -- GoTrue's two writes share one transaction ID.  Once Auth creation
    -- commits, the Auth row receives a new xmin on every later UPDATE while
    -- Account.xmin retains its creation transaction.
    and account.xmin = v_auth_xmin
    and account.created_at = account.updated_at
    and (
      select count(*)
      from public.learner_profile as profile
      where profile.account_id = account.id
    ) = 1
    and not exists (
      select 1
      from public.account_login_alias as alias
      where alias.account_id = account.id
    )
    and exists (
      select 1
      from public.account_security as security
      where security.account_id = account.id
        and security.pin_hash is null
        and security.pin_failed_attempts = 0
        and security.pin_locked_until is null
        and security.pin_created_at is null
        and security.pin_updated_at is null
        and security.last_pin_login_at is null
        and security.sessions_invalid_before is null
        and security.created_at = security.updated_at
    )
    and exists (
      select 1
      from public.account_preference as preference
      where preference.account_id = account.id
        and preference.last_selected_school_id is null
        and preference.theme is null
        and preference.settings = '{}'::jsonb
        and preference.created_at = preference.updated_at
    );

  get diagnostics v_updated_count = row_count;

  if v_updated_count = 0
    and exists (
      select 1
      from public.account as account
      where account.auth_user_id = new.id
        and account.status = 'active'
        and account.xmin = v_auth_xmin
    )
  then
    -- A trusted marker in the creation transaction must either consume the
    -- pristine bootstrap or abort the Auth create.  Silently accepting a
    -- partially initialized active Account would strand the activation flow.
    raise exception 'learner_identity_provisional_auth_sync_pristine_mismatch'
      using errcode = '55000';
  end if;

  return new;
end
$_$;


--
-- Name: system_notification_projection(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.system_notification_projection(p_notification_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'id', notification.id,
    'eventType', notification.event_type,
    'severity', notification.severity,
    'title', notification.title,
    'body', notification.body,
    'payload', notification.payload,
    'occurredAt', notification.occurred_at,
    'readAt', notification.read_at
  )
  from public.system_notification as notification
  where notification.id = p_notification_id;
$$;


--
-- Name: teacher_learning_activity_profile_projection(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_learning_activity_profile_projection(p_learner_profile_id uuid, p_recorded_by_account_id uuid, p_generated_at timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with candidate as (
    select
      state.id as state_id,
      state.learning_objective_id,
      state.source_learning_objective_id_at_time,
      state.source_course_id_at_time,
      state.course_title_at_time,
      state.subject_at_time,
      state.objective_title_at_time,
      state.status,
      state.reason_code,
      state.reason_text,
      state.policy_version,
      state.evaluated_at,
      state.last_evidence_at,
      state.freshness_due_at,
      override_row.action as override_action,
      override_row.recommendation_type as override_type,
      override_row.private_reason as override_private_reason,
      override_row.updated_at as override_updated_at,
      true as has_data
    from public.learner_objective_state as state
    left join public.learner_recommendation_override as override_row
      on override_row.recorded_by_account_id =
        state.recorded_by_account_id
     and override_row.learner_profile_id = state.learner_profile_id
     and override_row.source_course_id_at_time =
        state.source_course_id_at_time
     and override_row.source_learning_objective_id_at_time =
        state.source_learning_objective_id_at_time
    where state.recorded_by_account_id = p_recorded_by_account_id
      and state.learner_profile_id = p_learner_profile_id

    union all

    select
      null::uuid,
      objective.id,
      objective.id,
      course.id,
      btrim(course.title),
      nullif(btrim(course.subject), ''),
      btrim(objective.title),
      'no_data'::text,
      'no_eligible_evidence'::text,
      'Пока нет подходящих наблюдений по этой учебной цели.'::text,
      1,
      p_generated_at,
      null::timestamptz,
      null::timestamptz,
      null::text,
      null::text,
      null::text,
      null::timestamptz,
      false
    from public.course as course
    join public.learning_objective as objective
      on objective.course_id = course.id
     and objective.archived_at is null
    where course.owner_account_id = p_recorded_by_account_id
      and course.archived_at is null
      and public.course_has_effective_learner(
        course.id,
        p_learner_profile_id
      )
      and not exists (
        select 1
        from public.learner_objective_state as state
        where state.recorded_by_account_id = p_recorded_by_account_id
          and state.learner_profile_id = p_learner_profile_id
          and state.source_course_id_at_time = course.id
          and state.source_learning_objective_id_at_time = objective.id
      )
  ), bounded as (
    select candidate.*
    from candidate
    order by
      candidate.has_data desc,
      candidate.evaluated_at desc,
      candidate.course_title_at_time,
      candidate.objective_title_at_time,
      candidate.source_course_id_at_time,
      candidate.source_learning_objective_id_at_time,
      candidate.state_id nulls last
    limit 200
  ), projected as (
    select
      bounded.*,
      coalesce(evidence_projection.items, '[]'::jsonb) as evidence_items,
      coalesce(evidence_projection.ids, '[]'::jsonb) as evidence_ids
    from bounded
    left join lateral (
      select
        jsonb_agg(
          jsonb_build_object(
            'id', evidence.id,
            'learnerProfileId', evidence.learner_profile_id,
            'recordedByAccountId', evidence.recorded_by_account_id,
            'learningRecordId', evidence.learning_record_id,
            'sourceObservationId', evidence.source_observation_id,
            'sourceCourseIdAtTime', evidence.source_course_id_at_time,
            'sourceLessonIdAtTime', evidence.source_lesson_id_at_time,
            'sourceLessonRunIdAtTime',
              evidence.source_lesson_run_id_at_time,
            'sourceComponentIdAtTime', evidence.source_component_id_at_time,
            'sourceLearningObjectiveIdAtTime',
              evidence.source_learning_objective_id_at_time,
            'lessonComponentId', evidence.lesson_component_id,
            'learningObjectiveId', evidence.learning_objective_id,
            'courseTitleAtTime', evidence.course_title_at_time,
            'lessonTitleAtTime', evidence.lesson_title_at_time,
            'subjectAtTime', evidence.subject_at_time,
            'componentTypeAtTime', evidence.component_type_at_time,
            'componentLabelAtTime', evidence.component_label_at_time,
            'objectiveTitleAtTime', evidence.objective_title_at_time,
            'criterionAtTime', evidence.criterion_at_time,
            'direction', evidence.direction,
            'support', evidence.support,
            'observedAt', evidence.observed_at,
            'finalizedAt', evidence.finalized_at,
            'materializedAt', evidence.materialized_at,
            'evidenceVersion', evidence.evidence_version,
            'eligibilityPolicyVersion',
              evidence.eligibility_policy_version,
            'reasonCode', evidence.reason_code,
            'supersedesEvidenceId', evidence.supersedes_evidence_id,
            'supersededByEvidenceId', evidence.superseded_by_evidence_id
          ) order by link.position
        ) as items,
        jsonb_agg(to_jsonb(evidence.id) order by link.position) as ids
      from public.learner_objective_state_evidence as link
      join public.learning_evidence as evidence
        on evidence.id = link.learning_evidence_id
      where link.learner_objective_state_id = bounded.state_id
    ) as evidence_projection on bounded.state_id is not null
  )
  select jsonb_build_object(
    'projectionVersion', 1,
    'learnerProfileId', p_learner_profile_id,
    'generatedAt', p_generated_at,
    'states', coalesce(
      jsonb_agg(
        jsonb_build_object(
          'stateId', projected.state_id,
          'learningObjectiveId', projected.learning_objective_id,
          'sourceLearningObjectiveIdAtTime',
            projected.source_learning_objective_id_at_time,
          'sourceCourseIdAtTime', projected.source_course_id_at_time,
          'courseTitleAtTime', projected.course_title_at_time,
          'subjectAtTime', projected.subject_at_time,
          'objectiveTitleAtTime', projected.objective_title_at_time,
          'status', projected.status,
          'reasonCode', projected.reason_code,
          'reasonText', projected.reason_text,
          'policyVersion', projected.policy_version,
          'evaluatedAt', projected.evaluated_at,
          'lastEvidenceAt', projected.last_evidence_at,
          'freshnessDueAt', projected.freshness_due_at,
          'evidence', projected.evidence_items,
          'recommendation', case
            when projected.state_id is null then null::jsonb
            else jsonb_build_object(
              'recommendationId', projected.state_id,
              'type', case projected.reason_code
                when 'latest_not_yet' then 'repeat'
                when 'latest_with_support' then 'try_without_support'
                when 'independent_opportunities_missing'
                  then 'apply_in_new_context'
                when 'multiple_independent_opportunities'
                  then 'move_forward'
                else 'recheck_freshness'
              end,
              'reasonCode', case projected.reason_code
                when 'latest_not_yet' then 'repeat_after_not_yet'
                when 'latest_with_support'
                  then 'try_without_support_after_supported_success'
                when 'independent_opportunities_missing'
                  then 'apply_in_new_context_after_one_independent_opportunity'
                when 'multiple_independent_opportunities'
                  then 'move_forward_after_confirmation'
                else 'recheck_due_to_freshness'
              end,
              'reasonText', case projected.reason_code
                when 'latest_not_yet' then
                  'Пока не получилось — повторите материал и попробуйте ещё раз.'
                when 'latest_with_support' then
                  'Получилось с поддержкой — следующим шагом попробуйте без подсказки.'
                when 'independent_opportunities_missing' then
                  'Получилось самостоятельно один раз — примените навык в новом контексте.'
                when 'multiple_independent_opportunities' then
                  'Навык подтверждён в нескольких занятиях — можно переходить дальше.'
                else
                  'Подтверждение давно не обновлялось — пора перепроверить навык.'
              end,
              'ruleVersion', 1,
              'generatedAt', projected.evaluated_at,
              'evidenceIds', projected.evidence_ids,
              'effectiveType', case projected.override_action
                when 'dismiss' then null
                when 'replace' then projected.override_type
                else case projected.reason_code
                  when 'latest_not_yet' then 'repeat'
                  when 'latest_with_support' then 'try_without_support'
                  when 'independent_opportunities_missing'
                    then 'apply_in_new_context'
                  when 'multiple_independent_opportunities'
                    then 'move_forward'
                  else 'recheck_freshness'
                end
              end,
              'effectiveReasonText', case projected.override_action
                when 'dismiss' then null
                when 'replace' then projected.override_private_reason
                else case projected.reason_code
                  when 'latest_not_yet' then
                    'Пока не получилось — повторите материал и попробуйте ещё раз.'
                  when 'latest_with_support' then
                    'Получилось с поддержкой — следующим шагом попробуйте без подсказки.'
                  when 'independent_opportunities_missing' then
                    'Получилось самостоятельно один раз — примените навык в новом контексте.'
                  when 'multiple_independent_opportunities' then
                    'Навык подтверждён в нескольких занятиях — можно переходить дальше.'
                  else
                    'Подтверждение давно не обновлялось — пора перепроверить навык.'
                end
              end,
              'source', case when projected.override_action is null
                then 'rule' else 'teacher_override' end,
              'override', case when projected.override_action is null
                then null::jsonb
                else jsonb_build_object(
                  'action', projected.override_action,
                  'recommendationType', projected.override_type,
                  'privateReason', projected.override_private_reason,
                  'updatedAt', projected.override_updated_at
                )
              end
            )
          end
        ) order by
          projected.has_data desc,
          projected.evaluated_at desc,
          projected.course_title_at_time,
          projected.objective_title_at_time,
          projected.source_course_id_at_time,
          projected.source_learning_objective_id_at_time,
          projected.state_id nulls last
      ),
      '[]'::jsonb
    )
  )
  from projected;
$$;


--
-- Name: touch_course_from_attestation_child(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_course_from_attestation_child() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_course_id uuid;
begin
  if tg_op = 'DELETE' then
    v_course_id := old.course_id;
  else
    v_course_id := new.course_id;
  end if;

  update public.course as course
  set updated_at = clock_timestamp(),
      publication_content_updated_at = clock_timestamp()
  where course.id = v_course_id;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


--
-- Name: touch_course_from_authoring_child(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_course_from_authoring_child() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_course_id uuid;
  v_new_course_id uuid;
begin
  if tg_table_name = 'lesson' then
    if tg_op <> 'INSERT' then
      v_old_course_id := old.course_id;
    end if;
    if tg_op <> 'DELETE' then
      v_new_course_id := new.course_id;
    end if;
  elsif tg_table_name in ('lesson_component', 'lesson_student_slide') then
    if tg_op <> 'INSERT' then
      select lesson.course_id
      into v_old_course_id
      from public.lesson as lesson
      where lesson.id = old.lesson_id;
    end if;
    if tg_op <> 'DELETE' then
      select lesson.course_id
      into v_new_course_id
      from public.lesson as lesson
      where lesson.id = new.lesson_id;
    end if;
  elsif tg_table_name = 'course_attachment' then
    if tg_op <> 'INSERT' then
      v_old_course_id := old.course_id;
    end if;
    if tg_op <> 'DELETE' then
      v_new_course_id := new.course_id;
    end if;
  else
    raise exception 'course_authoring_touch_table_not_supported'
      using errcode = '55000';
  end if;

  update public.course as course
  set updated_at = clock_timestamp(),
      publication_content_updated_at = clock_timestamp()
  where course.id in (v_old_course_id, v_new_course_id);

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end
$$;


