--
-- Name: touch_courses_from_stored_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_courses_from_stored_file() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.course as course
  set updated_at = clock_timestamp(),
      publication_content_updated_at = clock_timestamp()
  where exists (
    select 1
    from public.course_attachment as attachment
    where attachment.course_id = course.id
      and attachment.stored_file_id = new.id
  );

  return new;
end
$$;


--
-- Name: unpublish_course_publication_admin(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unpublish_course_publication_admin(p_actor_account_id uuid, p_source_course_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_publication public.course_publication%rowtype;
  v_revision public.course_publication_revision%rowtype;
  v_review public.educator_course_revision_review%rowtype;
begin
  if p_actor_account_id is null or p_source_course_id is null then
    raise exception 'course_publication_unpublish_invalid'
      using errcode = '22023';
  end if;

  perform 1
  from public.course as course
  where course.id = p_source_course_id
    and course.owner_account_id = p_actor_account_id
  for update;

  if not found then
    raise exception 'course_publication_source_not_found'
      using errcode = 'P0002';
  end if;

  select publication.*
  into v_publication
  from public.course_publication as publication
  where publication.source_course_id = p_source_course_id
    and publication.owner_account_id = p_actor_account_id
  for update;

  if not found then
    raise exception 'course_publication_not_found'
      using errcode = 'P0002';
  end if;

  if v_publication.learning_audience = 'educators' then
    select review.*
    into v_review
    from public.educator_course_revision_review as review
    where review.publication_id = v_publication.id
      and review.revision_id = v_publication.current_revision_id
    for update;

    if found and v_review.status = 'pending' then
      update public.educator_course_revision_review as review
      set status = 'rejected',
          reviewed_by_account_id = null,
          review_feedback = 'withdrawn_by_author',
          reviewed_at = clock_timestamp(),
          updated_at = clock_timestamp()
      where review.revision_id = v_publication.current_revision_id
        and review.status = 'pending';

      if v_publication.approved_revision_id is not null then
        update public.course_publication as publication
        set status = 'published',
            unpublished_at = null,
            updated_at = clock_timestamp()
        where publication.id = v_publication.id
        returning publication.* into v_publication;
      else
        update public.course_publication as publication
        set status = 'unpublished',
            unpublished_at = clock_timestamp(),
            updated_at = clock_timestamp()
        where publication.id = v_publication.id
        returning publication.* into v_publication;
      end if;
    else
      update public.course_publication as publication
      set status = 'unpublished',
          unpublished_at = clock_timestamp(),
          updated_at = clock_timestamp()
      where publication.id = v_publication.id
      returning publication.* into v_publication;
    end if;
  else
    update public.course_publication as publication
    set status = 'unpublished',
        unpublished_at = clock_timestamp(),
        updated_at = clock_timestamp()
    where publication.id = v_publication.id
    returning publication.* into v_publication;
  end if;

  select revision.*
  into strict v_revision
  from public.course_publication_revision as revision
  where revision.id = v_publication.current_revision_id;

  select review.*
  into v_review
  from public.educator_course_revision_review as review
  where review.publication_id = v_publication.id
    and review.revision_id = v_publication.current_revision_id;

  return jsonb_build_object(
    'publicationId', v_publication.id,
    'sourceCourseId', v_publication.source_course_id,
    'status', v_publication.status,
    'currentRevisionId', v_revision.id,
    'publishedAt', v_publication.published_at,
    'updatedAt', v_publication.updated_at,
    'sourceCourseUpdatedAt', v_revision.source_course_updated_at,
    'sourceContentUpdatedAt', v_publication.source_content_updated_at,
    'contentSha256', v_revision.content_sha256,
    'reviewStatus', v_review.status,
    'reviewRevisionId', v_review.revision_id,
    'approvedRevisionId', v_publication.approved_revision_id
  );
end
$$;


--
-- Name: unpublish_course_publications_for_inactive_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unpublish_course_publications_for_inactive_account() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status = 'active' and new.status <> 'active' then
    update public.course_publication as publication
    set status = 'unpublished',
        unpublished_at = clock_timestamp(),
        updated_at = clock_timestamp()
    where publication.owner_account_id = new.id
      and publication.status = 'published';
  end if;

  return new;
end
$$;


--
-- Name: account; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    auth_user_id uuid NOT NULL,
    display_name text NOT NULL,
    locale text DEFAULT 'ru'::text NOT NULL,
    timezone text DEFAULT 'Europe/Moscow'::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    can_author_educator_courses boolean DEFAULT false NOT NULL,
    avatar_kind text DEFAULT 'preset'::text NOT NULL,
    avatar_preset_key text DEFAULT 'sd-avatar-v1-01'::text,
    avatar_storage_path text,
    avatar_revision integer DEFAULT 1 NOT NULL,
    avatar_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_avatar_kind_check CHECK ((avatar_kind = ANY (ARRAY['preset'::text, 'custom'::text]))),
    CONSTRAINT account_avatar_preset_key_check CHECK (((avatar_preset_key IS NULL) OR (avatar_preset_key = ANY (ARRAY['sd-avatar-v1-01'::text, 'sd-avatar-v1-02'::text, 'sd-avatar-v1-03'::text, 'sd-avatar-v1-04'::text, 'sd-avatar-v1-05'::text, 'sd-avatar-v1-06'::text, 'sd-avatar-v1-07'::text, 'sd-avatar-v1-08'::text, 'sd-avatar-v1-09'::text, 'sd-avatar-v1-10'::text, 'sd-avatar-v1-11'::text, 'sd-avatar-v1-12'::text, 'sd-avatar-v1-13'::text, 'sd-avatar-v1-14'::text, 'sd-avatar-v1-15'::text, 'sd-avatar-v1-16'::text, 'sd-avatar-v1-17'::text, 'sd-avatar-v1-18'::text, 'sd-avatar-v1-19'::text, 'sd-avatar-v1-20'::text])))),
    CONSTRAINT account_avatar_revision_check CHECK ((avatar_revision >= 1)),
    CONSTRAINT account_avatar_selection_check CHECK ((((avatar_kind = 'preset'::text) AND (avatar_preset_key IS NOT NULL) AND (avatar_storage_path IS NULL)) OR ((avatar_kind = 'custom'::text) AND (avatar_preset_key IS NULL) AND (avatar_storage_path IS NOT NULL)))),
    CONSTRAINT account_avatar_storage_path_check CHECK (((avatar_storage_path IS NULL) OR (avatar_storage_path ~ (('^'::text || (id)::text) || '/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.webp$'::text)))),
    CONSTRAINT account_display_name_check CHECK ((btrim(display_name) <> ''::text)),
    CONSTRAINT account_status_check CHECK ((status = ANY (ARRAY['active'::text, 'provisional'::text, 'suspended'::text, 'deleted'::text])))
);


--
-- Name: COLUMN account.avatar_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account.avatar_kind IS 'Required Account avatar source: preset or private custom image.';


--
-- Name: COLUMN account.avatar_preset_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account.avatar_preset_key IS 'Allowlisted ShiDao preset key when avatar_kind is preset.';


--
-- Name: COLUMN account.avatar_storage_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account.avatar_storage_path IS 'Account-scoped private profile-avatars object path when avatar_kind is custom.';


--
-- Name: COLUMN account.avatar_revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account.avatar_revision IS 'Monotonic optimistic-concurrency revision for avatar updates.';


--
-- Name: COLUMN account.avatar_updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.account.avatar_updated_at IS 'Timestamp of the latest committed avatar selection.';


--
-- Name: update_current_account_profile(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_current_account_profile(p_display_name text, p_locale text, p_timezone text) RETURNS public.account
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.account%rowtype;
begin
  if (select auth.uid()) is null
    or p_display_name is null
    or btrim(p_display_name) = ''
    or char_length(btrim(p_display_name)) > 160
    or p_locale is null
    or btrim(p_locale) = ''
    or char_length(btrim(p_locale)) > 35
    or p_timezone is null
    or btrim(p_timezone) = ''
    or char_length(btrim(p_timezone)) > 100
  then
    raise exception 'account_profile_invalid' using errcode = '22023';
  end if;

  update public.account as account
  set display_name = btrim(p_display_name),
      locale = btrim(p_locale),
      timezone = btrim(p_timezone)
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  returning account.* into v_account;

  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;

  -- Account-owned canonical name follows the Account profile.  Every
  -- teacher-local directory name remains untouched in teacher_learner.
  update public.learner_profile as profile
  set display_name = v_account.display_name
  where profile.account_id = v_account.id;

  return v_account;
end
$$;


--
-- Name: update_learner_group(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learner_group(p_learner_group_id uuid, p_name text, p_learner_profile_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.learner_group
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_profile_ids uuid[];
  v_group public.learner_group%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if p_name is null
    or btrim(p_name) = ''
    or char_length(btrim(p_name)) > 160
  then
    raise exception 'learner_group_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_profile_ids, null) is not null
    or cardinality(coalesce(p_learner_profile_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_profile_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = p_learner_group_id
    and course.owner_account_id = v_teacher_account_id
  order by course.id
  for update of course;

  select learner_group.*
  into v_group
  from public.learner_group as learner_group
  where learner_group.id = p_learner_group_id
    and learner_group.owner_account_id = v_teacher_account_id
  for update of learner_group;

  if not found then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.learner_group as learner_group
    where learner_group.owner_account_id = v_teacher_account_id
      and learner_group.id <> p_learner_group_id
      and lower(btrim(learner_group.name)) = lower(btrim(p_name))
  ) then
    raise exception 'learner_group_name_taken' using errcode = '23505';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_profile_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_profile_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  perform 1
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = any(v_profile_ids)
    and teacher_learner.archived_at is null
  order by teacher_learner.learner_profile_id
  for update of teacher_learner;

  if cardinality(v_profile_ids) <> (
    select count(*)
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = any(v_profile_ids)
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.course_learner_group as target_link
    where target_link.learner_group_id = p_learner_group_id
      and (
        select count(*)
        from (
          select course_learner.learner_profile_id
          from public.course_learner as course_learner
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = course_learner.learner_profile_id
           and teacher_learner.archived_at is null
          where course_learner.course_id = target_link.course_id
          union
          select member.learner_profile_id
          from public.course_learner_group as course_group
          join public.learner_group_member as member
            on member.learner_group_id = course_group.learner_group_id
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = member.learner_profile_id
           and teacher_learner.archived_at is null
          where course_group.course_id = target_link.course_id
            and course_group.learner_group_id <> p_learner_group_id
          union
          select requested.id
          from unnest(v_profile_ids) as requested(id)
        ) as effective
      ) > 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  update public.learner_group as learner_group
  set name = btrim(p_name)
  where learner_group.id = p_learner_group_id
  returning learner_group.* into v_group;

  delete from public.learner_group_member as member
  where member.learner_group_id = p_learner_group_id
    and not (member.learner_profile_id = any(v_profile_ids));

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select p_learner_group_id, requested.id
  from unnest(v_profile_ids) as requested(id)
  on conflict (learner_group_id, learner_profile_id) do nothing;

  return v_group;
end
$$;


--
-- Name: update_learner_profile_with_groups(uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learner_profile_with_groups(p_learner_profile_id uuid, p_display_name text, p_learner_group_ids uuid[] DEFAULT '{}'::uuid[]) RETURNS public.teacher_learner
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_teacher_account_id uuid;
  v_group_ids uuid[];
  v_relation public.teacher_learner%rowtype;
begin
  if v_actor_user_id is null then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if p_display_name is null
    or btrim(p_display_name) = ''
    or char_length(btrim(p_display_name)) > 160
  then
    raise exception 'learner_profile_name_invalid' using errcode = '22023';
  end if;

  if array_position(p_learner_group_ids, null) is not null
    or cardinality(coalesce(p_learner_group_ids, '{}'::uuid[])) > 200
  then
    raise exception 'learner_group_ids_invalid' using errcode = '22023';
  end if;

  select account.id
  into v_teacher_account_id
  from public.account as account
  where account.auth_user_id = v_actor_user_id
  for update of account;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  if not exists (
    select 1
    from public.teacher_learner as teacher_learner
    where teacher_learner.teacher_account_id = v_teacher_account_id
      and teacher_learner.learner_profile_id = p_learner_profile_id
      and teacher_learner.archived_at is null
  ) then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(requested.id order by requested.id), '{}'::uuid[])
  into v_group_ids
  from (
    select distinct requested_id as id
    from unnest(coalesce(p_learner_group_ids, '{}'::uuid[]))
      as requested(requested_id)
  ) as requested;

  if cardinality(v_group_ids) <> (
    select count(*)
    from public.learner_group as learner_group
    where learner_group.id = any(v_group_ids)
      and learner_group.owner_account_id = v_teacher_account_id
  ) then
    raise exception 'learner_group_not_found' using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.course_learner_group as course_group
    on course_group.course_id = course.id
  where course_group.learner_group_id = any(v_group_ids)
    and course.owner_account_id = v_teacher_account_id
  order by course.id
  for update of course;

  if exists (
    select 1
    from (
      select distinct course_group.course_id
      from public.course_learner_group as course_group
      where course_group.learner_group_id = any(v_group_ids)
    ) as target_course
    where not exists (
      select 1
      from (
        select course_learner.learner_profile_id
        from public.course_learner as course_learner
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = course_learner.learner_profile_id
         and teacher_learner.archived_at is null
        where course_learner.course_id = target_course.course_id
        union
        select member.learner_profile_id
        from public.course_learner_group as linked_group
        join public.learner_group_member as member
          on member.learner_group_id = linked_group.learner_group_id
        join public.teacher_learner as teacher_learner
          on teacher_learner.teacher_account_id = v_teacher_account_id
         and teacher_learner.learner_profile_id = member.learner_profile_id
         and teacher_learner.archived_at is null
        where linked_group.course_id = target_course.course_id
      ) as current_effective
      where current_effective.learner_profile_id = p_learner_profile_id
    )
      and (
        select count(*)
        from (
          select course_learner.learner_profile_id
          from public.course_learner as course_learner
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = course_learner.learner_profile_id
           and teacher_learner.archived_at is null
          where course_learner.course_id = target_course.course_id
          union
          select member.learner_profile_id
          from public.course_learner_group as linked_group
          join public.learner_group_member as member
            on member.learner_group_id = linked_group.learner_group_id
          join public.teacher_learner as teacher_learner
            on teacher_learner.teacher_account_id = v_teacher_account_id
           and teacher_learner.learner_profile_id = member.learner_profile_id
           and teacher_learner.archived_at is null
          where linked_group.course_id = target_course.course_id
        ) as effective
      ) >= 200
  ) then
    raise exception 'course_audience_too_large' using errcode = '22023';
  end if;

  perform 1
  from public.learner_group as learner_group
  where learner_group.id = any(v_group_ids)
    and learner_group.owner_account_id = v_teacher_account_id
  order by learner_group.id
  for update of learner_group;

  select teacher_learner.*
  into v_relation
  from public.teacher_learner as teacher_learner
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = p_learner_profile_id
    and teacher_learner.archived_at is null
  for update of teacher_learner;

  if not found then
    raise exception 'learner_profile_not_found' using errcode = 'P0002';
  end if;

  update public.teacher_learner as teacher_learner
  set display_name = btrim(p_display_name)
  where teacher_learner.teacher_account_id = v_teacher_account_id
    and teacher_learner.learner_profile_id = p_learner_profile_id
  returning teacher_learner.* into v_relation;

  delete from public.learner_group_member as member
  using public.learner_group as learner_group
  where learner_group.id = member.learner_group_id
    and learner_group.owner_account_id = v_teacher_account_id
    and member.learner_profile_id = p_learner_profile_id
    and not (member.learner_group_id = any(v_group_ids));

  insert into public.learner_group_member (
    learner_group_id,
    learner_profile_id
  )
  select requested.id, p_learner_profile_id
  from unnest(v_group_ids) as requested(id)
  on conflict (learner_group_id, learner_profile_id) do nothing;

  return v_relation;
end
$$;


--
-- Name: update_learning_objective(uuid, text, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learning_objective(p_objective_id uuid, p_title text, p_update_title boolean, p_description text, p_update_description boolean) RETURNS SETOF public.learning_objective
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_course_id uuid;
  v_objective public.learning_objective%rowtype;
begin
  if v_actor_user_id is null
    or p_objective_id is null
    or coalesce(p_update_title, false) = false
       and coalesce(p_update_description, false) = false
    or (
      coalesce(p_update_title, false)
      and (
        p_title is null
        or char_length(btrim(p_title)) not between 2 and 240
      )
    )
    or (
      coalesce(p_update_description, false)
      and p_description is not null
      and (
        btrim(p_description) = ''
        or char_length(btrim(p_description)) > 2000
      )
    )
  then
    raise exception 'learning_objective_invalid'
      using errcode = '22023';
  end if;

  select objective.course_id
  into v_course_id
  from public.learning_objective as objective
  join public.course as course on course.id = objective.course_id
  join public.account as account on account.id = course.owner_account_id
  where objective.id = p_objective_id
    and course.archived_at is null
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'learning_objective_not_found'
      using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  where course.id = v_course_id
  for update of course;

  select objective.*
  into v_objective
  from public.learning_objective as objective
  where objective.id = p_objective_id
    and objective.course_id = v_course_id
  for update of objective;

  if not found then
    raise exception 'learning_objective_not_found'
      using errcode = 'P0002';
  end if;

  update public.learning_objective as objective
  set title = case
        when p_update_title then btrim(p_title)
        else objective.title
      end,
      description = case
        when p_update_description then nullif(btrim(p_description), '')
        else objective.description
      end
  where objective.id = p_objective_id
  returning objective.* into v_objective;

  return next v_objective;
end
$$;


--
-- Name: lesson_component; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.lesson_component (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lesson_id uuid NOT NULL,
    "position" integer NOT NULL,
    type_key text NOT NULL,
    schema_version integer DEFAULT 1 NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    placement_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    visibility text DEFAULT 'staff_only'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    student_slide_id uuid,
    primary_learning_objective_id uuid,
    activity_role text,
    CONSTRAINT lesson_component_activity_role_check CHECK (((activity_role IS NULL) OR (activity_role = ANY (ARRAY['practice'::text, 'assessment'::text, 'survey'::text])))),
    CONSTRAINT lesson_component_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT lesson_component_placement_config_check CHECK ((jsonb_typeof(placement_config) = 'object'::text)),
    CONSTRAINT lesson_component_position_check CHECK (("position" > 0)),
    CONSTRAINT lesson_component_schema_version_check CHECK ((schema_version > 0)),
    CONSTRAINT lesson_component_student_screen_assignment_check CHECK ((((visibility = 'staff_only'::text) AND (student_slide_id IS NULL)) OR ((visibility = 'learner_visible'::text) AND (student_slide_id IS NOT NULL)))),
    CONSTRAINT lesson_component_type_key_check CHECK (((btrim(type_key) <> ''::text) AND (lower(btrim(type_key)) <> 'divider'::text))),
    CONSTRAINT lesson_component_visibility_check CHECK ((visibility = ANY (ARRAY['staff_only'::text, 'learner_visible'::text])))
);


--
-- Name: update_lesson_component_v2(uuid, jsonb, boolean, jsonb, boolean, uuid, boolean, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_lesson_component_v2(p_component_id uuid, p_payload jsonb, p_update_payload boolean, p_placement_config jsonb, p_update_placement_config boolean, p_primary_learning_objective_id uuid, p_update_primary_learning_objective_id boolean, p_activity_role text, p_update_activity_role boolean) RETURNS SETOF public.lesson_component
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := (select auth.uid());
  v_course_id uuid;
  v_lesson_id uuid;
  v_component public.lesson_component%rowtype;
  v_primary_learning_objective_id uuid;
  v_activity_role text;
  v_objective_course_id uuid;
  v_objective_archived_at timestamptz;
begin
  if v_actor_user_id is null
    or p_component_id is null
    or p_update_payload is null
    or p_update_placement_config is null
    or p_update_primary_learning_objective_id is null
    or p_update_activity_role is null
    or not (
      p_update_payload
      or p_update_placement_config
      or p_update_primary_learning_objective_id
      or p_update_activity_role
    )
    or (
      p_update_payload
      and (
        p_payload is null
        or jsonb_typeof(p_payload) <> 'object'
      )
    )
    or (not p_update_payload and p_payload is not null)
    or (
      p_update_placement_config
      and (
        p_placement_config is null
        or jsonb_typeof(p_placement_config) <> 'object'
      )
    )
    or (
      not p_update_placement_config
      and p_placement_config is not null
    )
    or (
      not p_update_primary_learning_objective_id
      and p_primary_learning_objective_id is not null
    )
    or (
      p_update_activity_role
      and p_activity_role is not null
      and p_activity_role not in ('practice', 'assessment', 'survey')
    )
    or (not p_update_activity_role and p_activity_role is not null)
  then
    raise exception 'lesson_component_update_invalid'
      using errcode = '22023';
  end if;

  -- The first lookup is authorization/discovery only. Every authoritative
  -- value is read again under the canonical parent-to-child locks below.
  select lesson.course_id, lesson.id
  into v_course_id, v_lesson_id
  from public.lesson_component as component
  join public.lesson as lesson on lesson.id = component.lesson_id
  join public.course as course on course.id = lesson.course_id
  join public.account as account on account.id = course.owner_account_id
  where component.id = p_component_id
    and account.auth_user_id = v_actor_user_id;

  if not found then
    raise exception 'lesson_component_update_not_found'
      using errcode = 'P0002';
  end if;

  perform 1
  from public.course as course
  join public.account as account on account.id = course.owner_account_id
  where course.id = v_course_id
    and account.auth_user_id = v_actor_user_id
  for update of course;

  if not found then
    raise exception 'lesson_component_update_not_found'
      using errcode = 'P0002';
  end if;

  perform 1
  from public.lesson as lesson
  where lesson.id = v_lesson_id
    and lesson.course_id = v_course_id
  for update of lesson;

  if not found then
    raise exception 'lesson_component_update_not_found'
      using errcode = 'P0002';
  end if;

  select component.*
  into v_component
  from public.lesson_component as component
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id
  for update of component;

  if not found then
    raise exception 'lesson_component_update_not_found'
      using errcode = 'P0002';
  end if;

  v_primary_learning_objective_id := case
    when p_update_primary_learning_objective_id
      then p_primary_learning_objective_id
    else v_component.primary_learning_objective_id
  end;
  v_activity_role := case
    when p_update_activity_role then p_activity_role
    else v_component.activity_role
  end;

  if v_primary_learning_objective_id is not null then
    select objective.course_id, objective.archived_at
    into v_objective_course_id, v_objective_archived_at
    from public.learning_objective as objective
    where objective.id = v_primary_learning_objective_id
    for key share of objective;

    if not found then
      raise exception 'lesson_component_learning_objective_not_found'
        using errcode = '23503';
    end if;

    if v_objective_course_id <> v_course_id then
      raise exception 'lesson_component_learning_objective_cross_course'
        using errcode = '23514';
    end if;

    if v_objective_archived_at is not null
      and v_component.primary_learning_objective_id
        is distinct from v_primary_learning_objective_id
    then
      raise exception 'lesson_component_learning_objective_archived'
        using errcode = '23514';
    end if;
  end if;

  if v_activity_role = 'survey'
    and v_component.type_key <> 'single_choice_poll'
  then
    raise exception 'lesson_component_activity_role_unsupported'
      using errcode = '23514';
  end if;

  if v_activity_role in ('practice', 'assessment')
    and v_component.type_key not in (
      'matching_game',
      'choice_quiz',
      'fill_blanks',
      'word_bank',
      'sequence',
      'categorize',
      'free_response',
      'word_builder'
    )
  then
    raise exception 'lesson_component_activity_role_unsupported'
      using errcode = '23514';
  end if;

  update public.lesson_component as component
  set payload = case
        when p_update_payload then p_payload
        else component.payload
      end,
      placement_config = case
        when p_update_placement_config then p_placement_config
        else component.placement_config
      end,
      primary_learning_objective_id =
        v_primary_learning_objective_id,
      activity_role = v_activity_role
  where component.id = p_component_id
    and component.lesson_id = v_lesson_id
  returning component.* into v_component;

  return next v_component;
end
$$;


--
-- Name: update_my_assistant_conversation(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_my_assistant_conversation(p_conversation_id uuid, p_title text, p_archived boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_account_id uuid := public.communication_current_active_account_id();
begin
  if v_actor_account_id is null
    or p_conversation_id is null
    or (p_title is null and p_archived is null)
    or (p_title is not null and p_archived is not null)
    or (
      p_title is not null
      and (btrim(p_title) = '' or char_length(btrim(p_title)) > 160)
    )
  then
    raise exception 'assistant_conversation_invalid' using errcode = '22023';
  end if;

  update public.assistant_conversation as conversation
  set title = coalesce(btrim(p_title), conversation.title),
      archived_at = case
        when p_archived is null then conversation.archived_at
        when p_archived then coalesce(conversation.archived_at, now())
        else null
      end,
      updated_at = now()
  where conversation.id = p_conversation_id
    and conversation.owner_account_id = v_actor_account_id;

  if not found then
    raise exception 'assistant_conversation_not_found' using errcode = 'P0002';
  end if;

  return public.assistant_conversation_projection(
    p_conversation_id,
    v_actor_account_id
  );
end
$$;


--
-- Name: verify_account_pin_credential(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_account_pin_credential(p_identifier text, p_raw_pin text) RETURNS TABLE(auth_user_id uuid, auth_email text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_alias public.account_login_alias%rowtype;
  v_account public.account%rowtype;
  v_security public.account_security%rowtype;
begin
  if p_identifier is null or p_raw_pin is null
    or p_raw_pin !~ '^\d{4,8}$'
  then
    return;
  end if;

  select alias.* into v_alias
  from public.account_login_alias as alias
  where alias.normalized_login = lower(btrim(p_identifier))
    and alias.revoked_at is null
  for update of alias;

  if not found then
    return;
  end if;

  select account.* into v_account
  from public.account as account
  where account.id = v_alias.account_id
    and account.status = 'active'
  for update of account;

  if not found then return; end if;

  insert into public.account_security (account_id)
  values (v_account.id)
  on conflict (account_id) do nothing;

  select security.* into v_security
  from public.account_security as security
  where security.account_id = v_account.id
  for update of security;

  if v_security.pin_locked_until is not null
    and v_security.pin_locked_until > now()
  then
    return;
  end if;

  if v_security.pin_hash is not null
    and extensions.crypt(p_raw_pin, v_security.pin_hash) = v_security.pin_hash
  then
    update public.account_security
    set pin_failed_attempts = 0,
        pin_locked_until = null,
        last_pin_login_at = now()
    where account_id = v_account.id;

    return query
      select v_account.auth_user_id, auth_user.email::text
      from auth.users as auth_user
      where auth_user.id = v_account.auth_user_id;
    return;
  end if;

  update public.account_security
  set pin_failed_attempts = least(pin_failed_attempts + 1, 100),
      pin_locked_until = case
        when pin_failed_attempts + 1 >= 5 then now() + interval '15 minutes'
        else null
      end
  where account_id = v_account.id;
end
$_$;


--
-- Name: verify_current_account_pin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_current_account_pin(p_raw_pin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_account_id uuid;
  v_security public.account_security%rowtype;
begin
  if (select auth.uid()) is null
    or p_raw_pin is null
    or p_raw_pin !~ '^\d{4,8}$'
  then
    return false;
  end if;

  select account.id into v_account_id
  from public.account as account
  where account.auth_user_id = (select auth.uid())
    and account.status = 'active'
  for update of account;

  if not found then return false; end if;

  select security.* into v_security
  from public.account_security as security
  where security.account_id = v_account_id
  for update of security;

  if not found
    or v_security.pin_hash is null
    or (v_security.pin_locked_until is not null and v_security.pin_locked_until > now())
  then
    return false;
  end if;

  if extensions.crypt(p_raw_pin, v_security.pin_hash) = v_security.pin_hash then
    update public.account_security
    set pin_failed_attempts = 0,
        pin_locked_until = null,
        last_pin_login_at = now()
    where account_id = v_account_id;
    return true;
  end if;

  update public.account_security
  set pin_failed_attempts = least(pin_failed_attempts + 1, 100),
      pin_locked_until = case
        when pin_failed_attempts + 1 >= 5 then now() + interval '15 minutes'
        else null
      end
  where account_id = v_account_id;
  return false;
end
$_$;


--
-- Name: account_login_alias; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_login_alias (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    account_id uuid NOT NULL,
    normalized_login text NOT NULL,
    kind text DEFAULT 'login'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    CONSTRAINT account_login_alias_kind_check CHECK ((kind = 'login'::text)),
    CONSTRAINT account_login_alias_login_check CHECK (((normalized_login = lower(btrim(normalized_login))) AND ((char_length(normalized_login) >= 3) AND (char_length(normalized_login) <= 80)) AND (normalized_login ~ '^[[:alnum:]_.-]+$'::text)))
);


--
-- Name: account_preference; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_preference (
    account_id uuid NOT NULL,
    last_selected_school_id uuid,
    theme text,
    settings jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_preference_settings_check CHECK ((jsonb_typeof(settings) = 'object'::text))
);


--
-- Name: account_security; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_security (
    account_id uuid NOT NULL,
    pin_hash text,
    pin_failed_attempts integer DEFAULT 0 NOT NULL,
    pin_locked_until timestamp with time zone,
    pin_created_at timestamp with time zone,
    pin_updated_at timestamp with time zone,
    last_pin_login_at timestamp with time zone,
    sessions_invalid_before timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT account_security_pin_failed_attempts_check CHECK (((pin_failed_attempts >= 0) AND (pin_failed_attempts <= 100)))
);


--
-- Name: assistant_conversation; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assistant_conversation (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_account_id uuid NOT NULL,
    title text NOT NULL,
    context_course_id uuid,
    context_lesson_id uuid,
    last_turn_id bigint,
    last_assistant_turn_id bigint,
    last_read_assistant_turn_id bigint DEFAULT 0 NOT NULL,
    last_turn_at timestamp with time zone,
    archived_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT assistant_conversation_cursor_check CHECK (((COALESCE(last_turn_id, (0)::bigint) >= 0) AND (COALESCE(last_assistant_turn_id, (0)::bigint) >= 0) AND (last_read_assistant_turn_id >= 0) AND (last_read_assistant_turn_id <= COALESCE(last_assistant_turn_id, (0)::bigint)))),
    CONSTRAINT assistant_conversation_last_turn_shape_check CHECK ((((last_turn_id IS NULL) AND (last_turn_at IS NULL)) OR ((last_turn_id IS NOT NULL) AND (last_turn_at IS NOT NULL)))),
    CONSTRAINT assistant_conversation_title_check CHECK (((btrim(title) <> ''::text) AND (char_length(title) <= 160)))
);


--
-- Name: assistant_turn; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.assistant_turn (
    id bigint NOT NULL,
    conversation_id uuid NOT NULL,
    role text NOT NULL,
    delivery_kind text DEFAULT 'interactive'::text NOT NULL,
    body text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    client_turn_id uuid,
    source_key text,
