    CONSTRAINT learner_erasure_request_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT learner_erasure_request_fingerprint_check CHECK ((octet_length(preview_fingerprint) = 32)),
    CONSTRAINT learner_erasure_request_payload_check CHECK ((jsonb_typeof(preview_payload) = 'object'::text))
);


