    CONSTRAINT learner_identity_audit_event_type_check CHECK (((btrim(event_type) <> ''::text) AND (char_length(event_type) <= 100))),
    CONSTRAINT learner_identity_audit_metadata_check CHECK (((jsonb_typeof(metadata) = 'object'::text) AND (pg_column_size(metadata) <= 4096) AND (NOT (metadata ?| ARRAY['email'::text, 'token'::text, 'digest'::text, 'pin'::text, 'comment'::text, 'displayName'::text, 'display_name'::text, 'authUserId'::text, 'auth_user_id'::text]))))
);


--
-- Name: learner_identity_audit_event_id_seq; Type: SEQUENCE; Schema: public; Owner: -
--

ALTER TABLE public.learner_identity_audit_event ALTER COLUMN id ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.learner_identity_audit_event_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


