    CONSTRAINT learner_identity_reconciliation_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'accepted'::text, 'rejected'::text, 'needs_review'::text])))
);


--
-- Name: learner_objective_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learner_objective_state (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    recorded_by_account_id uuid NOT NULL,
    learner_profile_id uuid NOT NULL,
    learning_objective_id uuid,
    source_learning_objective_id_at_time uuid NOT NULL,
    source_course_id_at_time uuid NOT NULL,
    course_title_at_time text NOT NULL,
    subject_at_time text,
    objective_title_at_time text NOT NULL,
    status text NOT NULL,
    reason_code text NOT NULL,
    reason_text text NOT NULL,
    policy_version integer NOT NULL,
    evaluated_at timestamp with time zone NOT NULL,
    last_evidence_at timestamp with time zone NOT NULL,
    freshness_due_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_objective_state_context_bounds_check CHECK ((((char_length(btrim(course_title_at_time)) >= 1) AND (char_length(btrim(course_title_at_time)) <= 240)) AND ((subject_at_time IS NULL) OR ((char_length(btrim(subject_at_time)) >= 1) AND (char_length(btrim(subject_at_time)) <= 240))) AND ((char_length(btrim(objective_title_at_time)) >= 1) AND (char_length(btrim(objective_title_at_time)) <= 240)) AND ((char_length(btrim(reason_text)) >= 1) AND (char_length(btrim(reason_text)) <= 1000)))),
    CONSTRAINT learner_objective_state_live_objective_check CHECK (((learning_objective_id IS NULL) OR (learning_objective_id = source_learning_objective_id_at_time))),
    CONSTRAINT learner_objective_state_policy_check CHECK ((policy_version = 1)),
    CONSTRAINT learner_objective_state_semantics_check CHECK ((((status = 'forming'::text) AND (reason_code = ANY (ARRAY['latest_not_yet'::text, 'latest_with_support'::text, 'independent_opportunities_missing'::text])) AND (freshness_due_at IS NULL)) OR ((status = 'confirmed'::text) AND (reason_code = 'multiple_independent_opportunities'::text) AND (freshness_due_at = (last_evidence_at + '90 days'::interval))) OR ((status = 'recheck_due'::text) AND (reason_code = 'confirmed_evidence_stale'::text) AND (freshness_due_at = (last_evidence_at + '90 days'::interval)) AND (evaluated_at >= freshness_due_at))))
);


