    CONSTRAINT learner_observer_invitation_expiry_check CHECK ((expires_at > created_at)),
    CONSTRAINT learner_observer_invitation_label_check CHECK (((relationship_label IS NULL) OR ((char_length(btrim(relationship_label)) >= 1) AND (char_length(btrim(relationship_label)) <= 80)))),
    CONSTRAINT learner_observer_invitation_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'bound'::text, 'accepted'::text, 'rejected'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT learner_observer_invitation_token_digest_check CHECK ((octet_length(token_digest) = 32))
);


