    action text NOT NULL,
    recommendation_type text,
    private_reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learner_recommendation_override_action_check CHECK ((((action = 'replace'::text) AND (recommendation_type = ANY (ARRAY['repeat'::text, 'try_without_support'::text, 'apply_in_new_context'::text, 'move_forward'::text, 'recheck_freshness'::text]))) OR ((action = 'dismiss'::text) AND (recommendation_type IS NULL)))),
    CONSTRAINT learner_recommendation_override_reason_check CHECK (((char_length(btrim(private_reason)) >= 1) AND (char_length(btrim(private_reason)) <= 500)))
);


--
-- Name: learning_evidence; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learning_evidence (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_profile_id uuid NOT NULL,
    recorded_by_account_id uuid NOT NULL,
    learning_record_id uuid NOT NULL,
    source_observation_id uuid NOT NULL,
    source_course_id_at_time uuid NOT NULL,
    source_lesson_id_at_time uuid NOT NULL,
    source_lesson_run_id_at_time uuid NOT NULL,
    source_component_id_at_time uuid NOT NULL,
    source_learning_objective_id_at_time uuid NOT NULL,
    lesson_component_id uuid,
    learning_objective_id uuid,
    course_title_at_time text NOT NULL,
    lesson_title_at_time text NOT NULL,
    subject_at_time text,
    component_type_at_time text NOT NULL,
    component_label_at_time text NOT NULL,
    component_visibility_at_time text NOT NULL,
    objective_title_at_time text NOT NULL,
    criterion_at_time text NOT NULL,
    direction text NOT NULL,
    support text,
    observed_at timestamp with time zone NOT NULL,
    finalized_at timestamp with time zone NOT NULL,
    materialized_at timestamp with time zone NOT NULL,
    evidence_version integer NOT NULL,
    eligibility_policy_version integer NOT NULL,
    reason_code text NOT NULL,
    supersedes_evidence_id uuid,
    superseded_by_evidence_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT learning_evidence_context_bounds_check CHECK ((((char_length(btrim(course_title_at_time)) >= 1) AND (char_length(btrim(course_title_at_time)) <= 240)) AND ((char_length(btrim(lesson_title_at_time)) >= 1) AND (char_length(btrim(lesson_title_at_time)) <= 240)) AND ((subject_at_time IS NULL) OR ((char_length(btrim(subject_at_time)) >= 1) AND (char_length(btrim(subject_at_time)) <= 240))) AND ((char_length(btrim(component_type_at_time)) >= 1) AND (char_length(btrim(component_type_at_time)) <= 80)) AND ((char_length(btrim(component_label_at_time)) >= 1) AND (char_length(btrim(component_label_at_time)) <= 500)) AND (component_visibility_at_time = ANY (ARRAY['learner_visible'::text, 'staff_only'::text])) AND ((char_length(btrim(objective_title_at_time)) >= 1) AND (char_length(btrim(objective_title_at_time)) <= 240)) AND ((char_length(btrim(criterion_at_time)) >= 1) AND (char_length(btrim(criterion_at_time)) <= 500)))),
    CONSTRAINT learning_evidence_live_component_check CHECK (((lesson_component_id IS NULL) OR (lesson_component_id = source_component_id_at_time))),
    CONSTRAINT learning_evidence_live_objective_check CHECK (((learning_objective_id IS NULL) OR (learning_objective_id = source_learning_objective_id_at_time))),
    CONSTRAINT learning_evidence_not_self_superseded_check CHECK ((((supersedes_evidence_id IS NULL) OR (supersedes_evidence_id <> id)) AND ((superseded_by_evidence_id IS NULL) OR (superseded_by_evidence_id <> id)))),
    CONSTRAINT learning_evidence_semantics_check CHECK ((((direction = 'positive'::text) AND (support = 'independent'::text) AND (reason_code = 'independent_positive_evidence'::text)) OR ((direction = 'positive'::text) AND (support = 'with_support'::text) AND (reason_code = 'supported_positive_evidence'::text)) OR ((direction = 'negative'::text) AND (support IS NULL) AND (reason_code = 'not_yet_negative_evidence'::text)))),
    CONSTRAINT learning_evidence_time_check CHECK (((observed_at <= materialized_at) AND (finalized_at <= materialized_at))),
    CONSTRAINT learning_evidence_version_check CHECK (((evidence_version = 1) AND (eligibility_policy_version = 1)))
);


--
-- Name: learning_record; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.learning_record (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    learner_profile_id uuid NOT NULL,
    lesson_run_id uuid,
    source_course_id uuid,
    source_lesson_id uuid,
    occurred_at timestamp with time zone,
    was_present boolean,
    needs_repeat boolean,
    teacher_comment text,
    course_title_at_time text,
    lesson_title_at_time text,
    subject_at_time text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recorded_by_account_id uuid NOT NULL,
    shared_with_learner_at timestamp with time zone,
    actual_duration_minutes_at_time integer,
    superseded_by_record_id uuid,
    source_course_id_at_time uuid,
    source_lesson_id_at_time uuid,
    source_lesson_run_id_at_time uuid,
    corrected_from_record_id uuid,
    correction_reason text,
    correction_idempotency_key uuid,
    corrected_at timestamp with time zone,
    CONSTRAINT learning_record_actual_duration_check CHECK (((actual_duration_minutes_at_time IS NULL) OR ((occurred_at IS NOT NULL) AND ((actual_duration_minutes_at_time >= 1) AND (actual_duration_minutes_at_time <= 720))))),
    CONSTRAINT learning_record_correction_shape_check CHECK ((((corrected_from_record_id IS NULL) AND (correction_reason IS NULL) AND (correction_idempotency_key IS NULL) AND (corrected_at IS NULL)) OR ((corrected_from_record_id IS NOT NULL) AND (corrected_from_record_id <> id) AND (correction_reason IS NOT NULL) AND (btrim(correction_reason) <> ''::text) AND (char_length(btrim(correction_reason)) <= 500) AND (correction_idempotency_key IS NOT NULL) AND (corrected_at IS NOT NULL) AND (occurred_at IS NOT NULL)))),
    CONSTRAINT learning_record_draft_or_final_check CHECK ((((occurred_at IS NULL) AND (lesson_run_id IS NOT NULL) AND (was_present IS NULL) AND (needs_repeat IS NULL) AND (teacher_comment IS NULL) AND (course_title_at_time IS NULL) AND (lesson_title_at_time IS NULL) AND (subject_at_time IS NULL)) OR ((occurred_at IS NOT NULL) AND (was_present IS NOT NULL) AND (course_title_at_time IS NOT NULL) AND (btrim(course_title_at_time) <> ''::text) AND (lesson_title_at_time IS NOT NULL) AND (btrim(lesson_title_at_time) <> ''::text)))),
    CONSTRAINT learning_record_not_self_superseded_check CHECK (((superseded_by_record_id IS NULL) OR (superseded_by_record_id <> id))),
    CONSTRAINT learning_record_repeat_requires_presence_check CHECK (((needs_repeat IS NOT TRUE) OR (was_present IS TRUE))),
    CONSTRAINT learning_record_shared_comment_shape_check CHECK (((shared_with_learner_at IS NULL) OR ((occurred_at IS NOT NULL) AND (teacher_comment IS NOT NULL) AND (btrim(teacher_comment) <> ''::text)))),
    CONSTRAINT learning_record_teacher_comment_check CHECK (((teacher_comment IS NULL) OR ((btrim(teacher_comment) <> ''::text) AND (char_length(teacher_comment) <= 2000))))
);


