-- Name: course_attestation course_attestation_owner_all; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY course_attestation_owner_all ON public.course_attestation TO authenticated USING ((EXISTS ( SELECT 1
   FROM (public.course course
     JOIN public.account account ON ((account.id = course.owner_account_id)))
  WHERE ((course.id = course_attestation.course_id) AND (course.owner_account_id = ( SELECT public.current_account_id() AS current_account_id)) AND (course.archived_at IS NULL) AND (account.status = 'active'::text))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM (public.course course
     JOIN public.account account ON ((account.id = course.owner_account_id)))
  WHERE ((course.id = course_attestation.course_id) AND (course.owner_account_id = ( SELECT public.current_account_id() AS current_account_id)) AND (course.archived_at IS NULL) AND (account.status = 'active'::text)))));


