-- Auth Account bootstrap trigger. Its function and ACL are part of the public
-- dump above; the trigger itself belongs to auth.users and is recorded here.
CREATE TRIGGER trg_auth_user_create_account
AFTER INSERT ON auth.users
FOR EACH ROW EXECUTE FUNCTION public.handle_auth_user_account();

-- GoTrue writes custom app_metadata after its initial auth.users INSERT. This
-- trigger synchronizes only the trusted same-transaction child-activation
-- marker; the public function above owns the complete fail-closed predicate.
CREATE TRIGGER trg_auth_user_sync_provisional_account
AFTER UPDATE OF raw_app_meta_data ON auth.users
FOR EACH ROW
WHEN (
    (OLD.raw_app_meta_data ->> 'identity_status') IS DISTINCT FROM
        (NEW.raw_app_meta_data ->> 'identity_status')
    OR
    (OLD.raw_app_meta_data ->> 'activation_invitation_id') IS DISTINCT FROM
        (NEW.raw_app_meta_data ->> 'activation_invitation_id')
)
EXECUTE FUNCTION public.sync_provisional_account_from_auth_metadata();

-- Private Storage bucket data invariant. This does not change the base Storage
-- schema; it records the current bucket row that accompanies the public model.
INSERT INTO storage.buckets (
    id,
    name,
    public,
    file_size_limit,
    allowed_mime_types
)
VALUES (
    'course-assets',
    'course-assets',
    false,
    10485760,
    ARRAY[
        'image/jpeg',
        'image/png',
        'image/webp',
        'image/gif',
        'application/pdf',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'application/vnd.openxmlformats-officedocument.presentationml.presentation',
        'text/plain',
        'text/markdown'
    ]::text[]
)
ON CONFLICT (id) DO UPDATE
SET name = EXCLUDED.name,
    public = EXCLUDED.public,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

INSERT INTO storage.buckets (
